		[MethodImpl(MethodImplOptions.NoInlining)]
		public static Exception GetApiRequestNotSupported<T>(IApiProvider<T> apiProvider, object? request, IReadOnlyMetadataContext? metadata) where T : class, IApiProvider<T>
		{
			IDebugApiRequestTracer requestTracer = ((T)apiProvider).GetRequestTracer(metadata);
			if (requestTracer != null)
			{
				return requestTracer.GetNotSupportedException();
			}
			return new ApiRequestNotSupportedException("The api request '{0}' could not be handled by {1}, configure the application with .DebugConfiguration to get more info.".Format(request, typeof(T).Name), request, new MetadataContext(metadata));
		}
