	public static class BuildSettings
	{
		internal const string CodeGeneratorCondition = "MUGEN_SOURCE_GENERATOR";

		public static bool CollectionRaiseItemChangedCheckDuplicates = false;

		public static short CollectionRaiseItemChangedResetThreshold = 50;

		internal static void LinkerInclude()
		{
			if (!RuntimeFeature.IsDynamicCodeSupported)
			{
				IncludeCore(null);
			}
		}

		private static void IncludeCore(IHasDynamicCodeLinkerInfo linkerInfo)
		{
			MugenExtensions.Convert<object, object>(null);
			PropertyAccessorMemberInfoBase.LinkerInclude<object>();
			linkerInfo.Include();
			linkerInfo.LinkerType.GetInterfaces();
			((IDecoratorComponentBase)null).IsDecorable((IMugenApplication)null, (IReadOnlyMetadataContext?)null);
			((IDecoratorComponentBase)null).IsDecorable<IMugenApplication, IComponent<IMugenApplication>>((IMugenApplication)null, (ComponentDescriptor)null, (IReadOnlyMetadataContext?)null);
			((IDecoratorComponentBase)null).TryGetFilter<IMugenApplication, IComponent<IMugenApplication>>((IMugenApplication)null, (ComponentDescriptor)null, (IReadOnlyMetadataContext?)null);
			((IDecoratorComponentBase)null).SetDecoratedComponents((IMugenApplication)null, (ComponentDescriptor)null, default(ItemOrArray<IComponent<IMugenApplication>>), (IReadOnlyMetadataContext?)null);
			((IHasComponentCollectionHandlerComponent)null).GetComponentCollectionHandler((IMugenApplication)null, (IReadOnlyMetadataContext?)null);
			((ICacheDecoratorComponentBase)null).IsCacheable((IMugenApplication)null, (IReadOnlyMetadataContext?)null);
			((ICacheDecoratorComponentBase)null).IsCacheable((IMugenApplication)null, (object)null, (IReadOnlyMetadataContext?)null);
		}
	}
	public static class MugenFeature
	{
		internal const string IsDebugName = "MugenMvvm.IsDebug";

		[FeatureSwitchDefinition("MugenMvvm.IsDebug")]
		public static bool IsDebug
		{
			get
			{
				bool isEnabled;
				return AppContext.TryGetSwitch("MugenMvvm.IsDebug", out isEnabled) && isEnabled;
			}
		}
	}
	public static class MugenService
	{
		public static class Configuration
		{
			public static IFallbackServiceConfiguration? FallbackConfiguration { get; set; }

			public static void InitializeInstance<TService>(TService service) where TService : class
			{
				Configuration<TService>.Initialize(service);
			}

			public static void Clear<TService>() where TService : class
			{
				Configuration<TService>.Clear();
			}
		}

		internal static class Configuration<TService> where TService : class
		{
			private static TService? _service;

			public static TService Instance
			{
				[MethodImpl(MethodImplOptions.AggressiveInlining)]
				get
				{
					if (_service != null)
					{
						return _service;
					}
					return GetInstanceSlow();
				}
			}

			public static TService? Optional
			{
				[MethodImpl(MethodImplOptions.AggressiveInlining)]
				get
				{
					if (_service != null)
					{
						return _service;
					}
					return GetOptionalSlow();
				}
			}

			public static void Initialize(TService service)
			{
				Should.NotBeNull(service, "service");
				_service = service;
			}

			public static void Clear(bool clearFallback = false)
			{
				_service = null;
				if (clearFallback)
				{
					Configuration.FallbackConfiguration = null;
				}
			}

			[MethodImpl(MethodImplOptions.NoInlining)]
			private static TService GetInstanceSlow()
			{
				IFallbackServiceConfiguration? fallbackConfiguration = Configuration.FallbackConfiguration;
				TService val = ((fallbackConfiguration != null) ? fallbackConfiguration.Instance<TService>() : null);
				if (val == null)
				{
					if (typeof(TService) == typeof(IMugenApplication))
					{
						return InitApp();
