	public abstract class BindableModelBase : NotifyPropertyChangedBase, IViewModelBase, INotifyPropertyChangedEx, INotifyPropertyChanged, ISuspendable, IExternalValueHolder<IWeakReference>, IExternalValueHolder<MemberListenerCollection>, IExternalValueHolder<AttachedValueContainer>
	{
		private MemberListenerCollection? _memberListeners;

		private bool _isDirty;

		private int _suspendCount;

		public bool IsSuspended => Volatile.Read(in _suspendCount) != 0;

		AttachedValueContainer? IExternalValueHolder<AttachedValueContainer>._Value { get; set; }

		IWeakReference? IExternalValueHolder<IWeakReference>._Value { get; set; }

