			}
		}

		[DynamicDependency(DynamicallyAccessedMemberTypes.PublicProperties | DynamicallyAccessedMemberTypes.PublicEvents | DynamicallyAccessedMemberTypes.Interfaces, typeof(BindableModelBase))]
		protected BindableModelBase()
		{
		}

		public ActionToken Suspend(IReadOnlyMetadataContext? metadata = null)
		{
			Interlocked.Increment(ref _suspendCount);
			return ActionToken.FromDelegate(delegate(object? m, object? _)
			{
				((BindableModelBase)m).EndSuspend();
			}, this);
		}

		protected virtual void OnEndSuspend(bool isDirty)
		{
			if (isDirty)
			{
				OnPropertyChanged(Default.EmptyPropertyChangedArgs);
			}
		}

		protected override void OnPropertyChanged(PropertyChangedEventArgs args)
		{
			if (IsSuspended)
			{
				_isDirty = true;
				return;
			}
			_memberListeners?.Raise(this, args, args.PropertyName, null);
			base.OnPropertyChanged(args);
		}

		protected override void ClearPropertyChangedSubscribers()
		{
			_memberListeners?.Clear();
			base.ClearPropertyChangedSubscribers();
		}

		private void EndSuspend()
		{
			if (Interlocked.Decrement(ref _suspendCount) == 0)
			{
				OnEndSuspend(_isDirty);
				_isDirty = false;
				OnPropertyChanged(Default.IsSuspendedEventArgs);
			}
		}
	}
