	public abstract class NotifyPropertyChangedBase : INotifyPropertyChangedEx, INotifyPropertyChanged
	{
		internal bool HasSubscribers => this.PropertyChanged != null;

		public event PropertyChangedEventHandler? PropertyChanged;

		[DynamicDependency(DynamicallyAccessedMemberTypes.PublicProperties | DynamicallyAccessedMemberTypes.PublicEvents | DynamicallyAccessedMemberTypes.Interfaces, typeof(NotifyPropertyChangedBase))]
		protected NotifyPropertyChangedBase()
		{
		}

		protected virtual void OnPropertyChanged(PropertyChangedEventArgs args)
		{
			this.PropertyChanged?.Invoke(this, args);
		}

		protected virtual void ClearPropertyChangedSubscribers()
		{
			this.PropertyChanged = null;
		}

		protected void OnPropertyChanged([CallerMemberName] string? propertyName = null)
		{
			OnPropertyChanged(new PropertyChangedEventArgs(propertyName));
		}

		protected bool SetField<T>(ref T field, T value, [CallerMemberName] string? propertyName = null)
		{
			if (EqualityComparer<T>.Default.Equals(field, value))
			{
				return false;
			}
			field = value;
			OnPropertyChanged(propertyName);
			return true;
		}

		void INotifyPropertyChangedEx.OnPropertyChanged(PropertyChangedEventArgs args)
		{
			OnPropertyChanged(args);
		}
	}
