	public sealed class ViewModelCacheById : IHasPriority, IApiHandlerComponent<IViewModelManager, GetViewModelByIdRequest, object>, IApiHandlerComponent<IViewModelManager>, IApiProviderComponent<IViewModelManager>, IApiProviderComponent, IComponent, ISupportRequestComponent<IViewModelManager>, IComponent<IViewModelManager>, ISupportApiHandlerComponent<IViewModelManager, GetViewModelByIdRequest>, IApiHandlerComponent<IViewModelManager, OnLifecycleChangedRequest<IViewModelManager, ViewModelLifecycleState, object>, Unit>, ISupportApiHandlerComponent<IViewModelManager, OnLifecycleChangedRequest<IViewModelManager, ViewModelLifecycleState, object>>
	{
		private readonly Lock _locker;

		private readonly bool _isWeak;

		private DictionarySlim<string, object> _viewModelsCache;

		public int Priority { get; init; }

		public ViewModelCacheById(bool isWeak)
		{
			_locker = new Lock();
			_isWeak = isWeak;
			_viewModelsCache = new DictionarySlim<string, object>(37);
		}

		public object? TryInvoke(GetViewModelByIdRequest request, IViewModelManager apiProvider, IReadOnlyMetadataContext? metadata, CancellationToken cancellationToken)
		{
			object value;
			using (_locker.EnterScope())
			{
				if (!_viewModelsCache.TryGetValue(request.Id, out value))
				{
					return null;
				}
			}
			if (!_isWeak)
			{
				return value;
			}
			object? target = ((IWeakReference)value).Target;
			if (target == null)
			{
				Remove(request.Id);
			}
			return target;
		}

		public Unit TryInvoke(OnLifecycleChangedRequest<IViewModelManager, ViewModelLifecycleState, object> request, IViewModelManager apiProvider, IReadOnlyMetadataContext? metadata, CancellationToken cancellationToken)
		{
			if (!(request.Target is IDisposable disposable) || !(disposable is IMetadataOwner<IMetadataContext>))
			{
				return default(Unit);
			}
			ViewModelLifecycleState lifecycleState = request.LifecycleState;
			object target = request.Target;
			if (lifecycleState.IsInState(ViewModelLifecycleState.Created))
			{
				string id = MugenExtensions.GetId(target, metadata);
				Add(id, target);
			}
			else if (lifecycleState.IsInState(ViewModelLifecycleState.Disposed))
			{
				Remove(MugenExtensions.GetId(target));
			}
			return default(Unit);
		}

		private void Add(string? id, object viewModel)
		{
			if (id == null)
			{
				return;
			}
			using (_locker.EnterScope())
			{
				_viewModelsCache.GetOrAddValueRef(id) = ((_isWeak || !(viewModel is IDisposable)) ? viewModel.ToWeakReferenceRaw() : viewModel);
			}
		}

		private void Remove(string? id)
		{
			if (id == null)
			{
				return;
			}
			using (_locker.EnterScope())
			{
				_viewModelsCache.Remove(id);
			}
		}
	}
