	public sealed class ApiRequestEventListenerHandler<T, TRequest, TResponse> : EventListenerCollection, IApiHandlerComponent<T, TRequest, TResponse>, IApiHandlerComponent<T>, IApiProviderComponent<T>, IApiProviderComponent, IComponent, ISupportRequestComponent<T>, IComponent<T>, ISupportApiHandlerComponent<T, TRequest> where T : class, IApiProvider<T> where TRequest : IApiRequestBase<T, TRequest, TResponse>
	{
		public TResponse? TryInvoke(TRequest request, T apiProvider, IReadOnlyMetadataContext? metadata, CancellationToken cancellationToken)
		{
			Raise(apiProvider, typeof(TRequest).IsValueType ? EventArgs.Empty : ((object)request), metadata);
			return default(TResponse);
		}
	}
	public sealed class EventInfoObserverProvider : IApiHandlerComponent<IObservationManager, GetMemberObservableRequest, MemberObservable>, IApiHandlerComponent<IObservationManager>, IApiProviderComponent<IObservationManager>, IApiProviderComponent, IComponent, ISupportRequestComponent<IObservationManager>, IComponent<IObservationManager>, ISupportApiHandlerComponent<IObservationManager, GetMemberObservableRequest>, IHasPriority
	{
		private static MethodInfo? _raiseMethod;

		private static readonly Func<object?, object, IEventListener, IReadOnlyMetadataContext?, ActionToken> MemberObserverHandler = TryObserve;

		public int Priority { get; init; } = 10;

		private static MethodInfo RaiseMethod => _raiseMethod ?? (_raiseMethod = typeof(EventListenerCollection).GetMethodOrThrow("RaiseEventHandler", BindingFlags.Instance | BindingFlags.Public));

		[UnconditionalSuppressMessage("Trimming", "IL2072")]
		public MemberObservable TryInvoke(GetMemberObservableRequest request, IObservationManager apiProvider, IReadOnlyMetadataContext? metadata, CancellationToken cancellationToken)
		{
			if (request.Member is EventInfo eventInfo)
			{
				if (eventInfo.EventHandlerType == null)
				{
					return default(MemberObservable);
				}
				if (eventInfo.EventHandlerType == typeof(EventHandler) || IMugenService<IReflectionManager>.Instance.CanCreateDelegate(RaiseMethod, eventInfo.EventHandlerType, metadata, cancellationToken))
				{
					return new MemberObservable(MemberObserverHandler, Tuple.Create(eventInfo, "~e" + eventInfo.Name));
				}
			}
			return default(MemberObservable);
		}

		private static ActionToken TryObserve(object? target, object member, IEventListener listener, IReadOnlyMetadataContext? metadata)
		{
			Tuple<EventInfo, string> tuple = (Tuple<EventInfo, string>)member;
			if (target == null && !tuple.Item1.IsStatic())
			{
				return default(ActionToken);
			}
			AttachedValueStorage attachedValueStorage = (target ?? tuple.Item1.DeclaringType).AttachedValues(metadata).BatchUpdate();
			EventListenerCollection value;
			try
			{
				if (!attachedValueStorage.TryGet((ReadOnlySpan<char>)tuple.Item2, out value))
				{
					value = CreateWeakListener(target, tuple.Item1, metadata);
					attachedValueStorage.Set(tuple.Item2, value);
				}
			}
			finally
			{
				((IDisposable)attachedValueStorage/*cast due to .constrained prefix*/).Dispose();
			}
			return value?.Add(listener) ?? default(ActionToken);
		}

		private static EventListenerCollection? CreateWeakListener(object? target, EventInfo eventInfo, IReadOnlyMetadataContext? metadata)
		{
			MethodInfo addMethod = eventInfo.GetAddMethod(nonPublic: true);
			if (addMethod == null)
			{
				return null;
			}
			EventListenerCollection eventListenerCollection = new EventListenerCollection();
			Delegate obj = ((eventInfo.EventHandlerType == typeof(EventHandler)) ? new EventHandler(eventListenerCollection.RaiseEventHandler) : IMugenService<IReflectionManager>.Instance.TryCreateDelegate(eventListenerCollection, RaiseMethod, eventInfo.EventHandlerType, metadata));
			if ((object)obj == null)
			{
				return null;
			}
			addMethod.Invoke(target, new object[1] { obj });
			return eventListenerCollection;
		}
	}
	[DebuggerDisplay("{_listeners}")]
	public class EventListenerCollection
	{
		private const int ItemCount = -1;

		[DebuggerBrowsable(DebuggerBrowsableState.RootHidden)]
		private object? _listeners;

		private int _count;

		public int Count
		{
			get
			{
				if (_count != -1)
				{
					return _count;
				}
				return 1;
			}
		}

		private ReadOnlySpan<object> Span
		{
			get
			{
				if (_count == 0)
				{
					return default(ReadOnlySpan<object>);
				}
				if (_count == -1)
				{
					return MemoryMarshal.CreateReadOnlySpan(in _listeners, 1);
				}
				return new ReadOnlySpan<object>((object[])_listeners, 0, _count);
			}
		}

		public static EventListenerCollection GetOrAdd(object target, string path, IReadOnlyMetadataContext? metadata = null)
		{
			Should.NotBeNull(target, "target");
			Should.NotBeNull(path, "path");
			AttachedValueStorage attachedValueStorage = target.AttachedValues(metadata).BatchUpdate();
			try
			{
				if (attachedValueStorage.TryGet((ReadOnlySpan<char>)path, out EventListenerCollection value))
				{
					return value;
				}
				EventListenerCollection eventListenerCollection = new EventListenerCollection();
				attachedValueStorage.Set(path, eventListenerCollection);
				return eventListenerCollection;
			}
			finally
			{
				((IDisposable)attachedValueStorage/*cast due to .constrained prefix*/).Dispose();
			}
		}

		public static void Raise(object target, string path, object? message, IReadOnlyMetadataContext? metadata)
		{
			Should.NotBeNull(target, "target");
			Should.NotBeNull(path, "path");
			if (target.AttachedValues(metadata).TryGet((ReadOnlySpan<char>)path, out EventListenerCollection value))
			{
				value.Raise(target, message, metadata);
			}
		}

		public void RaiseEventHandler(object? sender, object? args)
		{
			Raise(sender, args, null);
		}

		public void Raise(object? sender, object? args, IReadOnlyMetadataContext? metadata)
		{
			InlineObjectArray inlineObjectArray;
			lock (this)
			{
				if (Count == 0)
				{
					return;
				}
				inlineObjectArray = new InlineObjectArray(Span);
			}
			try
			{
				Span<object> span = inlineObjectArray.Span;
				for (int i = 0; i < span.Length; i++)
				{
					object obj = span[i];
					if (!WeakEventListener.TryHandle(obj, sender, args, metadata))
					{
						Remove(obj);
					}
				}
			}
			finally
			{
				inlineObjectArray.Dispose();
			}
		}

		public void RaiseOnError(object? sender, Exception error, object? state, IReadOnlyMetadataContext? metadata)
		{
			Should.NotBeNull(error, "error");
			InlineObjectArray inlineObjectArray;
			lock (this)
			{
				if (Count == 0)
				{
					return;
				}
				inlineObjectArray = new InlineObjectArray(Span);
			}
			try
			{
				Span<object> span = inlineObjectArray.Span;
				for (int i = 0; i < span.Length; i++)
				{
					object obj = span[i];
