		{
			Path = path;
			_members = Split(path).GetRawValue();
		}

		public static IMemberPath Get(string path)
		{
			Should.NotBeNull(path, "path");
			if (string.IsNullOrWhiteSpace(path))
			{
				return Empty;
			}
			if (path.Contains('.') || path.Contains('['))
			{
				return new MemberPath(path);
			}
			return new SingleMemberPath(path);
		}

		public override string ToString()
		{
			return Path;
		}

		private static ItemOrArray<string> Split(ReadOnlySpan<char> span)
		{
			using PooledItemOrList<string> items = default(PooledItemOrList<string>);
			int start = 0;
			int num = 0;
			int num2 = 0;
			int num3 = 0;
			for (int i = 0; i < span.Length; i++)
			{
				switch (span[i])
				{
				case '<':
					num++;
					break;
				case '>':
					num--;
					break;
				case '(':
					num2++;
					break;
				case ')':
					num2--;
					break;
				case '[':
					if (num == 0 && num2 == 0 && num3 == 0)
					{
						items.AddIfNotNull(GetMember(span, i));
						int j = i + 1;
						num3 = 1;
						for (; j < span.Length; j++)
						{
							if (num3 <= 0)
							{
								break;
							}
							if (span[j] == '[')
							{
								num3++;
							}
							else if (span[j] == ']')
							{
								num3--;
							}
						}
						Should.BeValid(num3 == 0, "path");
						items.AddIfNotNull(GetMember(span, j));
						i = j - 1;
					}
					else
					{
						num3++;
					}
					break;
				case ']':
					num3--;
					break;
				case '.':
					if (num == 0 && num2 == 0 && num3 == 0)
					{
						items.AddIfNotNull(GetMember(span, i));
						start = i + 1;
					}
					break;
				}
			}
			items.AddIfNotNull(GetMember(span, span.Length));
			return items.ToItemOrArray();
			string? GetMember(ReadOnlySpan<char> st, int end)
			{
				ReadOnlySpan<char> readOnlySpan = st.Slice(start, end - start).Trim();
				start = end;
				if (readOnlySpan.Length != 0)
				{
					return readOnlySpan.ToString();
				}
				return null;
			}
		}
	}
