		{
			if (typeof(IExternalValueHolder<MemberListenerCollection>).IsAssignableFrom(type))
			{
				return new MemberObservable(MemberObserverHolderHandler, member);
			}
			if (typeof(INotifyPropertyChanged).IsAssignableFrom(type))
			{
				return new MemberObservable(MemberObserverHandler, member);
			}
			return default(MemberObservable);
