		private static ActionToken TryObserve(object? target, object member, IEventListener listener, IReadOnlyMetadataContext? metadata)
		{
			if (target == null)
			{
				return default(ActionToken);
			}
			AttachedValueStorage attachedValueStorage = target.AttachedValues(metadata).BatchUpdate();
			MemberListenerCollection value;
			try
			{
				if (!attachedValueStorage.TryGet((ReadOnlySpan<char>)"~p", out value))
				{
					value = new MemberListenerCollection();
					((INotifyPropertyChanged)target).PropertyChanged += value.RaiseEventHandler;
					attachedValueStorage.Set("~p", value);
				}
			}
			finally
			{
				((IDisposable)attachedValueStorage/*cast due to .constrained prefix*/).Dispose();
			}
			return value.Add(listener, (string)member);
		}
