	public sealed class RootSourceObserver : EventListenerCollection, IEventListener, IWeakItem, IDisposable
	{
		private readonly IWeakReference _targetRef;

		private IWeakReference? _parentRef;

		private ActionToken _parentToken;

		public bool IsWeak => true;

		public bool IsAlive => _targetRef.IsAlive;

		private RootSourceObserver(object target)
		{
			Should.NotBeNull(target, "target");
			_targetRef = target.ToWeakReferenceRaw();
		}

		public static RootSourceObserver GetOrAdd(object target)
		{
			AttachedValueStorage attachedValueStorage = target.AttachedValues().BatchUpdate();
			try
			{
				if (!attachedValueStorage.TryGet((ReadOnlySpan<char>)"@$r$", out RootSourceObserver value))
				{
					value = new RootSourceObserver(target);
					attachedValueStorage.Set("@$r$", value);
				}
				return value;
			}
			finally
			{
				((IDisposable)attachedValueStorage/*cast due to .constrained prefix*/).Dispose();
			}
		}

		public static void Clear(object target)
		{
			if (target.AttachedValues().Remove("@$r$", out object oldValue))
			{
				(oldValue as RootSourceObserver)?.Dispose();
			}
		}

		public object? Get(IReadOnlyMetadataContext? metadata)
		{
			return BindingMacrosMethodExtensions.GetRoot(_targetRef.Target, metadata);
		}

		public void Dispose()
		{
			ClearParent();
			Clear();
		}

		protected override void OnListenersAdded()
		{
			object target = _targetRef.Target;
			if (target != null)
			{
				UpdateParent(target, null);
			}
