		}

		private bool UpdateParent(object target, IReadOnlyMetadataContext? metadata)
		{
			IAccessorMemberInfo accessorMemberInfo = ObjectInternalBindableMembers.TryGetParentAccessorMember(target, metadata);
			object obj = _parentRef?.Target;
			object obj2 = accessorMemberInfo?.GetValue(target, metadata);
			if (obj == obj2)
			{
