				{
					_parentToken = accessorMemberInfo.TryObserve(target, this, metadata);
				}
				return false;
			}
			if (accessorMemberInfo != null && !_parentToken.IsInitialized)
			{
				_parentToken = accessorMemberInfo.TryObserve(target, this, metadata);
			}
			if (obj != null)
			{
				GetOrAdd(obj).Remove(this);
			}
			if (obj2 != null)
			{
				GetOrAdd(obj2).Add(this);
			}
			_parentRef = obj2?.ToWeakReferenceRaw();
			return true;
		}

		private void ClearParent()
