				return null;
			}
		}

		public ViewModelPresenterMediator(object viewModel, IViewMapping mapping, NavigationType navigationType)
		{
			Should.NotBeNull(viewModel, "viewModel");
			Should.NotBeNull(mapping, "mapping");
			Should.NotBeNull(navigationType, "navigationType");
			ViewModel = viewModel;
			Mapping = mapping;
			NavigationType = navigationType;
			Id = "p_" + navigationType.Name + "/" + mapping.Id;
			_locker = new Lock();
			IMugenService<IMugenApplication>.Instance.TryRegisterDisposeToken(viewModel, ActionToken.FromDelegate(this, delegate(ViewModelPresenterMediator m)
			{
				m.OnCanceled(disposed: true);
			}));
		}

		public NavigationResult TryShow(object? view, IReadOnlyMetadataContext? metadata, CancellationToken cancellationToken)
		{
			using (_locker.EnterScope())
			{
				if (!CanShow(metadata))
				{
					return default(NavigationResult);
				}
				if (_showingContext != null)
				{
					return GetPresenterResult(_showingContext.Metadata);
				}
				if (_isShown && view != null && metadata.Get(NavigationMetadata.IsRestoration, defaultValue: false))
				{
					_isRestored = true;
					Restore(view, metadata, cancellationToken);
				}
				else
				{
					_isRestored = false;
					Show(view, metadata, cancellationToken);
				}
				return GetPresenterResult(metadata);
			}
		}

		public NavigationResult TryClose(object? view, IReadOnlyMetadataContext? metadata, CancellationToken cancellationToken)
		{
			using (_locker.EnterScope())
			{
				if (!IsShowing && !_isShown)
				{
					return default(NavigationResult);
				}
				if (!CanClose(view, metadata))
				{
					return default(NavigationResult);
				}
				if (_closingContext != null)
				{
					return GetPresenterResult(_closingContext.Metadata);
				}
				Close(view, metadata.Get(NavigationMetadata.IsBackNavigationClose, defaultValue: false) ? NavigationMode.Back : NavigationMode.Close, metadata, cancellationToken);
				return GetPresenterResult(metadata);
			}
		}

		private void OnViewLifecycleChanged(OnLifecycleChangedRequest<IViewManager, ViewLifecycleState, RawViewInfo> request, IReadOnlyMetadataContext? metadata)
		{
			try
			{
				ViewLifecycleState lifecycleState = request.LifecycleState;
				IView view = request.Target.TryGet<IView>();
				if ((View == null || View.IsInState((FlagsEnumBase<ViewLifecycleState, long>?)ViewLifecycleState.Cleared) || View.IsInState((FlagsEnumBase<ViewLifecycleState, long>?)ViewLifecycleState.Clearing)) && lifecycleState.IsInState(ViewLifecycleState.Initializing) && view != null && object.Equals(view.ViewModel, ViewModel) && view.Mapping.Id == Mapping.Id && !view.IsInState((FlagsEnumBase<ViewLifecycleState, long>?)ViewLifecycleState.Closed, metadata))
				{
					UpdateView(view, metadata);
				}
				if (View != null && view.IsSameView(View))
				{
					OnViewLifecycleChanged(lifecycleState, request.State, metadata);
				}
			}
			catch (Exception exception)
			{
				OnNavigationFailed(_showingContext ?? _closingContext ?? GetNavigationContext(NavigationMode.Refresh, metadata), exception, metadata);
			}
		}

		private void OnViewShown(IReadOnlyMetadataContext? metadata)
		{
			if (View != null)
			{
				if (_showingContext == null)
				{
					_showingContext = GetShowNavigationContext(null, metadata);
				}
				OnNavigated(_showingContext, metadata);
			}
		}

		private void OnViewClosing(NavigationMode navigationMode, ICancelableRequest e, IReadOnlyMetadataContext? metadata)
		{
			try
			{
				if (View == null || (e.Cancel ?? false) || _isDisposed || !_isShown)
				{
					return;
				}
				_closingCancelArgs = e;
				using (_locker.EnterScope())
				{
					if (_closingContext == null)
					{
						e.Cancel = true;
						Close(View.RawView, navigationMode, metadata, CancellationToken.None);
					}
					else
					{
						e.Cancel = false;
					}
				}
			}
			finally
			{
				_closingCancelArgs = null;
			}
		}

		private void OnViewClosed(NavigationMode navigationMode, IReadOnlyMetadataContext? metadata)
		{
			if (_closingContext == null)
			{
				_isClosingFromLifecycle = true;
				if (_showingContext != null)
				{
					TryClose(View, metadata, CancellationToken.None);
					return;
				}
				_closingContext = GetNavigationContext(navigationMode, metadata);
				OnNavigating(_closingContext, metadata);
			}
			if (!_isAppeared)
			{
				_isClosingFromLifecycle = false;
				WeakListener listener = _listener;
				if (listener != null)
				{
					_listener = null;
					IMugenService<IViewManager>.Instance.RemoveComponent(listener);
				}
				if (View != null)
				{
					OnNavigated(_closingContext ?? GetNavigationContext(navigationMode, metadata), metadata);
				}
			}
		}

		private void OnViewAppearing(object? state, IReadOnlyMetadataContext? metadata)
		{
			ICancelableRequest cancelableRequest = state as ICancelableRequest;
			if (cancelableRequest != null && cancelableRequest.Cancel == true)
			{
				if (_showingContext != null)
				{
					OnNavigationCanceled(_showingContext, metadata, CancellationToken.None);
				}
				return;
			}
			if (_isClosingFromLifecycle && _closingContext != null)
			{
				OnNavigationCanceled(_closingContext, metadata, CancellationToken.None);
			}
			if (_closingContext != null && cancelableRequest != null)
			{
				if (_showingContext != null)
				{
					cancelableRequest.Cancel = true;
					OnNavigationCanceled(_showingContext, metadata, CancellationToken.None);
				}
			}
			else if (_showingContext == null)
			{
				_showingContext = GetNavigationContext(NavigationMode.Refresh, metadata);
				if (_isRestored)
				{
					metadata = metadata.WithValue(NavigationMetadata.IsRestoration, value: true);
					_showingContext.Metadata.Set(NavigationMetadata.IsRestoration, value: true);
					_isRestored = false;
				}
				OnNavigating(_showingContext, metadata);
			}
		}

		private void OnViewAppeared(IReadOnlyMetadataContext? metadata)
		{
			_isClosingFromLifecycle = false;
			_isAppeared = true;
			if (_showingContext != null)
			{
				OnViewShown(metadata);
			}
			if (_closingContext == null && _isDisposed)
			{
				TryClose(View, metadata, CancellationToken.None);
			}
		}

		private void OnViewDisappeared(IReadOnlyMetadataContext? metadata)
		{
			_isAppeared = false;
			if (_closingContext != null && !_isClosing)
			{
				OnViewClosed(NavigationMode.Close, metadata);
			}
			else if (_showingContext != null)
			{
				OnNavigationCanceled(_showingContext, metadata, CancellationToken.None);
			}
		}

		private void OnViewCleared(IReadOnlyMetadataContext? metadata)
		{
			if (!IsClosing)
			{
				UpdateView(null, metadata);
			}
		}

		private void OnViewLifecycleChanged(ViewLifecycleState lifecycleState, object? state, IReadOnlyMetadataContext? metadata)
		{
			if (lifecycleState.IsInState(ViewLifecycleState.Appearing))
			{
				OnViewAppearing(state, metadata);
			}
			else if (lifecycleState.IsInState(ViewLifecycleState.Appeared))
			{
				OnViewAppeared(metadata);
			}
			else if (lifecycleState.IsInState(ViewLifecycleState.Disappeared))
			{
				OnViewDisappeared(metadata);
			}
			else if (lifecycleState.IsInState(ViewLifecycleState.Closing) && state is ICancelableRequest e)
			{
				if (_closingContext == null)
				{
					_isClosingFromLifecycle = true;
				}
				OnViewClosing(lifecycleState.NavigationMode ?? NavigationMode.Close, e, metadata);
			}
			else if (lifecycleState.IsInState(ViewLifecycleState.Closed))
			{
				OnViewClosed(lifecycleState.NavigationMode ?? NavigationMode.Close, metadata);
			}
			else if (lifecycleState.IsInState(ViewLifecycleState.Cleared))
			{
				OnViewCleared(metadata);
			}
		}

		private ValueTask<IView> InitializeViewAsync(object? view, INavigationContext navigationContext, IReadOnlyMetadataContext? metadata, CancellationToken cancellationToken)
		{
			return IMugenService<IViewManager>.Instance.InitializeAsync(new InitializeNavigationViewRequest(navigationContext, Mapping, ViewModel, view), metadata, cancellationToken);
		}

		private async Task ShowViewAsync(IView view, INavigationContext navigationContext, IReadOnlyMetadataContext? metadata, CancellationToken cancellationToken)
		{
			bool isAppeared = _isAppeared;
			if (!(await view.ShowAsync(navigationContext, metadata, cancellationToken)))
			{
				OnNavigationCanceled(navigationContext, metadata, cancellationToken);
			}
			else if (_isAppeared && isAppeared)
			{
				OnViewShown(null);
			}
		}

		private async Task<bool> ActivateViewAsync(IView view, INavigationContext navigationContext, IReadOnlyMetadataContext? metadata, CancellationToken cancellationToken)
		{
			bool isAppeared = _isAppeared;
			await view.ActivateAsync(navigationContext, metadata, cancellationToken);
			if (_isAppeared && isAppeared)
			{
				OnNavigated(_showingContext ?? (_showingContext = GetShowNavigationContext(null, metadata)), metadata);
			}
			return true;
		}

		private NavigationResult GetPresenterResult(IReadOnlyMetadataContext? metadata)
		{
			return new NavigationResult(ViewModel, NavigationId, this, NavigationType, metadata);
		}

		private INavigationContext GetShowNavigationContext(object? view, IReadOnlyMetadataContext? metadata)
		{
			NavigationMode navigationMode = null;
			if (_isShown)
			{
				navigationMode = NavigationMode.Refresh;
			}
			else
			{
				HashSet<string> hashSet = ViewModel.AttachedMetadata().Get(InternalMetadata.OpenedNavigationProviders);
				if (hashSet != null)
				{
					lock (hashSet)
					{
						if (hashSet.Contains(Id))
						{
							navigationMode = NavigationMode.Restore;
						}
					}
				}
			}
			INavigationContext navigationContext = GetNavigationContext(navigationMode ?? NavigationMode.New, metadata);
			if (view != null)
			{
				navigationContext.Metadata.Set(InternalMetadata.View, view);
			}
			return navigationContext;
		}

		private INavigationContext GetNavigationContext(NavigationMode mode, IReadOnlyMetadataContext? metadata)
		{
			return IMugenService<INavigationDispatcher>.Instance.GetNavigationContext(ViewModel, this, NavigationId, NavigationType, mode, metadata);
		}

		private bool CanShow(IReadOnlyMetadataContext? metadata)
		{
			return CheckNavigationType(metadata);
		}

		private bool CanClose(object? view, IReadOnlyMetadataContext? metadata)
		{
			if (CheckNavigationType(metadata) && View != null)
			{
				if (view != null)
				{
					return View.IsSameView(view);
				}
				return true;
			}
			return false;
		}

		private void OnNavigating(INavigationContext navigationContext, IReadOnlyMetadataContext? metadata)
		{
			IMugenService<INavigationDispatcher>.Instance.OnNavigating(navigationContext, metadata);
		}

		private void OnNavigated(INavigationContext navigationContext, IReadOnlyMetadataContext? metadata)
		{
			HashSet<string> orAdd = ViewModel.AttachedMetadata().GetOrAdd(InternalMetadata.OpenedNavigationProviders);
			lock (orAdd)
			{
				if (navigationContext.NavigationMode.IsClose)
				{
					orAdd.Remove(Id);
				}
				else
				{
					orAdd.Add(Id);
				}
			}
			ClearFields(navigationContext, null, null, metadata);
			IMugenService<INavigationDispatcher>.Instance.OnNavigated(navigationContext, metadata);
			if (navigationContext.NavigationMode.IsClose)
			{
				UpdateView(null, metadata);
			}
		}

		private void OnNavigationFailed(INavigationContext navigationContext, Exception exception, IReadOnlyMetadataContext? metadata)
		{
			exception = exception.TryGetBaseException(out OperationCanceledException canceledException);
			if (canceledException == null)
			{
				ClearFields(navigationContext, null, exception, metadata);
				IMugenService<INavigationDispatcher>.Instance.OnNavigationFailed(navigationContext, exception, metadata);
			}
			else
			{
				OnNavigationCanceled(navigationContext, metadata, canceledException.CancellationToken);
			}
		}

		private void OnNavigationCanceled(INavigationContext navigationContext, IReadOnlyMetadataContext? metadata, CancellationToken cancellationToken)
		{
			ClearFields(navigationContext, cancellationToken, null, metadata);
			IMugenService<INavigationDispatcher>.Instance.OnNavigationCanceled(navigationContext, cancellationToken, metadata);
		}

		private void UpdateView(IView? view, IReadOnlyMetadataContext? metadata)
		{
			if (View.IsSameView(view))
			{
				return;
			}
			if (View != null)
			{
				IMugenService<IViewManager>.Instance.TryCleanup(View, metadata);
			}
			View = view;
			if (view != null)
			{
				if (_listener == null)
				{
					_listener = new WeakListener(this);
					IMugenService<IViewManager>.Instance.AddComponent(_listener);
				}
				if (view.IsInState((FlagsEnumBase<ViewLifecycleState, long>?)ViewLifecycleState.Closed, metadata))
				{
					ExceptionManager.ThrowCanceledException();
				}
				else if (view.IsInState((FlagsEnumBase<ViewLifecycleState, long>?)ViewLifecycleState.Appeared, metadata))
				{
					_isAppeared = true;
				}
				else if (view.IsInState((FlagsEnumBase<ViewLifecycleState, long>?)ViewLifecycleState.Disappeared, metadata))
				{
					_isAppeared = false;
				}
			}
		}

		private async void Show(object? view, IReadOnlyMetadataContext? metadata, CancellationToken cancellationToken)
		{
			INavigationContext context = null;
			try
			{
				CancellationToken originalToken = cancellationToken;
				_showingTask?.TrySetCanceled(CancellationToken.None);
				_showingToken.SafeCancel();
				_showingToken = CancellationTokenSource.CreateLinkedTokenSource(cancellationToken);
				_showingTask = new TaskCompletionSource<object>();
				cancellationToken = _showingToken.Token;
				context = (_showingContext = GetShowNavigationContext(view, metadata));
				await IMugenService<IMugenApplication>.Instance.SwitchToAsync(ThreadExecutionMode.Main);
				if (!EnsureValidState(context, metadata, cancellationToken))
				{
					return;
				}
				if (!CanShow(metadata))
				{
					OnNavigationCanceled(context, metadata, cancellationToken);
				}
				else if (!(await IMugenService<INavigationDispatcher>.Instance.OnNavigatingAsync(context, metadata, cancellationToken)))
				{
					OnNavigationCanceled(context, metadata, cancellationToken);
				}
				else
				{
					if (!EnsureValidState(context, metadata, cancellationToken))
					{
						return;
					}
					if (!context.NavigationMode.IsNew && View != null && (view == null || View.IsSameView(view)))
					{
						await RefreshAsync(View, context, metadata, cancellationToken);
						return;
					}
					IView view2 = await InitializeViewAsync(view, context, metadata, cancellationToken);
					UpdateView(view2, metadata);
					if (EnsureValidState(context, metadata, cancellationToken))
					{
						if (!context.NavigationMode.IsNew && view != null)
						{
							await RefreshAsync(view2, context, metadata, cancellationToken);
						}
						else
						{
							await ShowViewAsync(view2, context, metadata, cancellationToken);
						}
						_isShown = true;
						originalToken.Register(delegate(object? o)
						{
							((ViewModelPresenterMediator)o).OnCanceled(disposed: false);
						}, this);
					}
				}
			}
			catch (Exception exception)
			{
				OnNavigationFailed(context ?? GetNavigationContext(NavigationMode.Refresh, metadata), exception, metadata);
			}
		}

		private async void Restore(object? view, IReadOnlyMetadataContext? metadata, CancellationToken cancellationToken)
		{
			INavigationContext context = GetNavigationContext(NavigationMode.Refresh, metadata);
			try
			{
				UpdateView(await InitializeViewAsync(view, context, metadata, cancellationToken), metadata);
			}
			catch (Exception exception)
			{
				OnNavigationFailed(context, exception, metadata);
			}
		}

		private async void Close(object? view, NavigationMode navigationMode, IReadOnlyMetadataContext? metadata, CancellationToken cancellationToken)
		{
			INavigationContext context = null;
			try
			{
				_showingToken.SafeCancel();
				context = (_closingContext = GetNavigationContext(navigationMode, metadata));
				if (_showingTask != null)
				{
					await _showingTask.Task;
				}
				await IMugenService<IMugenApplication>.Instance.SwitchToAsync(ThreadExecutionMode.Main);
				if (!EnsureValidState(context, metadata, cancellationToken))
				{
					return;
				}
				if (!CanClose(view, metadata))
				{
					OnNavigationCanceled(context, metadata, cancellationToken);
					return;
				}
				_isClosing = true;
				if (!(await IMugenService<INavigationDispatcher>.Instance.OnNavigatingAsync(context, metadata, cancellationToken)))
				{
					OnNavigationCanceled(context, metadata, cancellationToken);
					return;
				}
				cancellationToken.ThrowIfCancellationRequested();
				if (_closingCancelArgs != null)
				{
					_closingCancelArgs.Cancel = false;
				}
				else if (View != null && !(await View.CloseAsync(context, metadata, cancellationToken)))
				{
					OnNavigationCanceled(context, metadata, cancellationToken);
				}
			}
			catch (Exception exception)
			{
				OnNavigationFailed(context ?? GetNavigationContext(navigationMode, metadata), exception, metadata);
			}
			finally
			{
				_isClosing = false;
			}
		}

		private async Task RefreshAsync(IView view, INavigationContext context, IReadOnlyMetadataContext? metadata, CancellationToken cancellationToken)
		{
			if (!(await ActivateViewAsync(view, context, metadata, cancellationToken)))
			{
				OnNavigationCanceled(context, metadata, CancellationToken.None);
			}
		}

		private async void OnCanceled(bool disposed)
		{
			if (disposed)
			{
				_isDisposed = true;
			}
			INavigationContext context = null;
			try
			{
				await IMugenService<IMugenApplication>.Instance.SwitchToAsync(ThreadExecutionMode.Main);
				if (_isShown)
				{
					IView view = View;
					if (view == null)
					{
						context = (_closingContext = GetNavigationContext(NavigationMode.New, null));
						OnNavigationCanceled(context, null, CancellationToken.None);
					}
					else
					{
						TryClose(view, null, CancellationToken.None);
					}
				}
			}
			catch (Exception exception)
			{
				OnNavigationFailed(context ?? GetNavigationContext(NavigationMode.New, null), exception, null);
			}
		}

		private void ClearFields(INavigationContext navigationContext, CancellationToken? cancellationToken, Exception? error, IReadOnlyMetadataContext? metadata)
		{
			using (_locker.EnterScope())
			{
				if (View != null && (cancellationToken.HasValue || error != null) && (navigationContext.NavigationMode.IsNew || navigationContext.NavigationMode.IsRestore || View.IsSameView(navigationContext.Metadata.Get(InternalMetadata.View))))
				{
					UpdateView(null, metadata);
				}
				_showingToken?.Dispose();
				_showingToken = null;
				if (navigationContext.NavigationMode.IsClose)
				{
					if (!cancellationToken.HasValue && error == null)
					{
						_isShown = false;
					}
					_closingContext = null;
					_closingCancelArgs = null;
					return;
				}
				_showingContext = null;
				TaskCompletionSource<object> showingTask = _showingTask;
				_showingTask = null;
				if (showingTask != null)
				{
					if (error != null)
					{
						showingTask.TrySetException(error);
						showingTask.Task.LogException(UnhandledExceptionType.Navigation);
					}
					else if (cancellationToken.HasValue)
					{
						showingTask.TrySetCanceled(cancellationToken.Value);
					}
					else
					{
						showingTask.TrySetResult(null);
					}
					if (cancellationToken.HasValue || error != null)
					{
						_isShown = false;
						_closingContext = null;
						_closingCancelArgs = null;
					}
				}
			}
		}

		private bool CheckNavigationType(IReadOnlyMetadataContext? metadata)
		{
			if (metadata.TryGet(NavigationMetadata.NavigationType, out var value))
			{
				return value == NavigationType;
			}
			return true;
		}

		private bool EnsureValidState(INavigationContext navigationContext, IReadOnlyMetadataContext? metadata, CancellationToken cancellationToken)
		{
			if (!navigationContext.NavigationMode.IsClose && _isDisposed)
			{
				OnNavigationFailed(navigationContext, new ObjectDisposedException(ViewModel.GetType().FullName), metadata);
				return false;
			}
			if (cancellationToken.IsCancellationRequested)
			{
				OnNavigationCanceled(navigationContext, metadata, cancellationToken);
				return false;
			}
			return true;
		}
	}
	public sealed class ViewNavigationConditionDispatcher : IHasPriority, IApiHandlerComponent<INavigationDispatcher, OnNavigatingAsyncRequest, ValueTask<bool?>>, IApiHandlerComponent<INavigationDispatcher>, IApiProviderComponent<INavigationDispatcher>, IApiProviderComponent, IComponent, ISupportRequestComponent<INavigationDispatcher>, IComponent<INavigationDispatcher>, ISupportApiHandlerComponent<INavigationDispatcher, OnNavigatingAsyncRequest>
	{
		private readonly bool _waitBackground;

		private readonly NavigationType? _rootNavigationType;

		private readonly Lock _locker;

		private DictionarySlim<NavigationType, (SemaphoreSlim, SemaphoreSlim)> _mapping;

		public int Priority { get; init; }

		public ViewNavigationConditionDispatcher(bool waitBackground, NavigationType? rootNavigationType)
		{
			_waitBackground = waitBackground;
			_rootNavigationType = rootNavigationType;
			_locker = new Lock();
			_mapping = new DictionarySlim<NavigationType, (SemaphoreSlim, SemaphoreSlim)>(3);
		}

		public async ValueTask<bool?> TryInvoke(OnNavigatingAsyncRequest request, INavigationDispatcher apiProvider, IReadOnlyMetadataContext? metadata, CancellationToken cancellationToken)
		{
			INavigationContext context = request.NavigationContext;
			NavigationMode navigationMode = context.NavigationMode;
			if ((object)navigationMode != null && !navigationMode.IsNew && !navigationMode.IsRefresh && !navigationMode.IsRestore && !navigationMode.IsClose)
			{
				return true;
			}
			bool showTaken = false;
			bool closeTaken = false;
			var (showSemaphore, closeSemaphore) = GetSemaphores(context.NavigationType);
			try
			{
				if (context.NavigationMode.IsNew || context.NavigationMode.IsRefresh || context.NavigationMode.IsRestore)
				{
					showTaken = await showSemaphore.WaitAsync(-1, cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
				}
				else if (context.NavigationMode.IsClose)
				{
					closeTaken = await closeSemaphore.WaitAsync(-1, cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
				}
				cancellationToken.ThrowIfCancellationRequested();
				long timestamp = DateTime.UtcNow.Ticks;
				context.Metadata.Set(NavigationMetadata.ConditionState, "");
				if (metadata is IMetadataContext metadata2)
				{
					metadata2.Set(NavigationMetadata.ConditionState, "");
				}
				foreach (INavigationEntry navigationEntry in apiProvider.GetNavigationEntries(null, metadata, cancellationToken).GetDisposableEnumerator())
				{
					if (context.Target != null && context.Target.Equals(navigationEntry.Target))
					{
						if (navigationEntry.IsPending)
						{
							navigationEntry.Metadata.Set(NavigationMetadata.ConditionState, "");
						}
						continue;
					}
					if (_waitBackground && navigationEntry.NavigationType == NavigationType.Background)
					{
						await apiProvider.WaitCloseNavigationAsync(navigationEntry.NavigationId, metadata, cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
					}
					if ((!(navigationEntry.NavigationType != context.NavigationType) || !(navigationEntry.NavigationType != _rootNavigationType)) && navigationEntry.Timestamp < timestamp && (!navigationEntry.IsPending || !(navigationEntry.NavigationType == context.NavigationType) || navigationEntry.Metadata.Contains(NavigationMetadata.ConditionState)) && (!context.NavigationMode.IsClose || !navigationEntry.IsPending))
					{
						await apiProvider.WaitShowNavigationAsync(navigationEntry.NavigationId, metadata, cancellationToken).ConfigureAwait(ConfigureAwaitOptions.SuppressThrowing);
						cancellationToken.ThrowIfCancellationRequested();
						await apiProvider.WaitClosingNavigationAsync(navigationEntry.NavigationId, metadata, cancellationToken).ConfigureAwait(ConfigureAwaitOptions.SuppressThrowing);
						cancellationToken.ThrowIfCancellationRequested();
					}
