		private sealed class BatchUpdateAwaiter : TaskCompletionSource<object?>, IApiHandlerComponent<IReadOnlyObservableCollection, OnEndBatchCollectionRequest, Unit>, IApiHandlerComponent<IReadOnlyObservableCollection>, IApiProviderComponent<IReadOnlyObservableCollection>, IApiProviderComponent, IComponent, ISupportRequestComponent<IReadOnlyObservableCollection>, IComponent<IReadOnlyObservableCollection>, ISupportApiHandlerComponent<IReadOnlyObservableCollection, OnEndBatchCollectionRequest>, IHasPriority
		{
			private readonly IReadOnlyObservableCollection _collection;

			private readonly bool _raisePendingNotifications;

			public int Priority => int.MinValue;

			public BatchUpdateAwaiter(IReadOnlyObservableCollection collection, bool raisePendingNotifications, CancellationToken cancellationToken)
			{
				_collection = collection;
				_raisePendingNotifications = raisePendingNotifications;
				if (!collection.Components.TryAdd(this) || !collection.IsInBatch(null, cancellationToken))
				{
					Complete(canceled: false);
				}
				else if (cancellationToken.CanBeCanceled)
				{
					cancellationToken.Register(delegate(object? o)
					{
						((BatchUpdateAwaiter)o).Complete(canceled: true);
					}, this);
				}
			}

			public Unit TryInvoke(OnEndBatchCollectionRequest request, IReadOnlyObservableCollection apiProvider, IReadOnlyMetadataContext? metadata, CancellationToken cancellationToken)
			{
				Complete(canceled: false);
				return default(Unit);
			}

			private void Complete(bool canceled)
			{
				_collection.Components.Remove(this);
				if (canceled)
				{
					TrySetCanceled();
					return;
				}
				if (!base.Task.IsCompleted && _raisePendingNotifications)
				{
					_collection.RaisePendingNotifications();
				}
				TrySetResult(null);
			}
		}

