		{
			ValueTask<TResponse> valueTask = apiProvider.TryInvoke<T, TRequest, ValueTask<TResponse>>(request, metadata, cancellationToken);
			if (default(TResponse) != null && (!typeof(TResponse).IsValueType || !typeof(IHasInitializedState).IsAssignableFrom(typeof(TResponse))))
			{
				return valueTask;
