		public static ValueTask<TResponse> TryInvokeAsync<T, [DynamicallyAccessedMembers(DynamicallyAccessedMemberTypes.Interfaces)] TRequest, TResponse>(this T apiProvider, TRequest request, TResponse defaultValue, IReadOnlyMetadataContext? metadata, CancellationToken cancellationToken) where T : class, IApiProvider<T> where TRequest : IApiRequestBase<T, TRequest, ValueTask<TResponse?>> where TResponse : struct
		{
			ValueTask<TResponse?> valueTask = apiProvider.TryInvoke<T, TRequest, ValueTask<TResponse?>>(request, metadata, cancellationToken);
