			return valueTask.AsTask().ContinueWith((Task<TResponse?> t, object? s) => t.Result ?? ((TResponse)s), BoxingExtensions.Box(defaultValue), cancellationToken, TaskContinuationOptions.ExecuteSynchronously, TaskScheduler.Current).AsValueTask();
		}

