		public static int GetCapacity(int oldCapacity, int requestedSize, bool pooled)
		{
			int num = (pooled ? (oldCapacity * 2) : ((oldCapacity <= 256) ? (oldCapacity * 2) : (oldCapacity + (oldCapacity >> 1))));
			if (oldCapacity + requestedSize > num)
			{
				num = oldCapacity + requestedSize;
			}
			if (num < 4)
			{
				return 4;
			}
			if ((uint)num <= 2146435071u)
			{
				return num;
			}
			return 2146435071;
		}

