		public static ItemOrArray<T> ToItemOrArray<T>(this IList<T>? list)
		{
			if (list == null || list.Count == 0)
			{
				return default(ItemOrArray<T>);
			}
			if (list.Count == 1)
			{
				return new ItemOrArray<T>(list[0]);
			}
			if (list is T[] array)
			{
				return array;
			}
			return new ItemOrArray<T>(default(T), list.ToArray());
		}

