				return default(ItemOrArray<T>);
			}
			if (list.Count == 1)
			{
				return new ItemOrArray<T>(list.ElementAt(0));
			}
			if (list is T[] array)
			{
				return array;
			}
			return new ItemOrArray<T>(default(T), list.ToArray());
		}

