		{
			Should.NotBeNull(list, "list");
			if (list is IObservableList<T> observableList)
			{
				observableList.Move(oldIndex, newIndex);
				return;
			}
			if (list is List<T> list2)
			{
				list2.Move(oldIndex, newIndex);
