		public static void Move<T>(this Span<T> span, int oldIndex, int newIndex)
		{
			if (oldIndex != newIndex)
			{
				T val = span[oldIndex];
				if (newIndex < oldIndex)
				{
					span.Copy(newIndex, newIndex + 1, oldIndex - newIndex);
				}
				else
				{
					span.Copy(oldIndex + 1, oldIndex, newIndex - oldIndex);
				}
				span[newIndex] = val;
			}
		}

