		public static TResult[] ToArray<T, TResult>(this ReadOnlySpan<T> span, Func<T, TResult> selector)
		{
			if (span.Length == 0)
			{
				return Array.Empty<TResult>();
			}
			TResult[] array = new TResult[span.Length];
			for (int i = 0; i < span.Length; i++)
			{
				array[i] = selector(span[i]);
			}
			return array;
