		public static PooledArrayStorage<T> Rent<T>(int size, bool suppressEmpty = false)
		{
			if (size == 0 && !suppressEmpty)
			{
				return PooledArrayStorage<T>.Empty;
			}
			PooledArrayStorage<T> pooledArrayStorage = PooledArrayStorage<T>.Allocate();
			pooledArrayStorage.Version = Default.NextCounter();
			pooledArrayStorage.Array = RentRaw<T>(size);
			return pooledArrayStorage;
		}

