		internal static ReadOnlySpan<char> ToDictionaryKey(this ref ValueSpanBuilder<char> spanBuilder)
		{
			if (spanBuilder.Length < 10)
			{
				return spanBuilder.Span;
			}
			Span<char> span = spanBuilder.Span;
			Span<byte> span2 = stackalloc byte[span.Length * 2];
			for (int i = 0; i < span.Length; i++)
			{
				char c = span[i];
				span2[i * 2] = (byte)c;
				span2[i * 2 + 1] = (byte)((int)c >> 8);
			}
			Span<byte> destination = stackalloc byte[32];
			SHA256.HashData(span2, destination);
			spanBuilder.Clear();
			spanBuilder.Append('~');
			for (int j = 0; j < 8; j++)
			{
				spanBuilder.Append((char)(destination[j * 2] | (destination[j * 2 + 1] << 8)));
			}
			return spanBuilder.Span;
		}

		internal static void AppendCompact(this ref ValueSpanBuilder<char> spanBuilder, int value)
		{
			if ((uint)value <= 65535u)
			{
				spanBuilder.Append((char)value);
				return;
			}
			spanBuilder.Append((char)(value & 0xFFFF));
			spanBuilder.Append((char)((uint)value >> 16));
		}

		internal static void AddRaw<T>(ref object? source, T value) where T : class
		{
			if (source == null)
			{
				source = value;
				return;
			}
			T[] array = source as T[];
			if (array != null)
			{
				Array.Resize(ref array, array.Length + 1);
				array[^1] = value;
				source = array;
			}
			else
			{
				source = new T[2]
				{
					(T)source,
					value
				};
			}
		}

		internal static bool RemoveRaw<T>(ref object? source, T value) where T : class
		{
			if (source == null)
			{
				return false;
			}
			if (source == value)
			{
				source = null;
				return true;
			}
			T[] items = source as T[];
			if (items == null)
			{
				return false;
			}
			if (items.Length == 1)
			{
				if (items[0] == value)
				{
					source = null;
					return true;
				}
				return false;
			}
			if (items.Length == 2)
			{
				if (items[0] == value)
				{
					source = items[1];
					return true;
				}
				if (items[1] == value)
				{
					source = items[0];
					return true;
				}
				return false;
			}
			if (Remove(ref items, value))
			{
				source = items;
				return true;
			}
			return false;
		}

