		internal static void FindAllIndexOf(this IEnumerable items, object? item, bool ignoreDuplicates, ref ValueSpanBuilder<int> indexes, IReadOnlyMetadataContext? metadata)
		{
			if (items is ISupportFindAllIndexes supportFindAllIndexes)
			{
				supportFindAllIndexes.FindAllIndexOf(item, ignoreDuplicates, ref indexes, metadata);
				return;
			}
			if (items is IHasReadOnlySpan<object> hasReadOnlySpan)
			{
				hasReadOnlySpan.ReadOnlySpan.FindAllIndexOf(item, ignoreDuplicates, ref indexes);
				return;
			}
			if (ignoreDuplicates && items is IList<object> list)
			{
				int num = list.IndexOf(item);
				if (num >= 0)
				{
					indexes.Append(num);
				}
				return;
			}
			int num2 = 0;
			foreach (object item2 in items)
			{
				if (object.Equals(item, item2))
				{
					indexes.Append(num2);
					if (ignoreDuplicates)
					{
						break;
					}
				}
				num2++;
			}
		}

