		internal static AvlNode<T> AvlNodeFromList<T>(IReadOnlyList<T> items, int start, int length)
		{
			Should.NotBeNull(items, "items");
			Should.BeValid(start >= 0, "start");
			Should.BeValid(length >= 0, "length");
			if (length == 0)
			{
				return AvlNode<T>.EmptyNode;
			}
			int num = (length - 1) / 2;
			int num2 = length - 1 - num;
			AvlNode<T> left = AvlNodeFromList(items, start, num2);
			AvlNode<T> right = AvlNodeFromList(items, start + num2 + 1, num);
			return AvlNodePool.Rent(items[start + num2], left, right);
		}

		internal static AvlNode<T> AvlNodeFromList<T>(ReadOnlySpan<T> items)
		{
			if (items.IsEmpty)
			{
				return AvlNode<T>.EmptyNode;
			}
			int num = (items.Length - 1) / 2;
			int num2 = items.Length - 1 - num;
			AvlNode<T> left = AvlNodeFromList(items.Slice(0, num2));
			AvlNode<T> right = AvlNodeFromList(items.Slice(num2 + 1));
			return AvlNodePool.Rent(items[num2], left, right);
		}

