		internal static AvlNode<T> AddOrdered<T>(this AvlNode<T> node, T item, Comparison<T>? comparison, out int index, out AvlNode<T> newNode, int? binaryIndex = null)
		{
			index = binaryIndex ?? node.BinarySearch(0, node.Count, item, comparison);
			if (index < 0)
			{
				index = ~index;
			}
			return node.Insert(index, item, out newNode);
		}

		internal static int BinarySearch<T>(this AvlNode<T> node, int index, int count, T item, Comparison<T>? comparison)
		{
			Should.BeValid(index >= 0, "index");
			Should.BeValid(count >= 0, "count");
			Comparer<T> comparer = Comparer<T>.Default;
			if (node.IsEmpty || count <= 0)
			{
				return ~index;
			}
			int count2 = node.Left.Count;
			if (index + count <= count2)
			{
				return node.Left.BinarySearch(index, count, item, comparison);
			}
			if (index > count2)
			{
				int num = node.Right.BinarySearch(index - count2 - 1, count, item, comparison);
				int num2 = count2 + 1;
				if (num >= 0)
				{
					return num + num2;
				}
				return num - num2;
			}
			int num3 = comparison?.Invoke(item, node.Value) ?? comparer.Compare(item, node.Value);
			if (num3 == 0)
			{
				return count2;
			}
			if (num3 > 0)
			{
				int num4 = count - (count2 - index) - 1;
				int num5 = ((num4 < 0) ? (-1) : node.Right.BinarySearch(0, num4, item, comparison));
				int num6 = count2 + 1;
				if (num5 >= 0)
				{
					return num5 + num6;
				}
				return num5 - num6;
			}
			if (index == count2)
			{
				return ~index;
			}
			return node.Left.BinarySearch(index, count, item, comparison);
		}

		internal static int BinarySearch<T>(this AvlNode<T> node, int index, int count, int value, Func<T, int> getItemValue)
		{
			Should.BeValid(index >= 0, "index");
			Should.BeValid(count >= 0, "count");
			if (node.IsEmpty || count <= 0)
			{
				return ~index;
			}
			int count2 = node.Left.Count;
			if (index + count <= count2)
			{
				return node.Left.BinarySearch(index, count, value, getItemValue);
			}
			if (index > count2)
			{
				int num = node.Right.BinarySearch(index - count2 - 1, count, value, getItemValue);
				int num2 = count2 + 1;
				if (num >= 0)
				{
					return num + num2;
				}
				return num - num2;
			}
			int num3 = value.CompareTo(getItemValue(node.Value));
			if (num3 == 0)
			{
				return count2;
			}
			if (num3 > 0)
			{
				int num4 = count - (count2 - index) - 1;
				int num5 = ((num4 < 0) ? (-1) : node.Right.BinarySearch(0, num4, value, getItemValue));
				int num6 = count2 + 1;
				if (num5 >= 0)
				{
					return num5 + num6;
				}
				return num5 - num6;
			}
			if (index == count2)
			{
				return ~index;
			}
			return node.Left.BinarySearch(index, count, value, getItemValue);
		}

		internal static void CopyTo<T>(this AvlNode<T> node, T[] array, int arrayIndex)
		{
			Should.NotBeNull(array, "array");
			Should.BeValid(arrayIndex >= 0, "arrayIndex");
			Should.BeValid(array.Length >= arrayIndex + node.Count, "arrayIndex");
			using AvlNodeValueEnumerator<T> avlNodeValueEnumerator = node.GetEnumerator();
			while (avlNodeValueEnumerator.MoveNext())
			{
				T current = avlNodeValueEnumerator.Current;
				array[arrayIndex++] = current;
			}
		}

