			return ContainsImpl(node, item, equalityComparer);
		}

		internal static AvlNode<T> Reset<T>(this AvlNode<T> node, IEnumerable<T>? enumerable)
		{
			int? num = enumerable.TryGetCount();
			if (num == 0)
			{
				return node.Clear();
			}
			node.BeginBatchUpdate(num);
			try
			{
				return node.Clear().AddRange(enumerable);
			}
			finally
			{
				node.EndBatchUpdate();
			}
		}

		internal static int GetIndex<T>(this AvlNode<T> node)
		{
			if (node.IsEmpty)
			{
				return -1;
			}
			int num = node.Left.Count;
			AvlNode<T> avlNode = node;
			while (avlNode.Parent != null)
			{
				if (avlNode == avlNode.Parent.Right)
				{
					num += avlNode.Parent.Left.Count + 1;
				}
				avlNode = avlNode.Parent;
			}
			return num;
		}

		public static int NodeSum<T>(this IndexMapTree<T> tree, int originalIndex)
		{
			int item = tree.Locate(originalIndex).rankBefore;
			return SumFirstK(tree, item) - item;
		}

		private static int SumFirstK<T>(IndexMapTree<T> tree, int k)
		{
			int num = 0;
			IndexMapTreeNode<T> indexMapTreeNode = tree.Root;
			while (indexMapTreeNode != null && k > 0)
			{
				int num2 = indexMapTreeNode.L?.Size ?? 0;
				int num3 = indexMapTreeNode.L?.Sum ?? 0;
				if (k <= num2)
				{
					indexMapTreeNode = indexMapTreeNode.L;
					continue;
				}
				num += num3 + indexMapTreeNode.ItemSize;
				k -= num2 + 1;
				indexMapTreeNode = indexMapTreeNode.R;
			}
			return num;
		}

		private static AvlNode<T> MutateKey<T>(this AvlNode<T> node, T key)
		{
			if (node.IsEmpty)
			{
				return AvlNodePool.Rent(key, node.Left, node.Right);
			}
			node.Value = key;
			return node;
		}

		private static AvlNode<T> AvlNodeCreateRange<T>(IEnumerable<T> keys)
		{
			if (keys is IReadOnlyList<T> readOnlyList)
			{
				return AvlNodeFromList(readOnlyList, 0, readOnlyList.Count);
			}
			using PooledArray<T> pooledArray = keys.ToPooledArray();
			return AvlNodeFromList(pooledArray.ReadOnlySpan);
		}

		private static void FindAllIndexOf(this ReadOnlySpan<object> items, object? item, bool ignoreDuplicates, ref ValueSpanBuilder<int> indexes)
		{
			for (int i = 0; i < items.Length; i++)
			{
				if (object.Equals(item, items[i]))
				{
					indexes.Append(i);
					if (ignoreDuplicates)
					{
						break;
					}
				}
			}
		}

		private static bool ContainsImpl<T>(AvlNode<T> node, T value, IEqualityComparer<T> equalityComparer)
		{
			if (!node.IsEmpty)
			{
				if (!equalityComparer.Equals(value, node.Value) && !node.Left.Contains(value, equalityComparer))
				{
					return node.Right.Contains(value, equalityComparer);
				}
				return true;
			}
			return false;
		}

		private static T[] RentInternal<T>(int size)
		{
			T[] array = ArrayPool<T>.Shared.Rent(size);
			MugenService.ArrayPoolTracer?.OnRented(array);
			return array;
		}

