		public static T GetOrAddComponent<T, TState>(this IComponentOwner owner, TState state, Func<TState, IReadOnlyMetadataContext?, T> getComponent, IReadOnlyMetadataContext? metadata = null) where T : class, IComponent
		{
			Should.NotBeNull(owner, "owner");
			Should.NotBeNull(getComponent, "getComponent");
			T val = owner.TryGetComponent<T>(metadata);
			if (val != null)
			{
				return val;
			}
			ComponentCollection components = owner.Components;
			using (components.Lock())
			{
				ItemOrArray<T> components2 = owner.GetComponents<T>(metadata);
				if (components2.Count != 0)
				{
					return components2[0];
				}
				T val2 = getComponent(state, metadata);
				if (!components.TryAdd(val2, metadata))
				{
					ExceptionManager.ThrowCannotAddComponent(owner.Components, typeof(T));
				}
				return val2;
			}
		}

