		public static ItemOrArray<T> GetComponents<T>(ref PooledItemOrList<object> components, T decoratorComponent) where T : class
		{
			Should.NotBeNull(decoratorComponent, "decoratorComponent");
			int num = components.ReadOnlySpan.IndexOfComponent(decoratorComponent);
			if (num < 0)
			{
				return default(ItemOrArray<T>);
			}
			num++;
			switch (components.Count - num)
			{
			case 0:
				return default(ItemOrArray<T>);
			case 1:
			{
				object obj = components[num];
				components.RemoveAt(num);
				return (T)obj;
			}
			default:
			{
				ItemOrArray<T> result = components.ReadOnlySpan.Slice(num).ToItemOrArray<T>();
				components.RemoveRange(num, components.Count - num);
				return result;
			}
			}
		}

		public static ItemOrArray<T> GetComponents<T>(ref PooledItemOrList<object> components, T decoratorComponent, IReadOnlyMetadataContext? metadata, Func<T, IReadOnlyMetadataContext?, bool> filter) where T : class
		{
			Should.NotBeNull(decoratorComponent, "decoratorComponent");
			int num = components.ReadOnlySpan.IndexOfComponent(decoratorComponent);
			if (num < 0)
			{
				return default(ItemOrArray<T>);
			}
			num++;
			int num2 = components.Count - num;
			if (num2 == 0)
			{
				return default(ItemOrArray<T>);
			}
			using PooledItemOrList<object> items = new PooledItemOrList<object>(num2);
			for (int i = num; i < components.Count; i++)
			{
				object obj = components[i];
				if (filter((T)obj, metadata))
				{
					items.Add((T)obj);
					components.RemoveAt(i);
					i--;
				}
			}
			return items.ToItemOrArray<T>();
		}

