		{
			if (component is IHasPriorityComponent hasPriorityComponent)
			{
				int? num = hasPriorityComponent.TryGetPriority(owner, metadata);
				if (num.HasValue)
				{
					return num.Value;
				}
			}
			if (component is IHasPriority hasPriority)
			{
				return hasPriority.Priority;
			}
			return 0;
		}

		private static int IndexOfComponent<T>(this ReadOnlySpan<T> components, T component) where T : class
		{
			for (int i = 0; i < components.Length; i++)
			{
				if (Unwrap(components[i]) == component || components[i] == component)
				{
					return i;
				}
			}
			return -1;
		}

