		public static TTo Convert<TFrom, TTo>(TFrom? value)
		{
			if (TryConvert<TFrom, TTo>(value, out var result))
			{
				return result;
			}
			ExceptionManager.ThrowCannotConvert(typeof(TFrom), typeof(TTo), value?.ToString());
			return default(TTo);
		}

		public static bool TryConvert<TFrom, TTo>(TFrom? value, [MaybeNullWhen(false)] out TTo result)
		{
			if (value == null)
			{
				result = default(TTo);
				return true;
			}
			if (typeof(TTo) == typeof(Unit))
			{
				result = default(TTo);
				return true;
			}
			if (value is TTo)
			{
				result = ((typeof(TFrom).IsValueType && !typeof(TTo).IsValueType) ? ((TTo)BoxingExtensions.Box(value)) : ((TTo)(object)value));
				return true;
			}
			if (value is IConvertible<TFrom> && ((IConvertible<TFrom>)(object)value).TryConvertTo<TTo>(value, out result))
			{
				return true;
			}
			if (typeof(TTo).IsValueType && typeof(IConvertible<TTo>).IsAssignableFrom(typeof(TTo)) && ((IConvertible<TTo>)(object)default(TTo)).TryConvertFrom(value, out result))
			{
				return true;
			}
			if ((typeof(TFrom).IsValueType || typeof(TTo) != typeof(object)) && value is IInner<TTo>)
			{
				result = ((IInner<TTo>)(object)value).Inner;
				return true;
			}
			TypeConverterBase<TFrom, TTo> typeConverterBase = TypeConverterBase<TFrom, TTo>.Default;
			if ((typeConverterBase != null && typeConverterBase.TryConvert(value, out result)) || TryConvertSlow<TFrom, TTo>(value, out result))
			{
				return true;
			}
			return false;
		}

