		{
			Should.NotBeNull(converter, "converter");
			TypeConverterBase<TFrom, TTo>.Default = new DelegateTypeConverter<TFrom, TTo>(converter);
		}

		private static bool TryConvertSlow<TFrom, TTo>([DisallowNull] TFrom value, [MaybeNullWhen(false)] out TTo result)
		{
			if (!typeof(TFrom).IsValueType && !typeof(TTo).IsValueType && value is IInner<object> target)
			{
				result = TryUnwrap<object, TTo>((object?)target);
				if (result != null)
				{
					return true;
				}
			}
			if (typeof(TTo) == typeof(string))
			{
				result = (TTo)(object)value.ToString();
				return true;
			}
			if (typeof(TFrom) == typeof(object) && typeof(TTo).IsValueType && typeof(IConvertible).IsAssignableFrom(typeof(TTo)) && value is IConvertible value2)
			{
				return TryConvertSlowValueType<TTo>(value2, out result);
			}
			if (typeof(TTo) == typeof(bool))
			{
				if (!typeof(TFrom).IsValueType)
				{
					result = (TTo)(object)true;
					return true;
				}
				if (typeof(IHasInitializedState).IsAssignableFrom(typeof(TFrom)))
				{
					result = (TTo)(object)((IHasInitializedState)(object)value).IsInitialized;
					return true;
				}
				if (typeof(IEquatable<TFrom>).IsAssignableFrom(typeof(TFrom)))
				{
					result = (TTo)(object)(!((IEquatable<TFrom>)(object)value).Equals(default(TFrom)));
					return true;
				}
			}
			result = default(TTo);
			return false;
		}

		private static bool TryConvertSlowValueType<TTo>(IConvertible value, [MaybeNullWhen(false)] out TTo result)
		{
			switch (value.GetTypeCode())
			{
			case TypeCode.Boolean:
				return TryConvert<bool, TTo>((bool)(object)value, out result);
			case TypeCode.Char:
				return TryConvert<char, TTo>((char)(object)value, out result);
			case TypeCode.SByte:
				return TryConvert<sbyte, TTo>((sbyte)(object)value, out result);
			case TypeCode.Byte:
				return TryConvert<byte, TTo>((byte)(object)value, out result);
			case TypeCode.Int16:
				return TryConvert<short, TTo>((short)(object)value, out result);
			case TypeCode.UInt16:
				return TryConvert<ushort, TTo>((ushort)(object)value, out result);
			case TypeCode.Int32:
				return TryConvert<int, TTo>((int)(object)value, out result);
			case TypeCode.UInt32:
				return TryConvert<uint, TTo>((uint)(object)value, out result);
			case TypeCode.Int64:
				return TryConvert<long, TTo>((long)(object)value, out result);
			case TypeCode.UInt64:
				return TryConvert<ulong, TTo>((ulong)(object)value, out result);
			case TypeCode.Single:
				return TryConvert<float, TTo>((float)(object)value, out result);
			case TypeCode.Double:
				return TryConvert<double, TTo>((double)(object)value, out result);
			case TypeCode.Decimal:
				return TryConvert<decimal, TTo>((decimal)(object)value, out result);
			case TypeCode.DateTime:
				return TryConvert<DateTime, TTo>((DateTime)(object)value, out result);
			case TypeCode.String:
				return TryConvert<string, TTo>((string)value, out result);
			default:
				if (typeof(TTo) == typeof(bool))
				{
					result = (TTo)(object)true;
					return true;
				}
				result = default(TTo);
				return false;
			}
		}

		[MethodImpl(MethodImplOptions.AggressiveInlining)]
