		private static PooledReadOnlyList<T> GetFlags<[DynamicallyAccessedMembers(DynamicallyAccessedMemberTypes.PublicConstructors | DynamicallyAccessedMemberTypes.PublicFields | DynamicallyAccessedMemberTypes.Interfaces)] T, TValue>(this EnumFlags<T> flags) where T : FlagsEnumBase<T, TValue> where TValue : IComparable<TValue>, IEquatable<TValue>
		{
			PooledItemOrList<T> pooledItemOrList = default(PooledItemOrList<T>);
			T[] all = EnumBase<T, TValue>.GetAll();
			foreach (T val in all)
			{
				if (flags.HasFlag(val.Flag))
				{
					pooledItemOrList.Add(val);
				}
			}
			return pooledItemOrList;
		}

