		[return: NotNullIfNotNull("metadata")]
		[return: NotNullIfNotNull("metadataValue")]
		public static IReadOnlyMetadataContext? Merge(this IReadOnlyMetadataContext? metadata, IReadOnlyMetadataContext? metadataValue)
		{
			if (metadata.IsNullOrEmpty())
			{
				return metadataValue;
