		public static string Dump(this IReadOnlyMetadataContext? metadata, string nullResult = "null")
		{
			if (metadata == null)
			{
				return nullResult;
			}
			Span<char> initialBuffer = stackalloc char[256];
			ValueSpanBuilder<char> valueSpanBuilder = new ValueSpanBuilder<char>(initialBuffer);
			try
			{
				valueSpanBuilder.Append('(');
				foreach (KeyValuePair<IMetadataContextKey, object> item in metadata.GetValues().GetDisposableEnumerator())
				{
					valueSpanBuilder.Append(item.Key.ToString());
					valueSpanBuilder.Append('=');
					valueSpanBuilder.Append(item.Value?.ToString());
					valueSpanBuilder.Append(';');
				}
				if (valueSpanBuilder.Length != 0)
				{
					valueSpanBuilder.SetLength(valueSpanBuilder.Length - 1);
				}
				valueSpanBuilder.Append(')');
				return valueSpanBuilder.ToString();
			}
			finally
			{
				valueSpanBuilder.Dispose();
			}
		}

		public static void ClearMetadata<T>(this IMetadataOwner<T> metadataOwner, bool clearComponents = false) where T : class, IMetadataContext
		{
			Should.NotBeNull(metadataOwner, "metadataOwner");
			if (metadataOwner is ILazyMetadataOwner<T> lazyMetadataOwner)
			{
				lazyMetadataOwner.MetadataOptional?.Clear();
			}
			else
			{
				metadataOwner.Metadata.Clear();
			}
			if (clearComponents && metadataOwner.Metadata is ICompositeMetadataContext compositeMetadataContext)
			{
				compositeMetadataContext.ClearComponents();
			}
		}

		public static bool MetadataEquals(this IReadOnlyMetadataContext? metadata, IReadOnlyMetadataContext? otherMetadata)
		{
			if (metadata == otherMetadata)
			{
				return true;
			}
			if (metadata == null)
			{
				return false;
			}
			if (otherMetadata == null)
			{
				return false;
			}
			if (metadata.Count != otherMetadata.Count)
			{
				return false;
			}
			foreach (KeyValuePair<IMetadataContextKey, object> item in metadata.GetValues().GetDisposableEnumerator())
			{
				if (!otherMetadata.TryGetRaw(item.Key, out object value) || !object.Equals(value, item.Value))
				{
					return false;
				}
			}
			return true;
		}

		public static IMetadataContext AttachedMetadata<T>(this T item, IReadOnlyMetadataContext? metadata = null) where T : class
		{
			if (item is IMetadataOwner<IMetadataContext> metadataOwner)
			{
				return metadataOwner.Metadata;
			}
			AttachedValueStorage attachedValueStorage = item.AttachedValues(metadata).BatchUpdate();
			try
			{
				if (!attachedValueStorage.TryGet((ReadOnlySpan<char>)"`m", out MetadataContext value))
				{
					value = new MetadataContext();
					attachedValueStorage.Set("`m", value);
				}
				return value;
			}
			finally
			{
				((IDisposable)attachedValueStorage/*cast due to .constrained prefix*/).Dispose();
			}
		}

		internal static SortedListSlim<IMetadataContextKey, object?> ToSortedList(this IReadOnlyMetadataContext? metadata)
		{
			if (metadata == null)
			{
				return default(SortedListSlim<IMetadataContextKey, object>);
			}
			int count = metadata.Count;
			if (count == 0)
			{
				return default(SortedListSlim<IMetadataContextKey, object>);
			}
			SortedListSlim<IMetadataContextKey, object> result = new SortedListSlim<IMetadataContextKey, object>(count);
			foreach (KeyValuePair<IMetadataContextKey, object> item in metadata.GetValues().GetDisposableEnumerator())
			{
				result.AddOrUpdate(item.Key, item.Value);
			}
			return result;
		}

