		public static void CloseOnParentClose(this IView view, object parent, IReadOnlyMetadataContext? metadata)
		{
			Should.NotBeNull(view, "view");
			Should.NotBeNull(parent, "parent");
			if (view.IsInState((FlagsEnumBase<ViewLifecycleState, long>?)ViewLifecycleState.Closed))
			{
				return;
			}
			IViewManager instance = IMugenService<IViewManager>.Instance;
			if (instance.IsInState(parent, (FlagsEnumBase<ViewLifecycleState, long>?)ViewLifecycleState.Closed))
			{
				instance.OnLifecycleChanged(view, ViewLifecycleState.Closed, null, metadata);
				return;
			}
			AutoCloseViewListener component = new AutoCloseViewListener(view, parent);
			instance.AddComponent(component, metadata);
			if (view.IsInState((FlagsEnumBase<ViewLifecycleState, long>?)ViewLifecycleState.Closed))
			{
				instance.RemoveComponent(component);
			}
			else if (instance.IsInState(parent, (FlagsEnumBase<ViewLifecycleState, long>?)ViewLifecycleState.Closed))
			{
				instance.RemoveComponent(component);
				instance.OnLifecycleChanged(view, ViewLifecycleState.Closed, null, metadata);
			}
		}

