		public static Task WaitStateAsync<T, TState, TTarget>(this IHasLifecycleApi<T, TState, TTarget> apiProvider, TTarget target, EnumFlags<TState> state, IReadOnlyMetadataContext? metadata = null, CancellationToken cancellationToken = default(CancellationToken)) where T : class, IHasLifecycleApi<T, TState, TTarget> where TState : class, IEnum<TState>, IFlagsEnum
		{
			if (apiProvider.IsInState(target, state, metadata))
			{
				return Task.CompletedTask;
			}
			StateWatcher<T, TState, TTarget> stateWatcher = new StateWatcher<T, TState, TTarget>(state, cancellationToken);
			apiProvider.AddComponent(stateWatcher);
			if (apiProvider.IsInState(target, state, metadata))
			{
				apiProvider.RemoveComponent(stateWatcher);
				return Task.CompletedTask;
			}
			return stateWatcher.Task;
		}

