		public static ActionToken SynchronizeLockerWith<T>(this T source, T target, IReadOnlyMetadataContext? metadata = null) where T : class, IApiProvider<T>, ISynchronizable
		{
			Should.NotBeNull(source, "source");
			Should.NotBeNull(target, "target");
			if (source == target)
			{
				return default(ActionToken);
			}
			while (true)
			{
				using ActionToken actionToken = source.TryLock(10, metadata);
				if (!actionToken.IsInitialized)
				{
					continue;
				}
				using ActionToken actionToken2 = target.TryLock(10, metadata);
				if (!actionToken2.IsInitialized)
				{
					continue;
				}
				ReadOnlySpan<LockerSynchronizer<T>> readOnlySpan = source.Components.Components.Get<T, LockerSynchronizer<T>>().ReadOnlySpan;
				for (int i = 0; i < readOnlySpan.Length; i++)
				{
					LockerSynchronizer<T> lockerSynchronizer = readOnlySpan[i];
					if (lockerSynchronizer.IsSynchronized(source, target))
					{
						return lockerSynchronizer.GetUnsubscriber();
					}
				}
				LockerSynchronizer<T> lockerSynchronizer2 = new LockerSynchronizer<T>(source, target, metadata);
				source.Components.Add(lockerSynchronizer2, metadata);
				target.Components.Add(lockerSynchronizer2, metadata);
				return lockerSynchronizer2.GetUnsubscriber();
			}
		}

