		public static bool IsWrappedAs<TInner, T>(object? target) where TInner : class? where T : class?
		{
			while (target != null)
			{
				if (target is T)
				{
					return true;
				}
				if (!TryStepNext<TInner>(ref target))
				{
					return false;
				}
			}
			return false;
		}

		public static T? TryUnwrap<TInner, T>(object? target) where TInner : class?
		{
