				obj = dataContextWrapper.DataContext;
			}
			return obj;
		}

		public static T? TryUnwrapDataContext<T>(object? dataContext) where T : class
		{
			object obj = dataContext;
			while (true)
			{
				if (obj is T result)
				{
					return result;
				}
				if (!(obj is IDataContextWrapper dataContextWrapper) || obj == dataContextWrapper.DataContext)
				{
					break;
				}
				obj = dataContextWrapper.DataContext;
			}
			return null;
		}

