		public static void Flatten(this Exception? exception, bool includeStackTrace, ref ValueSpanBuilder<char> sb)
		{
			if (exception == null)
			{
				return;
			}
			if (exception is AggregateException ex)
			{
				sb.AppendLine(ex.Message);
				if (includeStackTrace)
				{
					sb.Append(exception.StackTrace);
					sb.AppendLine();
				}
				for (int i = 0; i < ex.InnerExceptions.Count; i++)
				{
					ex.InnerExceptions[i].Flatten(includeStackTrace, ref sb);
				}
				return;
			}
			while (exception != null)
			{
				sb.AppendLine(exception.Message);
				if (includeStackTrace)
				{
					sb.Append(exception.StackTrace);
				}
				if (exception is ReflectionTypeLoadException ex2)
				{
					if (includeStackTrace)
					{
						sb.AppendLine();
					}
					Exception[] loaderExceptions = ex2.LoaderExceptions;
					for (int j = 0; j < loaderExceptions.Length; j++)
					{
						loaderExceptions[j].Flatten(includeStackTrace, ref sb);
					}
				}
				exception = exception.InnerException;
				if (exception != null && includeStackTrace)
				{
					sb.AppendLine();
				}
			}
		}

		public static string Flatten(this Exception exception, bool includeStackTrace = false)
		{
			return exception.Flatten(null, includeStackTrace);
		}

		public static string Flatten(this Exception exception, string? message, bool includeStackTrace = false)
		{
			Should.NotBeNull(exception, "exception");
			Span<char> initialBuffer = stackalloc char[256];
			ValueSpanBuilder<char> spanBuilder = new ValueSpanBuilder<char>(initialBuffer);
			try
			{
				if (message != null)
				{
					spanBuilder.AppendLine(message);
				}
				exception.Flatten(includeStackTrace, ref spanBuilder);
				return spanBuilder.ToString();
			}
			finally
			{
				spanBuilder.Dispose();
			}
		}

		public static T? TryGetException<T>(this Exception? exception) where T : class
		{
			if (exception == null)
			{
				return null;
			}
			if (exception is T result)
			{
				return result;
			}
			T val = exception.InnerException.TryGetException<T>();
			if (val != null)
			{
				return val;
			}
			if (exception is AggregateException ex)
			{
				ReadOnlyCollection<Exception> innerExceptions = ex.InnerExceptions;
				for (int i = 0; i < innerExceptions.Count; i++)
				{
					val = innerExceptions[i].TryGetException<T>();
					if (val != null)
					{
						return val;
					}
				}
			}
			return null;
		}

