		internal static void EnsureComponentsInitialized(IComponentAwareOwner target, [NotNull] ref ComponentCollection? item, ref bool initialized, IReadOnlyMetadataContext? metadata = null)
		{
			lock (target)
			{
				if (item == null)
				{
					item = new ComponentCollection(target);
					if (!(target is IMugenApplication) && (!(target is ComponentCollection componentCollection) || !(componentCollection.Owner is IMugenApplication)))
					{
						IMugenService<IMugenApplication>.Instance.TryInvoke<IMugenApplication, OnComponentCollectionInitialized, Unit>(new OnComponentCollectionInitialized(item), metadata);
					}
					initialized = true;
				}
			}
		}

