		internal static bool TryLock(object? target, int timeout, IReadOnlyMetadataContext? metadata, [MustDisposeResource] out ActionToken lockToken)
		{
			ISynchronizable synchronizable = target as ISynchronizable;
			if ((synchronizable != null && !(synchronizable is IHasDisposedState { IsDisposed: not false })) ? true : false)
			{
				return synchronizable.TryLock(timeout, metadata, out lockToken);
			}
			lockToken = default(ActionToken);
			return true;
		}

