		internal static T GetOrAdd<T>(IApiProvider apiProvider) where T : class, new()
		{
			SortedList<string, object> orCreateValue = DebugItems.GetOrCreateValue(apiProvider);
			lock (orCreateValue)
			{
				if (!orCreateValue.TryGetValue(typeof(T).Name, out var value))
				{
					value = new T();
					orCreateValue.Add(typeof(T).Name, value);
				}
				return (T)value;
			}
		}

		internal static T? TryGet<T>(IApiProvider apiProvider) where T : class, new()
		{
			SortedList<string, object> orCreateValue = DebugItems.GetOrCreateValue(apiProvider);
			lock (orCreateValue)
			{
				if (orCreateValue.TryGetValue(typeof(T).Name, out var value))
				{
					return (T)value;
				}
				return null;
			}
		}

		internal static bool TryStepNext<T>([NotNullWhen(true)] ref object? current) where T : class?
		{
			if (current is IDecorator<T> { Next: not null } decorator && current != decorator.Next)
			{
				current = decorator.Next;
				return true;
			}
			if (current is IInner<T> inner && current != inner.Inner)
			{
				current = inner.Inner;
				return current != null;
			}
			return false;
		}

		public static bool OnNavigationFailedOrCancelled(this INavigationDispatcher dispatcher, INavigationContext navigationContext, Exception exception, IReadOnlyMetadataContext? metadata = null)
		{
			Should.NotBeNull(dispatcher, "dispatcher");
			Should.NotBeNull(navigationContext, "navigationContext");
			Should.NotBeNull(exception, "exception");
			exception = exception.TryGetBaseException(out OperationCanceledException canceledException);
			if (canceledException == null)
			{
				dispatcher.OnNavigationFailed(navigationContext, exception, metadata);
				return true;
			}
			dispatcher.OnNavigationCanceled(navigationContext, canceledException.CancellationToken, metadata);
			return false;
		}

		public static Task ClearBackStackAsync(this INavigationDispatcher dispatcher, NavigationType navigationType, object navigationTarget, bool includePending = false, IReadOnlyMetadataContext? metadata = null, CancellationToken cancellationToken = default(CancellationToken))
		{
			Should.NotBeNull(dispatcher, "dispatcher");
			Should.NotBeNull(navigationType, "navigationType");
			Should.NotBeNull(navigationTarget, "navigationTarget");
			IReadOnlyMetadataContext readOnlyMetadataContext = null;
			PooledItemOrList<Task> tasks = default(PooledItemOrList<Task>);
			foreach (INavigationEntry item in dispatcher.GetNavigationEntries(navigationType, metadata, cancellationToken).GetDisposableEnumerator())
			{
				if ((includePending || !item.IsPending) && item.Target != null && !object.Equals(item.Target, navigationTarget))
				{
					if (readOnlyMetadataContext == null)
					{
						readOnlyMetadataContext = new MetadataContext(metadata).Set(NavigationMetadata.SuppressNavigationCondition, value: true).Set(NavigationMetadata.NavigationType, navigationType);
					}
					using PooledReadOnlyList<NavigationResult> values = dispatcher.TryCloseViewModel(item.Target, null, readOnlyMetadataContext, cancellationToken);
					tasks.AddTask(values.WaitClosingAsync(metadata, cancellationToken));
				}
			}
			return tasks.WhenAll(throwOnCancel: false, throwOnDispose: false);
		}

