		public static async ValueTask<TResult?> NavigateAsync<TState, TResult>(this INavigationDispatcher dispatcher, object? target, INavigationProvider navigationProvider, string navigationId, NavigationType navigationType, bool onNavigatingAsync, TState state, Func<TState, CancellationToken, IReadOnlyMetadataContext?, ValueTask<TResult>> handler, TResult? defaultResult = default(TResult?), NavigationMode? navigationMode = null, IReadOnlyMetadataContext? metadata = null, CancellationToken cancellationToken = default(CancellationToken))
		{
			Should.NotBeNull(dispatcher, "dispatcher");
			Should.NotBeNull(handler, "handler");
			INavigationContext context = dispatcher.GetNavigationContext(target, navigationProvider, navigationId, navigationType, navigationMode ?? NavigationMode.New, metadata, cancellationToken);
			try
			{
				if (onNavigatingAsync)
				{
					if (!(await dispatcher.OnNavigatingAsync(context, metadata, cancellationToken).ConfigureAwait(continueOnCapturedContext: false)))
					{
						dispatcher.OnNavigationCanceled(context, CancellationToken.None, metadata);
						return defaultResult;
					}
				}
				else
				{
					dispatcher.OnNavigating(context, metadata);
				}
				ValueTask<TResult> valueTask = handler(state, cancellationToken, metadata);
				dispatcher.OnNavigated(context, metadata);
				TResult result = await valueTask.ConfigureAwait(continueOnCapturedContext: false);
				context = dispatcher.GetNavigationContext(target, navigationProvider, navigationId, navigationType, NavigationMode.Close, metadata, CancellationToken.None);
				dispatcher.OnNavigated(context, metadata);
				return result;
			}
			catch (Exception exception)
			{
				dispatcher.OnNavigationFailedOrCancelled(context, exception, metadata);
				return defaultResult;
			}
		}

