			return navigationDispatcher.TryGetTopNavigation<TView, (TState, Func<IView, TState, TView>, Func<INavigationEntry, TState, bool>)>((state, getView, entryPredicate), GetTopViewImpl, navigationType, metadata, cancellationToken);
		}

		public static TResult? TryGetTopNavigation<TResult, TState>(this INavigationDispatcher navigationDispatcher, TState state, Func<INavigationEntry, TState, IReadOnlyMetadataContext?, CancellationToken, TResult?> predicate, NavigationType? navigationType = null, IReadOnlyMetadataContext? metadata = null, CancellationToken cancellationToken = default(CancellationToken)) where TResult : class
		{
			Should.NotBeNull(navigationDispatcher, "navigationDispatcher");
			Should.NotBeNull(predicate, "predicate");
			foreach (INavigationEntry item in navigationDispatcher.GetNavigationEntries(navigationType, metadata, cancellationToken).GetDisposableEnumerator())
			{
				TResult val = predicate(item, state, metadata, cancellationToken);
				if (val != null)
				{
					return val;
				}
			}
			return null;
		}

		private static TView? GetTopViewImpl<TView, TState>(INavigationEntry entry, (TState?, Func<IView, TState, TView?>, Func<INavigationEntry, TState, bool>?) state, IReadOnlyMetadataContext? m, CancellationToken c) where TView : class
		{
			if (entry.Target == null || (state.Item3 != null && !state.Item3(entry, state.Item1)))
			{
				return null;
			}
			foreach (IView item in IMugenService<IViewManager>.Instance.GetViewsByViewModel(entry.Target, m, c).GetDisposableEnumerator())
			{
				TView val = state.Item2(item, state.Item1);
				if (val != null)
				{
					return val;
				}
			}
			return null;
		}

		[MustDisposeResource]
		public static ActionToken BatchUpdate(this IReadOnlyObservableCollection collection, IReadOnlyMetadataContext? metadata = null)
		{
			return ActionToken.BeginBatchUpdate(collection, metadata);
		}

		public static Task WaitBatchUpdateAsync(this IReadOnlyObservableCollection collection, bool raisePendingNotifications = true, IReadOnlyMetadataContext? metadata = null, CancellationToken cancellationToken = default(CancellationToken))
		{
			Should.NotBeNull(collection, "collection");
			if (collection.IsDisposed)
			{
				return Task.CompletedTask;
			}
			if (collection.IsInBatch(metadata, cancellationToken))
			{
				return new BatchUpdateAwaiter(collection, raisePendingNotifications, cancellationToken).Task;
			}
			if (raisePendingNotifications)
			{
				collection.RaisePendingNotifications(metadata);
			}
			return Task.CompletedTask;
		}

		public static void RaisePendingNotifications(this IReadOnlyObservableCollection collection, IReadOnlyMetadataContext? metadata = null)
		{
			Should.NotBeNull(collection, "collection");
			if (!collection.IsDisposed)
			{
				collection.TryInvoke<IReadOnlyObservableCollection, RaisePendingNotifications<IReadOnlyObservableCollection>, Unit>(RaisePendingNotifications<IReadOnlyObservableCollection>.Instance, metadata, CancellationToken.None);
			}
		}

