		public static void ApplyChangesTo<T>(this CollectionGroupChangedAction action, IList<T> items, IEnumerable<T> groupItems, T? item, object? args, bool checkDisposable = true)
		{
			switch (action)
			{
			case CollectionGroupChangedAction.GroupRemoved:
				if (!checkDisposable || !(items is IHasDisposedState { IsDisposed: not false }))
				{
					items.Clear();
				}
				break;
			case CollectionGroupChangedAction.ItemAdded:
				items.Add(item);
				break;
			case CollectionGroupChangedAction.ItemRemoved:
				items.Remove(item);
				break;
			case CollectionGroupChangedAction.Reset:
				items.Reset(groupItems);
				break;
			case CollectionGroupChangedAction.ItemChanged:
				(items as IReadOnlyObservableCollection)?.RaiseItemChanged(item, args);
				break;
			}
		}

