			Should.NotBeNull(task, "task");
			if (task.IsCompleted)
			{
				try
				{
					if (task is Task<TResult> task2)
					{
						tcs.TrySetResult(task2.Result);
					}
					else
					{
						task.Wait();
						tcs.TrySetResult(default(TResult));
					}
					return;
				}
				catch (Exception e)
				{
					tcs.TrySetExceptionEx(e);
					return;
				}
			}
			task.ContinueWith(delegate(Task t, object? o)
			{
				((TaskCompletionSource<TResult>)o).TrySetFromTask(t);
			}, tcs, continuationOptions);
		}

