		internal static async Task WhenAll(this PooledItemOrList<Task> tasks, bool throwOnCancel, bool throwOnDispose)
		{
			try
			{
				await tasks.WhenAll().ConfigureAwait(continueOnCapturedContext: false);
			}
			catch (OperationCanceledException)
			{
				if (throwOnCancel)
				{
					throw;
				}
			}
			catch (ObjectDisposedException)
			{
				if (throwOnDispose)
				{
					throw;
				}
			}
		}

		internal static void TrySetExceptionEx<T>(this TaskCompletionSource<T> tcs, Exception e)
		{
			e = e.TryGetBaseException(out OperationCanceledException canceledException);
			if (canceledException == null)
			{
				tcs.TrySetException(e);
			}
			else
			{
				tcs.TrySetCanceled(canceledException.CancellationToken);
			}
		}

		internal static Exception TryGetBaseException(this Exception e, out OperationCanceledException? canceledException)
		{
			while (true)
			{
				if (e is OperationCanceledException ex)
				{
					canceledException = ex;
					return e;
				}
				if (!(e is AggregateException ex2))
				{
					break;
				}
				e = ex2.GetBaseException();
			}
			canceledException = null;
			return e;
		}

