	public static class ApiRequestExtensions
	{
		public static ValueTask<ActionToken> ActionTokenAsyncApiRequestImpl<T, TRequest>(ItemOrArray<IApiProviderComponent<T>> componentsRaw, TRequest request, T apiProvider, IReadOnlyMetadataContext? metadata, CancellationToken cancellationToken) where T : class, IApiProvider<T> where TRequest : IActionTokenAsyncApiRequest<T, TRequest>
		{
			if (componentsRaw.Count == 0)
			{
				return default(ValueTask<ActionToken>);
			}
			if (componentsRaw.Count == 1)
			{
				return componentsRaw.Item.TryInvoke<TRequest, ValueTask<ActionToken>>(request, apiProvider, metadata, cancellationToken);
			}
			return Invoke(componentsRaw.List, request, apiProvider, metadata, cancellationToken);
		}

		public static ActionToken ActionTokenApiRequestImpl<T, TRequest>(ItemOrArray<IApiProviderComponent<T>> componentsRaw, TRequest request, T apiProvider, IReadOnlyMetadataContext? metadata, CancellationToken cancellationToken) where T : class, IApiProvider<T> where TRequest : IActionTokenApiRequest<T, TRequest>
		{
			if (componentsRaw.Count == 0)
			{
				return default(ActionToken);
			}
			if (componentsRaw.Count == 1)
			{
				return componentsRaw.Item.TryInvoke<TRequest, ActionToken>(request, apiProvider, metadata, cancellationToken);
			}
			IApiProviderComponent<T>[] list = componentsRaw.List;
			PooledListSlim<object> values = new PooledListSlim<object>(0);
			try
			{
				IApiProviderComponent<T>[] array = list;
				foreach (IApiProviderComponent<T> obj in array)
				{
					cancellationToken.ThrowIfCancellationRequested();
					obj.TryInvoke<TRequest, ActionToken>(request, apiProvider, metadata, cancellationToken).WriteTo(ref values);
				}
				return ActionToken.FromTokens(values.ToArray());
			}
			catch
			{
				values.DisposeActionTokens();
				throw;
			}
			finally
			{
				values.Dispose();
			}
		}

		public static TResponse? ApiRequestImpl<T, TRequest, TResponse>(ItemOrArray<IApiProviderComponent<T>> componentsRaw, TRequest request, T apiProvider, IReadOnlyMetadataContext? metadata, CancellationToken cancellationToken) where T : class, IApiProvider<T> where TRequest : IApiRequest<T, TRequest, TResponse>
		{
			if (componentsRaw.Count == 0)
			{
				return default(TResponse);
			}
			if (componentsRaw.Count == 1)
			{
				return componentsRaw.Item.TryInvoke<TRequest, TResponse>(request, apiProvider, metadata, cancellationToken);
			}
			if (TRequest.IsReverse)
			{
				if (TRequest.InvokeAll)
				{
					return InvokeReverseAllImpl<T, TRequest, TResponse>(componentsRaw.List, request, apiProvider, metadata, cancellationToken);
				}
				return InvokeReverseImpl<T, TRequest, TResponse>(componentsRaw.List, request, apiProvider, metadata, cancellationToken);
			}
			if (TRequest.InvokeAll)
			{
				return InvokeAllImpl<T, TRequest, TResponse>(componentsRaw.List, request, apiProvider, metadata, cancellationToken);
			}
			return InvokeImpl<T, TRequest, TResponse>(componentsRaw.List, request, apiProvider, metadata, cancellationToken);
		}

		public static ValueTask<TResponse?> ApiRequestAsyncImpl<T, TRequest, TResponse>(ItemOrArray<IApiProviderComponent<T>> componentsRaw, TRequest request, T apiProvider, IReadOnlyMetadataContext? metadata, CancellationToken cancellationToken) where T : class, IApiProvider<T> where TRequest : IAsyncApiRequest<T, TRequest, TResponse>
		{
			if (componentsRaw.Count == 0)
			{
				return default(ValueTask<TResponse>);
			}
			if (componentsRaw.Count == 1)
			{
				return componentsRaw.Item.TryInvoke<TRequest, ValueTask<TResponse>>(request, apiProvider, metadata, cancellationToken);
			}
			if (TRequest.IsReverse)
			{
				if (TRequest.InvokeAll)
				{
					return InvokeReverseAllImplAsync<T, TRequest, TResponse>(componentsRaw.List, request, apiProvider, metadata, cancellationToken);
				}
				return InvokeReverseImplAsync<T, TRequest, TResponse>(componentsRaw.List, request, apiProvider, metadata, cancellationToken);
			}
			if (TRequest.InvokeAll)
			{
				return InvokeAllImplAsync<T, TRequest, TResponse>(componentsRaw.List, request, apiProvider, metadata, cancellationToken);
			}
			return InvokeImplAsync<T, TRequest, TResponse>(componentsRaw.List, request, apiProvider, metadata, cancellationToken);
		}

		public static async IAsyncEnumerator<TItem>? AsyncEnumeratorRequestImpl<T, TRequest, TItem>(ItemOrArray<IApiProviderComponent<T>> components, TRequest request, T apiProvider, IReadOnlyMetadataContext? metadata, CancellationToken cancellationToken) where T : class, IApiProvider<T> where TRequest : IAsyncEnumeratorApiRequest<T, TRequest, TItem>
		{
			ArraySegmentEnumerator<IApiProviderComponent<T>> enumerator = components.GetEnumerator();
			while (enumerator.MoveNext())
			{
				IApiProviderComponent<T> current = enumerator.Current;
				await using IAsyncEnumerator<TItem> enumerator2 = current.TryInvoke<TRequest, IAsyncEnumerator<TItem>>(request, apiProvider, metadata, cancellationToken);
				if (enumerator2 != null)
				{
					while (await enumerator2.MoveNextAsync(cancellationToken).ConfigureAwait(continueOnCapturedContext: false))
					{
						yield return enumerator2.Current;
					}
				}
