				foreach (IApiProviderComponent<T> obj in components)
				{
					cancellationToken.ThrowIfCancellationRequested();
					val2 = obj.TryInvoke<TRequest, TResponse>(request, apiProvider, metadata, cancellationToken);
					if (TRequest.IsValidResponse(request, val2, metadata))
					{
						val = val2;
					}
				}
				return val;
			}
			catch
			{
				TRequest.CleanupResponse(request, val2, metadata);
				TRequest.CleanupResponse(request, val, metadata);
				throw;
			}
		}

		private static TResponse? InvokeReverseAllImpl<T, TRequest, TResponse>(IApiProviderComponent<T>[] components, TRequest request, T apiProvider, IReadOnlyMetadataContext? metadata, CancellationToken cancellationToken) where T : class, IApiProvider<T> where TRequest : IApiRequest<T, TRequest, TResponse>
		{
			TResponse val = default(TResponse);
			TResponse val2 = default(TResponse);
			try
			{
				for (int num = components.Length - 1; num >= 0; num--)
				{
					cancellationToken.ThrowIfCancellationRequested();
					val2 = components[num].TryInvoke<TRequest, TResponse>(request, apiProvider, metadata, cancellationToken);
					if (TRequest.IsValidResponse(request, val2, metadata))
					{
						val = val2;
					}
				}
				return val;
			}
			catch
			{
				TRequest.CleanupResponse(request, val2, metadata);
				TRequest.CleanupResponse(request, val, metadata);
				throw;
			}
		}

		private static TResponse? InvokeReverseImpl<T, TRequest, TResponse>(IApiProviderComponent<T>[] components, TRequest request, T apiProvider, IReadOnlyMetadataContext? metadata, CancellationToken cancellationToken) where T : class, IApiProvider<T> where TRequest : IApiRequest<T, TRequest, TResponse>
		{
			TResponse val = default(TResponse);
			try
			{
				for (int num = components.Length - 1; num >= 0; num--)
				{
					cancellationToken.ThrowIfCancellationRequested();
					val = components[num].TryInvoke<TRequest, TResponse>(request, apiProvider, metadata, cancellationToken);
					if (TRequest.IsValidResponse(request, val, metadata))
					{
						return val;
					}
				}
				return default(TResponse);
			}
			catch
			{
				TRequest.CleanupResponse(request, val, metadata);
				throw;
			}
		}

		private static async ValueTask<ActionToken> Invoke<T, TRequest>(IApiProviderComponent<T>[] components, TRequest request, T apiProvider, IReadOnlyMetadataContext? metadata, CancellationToken cancellationToken) where T : class, IApiProvider<T> where TRequest : IActionTokenAsyncApiRequest<T, TRequest>
		{
			PooledListSlim<object?> tokens = new PooledListSlim<object>(0);
			try
			{
				foreach (IApiProviderComponent<T> obj in components)
				{
					cancellationToken.ThrowIfCancellationRequested();
					(await obj.TryInvoke<TRequest, ValueTask<ActionToken>>(request, apiProvider, metadata, cancellationToken).ConfigureAwait(continueOnCapturedContext: false)).WriteTo(ref tokens);
				}
				cancellationToken.ThrowIfCancellationRequested();
				return ActionToken.FromTokens(tokens.ToArray());
			}
			catch
			{
				tokens.DisposeActionTokens();
				throw;
			}
			finally
			{
				tokens.Dispose();
			}
		}
	}
	public static class BindingBuilderExtensions
	{
		private static class CanExecuteClosure<TTarget> where TTarget : class
		{
			private static Action<IBinding, bool, object?, IReadOnlyMetadataContext?>? _delegate;

			public static Action<IBinding, bool, object?, IReadOnlyMetadataContext?>? Get(Action<IBinding, TTarget, bool, IReadOnlyMetadataContext?>? del)
			{
				object obj;
				if (del != null)
				{
					obj = _delegate;
					if (obj == null)
					{
						return _delegate = Impl;
					}
				}
				else
				{
					obj = null;
				}
				return (Action<IBinding, bool, object?, IReadOnlyMetadataContext?>?)obj;
			}

			private static void Impl(IBinding binding, bool value, object? state, IReadOnlyMetadataContext? metadata)
			{
				TTarget val = (TTarget)(binding.Target?.Target);
				if (val != null)
				{
					((Action<IBinding, TTarget, bool, IReadOnlyMetadataContext>)state)(binding, val, value, metadata);
				}
			}
		}

		private sealed class DisposableValueBind<T, TState> : IBindingComponent, IAttachableBindingComponent, IHasPriority
		{
			private readonly Func<T, TState, ActionToken> _bind;

			private readonly TState _state;

			private readonly Action<IBindingBuilderContext, TState>? _configurator;

			private ActionToken _actionToken;

			private T? _latestValue;

			public int Priority => int.MinValue;

			public DisposableValueBind(Func<T, TState, ActionToken> bind, TState state, Action<IBindingBuilderContext, TState>? configurator)
			{
				_bind = bind;
				_state = state;
				_configurator = configurator;
			}

			public void Invoke(T value)
			{
				if (EqualityComparer<T>.Default.Equals(_latestValue, value))
				{
					return;
				}
				lock (this)
				{
					if (!EqualityComparer<T>.Default.Equals(_latestValue, value))
					{
						_actionToken.Dispose();
						_actionToken = _bind(value, _state);
						_latestValue = value;
					}
				}
			}

			public void Configure(IBindingBuilderContext context)
			{
				context.Components.GetOrAddValueRef("@dv") = this;
				_configurator?.Invoke(context, _state);
			}

			public void OnAttached(IBindingInternal binding, IReadOnlyMetadataContext? metadata)
			{
			}

			public void OnDisposed(IBindingInternal? binding, IReadOnlyMetadataContext? metadata)
			{
				_actionToken.Dispose();
			}
		}

		private static class ParameterClosure<TTarget, TValue> where TTarget : class
		{
			private static Func<IBinding, object?, IReadOnlyMetadataContext?, TValue>? _delegate;

			public static BindingParameterValue Get(Func<IBinding, TTarget, IReadOnlyMetadataContext?, TValue>? del)
			{
				if (del != null)
				{
					return BindingParameterValue.FromDelegate(new Func<IBinding, object, IReadOnlyMetadataContext, TValue>(Impl), del);
				}
				return default(BindingParameterValue);
			}

			private static TValue Impl(IBinding binding, object? state, IReadOnlyMetadataContext? metadata)
			{
				if (!(binding.Target?.Target is TTarget arg))
				{
					return default(TValue);
				}
				return Unsafe.As<Func<IBinding, TTarget, IReadOnlyMetadataContext, TValue>>(state)(binding, arg, metadata);
			}
		}

