		private static IBinding BindCore(object target, object targetExpression, object source, object sourceMember, Action<IBindingBuilderContext>? configurator, IReadOnlyMetadataContext? metadata, IBindingHandler handler)
		{
			InlineObjectTuple state = new InlineObjectTuple
			{
				Item1 = target,
				Item2 = targetExpression,
				Item3 = source,
				Item4 = sourceMember,
				Item5 = handler,
				Item6 = configurator
			};
			return IMugenService<IBindingManager>.Instance.BuildBinding(target, state, delegate(IBindingManager manager, IBindingBuilderContext context, InlineObjectTuple s)
			{
				Unsafe.As<Action<IBindingBuilderContext>>(s.Item6)?.Invoke(context);
				context.Target = manager.GetBindingObserver(s.Item1, s.Item2, context);
				context.Sources = new ItemOrArray<object>(manager.GetBindingSource(s.Item3, s.Item4, context.Target, context));
				context.Handler = Unsafe.As<IBindingHandler>(s.Item5);
			}, metadata);
		}

		public static BindingResult<TSource1> ToAction<TSource1, T1>(this BindingSyntax<TSource1, T1> syntax, [RequireStaticDelegate] Action<T1> action, [RequireStaticDelegate] Action<IBindingBuilderContext>? configurator = null, bool distinct = false, IReadOnlyMetadataContext? metadata = null) where TSource1 : class
		{
			IBinding binding = MugenMvvmApiExtensions.BuildBinding(state: new InlineObjectTuple
			{
				Item1 = configurator,
				Item2 = (distinct ? new DistinctActionDelegateBindingHandler<Unit, T1, Unit>(action) : ActionDelegateBindingHandler<Unit, T1, Unit>.Get(action)),
				Item3 = syntax.Target,
				Item4 = syntax.Expression
			}, apiProvider: IMugenService<IBindingManager>.Instance, target: syntax.Target, callback: ToActionVoid1Impl, metadata: metadata);
			return new BindingResult<TSource1>(syntax.Target, binding);
		}

		private static void ToActionVoid1Impl(IBindingManager manager, IBindingBuilderContext context, InlineObjectTuple state)
		{
			Unsafe.As<Action<IBindingBuilderContext>>(state.Item1)?.Invoke(context);
			context.Target = null;
			context.Sources = new ItemOrArray<object>(manager.GetBindingSource(state.Item3, state.Item4, null, context));
