	public static class BindingExpressionMethodExtensions
	{
		public static bool LessThanOrEqual<T1, T2>(T1 x1, T2 x2)
		{
			return x1.Compare(x2) <= 0;
		}

		public static bool LessThan<T1, T2>(T1 x1, T2 x2)
		{
			return x1.Compare(x2) < 0;
		}

		public static bool GreaterThanOrEqual<T1, T2>(T1 x1, T2 x2)
		{
			return x1.Compare(x2) >= 0;
		}

		public static bool GreaterThan<T1, T2>(T1 x1, T2 x2)
		{
			return x1.Compare(x2) > 0;
		}

		public static bool Equality<T1, T2>(T1 x1, T2 x2)
		{
			if (!typeof(T1).IsValueType && !typeof(T2).IsValueType && (object)x1 == (object)x2)
			{
				return true;
			}
			if (typeof(T1) != typeof(T2))
			{
				if (MugenExtensions.TryConvert<T2, T1>(x2, out var result))
				{
					return EqualityComparer<T1>.Default.Equals(x1, result);
				}
				return false;
			}
			return EqualityComparer<T1>.Default.Equals(x1, MugenExtensions.ConvertExact<T2, T1>(x2));
		}

		public static bool NotEqual<T1, T2>(T1 x1, T2 x2)
		{
			return !Equality(x1, x2);
		}

		public static bool ConditionalAnd<T1, T2>(T1 x1, T2 x2)
		{
			if (MugenExtensions.Convert<T1, bool>(x1))
			{
				return MugenExtensions.Convert<T2, bool>(x2);
			}
			return false;
		}

		public static bool ConditionalOr<T1, T2>(T1 x1, T2 x2)
		{
			if (!MugenExtensions.Convert<T1, bool>(x1))
			{
				return MugenExtensions.Convert<T2, bool>(x2);
			}
			return true;
		}

		public static T1 NullCoalescing<T1, T2>(T1 x1, T2 x2)
		{
			if (x1 != null)
			{
				return x1;
			}
			return MugenExtensions.Convert<T2, T1>(x2);
		}

		public static T1 Multiplication<T1, T2>(T1 x1, T2 x2) where T1 : INumberBase<T1> where T2 : INumberBase<T2>
		{
			return x1 * T1.CreateChecked(x2);
		}

		public static T1 Division<T1, T2>(T1 x1, T2 x2) where T1 : INumberBase<T1> where T2 : INumberBase<T2>
		{
			return x1 / T1.CreateChecked(x2);
		}

		public static T1 Addition<T1, T2>(T1 x1, T2 x2) where T1 : INumberBase<T1> where T2 : INumberBase<T2>
		{
			return x1 + T1.CreateChecked(x2);
		}

		public static T1 Subtraction<T1, T2>(T1 x1, T2 x2) where T1 : INumberBase<T1> where T2 : INumberBase<T2>
		{
			return x1 - T1.CreateChecked(x2);
		}

		public static T1 Remainder<T1, T2>(T1 x1, T2 x2) where T1 : INumberBase<T1>, IModulusOperators<T1, T1, T1> where T2 : INumberBase<T2>
		{
			return x1 % T1.CreateChecked(x2);
		}

		public static T1? Multiplication<T1, T2>(T1? x1, T2? x2) where T1 : struct, INumberBase<T1> where T2 : struct, INumberBase<T2>
		{
			if (!x1.HasValue || !x2.HasValue)
			{
				return null;
			}
			return x1.GetValueOrDefault() * T1.CreateChecked(x2.GetValueOrDefault());
		}

		public static T1? Division<T1, T2>(T1? x1, T2? x2) where T1 : struct, INumberBase<T1> where T2 : struct, INumberBase<T2>
		{
			if (!x1.HasValue || !x2.HasValue)
			{
				return null;
			}
			return x1.GetValueOrDefault() / T1.CreateChecked(x2.GetValueOrDefault());
		}

		public static T1? Addition<T1, T2>(T1? x1, T2? x2) where T1 : struct, INumberBase<T1> where T2 : struct, INumberBase<T2>
		{
			if (!x1.HasValue || !x2.HasValue)
			{
				return null;
			}
			return x1.GetValueOrDefault() + T1.CreateChecked(x2.GetValueOrDefault());
		}

		public static T1? Subtraction<T1, T2>(T1? x1, T2? x2) where T1 : struct, INumberBase<T1> where T2 : struct, INumberBase<T2>
		{
			if (!x1.HasValue || !x2.HasValue)
			{
				return null;
			}
			return x1.GetValueOrDefault() - T1.CreateChecked(x2.GetValueOrDefault());
		}

		public static T1? Remainder<T1, T2>(T1? x1, T2? x2) where T1 : struct, INumberBase<T1>, IModulusOperators<T1, T1, T1> where T2 : struct, INumberBase<T2>
		{
			if (!x1.HasValue || !x2.HasValue)
			{
				return null;
			}
			return x1.GetValueOrDefault() % T1.CreateChecked(x2.GetValueOrDefault());
		}

		public static bool LogicalNegation<T1>(T1 x1)
		{
			return !MugenExtensions.Convert<T1, bool>(x1);
		}

		public static T2 Condition<T1, T2, T3>(T1 x1, T2 x2, T3 x3)
		{
			if (!MugenExtensions.Convert<T1, bool>(x1))
			{
				return MugenExtensions.Convert<T3, T2>(x3);
			}
			return x2;
		}

		private static int Compare<T1, T2>(this T1 x1, T2 x2)
		{
			if (!typeof(T1).IsValueType && !typeof(T2).IsValueType && (object)x1 == (object)x2)
			{
				return 0;
			}
			if (typeof(T1) != typeof(T2) && MugenExtensions.TryConvert<T2, T1>(x2, out var result))
			{
				return Comparer<T1>.Default.Compare(x1, result);
			}
			return Comparer<T2>.Default.Compare(MugenExtensions.Convert<T1, T2>(x1), x2);
		}
	}
	public static class BindingMugenExtensions
	{
		public readonly struct LazyBindingValue<T>
		{
			private readonly object? _target;

			private readonly IMemberInfo? _member;

			public LazyBindingValue(object? target, IMemberInfo? member)
			{
				_target = target;
				_member = member;
			}

			public T GetValue(IReadOnlyMetadataContext? metadata)
			{
				if (_member == null)
				{
					return MugenExtensions.Convert<object, T>(_target);
				}
				if (ConvertibleValue == _member)
				{
					return ((IHasConvertibleValue)_target).GetValue<T>();
				}
				if (DelegateMember == _member)
				{
					return ((Func<IReadOnlyMetadataContext, T>)_target)(metadata);
				}
				if (DelegateObjMember == _member)
				{
					return MugenExtensions.Convert<object, T>(((Func<IReadOnlyMetadataContext, object>)_target)(metadata));
				}
				return ((IAccessorMemberInfo)_member).GetValue<T>(_target, metadata);
			}
		}

