		public static bool TryBuildBindingMemberPath(this IExpressionNode? target, StringBuilder builder, Func<IExpressionNode, bool>? condition, string? rootPath, [NotNullWhen(true)] out IExpressionNode? firstExpression)
		{
			Should.NotBeNull(builder, "builder");
			firstExpression = null;
			builder.Clear();
			while (target != null)
			{
				firstExpression = target;
				if (condition != null && !condition(target))
				{
					return false;
				}
				IExpressionNode expressionNode = target;
				if (!(expressionNode is IMemberExpressionNode memberExpressionNode))
				{
					if (!(expressionNode is IIndexExpressionNode indexExpressionNode) || !indexExpressionNode.Arguments.IsConstants())
					{
						if (expressionNode is IMethodCallExpressionNode methodCallExpressionNode && methodCallExpressionNode.Arguments.IsConstants())
						{
							ItemOrIReadOnlyList<IExpressionNode> arguments = methodCallExpressionNode.Arguments;
							builder.Insert(0, ')');
							if (arguments.Count > 0)
							{
								arguments[arguments.Count - 1].ToStringValue(builder);
								for (int num = arguments.Count - 2; num >= 0; num--)
								{
									builder.Insert(0, ',');
									arguments[num].ToStringValue(builder);
								}
							}
							builder.Insert(0, '(');
							ItemOrIReadOnlyList<string> typeArgs = methodCallExpressionNode.TypeArgs;
							if (typeArgs.Count > 0)
							{
								builder.Insert(0, ">");
								builder.Insert(0, typeArgs[typeArgs.Count - 1]);
								for (int num2 = typeArgs.Count - 2; num2 >= 0; num2--)
								{
									builder.Insert(0, '|');
									builder.Insert(0, typeArgs[num2]);
								}
								builder.Insert(0, "<");
							}
							builder.Insert(0, methodCallExpressionNode.Method);
							if (methodCallExpressionNode.Target != null)
							{
								builder.Insert(0, '.');
							}
							target = methodCallExpressionNode.Target;
							continue;
						}
						return false;
					}
					ItemOrIReadOnlyList<IExpressionNode> arguments2 = indexExpressionNode.Arguments;
					builder.Insert(0, ']');
					if (arguments2.Count > 0)
					{
						arguments2[arguments2.Count - 1].ToStringValue(builder);
						for (int num3 = arguments2.Count - 2; num3 >= 0; num3--)
						{
							builder.Insert(0, ',');
							arguments2[num3].ToStringValue(builder);
						}
					}
					builder.Insert(0, '[');
					target = indexExpressionNode.Target;
					continue;
				}
				string text = memberExpressionNode.Member.Trim();
				if (text.Length == 0)
				{
					if (builder.Length != 0 && builder[0] == '.')
					{
						builder.Remove(0, 1);
					}
				}
				else
				{
					builder.Insert(0, text);
				}
				if (memberExpressionNode.Target != null)
				{
					builder.Insert(0, '.');
				}
				target = memberExpressionNode.Target;
			}
			if (firstExpression == null)
			{
				return false;
			}
			if (!string.IsNullOrEmpty(rootPath))
			{
				if (!(firstExpression is IIndexExpressionNode))
				{
					builder.Insert(0, ".");
				}
				builder.Insert(0, rootPath);
			}
			return true;
		}

