			if (!context.TryConvertExtension(member.DeclaringType ?? typeof(object), expression, metadata, out result))
			{
				if (expression == null)
				{
					result = TypeAccessExpressionNode.Get(member.DeclaringType);
				}
				else if (!context.TryConvert(expression, metadata, out result))
				{
					return false;
				}
			}
			if (result == MemberExpressionNode.Empty)
			{
				result = null;
			}
			return true;
		}

		public static bool TryConvert(this IExpressionConverterContext<Expression> context, ItemOrIReadOnlyList<Expression> expressions, IReadOnlyMetadataContext? metadata, out ItemOrList<IExpressionNode> result)
		{
			result = new ItemOrList<IExpressionNode>(expressions.Count);
			foreach (Expression item in expressions)
			{
				if (!context.TryConvert(item, metadata, out IExpressionNode result2))
				{
					return false;
				}
				result.Add(result2);
			}
			return true;
		}

		public static bool TryConvertMethodCall(this IExpressionConverterContext<Expression> context, MethodCallExpression methodCallExpression, IReadOnlyMetadataContext? metadata, [NotNullWhen(true)] out IExpressionNode? result)
		{
			result = null;
			MethodInfo method = methodCallExpression.Method;
			ParameterInfo[] extensionParameters = null;
			if (!context.TryConvert(ItemOrIReadOnlyList.FromList(methodCallExpression.Arguments), metadata, out ItemOrList<IExpressionNode> result2))
			{
				return false;
			}
			Type type;
			IExpressionNode result3;
			if (method.GetAccessModifiers(checkExtension: true, ref extensionParameters).HasFlag(MemberFlags.Extension))
			{
				type = methodCallExpression.Arguments[0].Type;
				result3 = result2[0];
				result2.RemoveAt(0);
			}
			else
			{
				if (!context.TryConvertTarget(methodCallExpression.Object, method, metadata, out result3))
				{
					return false;
				}
				type = method.DeclaringType;
			}
			ItemOrArray<string> array = default(ItemOrArray<string>);
			if (method.IsGenericMethod)
			{
				Type[] genericArguments = method.GetGenericArguments();
				array = ItemOrArray.Get<string>(genericArguments.Length);
				for (int i = 0; i < genericArguments.Length; i++)
				{
					CollectionSlimExtensions.SetAt(ref array, i, genericArguments[i].AssemblyQualifiedName);
				}
			}
			result = new MethodCallExpressionNode(result3, method.Name, result2, array, method.GetMemberFlagsMetadata(type?.IsValueType ?? false));
			return true;
		}

