		public static bool IsToken(this ITokenParserContext context, string token, int? position = null, bool isPartOfIdentifier = true)
		{
			if (token.Length == 1)
			{
				return context.IsToken(token[0], position);
			}
			int position2 = context.GetPosition(position);
			int length = context.Length;
			if (position2 + token.Length > length)
			{
				return false;
			}
			for (int i = 0; i < token.Length; i++)
			{
				if (context.TokenAt(position2++) != token[i])
				{
					return false;
				}
			}
			if (!isPartOfIdentifier && position2 < length)
			{
				return !context.TokenAt(position2).IsValidIdentifierSymbol(isFirstSymbol: false);
			}
			return true;
		}

		public static bool IsAnyOf(this ITokenParserContext context, ReadOnlySpan<char> tokens, int? position = null)
		{
			if (!context.IsEof(position))
			{
