			}
			return false;
		}

		public static bool IsEofOrAnyOf(this ITokenParserContext context, ReadOnlySpan<char> tokens, int? position = null)
		{
			if (!context.IsEof(position))
			{
				return context.IsAnyOf(tokens, position);
			}
			return true;
		}

		public static bool IsIdentifier(this ITokenParserContext context, out int endPosition, int? position = null)
		{
			return context.IsIdentifier(out endPosition, context.GetPosition(position));
		}

		public static bool IsIdentifier(this ITokenParserContext context, out int endPosition, int position)
		{
			endPosition = position;
			if (context.IsEof(endPosition) || !TokenAt(context, endPosition).IsValidIdentifierSymbol(isFirstSymbol: true))
			{
				return false;
			}
			do
			{
				endPosition++;
			}
			while (!context.IsEof(endPosition) && TokenAt(context, endPosition).IsValidIdentifierSymbol(isFirstSymbol: false));
			return true;
		}

		public static bool IsDigit(this ITokenParserContext context, int? position = null)
