		public static int FindAnyOf(this ITokenParserContext context, ReadOnlySpan<char> tokens, int? position = null)
		{
			int position2 = context.GetPosition(position);
			int length = context.Length;
			for (int i = position2; i < length; i++)
			{
				if (tokens.Contains(context.TokenAt(i)))
				{
					return i;
				}
			}
			return -1;
		}

