		public static ITokenParserContext MoveNext(this ITokenParserContext context, int value = 1)
		{
			if (!context.IsEof())
			{
				context.Position += value;
			}
			return context;
		}

		public static IExpressionNode? TryParseWhileAnyOf(this ITokenParserContext context, ReadOnlySpan<char> tokens, int? minPriority, int? position = null, IExpressionNode? expression = null, IReadOnlyMetadataContext? metadata = null, CancellationToken cancellationToken = default(CancellationToken))
		{
			IExpressionNode expressionNode = context.TryParse(expression, minPriority, metadata, cancellationToken);
			if (expressionNode == null)
			{
				return null;
			}
			while (!context.SkipWhitespaces().IsEofOrAnyOf(tokens, position))
			{
				expressionNode = context.TryParse(expressionNode, minPriority, metadata, cancellationToken);
				if (expressionNode == null)
				{
					return null;
				}
			}
			return expressionNode;
		}

		public static ItemOrIReadOnlyList<IExpressionNode> ParseArguments(this ITokenParserContext context, IBindingManager apiProvider, string endSymbol, IReadOnlyMetadataContext? metadata, CancellationToken cancellationToken)
		{
			ItemOrList<IExpressionNode> itemOrList = default(ItemOrList<IExpressionNode>);
			IExpressionNode expressionNode;
			while (true)
			{
				expressionNode = context.TryParseWhileNotNull(null, null, metadata, cancellationToken);
				if (expressionNode == null)
				{
					break;
				}
				itemOrList.Add(expressionNode);
				if (context.SkipWhitespaces().IsToken(','))
				{
					context.MoveNext();
					continue;
				}
				if (!context.IsToken(endSymbol))
				{
					break;
				}
				context.MoveNext();
				return itemOrList;
			}
			apiProvider.GetRequestTracer(metadata)?.AddMessage((expressionNode == null) ? MugenExtensions.Format("Cannot parse argument expressions '{0}' expected expression", itemOrList.IsEmpty ? null : string.Join(",", itemOrList.AsList())) : MugenExtensions.Format("Cannot parse argument expressions '{0}' expected ',' or '{1}' token", string.Join(",", itemOrList.AsList()), endSymbol));
			return default(ItemOrIReadOnlyList<IExpressionNode>);
		}

		public static IExpressionNode? TryParse(this ITokenParserContext context, IExpressionNode? expression, int? minPriority, IReadOnlyMetadataContext? metadata, CancellationToken cancellationToken)
		{
			return IMugenService<IBindingManager>.Instance.TryParse(context, expression, minPriority, metadata, cancellationToken);
		}

		public static IExpressionNode Parse(this ITokenParserContext context, IExpressionNode? expression, int? minPriority, IReadOnlyMetadataContext? metadata, CancellationToken cancellationToken)
		{
			Should.NotBeNull(context, "context");
			IExpressionNode? expressionNode = context.TryParse(expression, minPriority, metadata, cancellationToken);
			if (expressionNode == null)
			{
				ExceptionManager.ThrowApiRequestNotSupported(IMugenService<IBindingManager>.Instance, new TokenParserRequest(context, expression, minPriority), metadata);
			}
			return expressionNode;
		}

		public static IExpressionNode? TryParseWhileNotNull(this ITokenParserContext context, IExpressionNode? expression = null, int? minPriority = null, IReadOnlyMetadataContext? metadata = null, CancellationToken cancellationToken = default(CancellationToken))
		{
			Should.NotBeNull(context, "context");
			while (true)
			{
				IExpressionNode expressionNode = context.TryParse(expression, minPriority, metadata, cancellationToken);
				if (expressionNode == null)
				{
					break;
				}
				expression = expressionNode;
			}
			return expression;
		}

		public static ItemOrArray<string> ParseStringArguments(this ITokenParserContext context, IBindingManager apiProvider, string endSymbol, bool isPointSupported, IReadOnlyMetadataContext? metadata)
		{
			Span<long> initialBuffer = stackalloc long[64];
			ValueSpanBuilder<long> args = new ValueSpanBuilder<long>(initialBuffer);
			try
			{
				int position = context.Position;
				int? num = null;
				while (true)
				{
					bool flag = context.SkipWhitespaces().IsToken(endSymbol);
					if (flag || context.IsToken(','))
					{
						if (!num.HasValue)
						{
							apiProvider.GetRequestTracer(metadata)?.AddMessage(MugenExtensions.Format("Cannot parse argument expressions '{0}' expected expression", context.Format(args)));
							return default(ItemOrArray<string>);
						}
						args.Append(new LongToIntMapper(position, num.Value).Long);
						context.MoveNext();
						if (flag)
						{
							break;
						}
						position = context.SkipWhitespaces().Position;
						num = null;
					}
					else if (isPointSupported && context.IsToken('.'))
					{
						context.MoveNext();
					}
					else
					{
						if (!context.IsIdentifier(out var endPosition))
						{
							apiProvider.GetRequestTracer(metadata)?.AddMessage(MugenExtensions.Format("Cannot parse argument expressions '{0}' expected ',' or '{1}' token", context.Format(args), endSymbol));
							return default(ItemOrArray<string>);
						}
						num = endPosition;
						context.Position = endPosition;
					}
				}
				if (args.IsEmpty)
				{
					return default(ItemOrArray<string>);
				}
				ItemOrArray<string> array = ItemOrArray.Get<string>(args.Length);
				for (int i = 0; i < array.Count; i++)
				{
					LongToIntMapper longToIntMapper = new LongToIntMapper(args[i]);
					array.SetAt(i, context.GetValue(longToIntMapper.Int1, longToIntMapper.Int2).ToString());
				}
				return array;
			}
			finally
			{
				args.Dispose();
			}
		}

		public static ItemOrArray<string?> GetMethodArgsRaw(string path, out string? methodName, out ItemOrArray<string> genericParams)
		{
			genericParams = default(ItemOrArray<string>);
			int num = path.IndexOf('(');
			if (num >= 0)
			{
				if (path[path.Length - 1] == ')')
				{
					ReadOnlySpan<char> span = path.AsSpan(0, num);
					int num2 = span.IndexOf('<');
					if (num2 >= 0)
					{
						int num3 = 0;
						int i = num2;
						int num4 = -1;
						for (; i < span.Length; i++)
						{
							switch (span[i])
							{
							case '<':
								num3++;
								continue;
							case '>':
								if (--num3 != 0)
								{
									continue;
								}
								break;
							default:
								continue;
							}
							num4 = i;
							break;
						}
						if (num4 < 0)
						{
							methodName = null;
							return default(ItemOrArray<string>);
						}
						genericParams = SplitTopLevel(span.Slice(num2 + 1, num4 - num2 - 1));
						if (genericParams.Count == 0)
						{
							methodName = null;
							return default(ItemOrArray<string>);
						}
						methodName = path.Substring(0, num2);
					}
					else
					{
						methodName = path.Substring(0, num);
					}
					return path.AsSpan(num + 1, path.Length - num - 2).UnescapeString(',');
				}
			}
			methodName = null;
			return default(ItemOrArray<string>);
		}

		internal static IReadOnlyMetadataContext? GetMemberFlagsMetadata(this MemberInfo memberInfo, bool suppressMethodIndexerAccessors)
		{
			if (!memberInfo.GetAccessModifiers().HasFlag(MemberFlags.NonPublic))
			{
				if (suppressMethodIndexerAccessors)
				{
					return _suppressMethodIndexerMetadata ?? (_suppressMethodIndexerMetadata = new ReadOnlyMetadataContext(new SortedListSlim<IMetadataContextKey, object>(2).Set(BindingBuilderMetadata.SuppressMethodAccessors, BoxingExtensions.TrueObject).Set(BindingBuilderMetadata.SuppressIndexAccessors, BoxingExtensions.TrueObject)));
				}
				return null;
			}
			if (suppressMethodIndexerAccessors)
			{
				return _memberFlagsSuppressMethodIndexerMetadata ?? (_memberFlagsSuppressMethodIndexerMetadata = new ReadOnlyMetadataContext(new SortedListSlim<IMetadataContextKey, object>(3).Set(BindingBuilderMetadata.SuppressMethodAccessors, BoxingExtensions.TrueObject).Set(BindingBuilderMetadata.SuppressIndexAccessors, BoxingExtensions.TrueObject).Set(BindingBuilderMetadata.MemberFlags, MemberFlags.AllBoxed)));
			}
			return _memberFlagsMetadata ?? (_memberFlagsMetadata = new ReadOnlyMetadataContext(new KeyValuePair<IMetadataContextKey, object>(BindingBuilderMetadata.MemberFlags, MemberFlags.AllBoxed)));
		}

		private static ReadOnlySpan<char> RemoveBounds(this ReadOnlySpan<char> st, int start = 1)
		{
			return st.Slice(start, st.Length - start - 1);
		}

		private static ItemOrArray<string> SplitTopLevel(ReadOnlySpan<char> span)
		{
			using PooledItemOrList<string> items = default(PooledItemOrList<string>);
			MemoryExtensions.SpanSplitEnumerator<char> enumerator = span.Split('|').GetEnumerator();
			while (enumerator.MoveNext())
			{
				Range current = enumerator.Current;
				Range range = current;
				ReadOnlySpan<char> readOnlySpan = span[range.Start..range.End];
				if (!readOnlySpan.IsEmpty)
				{
					items.Add(readOnlySpan.ToString());
				}
			}
			return CollectionSlimExtensions.ToItemOrArray(items);
		}

		private static ItemOrArray<string?> UnescapeString(this ReadOnlySpan<char> source, char separator)
		{
			if (source.Length == 0 || source.IsWhiteSpace())
			{
				return default(ItemOrArray<string>);
			}
			int num = 1;
			for (int i = 0; i < source.Length; i++)
			{
				if (source[i] == separator)
				{
					num++;
				}
			}
			ItemOrArray<string> array = ItemOrArray.Get<string>(num);
			int num2 = 0;
			MemoryExtensions.SpanSplitEnumerator<char> enumerator = source.Split(separator).GetEnumerator();
			while (enumerator.MoveNext())
			{
				Range current = enumerator.Current;
				Range range = current;
				ReadOnlySpan<char> readOnlySpan = source[range.Start..range.End].Trim();
				if ((readOnlySpan.StartsWith('"') && readOnlySpan.EndsWith('"')) || (readOnlySpan.StartsWith('\'') && readOnlySpan.EndsWith('\'')))
				{
					readOnlySpan = readOnlySpan.RemoveBounds();
				}
				else if (readOnlySpan.SequenceEqual("null"))
				{
					CollectionSlimExtensions.SetAt(ref array, num2++, null);
					continue;
				}
				array.SetAt(num2++, readOnlySpan.ToString());
			}
			return array;
		}

		private static bool IsValidIdentifierSymbol(this char symbol, bool isFirstSymbol)
		{
			if (isFirstSymbol)
			{
				if (!char.IsLetter(symbol) && symbol != '@')
				{
					return symbol == '_';
				}
				return true;
			}
			if (!char.IsLetterOrDigit(symbol))
			{
				return symbol == '_';
			}
			return true;
		}

		private static string? Format(this ITokenParserContext context, ValueSpanBuilder<long> args)
		{
			if (args.IsEmpty)
			{
				return null;
			}
			return string.Join(",", args.ToArray().Select(delegate(long l)
			{
				LongToIntMapper longToIntMapper = new LongToIntMapper(l);
				return context.GetValue(longToIntMapper.Int1, longToIntMapper.Int2).ToString();
			}));
		}

		private static bool Contains(this ReadOnlySpan<char> tokens, char token)
		{
			return tokens.IndexOf(token) > -1;
		}
	}
