						OnPropertyChanged(Default.ValueChangedArgs);
					}
				}
			}

			public FirstLastOrDefaultClosure<T> Init(IReadOnlyObservableCollection<object?> collection, bool isFirst)
			{
				if (Interlocked.CompareExchange(ref _state, int.MaxValue, 0) == 0)
				{
					ObservableCollectionConfiguration<T, FirstLastOrDefaultClosure<T>> configuration = collection.Configure().ForWrapper<object, T>().WithState(this);
					if (isFirst)
