						configuration.FirstOrDefault(delegate(IReadOnlyObservableCollection _, CollectionItemInfo<T> v, FirstLastOrDefaultClosure<T> s)
						{
							s.Value = v.Item;
						}).Bind();
					}
					else
					{
						configuration.LastOrDefault(delegate(IReadOnlyObservableCollection _, CollectionItemInfo<T> v, FirstLastOrDefaultClosure<T> s)
						{
							s.Value = v.Item;
						}).Bind();
					}
				}
				return this;
			}
		}

