	public static class BoxingExtensions
	{
		private static class BoxingType<T>
		{
			public static Func<T?, object?>? BoxDelegate = GetDefaultBox();

			public static Func<T?, object?>? TryBoxDelegate = GetDefaultTryBox();

			private static Func<T?, object?>? GetDefaultBox()
			{
				if (typeof(T) == typeof(bool))
				{
					return (Func<T, object>)(object)new Func<bool, object>(Box);
				}
				if (typeof(T) == typeof(bool?))
				{
					return (Func<T, object>)(object)new Func<bool?, object>(Box);
				}
				if (typeof(T) == typeof(int))
				{
					return (Func<T, object>)(object)new Func<int, object>(Box);
				}
				if (typeof(T) == typeof(int?))
				{
					return (Func<T, object>)(object)new Func<int?, object>(Box);
				}
				if (typeof(T) == typeof(Unit))
				{
					return (Func<T, object>)(object)(Func<Unit, object>)((Unit _) => Unit.Boxed);
				}
				return null;
			}

			private static Func<T?, object?>? GetDefaultTryBox()
			{
				if (typeof(T) == typeof(bool) || typeof(T) == typeof(bool?) || typeof(T) == typeof(Unit))
				{
					return BoxDelegate;
				}
				if (typeof(T) == typeof(int))
				{
					return (Func<T, object>)(object)new Func<int, object>(TryBox);
				}
				if (typeof(T) == typeof(int?))
				{
					return (Func<T, object>)(object)new Func<int?, object>(TryBox);
				}
				return null;
			}
		}

