		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public static bool CanBox<T>()
		{
			return BoxingType<T>.BoxDelegate != null;
		}

		public static bool CanBox(Type? type)
		{
			if ((object)type == null || !type.IsValueType)
			{
				return false;
			}
			if (TrueObject != null)
			{
				return _supportedBoxTypes.ContainsKey(type);
			}
			return false;
		}

		public static void RegisterBoxHandler<T>(Func<T?, object?> box, Func<T?, object?>? tryBox)
		{
			Should.NotBeNull(box, "box");
			BoxingType<T>.BoxDelegate = box;
			BoxingType<T>.TryBoxDelegate = tryBox ?? box;
			_supportedBoxTypes.GetOrAddValueRef(typeof(T));
		}

		private static DictionarySlim<Type, object?> GetSupportedTypes()
		{
			DictionarySlim<Type, object> result = new DictionarySlim<Type, object>(7);
			result.GetOrAddValueRef(typeof(bool));
			result.GetOrAddValueRef(typeof(int));
			result.GetOrAddValueRef(typeof(bool?));
			result.GetOrAddValueRef(typeof(int?));
			result.GetOrAddValueRef(typeof(Unit));
			return result;
		}
