		public static Type[] TryInferGenericParameters<T>(ReadOnlySpan<Type> genericArguments, ReadOnlySpan<T> parameters, Func<T, Type> getParameterType, ReadOnlySpan<Type?> argumentTypes, out bool hasUnresolved)
		{
			Should.NotBeNull(getParameterType, "getParameterType");
			hasUnresolved = false;
			int num = ((parameters.Length > argumentTypes.Length) ? argumentTypes.Length : parameters.Length);
			using PooledItemOrList<Type> items = default(PooledItemOrList<Type>);
			ReadOnlySpan<Type> readOnlySpan = genericArguments;
			for (int i = 0; i < readOnlySpan.Length; i++)
			{
				Type type = readOnlySpan[i];
				Type type2 = null;
				if (type.IsGenericParameter)
				{
					for (int j = 0; j < num; j++)
					{
						Type type3 = argumentTypes[j];
						if (type3 != null)
						{
							type2 = type.TryInferGenericParameter(getParameterType(parameters[j]), type3);
							if (type2 != null)
							{
								break;
							}
						}
					}
				}
				else
				{
					type2 = type;
				}
				if (type2 == null)
				{
					type2 = type;
					hasUnresolved = true;
				}
				items.Add(type2);
			}
			for (int k = 0; k < genericArguments.Length; k++)
			{
				Type type4 = items[k];
				Type type5 = genericArguments[k];
				if (type4 == type5)
				{
					continue;
				}
				if (!IsCompatible(type4, type5.GenericParameterAttributes))
				{
					return Type.EmptyTypes;
				}
				Type[] genericParameterConstraints = type5.GetGenericParameterConstraints();
				foreach (Type type6 in genericParameterConstraints)
				{
					bool flag = false;
					if (type6.IsGenericType)
					{
						Type[] genericArguments2 = type6.GetGenericArguments();
						for (int l = 0; l < genericArguments2.Length; l++)
						{
							if (genericArguments2[l].IsGenericParameter)
							{
								flag = true;
								break;
							}
						}
					}
					if (!flag && !type6.IsAssignableFrom(type4))
					{
						hasUnresolved = true;
						return Type.EmptyTypes;
					}
				}
			}
			return items.ToArray();
		}

