									valueSpanBuilder.Append("...");
									break;
								}
							}
						}
						finally
						{
							IDisposable disposable = enumerator as IDisposable;
							if (disposable != null)
							{
								disposable.Dispose();
							}
						}
						valueSpanBuilder.Append(']');
						return valueSpanBuilder.ToString();
					}
					finally
