		internal static string GetCsTypeName(this Type type, bool fullName)
		{
			if (type == typeof(string))
			{
				return "string";
			}
			if (type == typeof(object))
			{
				return "object";
			}
			if (type == typeof(bool))
			{
				return "bool";
			}
			if (type == typeof(char))
			{
				return "char";
			}
			if (type == typeof(int))
			{
				return "int";
			}
			if (type == typeof(float))
			{
				return "float";
			}
			if (type == typeof(double))
			{
				return "double";
			}
			if (type == typeof(long))
			{
				return "long";
			}
			if (type == typeof(ulong))
			{
				return "ulong";
			}
			if (type == typeof(uint))
			{
				return "uint";
			}
			if (type == typeof(byte))
			{
				return "byte";
			}
			if (type == typeof(long))
			{
				return "Int64";
			}
			if (type == typeof(short))
			{
				return "short";
			}
			if (type == typeof(decimal))
			{
				return "decimal";
			}
			if (type.IsGenericType)
			{
				return type.ToGenericTypeString(fullName) ?? "";
			}
			if (type.IsArray)
			{
				List<string> list = new List<string>();
				for (int i = 0; i < type.GetArrayRank(); i++)
				{
					list.Add("[]");
				}
				return type.GetElementType().GetCsTypeName(fullName) + string.Join("", list).Replace("+", ".");
			}
			if (fullName)
			{
				return type.FullName.Replace("+", ".");
			}
			return type.Name.Replace("+", ".");
		}

