		private static string ToGenericTypeString(this Type t, bool fullName, params Type[] arg)
		{
			if (t.IsGenericParameter || t.FullName == null)
			{
				return t.FullName;
			}
			bool flag = t.IsGenericType || t.FullName.Contains('`');
			bool flag2 = !t.IsGenericType && t.FullName.Contains('`');
			Type type = t;
			while (type.IsNested && type.DeclaringType.GetGenericArguments().Length == t.GetGenericArguments().Length)
			{
				type = type.DeclaringType;
			}
			if (!flag)
			{
				return t.ToCsReservedWord(fullName).Replace('+', '.');
			}
			Type[] source = ((arg.Length != 0) ? arg : t.GetGenericArguments());
			string text = type.ToCsReservedWord(fullName);
			if (type.IsNested)
			{
				Type[] array = source.Take(type.DeclaringType.GetGenericArguments().Length).ToArray();
				source = source.Skip(array.Length).ToArray();
				text = type.DeclaringType.ToGenericTypeString(fullName, array) + "." + type.ToCsReservedWord(fullName: false);
			}
			if (flag2)
			{
				text = t.GetElementType().ToGenericTypeString(fullName) + "[]";
			}
			if (text.IndexOf('`') >= 0)
			{
				text = text.Substring(0, text.IndexOf('`'));
				string text2 = string.Join(", ", source.Select((Type a) => a.ToGenericTypeString(fullName)).ToArray());
				text = text + "<" + text2 + ">";
				if (flag2)
				{
					text += "[]";
				}
			}
			if (t != type)
			{
				text += t.FullName.Replace(type.ToCsReservedWord(fullName: true), "").Replace('+', '.');
			}
			if (text.IndexOf('[') >= 0 && text.IndexOf(']') != text.IndexOf('[') + 1)
			{
				text = text.Substring(0, text.IndexOf('['));
			}
			return text;
		}

		[UnconditionalSuppressMessage("Trimming", "IL2067")]
		private static Type? TryInferGenericParameter(this Type genericArgument, Type parameterType, Type inputType)
		{
			if (parameterType == genericArgument)
			{
				return inputType;
			}
			if (parameterType.IsArray)
			{
				if (!inputType.IsArray)
				{
					return null;
				}
				return inputType.GetElementType();
			}
			if (parameterType.IsGenericType)
			{
				inputType = FindCommonType(parameterType.GetGenericTypeDefinition(), inputType);
				if (inputType == null)
				{
					return null;
				}
				Type[] genericArguments = inputType.GetGenericArguments();
				Type[] genericArguments2 = parameterType.GetGenericArguments();
				for (int i = 0; i < genericArguments2.Length; i++)
				{
					Type type = genericArgument.TryInferGenericParameter(genericArguments2[i], genericArguments[i]);
					if (type != null)
					{
						return type;
					}
				}
			}
			return null;
		}

		private static bool IsCompatible(Type type, GenericParameterAttributes attributes)
		{
			if (attributes.HasFlagEx(GenericParameterAttributes.ReferenceTypeConstraint) && type.IsValueType)
			{
				return false;
			}
			if (attributes.HasFlagEx(GenericParameterAttributes.NotNullableValueTypeConstraint) && !type.IsValueType)
			{
				return false;
			}
			return true;
		}

		private static Type? FindCommonType(Type genericDefinition, [DynamicallyAccessedMembers(DynamicallyAccessedMemberTypes.Interfaces)] Type type)
		{
			PooledDictionarySlim<Type, object> types = new PooledDictionarySlim<Type, object>(16);
			try
			{
				SelfAndBaseTypes(type, ref types);
				foreach (KeyValuePair<Type, object> item in types)
				{
					Type key = item.Key;
					if (key.IsGenericType && key.GetGenericTypeDefinition() == genericDefinition)
					{
						return key;
					}
				}
				return null;
			}
			finally
			{
				types.Dispose();
			}
		}

		private static void AddSelfAndBaseClasses(Type? type, ref PooledDictionarySlim<Type, object?> types)
		{
			while (type != null)
			{
				types.GetOrAddValueRef(type);
				type = type.BaseType;
			}
		}

