		public static async Task WaitAsync(this IValidator validator, IReadOnlyMetadataContext? metadata = null, CancellationToken cancellationToken = default(CancellationToken))
		{
			while (true)
			{
				Task task = validator.TryInvoke<IValidator, WaitValidationValidatorRequest, Task>(WaitValidationValidatorRequest.Instance, metadata, cancellationToken);
				if (task == null || task.IsCompletedSuccessfully)
				{
					break;
				}
				await task.ConfigureAwait(continueOnCapturedContext: false);
			}
		}

		public static T AddErrorMapping<T>(this T validator, string from, string to) where T : class, IHasService<IValidator>
		{
			Should.NotBeNull(validator, "validator");
			validator.Service.GetOrAddComponent<MappingValidatorDecorator>().Add(from, to);
			return validator;
		}

		public static bool RemoveErrorMapping<T>(this T validator, string mapping) where T : class, IHasService<IValidator>
		{
			Should.NotBeNull(validator, "validator");
			return validator.Service.TryGetComponent<MappingValidatorDecorator>()?.Remove(mapping) ?? false;
		}

		public static bool AddChildValidator(this IHasService<IValidator> owner, IValidator validator)
		{
