		}

		public static IHasService<IValidator> WithValidationRule<T>(this IHasService<IValidator> owner, Bindable<T?> bindable, object target, string member) where T : class
		{
			Should.NotBeNull(owner, "owner");
			Should.NotBeNull(target, "target");
			Should.NotBeNull(member, "member");
			owner.Service.Components.TryAdd(new BindableValidationRule<T>(bindable, target, member));
			return owner;
		}

		public static IHasService<IValidator> WithValidationRule<TError>(this IHasService<IValidator> owner, Bindable<bool> isValid, Bindable<TError> bindableError, object target, string member) where TError : class
		{
			Should.NotBeNull(owner, "owner");
			Should.NotBeNull(target, "target");
			Should.NotBeNull(member, "member");
			return owner.WithValidationRule(isValid.Combine(bindableError.As<TError, object>().GetValueOrDefault(""), (bool b, object error) => (!b) ? error : null), target, member);
		}
	}
