	public sealed class DebugActionToken : IDisposable
	{
		private static readonly List<WeakReference> Tokens = new List<WeakReference>(16);

		private readonly WeakReference _weakReference;

		private readonly int _threadId;

		private readonly StackFrame? _stackFrame;

		private ActionToken _token;

		private byte _state;

		public object Target { get; }

		private DebugActionToken(object target, ActionToken token, bool includeStackTrace)
		{
			Should.NotBeNull(target, "target");
			_token = token;
			Target = target;
			_threadId = Environment.CurrentManagedThreadId;
			if (includeStackTrace)
			{
				_stackFrame = new StackFrame();
			}
			_weakReference = new WeakReference(this);
			lock (Tokens)
			{
				Tokens.Add(_weakReference);
			}
		}

		~DebugActionToken()
		{
			ExceptionManager.ThrowActionTokenDisposeNotCalled(_threadId, Target, _stackFrame?.ToString());
		}

		public static ActionToken Wrap(object target, ActionToken actionToken, bool includeStackTrace)
		{
			return ActionToken.FromDisposable(new DebugActionToken(target, actionToken, includeStackTrace));
		}

		public static ItemOrIReadOnlyList<DebugActionToken> GetTokens()
		{
			ItemOrList<DebugActionToken> itemOrList = default(ItemOrList<DebugActionToken>);
			lock (Tokens)
			{
				for (int i = 0; i < Tokens.Count; i++)
				{
					if (Tokens[i].Target is DebugActionToken item)
					{
						itemOrList.Add(item);
						continue;
					}
					Tokens.RemoveAt(i);
					i--;
				}
				return itemOrList;
			}
		}

		public void Dispose()
		{
			if (Interlocked.Exchange(ref _state, 1) != 0)
			{
				ExceptionManager.ThrowObjectDisposed(this);
			}
			lock (Tokens)
			{
				Tokens.Remove(_weakReference);
			}
			_token.Dispose();
			GC.SuppressFinalize(this);
		}
	}
	public sealed class DebugArrayPoolTracer : IArrayPoolTracer
	{
		private sealed class Watcher : IDisposable
		{
			private readonly object _array;

			private readonly StackTrace? _stackTrace;

			private readonly Action<object, StackTrace?>? _callback;

			private readonly ConditionalWeakTable<object, Watcher> _table;

			public Watcher(object array, StackTrace? stackTrace, Action<object, StackTrace?>? callback, ConditionalWeakTable<object, Watcher> table)
			{
				_array = array;
				_stackTrace = stackTrace;
				_callback = callback;
				_table = table;
			}

			~Watcher()
			{
				if (_table.TryGetValue(_array, out Watcher _))
				{
					GC.ReRegisterForFinalize(this);
				}
				else
				{
					if (_callback == null)
					{
						ExceptionManager.ThrowArrayNotReturnedToPool(_array, _stackTrace?.ToString());
					}
					else
					{
						_callback(_array, _stackTrace);
					}
				}
			}

			public void Dispose()
			{
				GC.SuppressFinalize(this);
			}
		}

		private readonly bool _includeStackTrace;

		private readonly Action<object, StackTrace?>? _callback;

		private readonly ConditionalWeakTable<object, Watcher> _trackedItems = new ConditionalWeakTable<object, Watcher>();

		public DebugArrayPoolTracer(bool includeStackTrace = true, Action<object, StackTrace?>? callback = null)
		{
			_includeStackTrace = includeStackTrace;
			_callback = callback;
		}

		public object[] DumpRentedArrays()
		{
			lock (_trackedItems)
			{
				return _trackedItems.Select<KeyValuePair<object, Watcher>, object>((KeyValuePair<object, Watcher> pair) => pair.Key).ToArray();
			}
		}

		public void OnRented<T>(T[] array)
		{
			if (array.Length == 0)
			{
				return;
			}
			lock (_trackedItems)
			{
				if (_trackedItems.TryGetValue(array, out Watcher value))
				{
					ExceptionManager.ThrowCollectionPoolMisuse(array);
				}
				value = new Watcher(array, _includeStackTrace ? new StackTrace(2, fNeedFileInfo: true) : null, _callback, _trackedItems);
				_trackedItems.Add(array, value);
			}
		}

		public void OnReturned<T>(T[] array, bool clearArray)
		{
			if (array.Length == 0)
			{
				return;
			}
			if (RuntimeHelpers.IsReferenceOrContainsReferences<T>() && !clearArray)
			{
				foreach (T y in array)
				{
					if (!EqualityComparer<T>.Default.Equals(default(T), y))
					{
						ExceptionManager.ThrowNotValidArgument("array");
					}
				}
			}
			lock (_trackedItems)
			{
				if (!_trackedItems.TryGetValue(array, out Watcher value))
				{
					ExceptionManager.ThrowCollectionPoolMisuse(array);
				}
				value.Dispose();
				_trackedItems.Remove(array);
			}
		}
	}
