		{
			if (views.Length == 0)
			{
				return Array.Empty<INavigationEntry>();
			}
			using PooledItemOrList<INavigationEntry> items = default(PooledItemOrList<INavigationEntry>);
			foreach (INavigationEntry item in IMugenService<INavigationDispatcher>.Instance.GetNavigationEntries().GetDisposableEnumerator())
			{
				for (int i = 0; i < views.Length; i++)
				{
					if (views[i].ViewModel == item.Target)
					{
						items.Add(item);
						break;
					}
				}
			}
			return items.ToArray();
		}
	}
