				}
				ComponentTracker[] array = ComponentTrackers;
				ComponentTracker componentTracker = GetComponentTracker<TComponent>(descriptor, metadata);
				if (array != ComponentTrackers)
				{
					num = IndexOf(descriptor.Id);
					if (num >= 0)
					{
