					}
					array = ComponentTrackers;
				}
				Array.Resize(ref array, array.Length + 1);
				num = ~num;
				if (num < ComponentTrackers.Length)
				{
					Array.Copy(array, num, array, num + 1, ComponentTrackers.Length - num);
