		private void UpdateTrackers(object? component, IApiProviderComponent<ComponentCollection>? decorator, IReadOnlyMetadataContext? metadata)
		{
			Span<int> initialBuffer = stackalloc int[64];
			ValueSpanBuilder<int> valueSpanBuilder = new ValueSpanBuilder<int>(initialBuffer);
			try
			{
				initialBuffer = stackalloc int[64];
				ValueSpanBuilder<int> valueSpanBuilder2 = new ValueSpanBuilder<int>(initialBuffer);
				try
				{
					ComponentTracker[] componentTrackers = ComponentTrackers;
					for (int i = 0; i < componentTrackers.Length; i++)
					{
						ComponentDescriptor descriptor = componentTrackers[i].Descriptor;
						if (descriptor.IsComponentSupported(this, component, decorator, metadata))
						{
							if (descriptor.IsRequiredComponent)
							{
								valueSpanBuilder2.Append(i);
							}
							valueSpanBuilder.Append(i);
						}
					}
					if (valueSpanBuilder.Length == 0)
					{
						return;
					}
					if (valueSpanBuilder.Length == componentTrackers.Length)
					{
						ComponentTrackers = Array.Empty<ComponentTracker>();
					}
					else
					{
						ComponentTracker[] array = new ComponentTracker[componentTrackers.Length - valueSpanBuilder.Length];
						int num = 0;
						for (int j = 0; j < componentTrackers.Length; j++)
						{
							if (valueSpanBuilder.Span.BinarySearch(j) < 0)
							{
								array[num++] = componentTrackers[j];
							}
						}
						ComponentTrackers = array;
					}
					initialBuffer = valueSpanBuilder2.Span;
					for (int k = 0; k < initialBuffer.Length; k++)
					{
						int num2 = initialBuffer[k];
						componentTrackers[num2].Descriptor.Reload(this);
					}
				}
				finally
				{
					valueSpanBuilder2.Dispose();
				}
			}
			finally
			{
				valueSpanBuilder.Dispose();
			}
		}

