			if (TryInvoke<CanDecorateComponentRequest, bool?>(new CanDecorateComponentRequest(descriptor), metadata) == true)
			{
				return GetComponentTrackerWithDecorators<TComponent>(descriptor, metadata);
			}
			using PooledItemOrList<object> items = default(PooledItemOrList<object>);
			for (int i = 0; i < Items.Count; i++)
			{
				if (Items[i].Component is TComponent val && (!descriptor.IsSupportRequestComponent || descriptor.IsRequestSupported(Owner, val)))
				{
					items.Add(val);
				}
			}
			if (items.Count == 0)
			{
				return GetComponentTracker<TComponent>(descriptor, (TComponent?)null);
			}
			return GetComponentTracker(descriptor, items.ToItemOrArray<TComponent>());
		}

		private ComponentTracker GetComponentTrackerWithDecorators<TComponent>(ComponentDescriptor descriptor, IReadOnlyMetadataContext? metadata) where TComponent : class
		{
			PooledItemOrList<object> components = default(PooledItemOrList<object>);
			for (int i = 0; i < Items.Count; i++)
			{
				if (Items[i].Component is TComponent val && (!descriptor.IsSupportRequestComponent || descriptor.IsRequestSupported(Owner, val)))
				{
					components.Add(val);
				}
			}
			using PooledItemOrList<object> items = TryInvoke<DecorateComponentRequest, DecorateComponentRequest>(DecorateComponentRequest.Get(components, descriptor), metadata).GetComponents();
			return GetComponentTracker(descriptor, items.ToItemOrArray<TComponent>());
		}

