		private int IndexOf(ComponentInfo item)
		{
			Span<ComponentInfo> span = Items.Span;
			int num = span.BinarySearch(item);
			if (num < 0)
			{
				return num;
			}
			while (num > 0 && span[num - 1].CompareTo(item) == 0)
			{
				num--;
			}
			for (int i = num; i < span.Length && span[i].CompareTo(item) == 0; i++)
			{
				if (span[i].Component == item.Component)
				{
					return i;
				}
			}
			int j;
			for (j = num; j < span.Length && span[j].CompareTo(item) == 0; j++)
			{
			}
			return ~j;
		}

