		public static DecorateComponentRequest TryInvoke(ItemOrArray<IApiProviderComponent<ComponentCollection>> componentsRaw, DecorateComponentRequest request, ComponentCollection apiProvider, IReadOnlyMetadataContext? metadata, CancellationToken cancellationToken)
