		}

		private sealed class ActionObserverCompleted : ActionObserver<T, TState>
		{
			private readonly Action<TState> _onCompleted;

			public ActionObserverCompleted(TState state, Action<T, TState> onChanged, Action<TState> onCompleted)
				: base(state, onChanged)
			{
				_onCompleted = onCompleted;
