			_onChanged = onChanged;
		}

		public static ActionObserver<T, TState> Get(TState state, Action<T, TState> onChanged, Action<Exception, TState>? onError, Action<TState>? onCompleted)
		{
			if (onError != null)
			{
				if (onCompleted != null)
				{
					return new ActionObserverCompletedError(state, onChanged, onError, onCompleted);
				}
				return new ActionObserverError(state, onChanged, onError);
			}
			if (onCompleted != null)
			{
				return new ActionObserverCompleted(state, onChanged, onCompleted);
			}
			return new ActionObserver<T, TState>(state, onChanged);
		}

		public virtual void OnCompleted()
		{
		}

		public virtual void OnError(Exception error)
		{
		}

