		private static class ClosureAction<T> where T : class?
		{
			public static readonly Action<object?, object?> Closure = Impl;

			private static void Impl(object? a, object? s)
			{
				((Action<T>)a)((T)s);
			}
		}

		private static readonly Action<object?, object?> NoDoHandler = NoDoHandlerImpl;

		private static readonly Action<object?, object?> MonitorExitHandler = MonitorExitImpl;

		private static readonly Action<object?, object?> DisposableHandler = DisposableImpl;

		private static readonly Action<object?, object?> Disposable2Handler = Disposable2Impl;

		private static readonly Action<object?, object?> ActionHandler = ActionImpl;

		private static readonly Action<object?, object?> RemoveComponentHandler = RemoveComponentImpl;

		private static readonly Action<object?, object?> EndBatchUpdateHandler = EndBatchUpdateImpl;

		private object? _handler;

		private object? _state1;

		private object? _state2;

		public static ActionToken NoDo => new ActionToken(NoDoHandler, null, null);

		public readonly bool IsInitialized => _handler != null;

		public readonly bool IsRawDisposable => _handler == DisposableHandler;

		internal ActionToken(object handler, object? state, object? state2)
		{
			Should.NotBeNull(handler, "handler");
			_handler = handler;
			_state1 = state;
			_state2 = state2;
		}

		public static ActionToken FromRaw(object handler, object? state, object? state2)
		{
			Should.BeValid(handler.GetType() == typeof(Action<object, object>) || handler is IHandler, "handler");
			return new ActionToken(handler, state, state2);
		}

		public static ActionToken FromDisposable(IDisposable? disposable)
		{
			if (disposable != null)
			{
				return new ActionToken(DisposableHandler, disposable, null);
			}
			return default(ActionToken);
		}

		public static ActionToken FromHandler(IHandler handler, object? state1 = null, object? state2 = null)
		{
			return new ActionToken(handler, state1, state2);
		}

		public static ActionToken FromDelegate(Action<object?, object?> handler, object? state1 = null, object? state2 = null)
		{
			return new ActionToken(handler, state1, state2);
		}

		public static ActionToken FromDelegate<T>(T state, Action<T> handler) where T : class?
		{
			return new ActionToken(ClosureAction<T>.Closure, handler, state);
		}

		public static ActionToken FromDelegate(Action handler)
		{
			return new ActionToken(ActionHandler, handler, null);
		}

		public static ActionToken FromDisposables<T>(ItemOrIReadOnlyCollection<T> disposables) where T : IDisposable
		{
			if (disposables.HasItem)
			{
				if (!(typeof(T) == typeof(ActionToken)))
				{
					return FromDisposable(disposables.Item);
				}
				return (ActionToken)(object)disposables.Item;
			}
			if (disposables.List != null)
			{
				return FromDelegate(delegate(object? o, object? _)
				{
					foreach (T item in ItemOrIReadOnlyCollection.FromRawValue<T>(o))
					{
						if (item == null)
						{
							break;
						}
						item.Dispose();
					}
				}, disposables.List);
			}
			return default(ActionToken);
		}

		public static ActionToken Lock(object item)
		{
			Monitor.Enter(item);
			return new ActionToken(MonitorExitHandler, item, null);
		}

		public static ActionToken GetRemoveComponentToken(IComponentOwner owner, IComponent component)
		{
			return new ActionToken(RemoveComponentHandler, owner, component);
		}

		public static ActionToken BeginBatchUpdate(IReadOnlyObservableCollection collection, IReadOnlyMetadataContext? metadata = null)
		{
			if (collection.TryInvoke<IReadOnlyObservableCollection, BeginBatchCollectionRequest, bool?>(BeginBatchCollectionRequest.Instance, metadata) != true)
			{
				return default(ActionToken);
			}
			return new ActionToken(EndBatchUpdateHandler, collection, metadata);
		}

		[MustDisposeResource]
		[HandlesResourceDisposal]
		public IDisposable ToDisposable()
		{
			if (!IsRawDisposable)
			{
				return this;
			}
			return (IDisposable)_state1;
		}

		public override readonly bool Equals(object? obj)
		{
			if (obj is ActionToken other)
			{
				return Equals(other);
			}
			return false;
		}

		public override readonly int GetHashCode()
		{
			return HashCode.Combine(_handler, _state1, _state2);
		}

		public readonly void Deconstruct(out object? handler, out object? state1, out object? state2)
		{
			handler = _handler;
			state1 = _state1;
			state2 = _state2;
		}

		[MustDisposeResource]
		public ActionToken Merge([HandlesResourceDisposal] ActionToken other)
		{
			if (!other.IsInitialized)
			{
				return this;
			}
			if (IsRawDisposable && other.IsRawDisposable)
			{
				return FromDelegate(Disposable2Handler, _state1, other._state1);
			}
			return FromDisposables<ActionToken>(new ActionToken[2] { this, other });
		}

		public readonly void WriteTo<TList>(ref TList values) where TList : IList<object?>
		{
			object? handler = _handler;
			values.Add(handler);
			object? state = _state1;
			values.Add(state);
			object? state2 = _state2;
			values.Add(state2);
