			if (obj != null)
			{
				Dispose(obj, _state1, _state2);
				_state1 = null;
				_state2 = null;
			}
		}

		public readonly bool Equals(ActionToken other)
		{
			if (object.Equals(_handler, other._handler) && object.Equals(_state1, other._state1))
			{
				return object.Equals(_state2, other._state2);
			}
			return false;
		}

		internal static ActionToken FromTokens(object?[] tokens)
		{
			if (tokens.Length == 0)
			{
				return default(ActionToken);
			}
			return FromDelegate(delegate(object? o, object? _)
			{
				object[] array = (object[])o;
				for (int i = 0; i < array.Length && TryDispose(array, i); i += 3)
				{
				}
			}, tokens);
		}

		private static void Dispose(object handler, object? state1, object? state2)
		{
			if (handler is Action<object, object> action)
			{
				action(state1, state2);
			}
			else
			{
				((IHandler)handler).Invoke(state1, state2);
			}
		}

		private static bool TryDispose(IReadOnlyList<object?> values, int index)
		{
			object obj = values[index];
			if (obj == null)
			{
				return false;
			}
			Dispose(obj, values[index + 1], values[index + 2]);
			return true;
		}

		private static void MonitorExitImpl(object? state, object? _)
		{
			Monitor.Exit(state);
		}

		private static void DisposableImpl(object? state, object? _)
		{
			((IDisposable)state).Dispose();
		}

		private static void Disposable2Impl(object? state1, object? state2)
		{
			((IDisposable)state1).Dispose();
			((IDisposable)state2).Dispose();
		}

		private static void ActionImpl(object? state, object? _)
		{
			((Action)state)();
		}

		private static void RemoveComponentImpl(object? o, object? comp)
		{
			((IComponentOwner)o).Components.Remove(comp);
		}

		private static void EndBatchUpdateImpl(object? c, object? m)
		{
			((IReadOnlyObservableCollection)c).TryInvoke<IReadOnlyObservableCollection, EndBatchCollectionRequest, bool?>(EndBatchCollectionRequest.Instance, (IReadOnlyMetadataContext)m);
		}

		private static void NoDoHandlerImpl(object? arg1, object? arg2)
		{
		}
	}
	public sealed class AttachedValueContainer
	{
		private ListSlim<KeyValuePair<string, object?>> _values;

		public int Count => _values.Count;

		public bool ContainsKey(ReadOnlySpan<char> key)
		{
			return BinarySearch(key) > -1;
		}

		public bool TryGetValue(ReadOnlySpan<char> key, out object? value)
		{
			int num = BinarySearch(key);
			if (num < 0)
			{
				value = null;
				return false;
			}
			value = _values._items[num].Value;
			return true;
		}

		public void AddOrUpdate(ReadOnlySpan<char> key, object? value)
		{
			int num = BinarySearch(key);
			if (num < 0)
			{
				_values.Insert(~num, new KeyValuePair<string, object>(key.ToString(), value));
			}
			else
			{
				_values._items[num] = new KeyValuePair<string, object>(_values._items[num].Key, value);
			}
		}

		public bool AddOrUpdate(ReadOnlySpan<char> key, object? value, out object? oldValue)
		{
			int num = BinarySearch(key);
			if (num < 0)
			{
				oldValue = null;
				_values.Insert(~num, new KeyValuePair<string, object>(key.ToString(), value));
				return false;
			}
			oldValue = _values._items[num].Value;
			_values._items[num] = new KeyValuePair<string, object>(_values._items[num].Key, value);
			return true;
		}

		public bool Remove(ReadOnlySpan<char> key)
		{
			int num = BinarySearch(key);
			if (num < 0)
			{
				return false;
			}
			_values.RemoveAt(num);
			return true;
		}

		public bool Remove(ReadOnlySpan<char> key, out object? oldValue)
		{
			int num = BinarySearch(key);
			if (num < 0)
			{
				oldValue = null;
				return false;
			}
			oldValue = _values._items[num].Value;
			_values.RemoveAt(num);
			return true;
		}

		public void Clear()
		{
			_values.Clear();
		}

		public ArraySegmentEnumerator<KeyValuePair<string, object?>> GetEnumerator()
		{
			return _values.GetEnumerator();
		}

		private int BinarySearch(ReadOnlySpan<char> key)
		{
			KeyValuePair<string, object>[] items = _values._items;
			if (items == null)
			{
				return -1;
			}
			int num = 0;
			int num2 = _values.Count - 1;
			while (num <= num2)
			{
				int num3 = num + (num2 - num >> 1);
				int num4 = key.CompareTo(items[num3].Key, StringComparison.Ordinal);
				if (num4 == 0)
				{
					return num3;
				}
				if (num4 < 0)
				{
					num = num3 + 1;
				}
				else
				{
					num2 = num3 - 1;
				}
			}
			return ~num;
		}
	}
