		[MethodImpl(MethodImplOptions.NoInlining)]
		private static PooledReadOnlyList<KeyValuePair<string, object?>> GetValuesLock<TState>(AttachedValueContainer dictionary, object item, TState state, Func<object, string, object?, TState, bool>? predicate)
		{
			lock (dictionary)
			{
				return GetValues(dictionary, item, state, predicate);
			}
		}

		private static PooledReadOnlyList<KeyValuePair<string, object?>> GetValues<TState>(AttachedValueContainer dictionary, object item, TState state, Func<object, string, object?, TState, bool>? predicate)
		{
			if (dictionary.Count == 0)
			{
				return default(PooledReadOnlyList<KeyValuePair<string, object>>);
			}
			PooledItemOrList<KeyValuePair<string, object>> pooledItemOrList = default(PooledItemOrList<KeyValuePair<string, object>>);
			ArraySegmentEnumerator<KeyValuePair<string, object>> enumerator = dictionary.GetEnumerator();
			while (enumerator.MoveNext())
			{
				KeyValuePair<string, object> current = enumerator.Current;
				if (predicate == null || predicate(item, current.Key, current.Value, state))
				{
					pooledItemOrList.Add(new KeyValuePair<string, object>(current.Key, current.Value));
				}
			}
			return pooledItemOrList;
		}

