		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		[MemberNotNull(new string[] { "_storageManager", "_item" })]
		private void EnsureInitialized(bool optional)
		{
			if (_storageManager == null)
			{
				ExceptionManager.ThrowObjectNotInitialized(typeof(AttachedValueStorage), "EnsureInitialized");
			}
			if (_container == null)
			{
				_container = _storageManager.GetContainer(_item, optional);
			}
		}

		void IDisposable.Dispose()
		{
			if (!_inBatch)
			{
				ExceptionManager.ThrowObjectNotInitialized(typeof(AttachedValueStorage), "BatchUpdate");
			}
			_inBatch = false;
			Monitor.Exit(_container);
		}
