	public sealed class ClosureCheckerExpressionVisitor : ExpressionVisitor, IExpressionVisitor
	{
		private static readonly ClosureCheckerExpressionVisitor Instance = new ClosureCheckerExpressionVisitor();

		private static readonly Lock Locker = new Lock();

		private bool _hasClosure;

		public ExpressionTraversalType TraversalType => ExpressionTraversalType.Postorder;

		private ClosureCheckerExpressionVisitor()
		{
		}

		public static bool HasClosure(Expression expression)
		{
			using (Locker.EnterScope())
			{
				Instance._hasClosure = false;
				Instance.Visit(expression);
				return Instance._hasClosure;
			}
		}

		public static bool HasClosure(IExpressionNode expression)
		{
			using (Locker.EnterScope())
			{
				Instance._hasClosure = false;
				expression.Accept(Instance);
				return Instance._hasClosure;
			}
		}

		IExpressionNode IExpressionVisitor.Visit(IExpressionNode expression, IReadOnlyMetadataContext? metadata)
		{
			if (!_hasClosure && expression is IConstantExpressionNode constantExpressionNode)
			{
				CheckClosure(constantExpressionNode.Type);
			}
			return expression;
		}

		protected override Expression VisitConstant(ConstantExpression node)
		{
			if (!_hasClosure)
			{
				CheckClosure(node.Type);
			}
			return base.VisitConstant(node);
		}

		private void CheckClosure(Type type)
		{
			TypeCode typeCode = Type.GetTypeCode(type);
			if ((uint)typeCode <= 2u)
			{
				_hasClosure = true;
			}
		}
	}
