	public sealed class ConditionalWeakTableAttachedValueStorage : AttachedValueStorageProviderBase<object>, IHasPriority
	{
		private readonly ConditionalWeakTable<object, AttachedValueContainer> _weakTable;

		public int Priority { get; init; } = 7000;

		public ConditionalWeakTableAttachedValueStorage()
		{
			_weakTable = new ConditionalWeakTable<object, AttachedValueContainer>();
		}

		protected override AttachedValueContainer? GetAttachedContainer(object item, bool optional)
		{
			if (optional)
			{
				_weakTable.TryGetValue(item, out AttachedValueContainer value);
				return value;
			}
			return _weakTable.GetValue(item, (object _) => new AttachedValueContainer());
