	public static class Default
	{
		private static class SelectorImpl<T>
		{
			public static readonly Func<T, T> Value = DefaultFunc;

			private static T DefaultFunc(T v)
			{
				return v;
			}
		}

		internal static readonly PropertyChangedEventArgs EmptyPropertyChangedArgs = new PropertyChangedEventArgs(string.Empty);

		internal static readonly PropertyChangedEventArgs CountPropertyChangedArgs = new PropertyChangedEventArgs("Count");

		internal static readonly PropertyChangedEventArgs IndexerPropertyChangedArgs = new PropertyChangedEventArgs("Item[]");

		internal static readonly PropertyChangedEventArgs ValueChangedArgs = new PropertyChangedEventArgs("Value");

		internal static readonly PropertyChangedEventArgs IsSuspendedEventArgs = new PropertyChangedEventArgs("IsSuspended");

		internal static readonly NotifyCollectionChangedEventArgs ResetCollectionEventArgs = new NotifyCollectionChangedEventArgs(NotifyCollectionChangedAction.Reset);

		internal static Action NoDoAction = delegate
		{
		};

		internal static bool FalseCondition;

		private static int _counter;

		private static int _typeCounter;

		private static int _decoratedCollectionPriority;

		private static readonly Lock Locker = new Lock();

		private static DictionarySlim<Type, int> _typeToId = new DictionarySlim<Type, int>();

		public static Func<T, T> Selector<T>()
		{
			return SelectorImpl<T>.Value;
		}

		public static IEnumerator<T> Enumerator<T>()
		{
