		}

		public static int GetIdByType(Type type)
		{
			using (Locker.EnterScope())
			{
				bool hasValue;
				ref int orAddValueRef = ref _typeToId.GetOrAddValueRef(type, out hasValue);
				if (!hasValue)
				{
					orAddValueRef = _typeCounter++;
				}
				return orAddValueRef;
			}
		}

		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		internal static int NextCounter()
		{
			return Interlocked.Increment(ref _counter);
		}

		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		internal static int NextDecoratedCollectionPriority()
		{
			return Interlocked.Increment(ref _decoratedCollectionPriority);
		}
