	public static class DelayAction
	{
		public sealed class Handler<TDelegate, TState> : IHasDisposedState, IDisposable where TDelegate : Delegate
		{
			private readonly Action<TDelegate, TState?> _action;

			private readonly int _delay;

			private TDelegate? _target;

			private Timer? _timer;

			private TState? _state;

			public bool IsDisposed => _timer == null;

			public Handler(TDelegate target, int delay, Action<TDelegate, TState?> action)
			{
				Should.NotBeNull(target, "target");
				Should.NotBeNull(action, "action");
				_target = target;
				_delay = delay;
				_action = action;
				_timer = WeakTimer.Get(this, delegate(Handler<TDelegate, TState> h)
				{
					h.Handle();
				});
			}

			public void Invoke(TState? state)
			{
				_state = state;
				int delay = GetDelay(_delay);
				if (delay == 0)
				{
					Handle();
				}
				else
				{
					_timer?.SafeChange(delay, -1);
				}
			}

			public void Dispose()
			{
				_timer?.Dispose();
				_timer = null;
				_target = null;
			}

			private void Handle()
			{
				TDelegate target = _target;
				if (target != null)
				{
					_action(target, _state);
				}
			}
		}

		public static int? DelayOverride;

		[ThreadStatic]
		public static int? DelayOverrideThreadStatic;

		public static int GetDelay(int delay)
		{
			return DelayOverrideThreadStatic.GetValueOrDefault(DelayOverride ?? delay);
		}

		public static Action<T> Get<T>(int delay, Action<T> action)
		{
			return action.WithDelay(delay);
		}

		public static Action<T1, T2> Get<T1, T2>(int delay, Action<T1, T2> action)
		{
			return action.WithDelay(delay);
		}

		public static Action<T1, T2, T3> Get<T1, T2, T3>(int delay, Action<T1, T2, T3> action)
		{
			return action.WithDelay(delay);
		}

		public static Action<T1, T2, T3, T4> Get<T1, T2, T3, T4>(int delay, Action<T1, T2, T3, T4> action)
		{
			return action.WithDelay(delay);
		}

		public static Action<T1, T2, T3, T4, T5> Get<T1, T2, T3, T4, T5>(int delay, Action<T1, T2, T3, T4, T5> action)
		{
			return action.WithDelay(delay);
		}

		public static Action<T> WithDelay<T>(this Action<T> action, int delay)
		{
			if (delay <= 0)
			{
				return action;
			}
			return new Handler<Action<T>, T>(action, delay, delegate(Action<T> del, T? s)
			{
				del(s);
			}).Invoke;
		}

		public static Action<T1, T2> WithDelay<T1, T2>(this Action<T1, T2> action, int delay)
		{
			if (delay <= 0)
			{
				return action;
			}
			return new Handler<Action<T1, T2>, (T1, T2)>(action, delay, delegate(Action<T1, T2> del, (T1, T2) s)
			{
				del(s.Item1, s.Item2);
			}).Invoke<T1, T2>;
		}

		public static Action<T1, T2, T3> WithDelay<T1, T2, T3>(this Action<T1, T2, T3> action, int delay)
		{
			if (delay <= 0)
			{
				return action;
			}
			return new Handler<Action<T1, T2, T3>, (T1, T2, T3)>(action, delay, delegate(Action<T1, T2, T3> del, (T1, T2, T3) s)
			{
				del(s.Item1, s.Item2, s.Item3);
			}).Invoke<T1, T2, T3>;
		}

		public static Action<T1, T2, T3, T4> WithDelay<T1, T2, T3, T4>(this Action<T1, T2, T3, T4> action, int delay)
		{
			if (delay <= 0)
			{
				return action;
			}
			return new Handler<Action<T1, T2, T3, T4>, (T1, T2, T3, T4)>(action, delay, delegate(Action<T1, T2, T3, T4> del, (T1, T2, T3, T4) s)
			{
				del(s.Item1, s.Item2, s.Item3, s.Item4);
			}).Invoke<T1, T2, T3, T4>;
		}

		public static Action<T1, T2, T3, T4, T5> WithDelay<T1, T2, T3, T4, T5>(this Action<T1, T2, T3, T4, T5> action, int delay)
		{
			if (delay <= 0)
			{
				return action;
			}
			return new Handler<Action<T1, T2, T3, T4, T5>, (T1, T2, T3, T4, T5)>(action, delay, delegate(Action<T1, T2, T3, T4, T5> del, (T1, T2, T3, T4, T5) s)
			{
				del(s.Item1, s.Item2, s.Item3, s.Item4, s.Item5);
			}).Invoke<T1, T2, T3, T4, T5>;
		}

		private static void Invoke<T1, T2>(this Handler<Action<T1, T2>, (T1, T2)> action, T1 arg1, T2 arg2)
		{
			action.Invoke((arg1, arg2));
		}

		private static void Invoke<T1, T2, T3>(this Handler<Action<T1, T2, T3>, (T1, T2, T3)> action, T1 arg1, T2 arg2, T3 arg3)
		{
			action.Invoke((arg1, arg2, arg3));
		}

		private static void Invoke<T1, T2, T3, T4>(this Handler<Action<T1, T2, T3, T4>, (T1, T2, T3, T4)> action, T1 arg1, T2 arg2, T3 arg3, T4 arg4)
		{
			action.Invoke((arg1, arg2, arg3, arg4));
		}

		private static void Invoke<T1, T2, T3, T4, T5>(this Handler<Action<T1, T2, T3, T4, T5>, (T1, T2, T3, T4, T5)> action, T1 arg1, T2 arg2, T3 arg3, T4 arg4, T5 arg5)
		{
			action.Invoke((arg1, arg2, arg3, arg4, arg5));
		}
	}
