		{
			return EqualityComparer<T>.Default.GetHashCode(Target);
		}

		public Disposable<T> NonDisposable()
		{
			if (_state == 0)
			{
				return default(Disposable<T>);
			}
			return new Disposable<T>(Target, 1);
		}

		public void Dispose()
		{
			if (IsDisposable)
			{
				Target.Dispose();
			}
		}

		public bool Equals(Disposable<T> other)
