				}
				if (id == null)
				{
					return _disposeTokens.ToPooledReadOnlyList();
				}
				PooledItemOrList<KeyValuePair<string, ActionToken>> pooledItemOrList = default(PooledItemOrList<KeyValuePair<string, ActionToken>>);
				ArraySegmentEnumerator<KeyValuePair<string, ActionToken>> enumerator = _disposeTokens.GetEnumerator();
				while (enumerator.MoveNext())
