					return false;
				}
				_disposeTokens._count = ~_disposeTokens.Count;
				return true;
			}
		}

		public void EndDispose()
		{
			Should.BeValid(IsDisposed && _disposeTokens.Count != int.MinValue, "IsDisposed");
			ListSlim<KeyValuePair<string, ActionToken>> disposeTokens = _disposeTokens;
			if (disposeTokens._items != null)
			{
				disposeTokens._count = ~disposeTokens.Count;
				for (int i = 0; i < disposeTokens.ReadOnlySpan.Length; i++)
				{
					disposeTokens.ReadOnlySpan[i].Value.Dispose();
