	public sealed class MetadataOwnerAttachedValueStorage : AttachedValueStorageProviderBase<IMetadataOwner<ICompositeMetadataContext>>, IHasPriority
	{
		public int Priority { get; init; } = 8000;

		protected override AttachedValueContainer? GetAttachedContainer(IMetadataOwner<ICompositeMetadataContext> item, bool optional)
		{
			if (!optional)
			{
				return item.Metadata.GetOrAdd(InternalMetadata.AttachedValuesKey);
			}
			if (item is ILazyMetadataOwner<ICompositeMetadataContext> lazyMetadataOwner)
			{
				return lazyMetadataOwner.MetadataOptional?.Get(InternalMetadata.AttachedValuesKey);
			}
			return item.Metadata.Get(InternalMetadata.AttachedValuesKey);
		}

		protected override bool ClearCore(IMetadataOwner<ICompositeMetadataContext> item)
		{
			object oldValue;
			return item.Metadata.Remove(InternalMetadata.AttachedValuesKey, out oldValue);
		}
	}
	internal sealed class NullableFromToTypeConverter<TFrom, TTo> : TypeConverterBase<TFrom?, TTo?> where TFrom : struct where TTo : struct
	{
		public override bool TryConvert(TFrom? from, out TTo? value)
		{
			if (!from.HasValue)
			{
				value = null;
				return true;
			}
			if (MugenExtensions.TryConvert<TFrom, TTo>(from.GetValueOrDefault(), out var result))
			{
				value = result;
				return true;
			}
			value = null;
			return false;
		}
	}
	internal sealed class NullableFromTypeConverter<TFrom, TTo> : TypeConverterBase<TFrom?, TTo> where TFrom : struct
	{
		public override bool TryConvert(TFrom? from, [MaybeNullWhen(false)] out TTo value)
		{
			if (!from.HasValue)
			{
				value = default(TTo);
				return true;
			}
			return MugenExtensions.TryConvert<TFrom, TTo>(from.GetValueOrDefault(), out value);
		}
	}
	internal sealed class NullableToTypeConverter<TFrom, TTo> : TypeConverterBase<TFrom, TTo?> where TTo : struct
	{
		public override bool TryConvert(TFrom from, out TTo? value)
		{
			if (from == null)
			{
				value = null;
				return true;
			}
			if (MugenExtensions.TryConvert<TFrom, TTo>(from, out var result))
			{
				value = result;
				return true;
			}
			value = null;
			return false;
		}
	}
	public static class Optional
	{
		[StructLayout(LayoutKind.Sequential, Size = 1)]
		public readonly struct N
		{
		}

		[StructLayout(LayoutKind.Sequential, Size = 1)]
		public readonly struct D
		{
		}

		public static N None => default(N);

		public static D Default => default(D);

		public static Optional<T> Get<T>(T? value)
		{
			return new Optional<T>(value, value != null);
		}

		public static Optional<T> Get<T>(T? value) where T : struct
		{
			return new Optional<T>(value.GetValueOrDefault(), value.HasValue);
		}

		public static Optional<T> Get<T>(T? value, bool hasValue)
		{
			return new Optional<T>(value, hasValue);
		}

		public static Optional<T> GetNullable<T>(T? value) where T : class
		{
			return new Optional<T>(value);
		}
	}
	[StructLayout(LayoutKind.Auto)]
	[DebuggerDisplay("{_value}, HasValue={HasValue}")]
	public readonly struct Optional<T> : IOptional, IHasInitializedState, IEquatable<Optional<T>>, IInner<T>, IHasDefaultValue<Optional<T>>, IConvertible<Optional<T>>
	{
		private readonly T? _value;

		public bool HasValue { get; }

		[MemberNotNullWhen(true, "Value")]
		public bool HasNonNullValue
		{
			[MemberNotNullWhen(true, "Value")]
			get
			{
				if (HasValue)
				{
					return Value != null;
				}
				return false;
			}
		}

		public T? Value
		{
			get
			{
				if (!HasValue)
				{
					ExceptionManager.ThrowOptionalNoValue();
				}
				return _value;
			}
		}

		public bool IsInitialized => HasValue;

		object? IOptional.Value => Value;

		T IInner<T>.Inner => _value;

		public Optional(T? value)
		{
			_value = value;
			HasValue = true;
		}

		public Optional(T? value, bool hasValue)
		{
			_value = value;
			HasValue = hasValue;
		}

		public static implicit operator Optional<T>(T? value)
		{
			return new Optional<T>(value);
		}

		public static implicit operator Optional<T>(Optional.N _)
		{
			return default(Optional<T>);
		}

		public static implicit operator Optional<T>(Optional.D _)
		{
			return new Optional<T>(default(T));
		}

		public static implicit operator Unit(Optional<T> _)
		{
			return default(Unit);
		}

		public static explicit operator T?(Optional<T> value)
		{
			return value.Value;
		}

		public static bool operator ==(Optional<T> left, Optional<T> right)
		{
			return left.Equals(right);
		}

		public static bool operator !=(Optional<T> left, Optional<T> right)
		{
			return !left.Equals(right);
		}

		public static Optional<T> Cast<TFrom>(TFrom? value)
		{
			return new Optional<TFrom>(value).Cast<T>();
		}

		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public T? GetValueOrDefault()
		{
			return _value;
		}

		public T? GetValueOrDefault(T defaultValue)
		{
			if (HasValue)
			{
				return _value;
			}
			return defaultValue;
		}

		public Optional<TTo> Cast<TTo>()
		{
			if (!HasValue)
			{
				return default(Optional<TTo>);
			}
			if (!(typeof(TTo) == typeof(Unit)))
			{
				return new Optional<TTo>((TTo)(object)Value);
			}
			return Optional.Default;
		}

		public Optional<Unit> AsVoid()
		{
			return HasValue ? Optional.Default : default(Optional.D);
		}

		public bool Equals(Optional<T> other)
		{
			if (HasValue == other.HasValue)
			{
				return EqualityComparer<T>.Default.Equals(_value, other._value);
			}
			return false;
		}

		public Optional<T> ToDefaultValue()
		{
			return new Optional<T>(default(T));
		}

		public override bool Equals(object? obj)
		{
			if (obj is Optional<T> other)
			{
				return Equals(other);
			}
			return false;
		}

		public override int GetHashCode()
		{
			return (HasValue.GetHashCode() * 397) ^ EqualityComparer<T>.Default.GetHashCode(_value);
		}

		public override string ToString()
		{
			if (!HasValue)
			{
				return "none";
			}
			T value = _value;
			if (value == null)
			{
				return null;
			}
			return value.ToString();
		}

		object? IOptional.GetValueOrDefault()
		{
			return GetValueOrDefault();
		}

		bool IConvertible<Optional<T>>.TryConvertTo<TTo>(Optional<T> from, out TTo to)
		{
			if (typeof(TTo).IsAssignableFrom(typeof(T)))
			{
				to = (TTo)(object)_value;
				return true;
			}
			to = default(TTo);
			return false;
		}

		bool IConvertible<Optional<T>>.TryConvertFrom<TFrom>(TFrom from, out Optional<T> to)
		{
			if (typeof(T).IsAssignableFrom(typeof(TFrom)))
			{
				to = Optional.Get((T)(object)from);
				return true;
			}
			to = default(Optional<T>);
			return false;
		}
	}
	[DebuggerDisplay("PriorityLocker{_priority}")]
	public sealed class PriorityLocker : ILocker, IHasPriority
	{
		private static int _counter = 50;

		private static int? _uiThreadId;

		private readonly int _priority;

		private readonly Lock _locker;

		private int _priorityThreadWaitCount;

		private int _lockCount;

		private ListSlim<object> _unlockHandlers;

		public static int? UiThreadId
		{
			[MethodImpl(MethodImplOptions.AggressiveInlining)]
			get
			{
				return _uiThreadId ?? (_uiThreadId = CheckUiThread());
			}
		}

		public int Priority => _priority;

		public PriorityLocker()
		{
			_locker = new Lock();
			_priority = Interlocked.Decrement(ref _counter);
		}

		public bool IsEntered()
		{
			if (_lockCount != 0)
			{
				return _locker.IsHeldByCurrentThread;
			}
			return false;
		}

		public void Enter()
		{
			int? uiThreadId = UiThreadId;
			if (!uiThreadId.HasValue || _locker.IsHeldByCurrentThread)
			{
				_locker.Enter();
			}
			else
			{
				Enter(uiThreadId == Environment.CurrentManagedThreadId);
			}
			_lockCount++;
		}

		public bool TryEnter(int timeout)
		{
			int? uiThreadId = UiThreadId;
			bool flag = ((uiThreadId.HasValue && timeout != 0 && !_locker.IsHeldByCurrentThread) ? TryEnter(uiThreadId == Environment.CurrentManagedThreadId, timeout) : _locker.TryEnter(timeout));
			if (flag)
			{
				_lockCount++;
			}
			return flag;
		}

		public void Exit()
		{
			if (--_lockCount == 0 && _unlockHandlers.Count != 0)
			{
				ExitSlow();
			}
			else
			{
				_locker.Exit();
			}
		}

		public bool TryRegisterUnlockHandler(IUnlockHandler handler)
		{
			if (_lockCount == 0 || !_locker.IsHeldByCurrentThread)
			{
				return false;
			}
			if (!_unlockHandlers.Contains(handler))
			{
				_unlockHandlers.Add(handler);
			}
			return true;
		}

		[MethodImpl(MethodImplOptions.NoInlining)]
		private static int? CheckUiThread()
		{
			if (IMugenService<IMugenApplication>.Instance.CanExecuteInline(ThreadExecutionMode.Main))
			{
				return Environment.CurrentManagedThreadId;
			}
			return null;
		}

		private void ExitSlow()
		{
			InlineObjectArray inlineObjectArray = new InlineObjectArray(_unlockHandlers.ReadOnlySpan);
			_unlockHandlers.Clear();
			_locker.Exit();
			Span<object> span = inlineObjectArray.Span;
			for (int i = 0; i < span.Length; i++)
			{
				((IUnlockHandler)span[i]).OnUnlocked(this);
			}
			inlineObjectArray.Dispose();
		}

		private bool TryEnter(bool isHighPriorityThread, int timeout)
		{
			long tickCount = Environment.TickCount64;
			SpinWait spinWait = default(SpinWait);
			if (isHighPriorityThread)
			{
				Interlocked.Increment(ref _priorityThreadWaitCount);
			}
			while (true)
			{
				if (!isHighPriorityThread)
				{
					while (Volatile.Read(in _priorityThreadWaitCount) != 0)
					{
						spinWait.SpinOnce();
						if (Environment.TickCount64 - tickCount >= timeout)
						{
							return false;
						}
					}
				}
				bool flag = _locker.TryEnter(0);
				if (Environment.TickCount64 - tickCount >= timeout)
				{
					if (isHighPriorityThread)
					{
						Interlocked.Decrement(ref _priorityThreadWaitCount);
					}
					return flag;
				}
				if (flag)
				{
					if (isHighPriorityThread)
					{
						Interlocked.Decrement(ref _priorityThreadWaitCount);
						return true;
					}
					if (Volatile.Read(in _priorityThreadWaitCount) == 0)
					{
						break;
					}
					_locker.Exit();
				}
				spinWait.SpinOnce();
			}
			return true;
		}

		private void Enter(bool isHighPriorityThread)
		{
			if (isHighPriorityThread)
			{
				Interlocked.Increment(ref _priorityThreadWaitCount);
			}
			SpinWait spinWait = default(SpinWait);
			while (true)
			{
				if (!isHighPriorityThread)
				{
					while (Volatile.Read(in _priorityThreadWaitCount) != 0)
					{
						spinWait.SpinOnce();
					}
				}
				_locker.Enter();
				if (isHighPriorityThread)
				{
					Interlocked.Decrement(ref _priorityThreadWaitCount);
					break;
				}
				if (Volatile.Read(in _priorityThreadWaitCount) == 0)
				{
					break;
				}
				_locker.Exit();
				spinWait.SpinOnce();
			}
		}
	}
	public static class SortingComparerBuilder
	{
		public delegate ChildBuilder<T> BuilderDelegate<T>(Builder<T> builder);

		[StructLayout(LayoutKind.Sequential, Size = 1)]
		public ref struct Builder<T>
		{
			public ChildBuilder<T> Ascending()
			{
				return new ChildBuilder<T>(SortingInfo<T>.Create(isDescending: false));
			}

			public ChildBuilder<T> Ascending<TValue>(Func<T, TValue> expression)
			{
				return new ChildBuilder<T>(SortingInfo<T>.Create(expression, isDescending: false));
			}

			public ChildBuilder<T> Descending()
			{
				return new ChildBuilder<T>(SortingInfo<T>.Create(isDescending: true));
			}

			public ChildBuilder<T> Descending<TValue>(Func<T, TValue> expression)
			{
				return new ChildBuilder<T>(SortingInfo<T>.Create(expression, isDescending: true));
			}

			public ChildBuilder<T> Compare(Func<T, T, int> compare)
			{
				return new ChildBuilder<T>(SortingInfo<T>.Create(compare));
			}
		}

		public ref struct ChildBuilder<T>
		{
			private ItemOrList<SortingInfo<T>> _sortInfo;

			internal ChildBuilder(SortingInfo<T> sortingInfo)
			{
				_sortInfo = new ItemOrList<SortingInfo<T>>(2) { sortingInfo };
			}

			public ChildBuilder<T> ThenBy()
			{
				_sortInfo.Add(SortingInfo<T>.Create(isDescending: false));
				return this;
			}

			public ChildBuilder<T> ThenBy<TValue>(Func<T, TValue> expression)
			{
				_sortInfo.Add(SortingInfo<T>.Create(expression, isDescending: false));
				return this;
			}

			public ChildBuilder<T> ThenByDescending()
			{
				_sortInfo.Add(SortingInfo<T>.Create(isDescending: true));
				return this;
			}

			public ChildBuilder<T> ThenByDescending<TValue>(Func<T, TValue> expression)
			{
				_sortInfo.Add(SortingInfo<T>.Create(expression, isDescending: true));
				return this;
			}

			public ChildBuilder<T> ThenCompare(Func<T, T, int> compare)
			{
				_sortInfo.Add(SortingInfo<T>.Create(compare));
				return this;
			}

			public Comparer<T> Build()
			{
				if (_sortInfo.Count == 1)
				{
					return _sortInfo[0].ToComparer(isObject: false);
				}
				return new SortingComparer<T>(_sortInfo.ToArray());
			}

			public IComparer<object?> BuildObject()
			{
				if (_sortInfo.Count == 1)
				{
					return (IComparer<object>)_sortInfo[0].ToComparer(isObject: true);
				}
				return new SortingComparer<T>(_sortInfo.ToArray());
			}
		}

		[StructLayout(LayoutKind.Auto)]
		internal readonly struct SortingInfo<T>
		{
			private readonly Delegate? _expression;

			private readonly Func<Delegate, bool, T, T, int>? _compare;

			private readonly bool _isDescending;

			private SortingInfo(Func<Delegate, bool, T, T, int>? compare, Delegate? expression, bool isDescending)
			{
				_compare = compare;
				_expression = expression;
				_isDescending = isDescending;
			}

			public int Compare(T x, T y)
			{
				if (_compare == null)
				{
					if (_isDescending)
					{
						return Comparer<T>.Default.Compare(y, x);
					}
					return Comparer<T>.Default.Compare(x, y);
				}
				return _compare(_expression, _isDescending, x, y);
			}

			public Comparer<T> ToComparer(bool isObject)
			{
				if ((object)_expression == null)
				{
					if (_isDescending)
					{
						return DescendingComparer<T>.Instance;
					}
					if (isObject)
					{
						return ObjectComparer<T>.Instance;
					}
					return Comparer<T>.Default;
				}
				return new SingleComparer<T>(_expression, _compare, _isDescending);
			}

			public static SortingInfo<T> Create(bool isDescending)
			{
				return new SortingInfo<T>(null, null, isDescending);
			}

			public static SortingInfo<T> Create<TValue>(Func<T, TValue> expression, bool isDescending)
			{
				Should.NotBeNull(expression, "expression");
				return new SortingInfo<T>(delegate(Delegate exp, bool isDesc, T x, T y)
				{
					Func<T, TValue> func = Unsafe.As<Func<T, TValue>>(exp);
					return isDesc ? Comparer<TValue>.Default.Compare(func(y), func(x)) : Comparer<TValue>.Default.Compare(func(x), func(y));
				}, expression, isDescending);
			}

			public static SortingInfo<T> Create(Func<T, T, int> compare)
			{
				Should.NotBeNull(compare, "compare");
				return new SortingInfo<T>((Delegate exp, bool _, T x, T y) => Unsafe.As<Func<T, T, int>>(exp)(x, y), compare, isDescending: false);
			}
		}

		internal sealed class ObjectComparer<T> : Comparer<T>, IComparer<object?>
		{
			public static readonly ObjectComparer<T> Instance = new ObjectComparer<T>();

			private ObjectComparer()
			{
			}

			public override int Compare(T? x, T? y)
			{
				return Comparer<T>.Default.Compare(x, y);
			}

			int IComparer<object>.Compare(object? x, object? y)
			{
				if (x is T x2)
				{
					if (y is T y2)
					{
						return Compare(x2, y2);
					}
					return -1;
				}
				if (y is T)
				{
					return 1;
				}
				return 0;
			}
		}

		internal sealed class SingleComparer<T> : Comparer<T>, IComparer<object?>
		{
			private readonly Delegate _expression;

			private readonly Func<Delegate, bool, T, T, int> _compare;

			private readonly bool _isDescending;

			public SingleComparer(Delegate expression, Func<Delegate, bool, T, T, int> compare, bool isDescending)
			{
				_expression = expression;
				_compare = compare;
				_isDescending = isDescending;
			}

			public override int Compare(T? x, T? y)
			{
				return _compare(_expression, _isDescending, x, y);
			}

			int IComparer<object>.Compare(object? x, object? y)
			{
				if (x is T arg)
				{
					if (y is T arg2)
					{
						return _compare(_expression, _isDescending, arg, arg2);
					}
					return -1;
				}
				if (y is T)
				{
					return 1;
				}
				return 0;
			}
		}

		internal sealed class DescendingComparer<T> : Comparer<T>, IComparer<object?>
		{
			public static readonly DescendingComparer<T> Instance = new DescendingComparer<T>();

			private DescendingComparer()
			{
			}

			public override int Compare(T? x, T? y)
			{
				return Comparer<T>.Default.Compare(y, x);
			}

			int IComparer<object>.Compare(object? x, object? y)
			{
				if (x is T y2)
				{
					if (y is T x2)
					{
						return Comparer<T>.Default.Compare(x2, y2);
					}
					return -1;
				}
				if (y is T)
				{
					return 1;
				}
				return 0;
			}
		}

		private sealed class SortingComparer<T> : Comparer<T>, IComparer<object?>
		{
			private readonly SortingInfo<T>[] _sortInfo;

			public SortingComparer(SortingInfo<T>[] sortInfo)
			{
				_sortInfo = sortInfo;
			}

			public override int Compare(T? x, T? y)
			{
				SortingInfo<T>[] sortInfo = _sortInfo;
				foreach (SortingInfo<T> sortingInfo in sortInfo)
				{
					int num = sortingInfo.Compare(x, y);
					if (num != 0)
					{
						return num;
					}
				}
				return 0;
			}

			int IComparer<object>.Compare(object? x, object? y)
			{
				if (x is T x2)
				{
					if (y is T y2)
					{
						return Compare(x2, y2);
					}
					return -1;
				}
				if (y is T)
				{
					return 1;
				}
				return 0;
			}
		}

		public static Builder<T> Get<T>()
		{
			return default(Builder<T>);
		}
	}
	public sealed class StaticTypeAttachedValueStorage : AttachedValueStorageProviderBase<Type>, IHasPriority
	{
		private readonly Lock _locker = new Lock();

		private DictionarySlim<Type, AttachedValueContainer> _attachedValues = new DictionarySlim<Type, AttachedValueContainer>(7);

		public int Priority { get; init; } = 10000;

		protected override AttachedValueContainer? GetAttachedContainer(Type item, bool optional)
		{
			using (_locker.EnterScope())
			{
				ref AttachedValueContainer orAddValueRef = ref _attachedValues.GetOrAddValueRef(item);
				if (optional || orAddValueRef != null)
				{
					return orAddValueRef;
				}
				orAddValueRef = new AttachedValueContainer();
				return orAddValueRef;
			}
		}

		protected override bool ClearCore(Type item)
		{
			using (_locker.EnterScope())
			{
				return _attachedValues.Remove(item);
			}
		}
	}
	internal sealed class StringParsableTypeConverter<TTo> : TypeConverterBase<string, TTo> where TTo : IParsable<TTo>
	{
		public override bool TryConvert(string from, [MaybeNullWhen(false)] out TTo value)
		{
			return TTo.TryParse(from, CultureInfo.InvariantCulture, out value);
