	{
		private sealed class Impl<TState> : BusyCommandHandler, IHasReadOnlyValue<TState>, IHasReadOnlyValue
		{
			private readonly Func<ICompositeCommand, TState, IReadOnlyMetadataContext?, (int delay, int postDelay, object? message)?> _getMessage;

			public TState Value { get; }

			internal Impl(IBusyManager busyManager, TState state, Func<ICompositeCommand, TState, IReadOnlyMetadataContext?, (int delay, int postDelay, object? message)?> getMessage)
				: base(busyManager)
			{
				Value = state;
