			}

			protected override (int delay, int postDelay, object? message)? GetMessage(ICompositeCommand command, IReadOnlyMetadataContext? metadata)
			{
				return _getMessage(command, Value, metadata);
			}
		}

		private readonly IBusyManager _busyManager;

		private ICompositeCommand? _owner;

		private byte _busyState;

		private IBusyToken? _token;

		protected BusyCommandHandler(IBusyManager busyManager)
		{
			Should.NotBeNull(busyManager, "busyManager");
			_busyManager = busyManager;
		}

		public static BusyCommandHandler Get<TState>(IBusyManager busyManager, TState state, Func<ICompositeCommand, TState, IReadOnlyMetadataContext?, (int delay, int postDelay, object? message)?> getMessage)
		{
			return new Impl<TState>(busyManager, state, getMessage);
		}

		public Unit TryInvoke(RaiseCanExecuteChangedCommandRequest request, ICompositeCommand apiProvider, IReadOnlyMetadataContext? metadata, CancellationToken cancellationToken)
		{
			Invalidate(apiProvider, null, metadata);
			return default(Unit);
		}

		public void OnAttached(ICompositeCommand owner, IReadOnlyMetadataContext? metadata)
		{
			if (_owner != null)
			{
				ExceptionManager.ThrowObjectInitialized(this, "OnAttached");
			}
			_owner = owner;
			Invalidate(owner, null, metadata);
		}

		public void OnDetached(ICompositeCommand owner, IReadOnlyMetadataContext? metadata)
		{
			_token?.Dispose();
			_owner = null;
		}

		protected abstract (int delay, int postDelay, object? message)? GetMessage(ICompositeCommand command, IReadOnlyMetadataContext? metadata);

		private async void Invalidate(ICompositeCommand? command, int? delay, IReadOnlyMetadataContext? metadata)
		{
			if (command == null || !command.IsExecuting(metadata) || Interlocked.Exchange(ref _busyState, 1) != 0)
			{
				return;
			}
			IBusyToken token = null;
			bool repeat = true;
			try
			{
				(int delay, int postDelay, object? message)? message = GetMessage(command, metadata);
				if (!message.HasValue)
				{
					repeat = false;
					return;
				}
				token = _busyManager.TryBeginBusy(message.Value.message, delay ?? message.Value.delay, metadata);
				if (token == null)
				{
					repeat = false;
					return;
				}
				_token = token;
				while (command.IsExecuting(metadata))
				{
					await command.WaitAsync(metadata).ConfigureAwait(continueOnCapturedContext: false);
					if (message.Value.postDelay != 0 && token.IsActive)
					{
						await Task.Delay(message.Value.postDelay).ConfigureAwait(continueOnCapturedContext: false);
					}
				}
			}
			finally
			{
				Interlocked.Exchange(ref _busyState, 0);
				if (repeat)
				{
					Invalidate(_owner, 0, metadata);
				}
				token?.Dispose();
			}
		}
