		{
			_index = -1;
			_count = itemOrList.Count;
			_item = itemOrList.Item;
			_array = itemOrList.List;
			_version = 0;
		}

		public ArraySegmentEnumerator(PooledArray<T> pooledArray)
			: this(pooledArray._arrayRef, 0, pooledArray.Count, pooledArray._version)
		{
		}

		private ArraySegmentEnumerator(object? arrayRaw, int index, int count, int version)
		{
