	{
		internal interface IHandler
		{
			int Version { get; }

			bool IsReset { get; }

			void ResetRaw(ICollectionDecorator? decorator);

			void RaiseItemChangedRaw(object? item, object? args);

			void ResetCounter();
		}

		internal readonly Lock Locker;

		private DictionarySlim<PendingItemKey, object?> _pendingChangedItems;

		private int _workerState;

		public IReadOnlyObservableCollection? Owner { get; set; }

		public BatchActionCollectionManager()
		{
			Locker = new Lock();
			_pendingChangedItems = new DictionarySlim<PendingItemKey, object>();
			_workerState = 0;
		}

		public Unit TryInvoke(OnEndBatchCollectionRequest request, IReadOnlyObservableCollection apiProvider, IReadOnlyMetadataContext? metadata, CancellationToken cancellationToken)
		{
			RunIfNeed();
			return default(Unit);
		}

		public Unit TryInvoke(OnUnlockedRequest<IReadOnlyObservableCollection> request, IReadOnlyObservableCollection apiProvider, IReadOnlyMetadataContext? metadata, CancellationToken cancellationToken)
		{
			RunIfNeed();
			return default(Unit);
		}

		public Unit TryInvoke(RaisePendingNotifications<IReadOnlyObservableCollection> request, IReadOnlyObservableCollection apiProvider, IReadOnlyMetadataContext? metadata, CancellationToken cancellationToken)
		{
			RaisePendingChanges(metadata);
			return default(Unit);
		}

		internal void AddReset(IHandler handler, ICollectionDecorator? decorator, int version)
		{
			Add(new PendingItemKey(handler, decorator, this, version));
		}

		internal void Add(PendingItemKey item)
		{
			_pendingChangedItems.GetOrAddValueRef(item);
		}

		internal void RaisePendingChanges(IReadOnlyMetadataContext? metadata)
		{
			IReadOnlyObservableCollection owner = Owner;
			if (owner == null || owner.IsDisposed)
			{
				return;
			}
			using (owner.Lock(metadata))
			{
				if (owner.IsDisposed)
				{
					return;
				}
				InlineObjectArray inlineObjectArray = default(InlineObjectArray);
				try
				{
					Span<object> span;
					using (Locker.EnterScope())
					{
						if (_pendingChangedItems.Count == 0)
						{
							return;
						}
						inlineObjectArray = new InlineObjectArray(_pendingChangedItems.Count * 4);
						span = inlineObjectArray.Span;
						int length = 0;
						foreach (KeyValuePair<PendingItemKey, object> pendingChangedItem in _pendingChangedItems)
						{
							if (pendingChangedItem.Key.Version == pendingChangedItem.Key.Handler.Version)
							{
								if (pendingChangedItem.Key.Handler.IsReset)
								{
									span[length++] = pendingChangedItem.Key.Handler;
									span[length++] = null;
									span[length++] = this;
									span[length++] = BoxingExtensions.Box(pendingChangedItem.Key.Version);
									pendingChangedItem.Key.Handler.ResetCounter();
								}
								else
								{
									span[length++] = pendingChangedItem.Key.Handler;
									span[length++] = pendingChangedItem.Key.State1;
									span[length++] = pendingChangedItem.Key.State2;
									span[length++] = BoxingExtensions.Box(pendingChangedItem.Key.Version);
								}
							}
						}
						span = span.Slice(0, length);
						_pendingChangedItems.Clear();
					}
					for (int i = 0; i < span.Length; i += 4)
					{
						IHandler handler = (IHandler)span[i];
						if ((int)span[i + 3] == handler.Version)
						{
							object obj = span[i + 1];
							object obj2 = span[i + 2];
							if (obj2 == this)
							{
								handler.ResetRaw((ICollectionDecorator)obj);
							}
							else
							{
								handler.RaiseItemChangedRaw(obj, obj2);
							}
						}
					}
				}
				finally
				{
					inlineObjectArray.Dispose();
				}
			}
		}

		private void RunIfNeed()
		{
			if (_pendingChangedItems.Count != 0 && Volatile.Read(in _workerState) == 0 && Interlocked.CompareExchange(ref _workerState, 1, 0) == 0)
			{
				ThreadPool.QueueUserWorkItem(delegate(BatchActionCollectionManager s)
				{
					s.ProcessLoop();
				}, this, preferLocal: true);
			}
		}

		private void ProcessLoop()
		{
			while (true)
			{
				IReadOnlyObservableCollection owner = Owner;
				if (owner == null || owner.IsDisposed)
				{
					break;
				}
				try
				{
					RaisePendingChanges(null);
				}
				catch (Exception exception)
				{
					IMugenService<IMugenApplication>.Instance.OnUnhandledException(exception, UnhandledExceptionType.System, owner);
				}
				using (Locker.EnterScope())
				{
					if (_pendingChangedItems.Count == 0)
					{
						Volatile.Write(ref _workerState, 0);
						if (_pendingChangedItems.Count == 0 || Interlocked.CompareExchange(ref _workerState, 1, 0) != 0)
						{
							return;
						}
					}
				}
			}
			Volatile.Write(ref _workerState, 0);
		}

		bool IAttachableComponentBase.CanDetach<T>(T owner, IReadOnlyMetadataContext? metadata)
		{
			return false;
		}
	}
