	public readonly struct CollectionItemInfo<T> where T : class?
	{
		private const byte HasOldFlag = 1;

		private const byte HasNewFlag = 2;

		private const byte Unchanged = 4;

		public readonly object? OldItemRaw;

		public readonly object? ItemRaw;

		public readonly T? OldItem;

		public readonly T? Item;

		private readonly byte _flags;

		[MemberNotNullWhen(true, "OldItem")]
		public bool HasOldItem
		{
			[MethodImpl(MethodImplOptions.AggressiveInlining)]
			[MemberNotNullWhen(true, "OldItem")]
			get
			{
				return _flags.HasFlag((byte)1);
			}
		}

		[MemberNotNullWhen(true, "Item")]
		public bool HasItem
		{
			[MethodImpl(MethodImplOptions.AggressiveInlining)]
			[MemberNotNullWhen(true, "Item")]
			get
			{
				return _flags.HasFlag((byte)2);
			}
		}

		public bool IsUnchanged
		{
			[MethodImpl(MethodImplOptions.AggressiveInlining)]
			get
			{
				return _flags.HasFlag((byte)4);
			}
		}

		internal CollectionItemInfo(bool _)
		{
			OldItemRaw = null;
			ItemRaw = null;
			_flags = 4;
			OldItem = null;
			Item = null;
		}

		public CollectionItemInfo(bool hasOldItem, CollectionPredicateItem<T?> oldItem, bool hasItem, CollectionPredicateItem<T?> item)
		{
			_flags = 0;
			if (hasOldItem)
			{
				_flags |= 1;
			}
			if (hasItem)
			{
				_flags |= 2;
			}
			OldItemRaw = oldItem.OriginalItem;
			OldItem = oldItem.Item;
			ItemRaw = item.OriginalItem;
			Item = item.Item;
		}
	}
