	{
		public static readonly DictionarySlimStrategy<TKey, TValue> Instance = new DictionarySlimStrategy<TKey, TValue>();

		public override void Resize(scoped ArrayRef<DictionarySlimEntry<TKey, TValue>> entriesRef, scoped ArrayRef<int> bucketsRef, int count, IEqualityComparer<TKey>? comparer)
