			while (count-- > 0)
			{
				ref int reference = ref array2[(uint)(comparer?.GetHashCode(array[count].Key) ?? array[count].Key.GetHashCode()) % array.Length];
				array[count].Next = reference - 1;
				reference = count + 1;
			}
			bucketsRef.Update(array2, 0);
			entriesRef.Update(array, 0);
		}
