	public class DiffableBindableCollectionAdapter : BindableCollectionAdapter, INotifyCollectionChanged, INotifyPropertyChanged
	{
		public int MaxChangesLimit { get; init; } = 50;

		public int AsyncChangesLimit { get; init; } = 5000;

		public event NotifyCollectionChangedEventHandler? CollectionChanged;

		public event PropertyChangedEventHandler? PropertyChanged;

		public DiffableBindableCollectionAdapter(IEnumerable? collection = null)
		{
			base.Collection = collection;
		}

		protected virtual void OnAdded(object? item, int index)
		{
			Items.Insert(index, item);
			InvalidateProperties();
			this.CollectionChanged?.Invoke(this, new NotifyCollectionChangedEventArgs(NotifyCollectionChangedAction.Add, item, index));
		}

		protected virtual void OnReplaced(object? newItem, int index)
		{
			object oldItem = Items[index];
			Items[index] = newItem;
			OnPropertyChanged(Default.IndexerPropertyChangedArgs);
			this.CollectionChanged?.Invoke(this, new NotifyCollectionChangedEventArgs(NotifyCollectionChangedAction.Replace, newItem, oldItem, index));
		}

		protected virtual void OnMoved(int oldIndex, int newIndex)
		{
			object changedItem = Items[oldIndex];
			Items.Move(oldIndex, newIndex);
			OnPropertyChanged(Default.IndexerPropertyChangedArgs);
			this.CollectionChanged?.Invoke(this, new NotifyCollectionChangedEventArgs(NotifyCollectionChangedAction.Move, changedItem, newIndex, oldIndex));
		}

		protected virtual void OnRemoved(int index)
		{
			object changedItem = Items[index];
			Items.RemoveAt(index);
			InvalidateProperties();
			this.CollectionChanged?.Invoke(this, new NotifyCollectionChangedEventArgs(NotifyCollectionChangedAction.Remove, changedItem, index));
		}

		protected virtual void OnReset(ReadOnlySpan<object?> items)
		{
			Items.Reset(items);
			InvalidateProperties();
			this.CollectionChanged?.Invoke(this, Default.ResetCollectionEventArgs);
		}

		protected virtual void OnBeginApplyChanges()
		{
		}

		protected virtual void OnEndApplyChanges()
		{
		}

		protected sealed override async void Invalidate(int version, PooledReadOnlyList<CollectionChangedEvent> events, PooledReadOnlyDictionarySlim<object, int> reloads, CollectionChangedAction flags)
		{
			PooledListSlim<object?> newItems = default(PooledListSlim<object>);
			CollectionDiff<CollectionDiffHandler> diff = default(CollectionDiff<CollectionDiffHandler>);
			bool isAsync = false;
			try
			{
				try
				{
					if (!flags.HasFlagEx(CollectionChangedAction.Reset) && !flags.HasFlagEx(CollectionChangedAction.Add | CollectionChangedAction.Remove))
					{
						RaiseEvents(events);
						return;
					}
					newItems = new PooledListSlim<object>(Items.ReadOnlySpan);
					foreach (CollectionChangedEvent item in events)
					{
						item.ApplyToSource(ref newItems);
					}
				}
				finally
				{
					BindableCollectionAdapter.ReleasePendingEvents(events);
				}
				if (Items.Count == 0)
				{
					OnReset(newItems.ReadOnlySpan);
					return;
				}
				if (newItems.Count == 0)
				{
					OnReset(default(ReadOnlySpan<object>));
					return;
				}
				diff = new CollectionDiff<CollectionDiffHandler>(new CollectionDiffHandler(this, version, MaxChangesLimit), reloads);
				isAsync = (Items.Count > AsyncChangesLimit || newItems.Count > AsyncChangesLimit) && IMugenService<IMugenApplication>.Instance.CanExecuteInline(BindableCollectionAdapter.ExecutionMode);
				if (isAsync)
				{
					BeginBatchUpdate(version);
					await IMugenService<IMugenApplication>.Instance.SwitchToBackgroundAsync();
				}
				diff.Calculate(Items.ReadOnlySpan, newItems.ReadOnlySpan);
				if (diff.Handler.HasChanges)
				{
					if (isAsync)
					{
						await IMugenService<IMugenApplication>.Instance.SwitchToAsync(BindableCollectionAdapter.ExecutionMode);
					}
					if (base.Version == version)
					{
						ApplyChanges(diff.Handler, newItems.ReadOnlySpan);
					}
				}
			}
			catch (Exception exception)
			{
				if (base.Version == version)
				{
					IMugenService<IMugenApplication>.Instance.OnUnhandledException(exception, UnhandledExceptionType.View, this);
				}
			}
			finally
			{
				reloads.Dispose();
				diff.Dispose();
				newItems.Dispose();
				if (isAsync)
				{
					EndBatchUpdate(version, onBackgroundThread: true);
				}
			}
		}

		protected virtual void ApplyChanges(CollectionDiffHandler handler, ReadOnlySpan<object?> newItems)
		{
			OnBeginApplyChanges();
			if (handler.IsResetRequired)
			{
				OnReset(newItems);
				OnEndApplyChanges();
				return;
			}
			foreach (KeyValuePair<int, object> delete in handler.Deletes)
			{
				OnRemoved(delete.Key);
			}
			foreach (KeyValuePair<int, object> insert in handler.Inserts)
			{
				OnAdded(newItems[insert.Key], insert.Key);
			}
			ReadOnlySpan<long> readOnlySpan = handler.InsertsMoves.ReadOnlySpan;
			for (int i = 0; i < readOnlySpan.Length; i++)
			{
				LongToIntMapper longToIntMapper = new LongToIntMapper(readOnlySpan[i]);
				if (longToIntMapper.Int2 < 0)
				{
					OnAdded(newItems[~longToIntMapper.Int2], longToIntMapper.Int1);
				}
				else
				{
					OnMoved(longToIntMapper.Int1, longToIntMapper.Int2);
				}
			}
			ArraySegmentEnumerator<long> enumerator = handler.Updates.GetEnumerator();
			while (enumerator.MoveNext())
			{
				long current2 = enumerator.Current;
				LongToIntMapper longToIntMapper2 = new LongToIntMapper(current2);
				OnReplaced(newItems[longToIntMapper2.Int2], longToIntMapper2.Int2);
			}
			OnEndApplyChanges();
		}

		private void RaiseEvents(PooledReadOnlyList<CollectionChangedEvent> events)
		{
			foreach (CollectionChangedEvent item in events)
			{
				switch (item.Action)
				{
				case CollectionChangedAction.Add:
					OnAdded(item.NewItem, item.NewIndex);
					break;
				case CollectionChangedAction.Move:
					OnMoved(item.OldIndex, item.NewIndex);
					break;
				case CollectionChangedAction.Remove:
					OnRemoved(item.OldIndex);
					break;
				case CollectionChangedAction.Replace:
				case CollectionChangedAction.Reload:
					OnReplaced(item.NewItem, item.OldIndex);
					break;
				}
			}
		}

		private void InvalidateProperties()
		{
			PropertyChangedEventHandler propertyChangedEventHandler = this.PropertyChanged;
			if (propertyChangedEventHandler != null)
			{
				propertyChangedEventHandler(this, Default.CountPropertyChangedArgs);
				propertyChangedEventHandler(this, Default.IndexerPropertyChangedArgs);
			}
		}

		private void OnPropertyChanged(PropertyChangedEventArgs e)
		{
			this.PropertyChanged?.Invoke(this, e);
		}
	}
	internal static class HashHelpers
	{
		public const int HashCollisionThreshold = 100;

		public const int MaxPrimeArrayLength = 2146435069;

		public const int HashPrime = 101;

		public static readonly int[] Primes = new int[72]
		{
			3, 7, 11, 17, 23, 29, 37, 47, 59, 71,
			89, 107, 131, 163, 197, 239, 293, 353, 431, 521,
			631, 761, 919, 1103, 1327, 1597, 1931, 2333, 2801, 3371,
			4049, 4861, 5839, 7013, 8419, 10103, 12143, 14591, 17519, 21023,
			25229, 30293, 36353, 43627, 52361, 62851, 75431, 90523, 108631, 130363,
			156437, 187751, 225307, 270371, 324449, 389357, 467237, 560689, 672827, 807403,
			968897, 1162687, 1395263, 1674319, 2009191, 2411033, 2893249, 3471899, 4166287, 4999559,
			5999471, 7199369
		};

		internal static readonly int[] SizeOneIntArray = new int[1];

		public static bool IsPrime(int candidate)
		{
			if ((candidate & 1) != 0)
			{
				int num = (int)Math.Sqrt(candidate);
				for (int i = 3; i <= num; i += 2)
				{
					if (candidate % i == 0)
					{
						return false;
					}
				}
				return true;
			}
			return candidate == 2;
		}

		public static int GetPrime(int min)
		{
			Should.BeValid(min >= 0, "min");
			for (int i = 0; i < Primes.Length; i++)
			{
				int num = Primes[i];
				if (num >= min)
				{
					return num;
				}
			}
			for (int j = min | 1; j < int.MaxValue; j += 2)
			{
				if (IsPrime(j) && (j - 1) % 101 != 0)
				{
					return j;
				}
			}
			return min;
		}

		public static int ExpandPrime(int oldSize)
		{
			int num = 2 * oldSize;
			if ((uint)num > 2146435069u && 2146435069 > oldSize)
			{
				return 2146435069;
			}
			return GetPrime(num);
		}
	}
