	public struct LRUCache<TKey, TValue> : IHasInitializedState where TKey : notnull
	{
		internal sealed class Node
		{
			public TKey Key;

			public TValue Value;

			public Node? Prev;

			public Node? Next;

			public Node(TKey key, TValue value)
			{
				Key = key;
				Value = value;
			}
		}

		private const int DefaultCapacity = 255;

		private readonly int _capacity;

		internal readonly Lock _lockObj;

		internal DictionarySlim<TKey, Node> _map;

		private Node? _head;

		private Node? _tail;

		public readonly bool IsInitialized => _lockObj != null;

		public readonly int Count
		{
			get
			{
				using (_lockObj.EnterScope())
				{
					return _map.Count;
				}
			}
		}

		public LRUCache()
			: this(255, null)
		{
		}

		public LRUCache(int capacity)
			: this(capacity, null)
		{
		}

		public LRUCache(int capacity, IEqualityComparer<TKey>? comparer)
		{
			_head = null;
			_tail = null;
			_lockObj = new Lock();
			_map = new DictionarySlim<TKey, Node>(capacity, comparer);
			_capacity = ((capacity > 0) ? capacity : 255);
		}

		public bool TryGet(TKey key, out TValue value)
		{
			using (_lockObj.EnterScope())
			{
				ref Node valueRefOrNullRef = ref _map.GetValueRefOrNullRef(key);
				if (!Unsafe.IsNullRef(in valueRefOrNullRef))
				{
					Node node = valueRefOrNullRef;
					MoveToHead(node);
					value = node.Value;
					return true;
				}
			}
			value = default(TValue);
			return false;
		}

		public void Set(TKey key, TValue value)
		{
			Set(key, value, out TValue _);
		}

		public void Set(TKey key, TValue value, out TValue? released)
		{
			using (_lockObj.EnterScope())
			{
				bool hasValue;
				ref Node orAddValueRef = ref _map.GetOrAddValueRef(key, out hasValue);
				if (hasValue)
				{
					Node node = orAddValueRef;
					released = node.Value;
					node.Value = value;
					MoveToHead(node);
				}
				else if (_map.Count - 1 >= _capacity)
				{
					Node tail = _tail;
					released = tail.Value;
					RemoveNode(tail);
					_map.Remove(tail.Key);
					tail.Key = key;
					tail.Value = value;
					AddToHead(tail);
					orAddValueRef = tail;
				}
				else
				{
					released = default(TValue);
					Node node2 = new Node(key, value);
					AddToHead(node2);
					orAddValueRef = node2;
				}
			}
		}

		public bool Remove(TKey key)
		{
			using (_lockObj.EnterScope())
			{
				if (_map.TryGetValue(key, out Node value))
				{
					RemoveNode(value);
					_map.Remove(key);
					return true;
				}
				return false;
			}
		}

		public void Clear()
		{
			using (_lockObj.EnterScope())
			{
				_map.Clear();
				_head = (_tail = null);
			}
		}

		public readonly bool ContainsKey(TKey key)
		{
			using (_lockObj.EnterScope())
			{
				return _map.ContainsKey(key);
			}
		}

		public readonly bool TryPeekLru(out TKey key, out TValue value)
		{
			using (_lockObj.EnterScope())
			{
				if (_tail != null)
				{
					key = _tail.Key;
					value = _tail.Value;
					return true;
				}
			}
			key = default(TKey);
			value = default(TValue);
			return false;
		}

		private void AddToHead(Node node)
		{
			node.Prev = null;
			node.Next = _head;
			if (_head != null)
			{
				_head.Prev = node;
			}
			_head = node;
			if (_tail == null)
			{
				_tail = node;
			}
		}

		private void RemoveNode(Node node)
		{
			Node prev = node.Prev;
			Node next = node.Next;
			if (prev != null)
			{
				prev.Next = next;
			}
			else
			{
				_head = next;
			}
			if (next != null)
			{
				next.Prev = prev;
			}
			else
			{
				_tail = prev;
			}
			node.Prev = (node.Next = null);
		}

		private void MoveToHead(Node node)
		{
			if (_head != node)
			{
				RemoveNode(node);
				AddToHead(node);
			}
		}
	}
	public sealed class ObservableCollectionComponentProvider : IApiHandlerComponent<IMugenApplication, OnComponentCollectionInitialized, Unit>, IApiHandlerComponent<IMugenApplication>, IApiProviderComponent<IMugenApplication>, IApiProviderComponent, IComponent, ISupportRequestComponent<IMugenApplication>, IComponent<IMugenApplication>, ISupportApiHandlerComponent<IMugenApplication, OnComponentCollectionInitialized>
	{
		public int Priority { get; init; } = 100;

		public Unit TryInvoke(OnComponentCollectionInitialized request, IMugenApplication apiProvider, IReadOnlyMetadataContext? metadata, CancellationToken cancellationToken)
		{
			if (!(request.Collection.Owner is IReadOnlyObservableCollection readOnlyObservableCollection))
			{
				return default(Unit);
			}
			ComponentCollection collection = request.Collection;
			if (readOnlyObservableCollection is IDecorator<IReadOnlyObservableCollection>)
			{
				collection.TryAdd(new SynchronizableHandlerWrapper<IReadOnlyObservableCollection>(MugenExtensions.Unwrap(readOnlyObservableCollection)));
			}
			else
			{
				collection.TryAdd(new SynchronizableHandler<IReadOnlyObservableCollection>());
			}
			BatchUpdateCollectionManager component = new BatchUpdateCollectionManager();
			collection.TryAdd(component);
			collection.Components.TryAdd(component);
			readOnlyObservableCollection.Components.Get<IReadOnlyObservableCollection, IApiProviderComponent<IReadOnlyObservableCollection>, LockRequest<IReadOnlyObservableCollection>>(metadata);
			readOnlyObservableCollection.Components.Get<IReadOnlyObservableCollection, IApiProviderComponent<IReadOnlyObservableCollection>, TryLockRequest<IReadOnlyObservableCollection>>(metadata);
			readOnlyObservableCollection.Components.Get<IReadOnlyObservableCollection, IApiProviderComponent<IReadOnlyObservableCollection>, GetLockerRequest<IReadOnlyObservableCollection>>(metadata);
			readOnlyObservableCollection.Components.Get<IReadOnlyObservableCollection, IApiProviderComponent<IReadOnlyObservableCollection>, UpdateLockerRequest<IReadOnlyObservableCollection>>(metadata);
			readOnlyObservableCollection.Components.Get<IReadOnlyObservableCollection, IApiProviderComponent<IReadOnlyObservableCollection>, OnUnlockedRequest<IReadOnlyObservableCollection>>(metadata);
			readOnlyObservableCollection.Components.Get<IReadOnlyObservableCollection, IApiProviderComponent<IReadOnlyObservableCollection>, OnLockerChangedRequest<IReadOnlyObservableCollection>>(metadata);
			return default(Unit);
		}
	}
