	[StructLayout(LayoutKind.Auto)]
	public ref struct ValueSpanBuilder<T> : IHasEmptyState, IHasSpan<T>, IHasReadOnlySpan<T> where T : unmanaged
	{
		internal Span<T> _items;

		internal int _pos;

		internal byte[]? _array;

		public readonly bool IsEmpty => _pos == 0;

		public int Length
		{
			readonly get
			{
				return _pos;
			}
			set
			{
				_pos = value;
			}
		}

		public readonly int Capacity => _items.Length;

		public readonly Span<T> Span => _items.Slice(0, _pos);

		public readonly ReadOnlySpan<T> ReadOnlySpan => Span;

		public readonly Span<T> RawItems => _items;

		public readonly ref T this[int index] => ref _items[index];

		[MustDisposeResource]
		public ValueSpanBuilder(Span<T> initialBuffer)
		{
			_array = null;
			_items = initialBuffer;
			_pos = 0;
		}

		[MustDisposeResource]
		public ValueSpanBuilder(int initialCapacity)
		{
			_array = MugenExtensions.RentRaw<byte>(initialCapacity * Unsafe.SizeOf<T>());
			_items = MemoryMarshal.Cast<byte, T>(_array);
			_pos = 0;
		}

		public override readonly string ToString()
		{
			return Span.ToString();
		}

		public void EnsureCapacity(int capacity)
		{
			if ((uint)capacity > (uint)_items.Length)
			{
				Grow(capacity - _items.Length);
			}
		}

		public readonly ref T GetPinnableReference()
		{
			return ref MemoryMarshal.GetReference(_items);
		}

		public readonly Span<T>.Enumerator GetEnumerator()
		{
			return _items.Slice(0, _pos).GetEnumerator();
		}

		public void SetLength(int l)
		{
			Length = l;
		}

		public readonly ReadOnlySpan<T> AsSpan(int start)
		{
			return _items.Slice(start, _pos - start);
		}

		public readonly ReadOnlySpan<T> AsSpan(int start, int length)
		{
			return _items.Slice(start, length);
		}

		public readonly bool TryCopyTo(Span<T> destination, out int charsWritten)
		{
			if (_items.Slice(0, _pos).TryCopyTo(destination))
			{
				charsWritten = _pos;
				return true;
			}
			charsWritten = 0;
			return false;
		}

		public void Insert(int index, T value, int count = 1)
		{
			if (count > 0)
			{
				if (_pos > _items.Length - count)
				{
					Grow(count);
				}
				int length = _pos - index;
				_items.Slice(index, length).CopyTo(_items.Slice(index + count));
				_items.Slice(index, count).Fill(value);
				_pos += count;
			}
		}

		public void Insert(int index, ReadOnlySpan<T> value)
		{
			if (_pos > _items.Length - value.Length)
			{
				Grow(value.Length);
			}
			int length = _pos - index;
			_items.Slice(index, length).CopyTo(_items.Slice(index + value.Length));
			value.CopyTo(_items.Slice(index, value.Length));
			_pos += value.Length;
		}

		public void Append(T c)
		{
			int pos = _pos;
			if ((uint)pos < (uint)_items.Length)
			{
				_items[pos] = c;
				_pos = pos + 1;
			}
			else
			{
				GrowAndAppend(c);
			}
		}

		public void Append(T c, int count)
		{
			if (_pos > _items.Length - count)
			{
				Grow(count);
			}
			Span<T> span = _items.Slice(_pos, count);
			for (int i = 0; i < span.Length; i++)
			{
				span[i] = c;
			}
			_pos += count;
		}

		public void Append(ReadOnlySpan<T> value)
		{
			if (_pos > _items.Length - value.Length)
			{
				Grow(value.Length);
			}
			value.CopyTo(_items.Slice(_pos));
			_pos += value.Length;
		}

		public Span<T> AppendSpan(int length)
		{
			int pos = _pos;
			if (pos > _items.Length - length)
			{
				Grow(length);
			}
			_pos = pos + length;
			return _items.Slice(pos, length);
		}

		public readonly ItemOrArray<T> ToItemOrArray()
		{
			return ItemOrArray.FromSpan<T>(Span);
		}

		public readonly T[] ToArray()
		{
			return Span.ToArray();
		}

		public readonly TResult[] ToArray<TResult>(Func<T, TResult> getValue)
		{
			Should.NotBeNull(getValue, "getValue");
			if (Length == 0)
			{
				return Array.Empty<TResult>();
			}
			TResult[] array = new TResult[Length];
			for (int i = 0; i < Span.Length; i++)
			{
				array[i] = getValue(Span[i]);
			}
			return array;
		}

		public void Clear()
		{
			_pos = 0;
		}

		[HandlesResourceDisposal]
		public void Dispose()
		{
			byte[] array = _array;
			this = default(ValueSpanBuilder<T>);
			if (array != null)
			{
				MugenExtensions.ReturnRaw(array, clearArray: false);
			}
		}

		[HandlesResourceDisposal]
		public string ToStringDispose()
		{
			string result = ToString();
			Dispose();
			return result;
		}

		[MethodImpl(MethodImplOptions.NoInlining)]
		private void GrowAndAppend(T c)
		{
			Grow(1);
			Append(c);
		}

		[MethodImpl(MethodImplOptions.NoInlining)]
		private void Grow(int requiredAdditionalCapacity)
		{
			byte[] array = MugenExtensions.RentRaw<byte>(MugenExtensions.GetCapacity(_items.Length, requiredAdditionalCapacity, pooled: true) * Unsafe.SizeOf<T>());
			Span<T> span = MemoryMarshal.Cast<byte, T>(array);
			_items.CopyTo(span);
			byte[] array2 = _array;
			_items = span;
			_array = array;
			if (array2 != null)
			{
				MugenExtensions.ReturnRaw(array2, clearArray: false);
			}
		}
	}
