			{
				PooledDictionarySlim<TKey, TValue> result = new PooledDictionarySlim<TKey, TValue>(cache._map.Count, cache._map.Comparer);
				foreach (KeyValuePair<TKey, LRUCache<TKey, TValue>.Node> item in cache._map)
