		[MustDisposeResource]
		public static PooledDictionarySlim<TKey, TValue> ToPooledDictionarySlim<TKey, TValue>(DictionarySlimEnumerator<TKey, TValue> enumerator, int count, IEqualityComparer<TKey>? comparer) where TKey : notnull
		{
			PooledDictionarySlim<TKey, TValue> result = new PooledDictionarySlim<TKey, TValue>(count, comparer);
			while (enumerator.MoveNext())
			{
				KeyValuePair<TKey, TValue> current = enumerator.Current;
				result.GetOrAddValueRef(current.Key) = current.Value;
			}
			return result;
		}

		public static DictionarySlim<TKey, TValue> ToDictionarySlim<TKey, TValue>(DictionarySlimEnumerator<TKey, TValue> enumerator, int count, IEqualityComparer<TKey>? comparer) where TKey : notnull
