			while (enumerator.MoveNext())
			{
				KeyValuePair<TKey, TValue> current = enumerator.Current;
				result.GetOrAddValueRef(current.Key) = current.Value;
			}
			return result;
		}

		public static Dictionary<TKey, TValue> ToDictionary<TKey, TValue>(DictionarySlimEnumerator<TKey, TValue> enumerator, int count, IEqualityComparer<TKey>? comparer) where TKey : notnull
		{
			Dictionary<TKey, TValue> dictionary = new Dictionary<TKey, TValue>(count, comparer);
			while (enumerator.MoveNext())
			{
				KeyValuePair<TKey, TValue> current = enumerator.Current;
				dictionary[current.Key] = current.Value;
			}
			return dictionary;
		}

