		public static bool TryGetValue<TKey, TValue>(TKey key, DictionarySlimEntry<TKey, TValue>[] entries, int[] buckets, int count, IEqualityComparer<TKey>? comparer, out DictionarySlimEntry<TKey, TValue> value) where TKey : notnull
		{
			if (count != 0)
			{
				int index = GetIndex(key, entries, buckets, comparer);
				if (index != -1)
				{
