		public static bool BeginBatchUpdate(scoped ref int flags)
		{
			if (++MemoryMarshal.Cast<int, ushort>(MemoryMarshal.CreateSpan(ref flags, 1))[1] == 1)
			{
				SetFlag(ref flags, 1);
				return true;
			}
			return false;
		}

		public static bool EndBatchUpdate<T>(ref int count, scoped ArrayRef<T> itemsRef, scoped ref int flags, int shrinkSize = 0)
		{
			Should.BeValid(CheckFlag(flags, 1), "BeginBatch < 0");
			if (--MemoryMarshal.Cast<int, ushort>(MemoryMarshal.CreateSpan(ref flags, 1))[1] != 0)
			{
				return false;
			}
			if (CheckFlag(flags, 2))
			{
				T[] array = itemsRef.Array;
				T[] value = ((shrinkSize == 0) ? array.AsReadOnlySpan(0, Math.Min(array.Length, MugenExtensions.GetCapacity(count, 0, pooled: false))).ToArray() : array.AsReadOnlySpan(0, shrinkSize).ToArray());
				if (!itemsRef.IsPooled)
				{
					Return(array, count);
				}
				itemsRef.Update(value, count);
				if (shrinkSize != 0)
				{
					count = shrinkSize;
				}
			}
			flags = 0;
			return true;
		}

		public static void SetCapacity<T>(int value, int count, scoped ArrayRef<T> itemsRef, scoped ref int flags)
		{
			if (value < count)
			{
				ExceptionManager.ThrowCapacityLessThanCollection("value");
			}
			T[] array = itemsRef.Array;
			if (array != null && value == array.Length)
			{
				return;
			}
			if (value > 0)
			{
				if (CheckFlag(flags, 1))
				{
					T[] array2 = MugenExtensions.RentRaw<T>(value);
					if (count > 0)
					{
						Array.Copy(array, 0, array2, 0, count);
					}
					if (CheckFlag(flags, 2) && array.Length != 0 && !itemsRef.IsPooled)
					{
						Return(array, count);
					}
					itemsRef.Update(array2, count);
					SetFlag(ref flags, 2);
				}
				else
				{
					T[] array3 = new T[value];
					if (count > 0)
					{
						Array.Copy(array, 0, array3, 0, count);
					}
					itemsRef.Update(array3, count);
				}
			}
			else
			{
				itemsRef.Update(Array.Empty<T>(), count);
			}
		}

		public static void Return<T>(T[] items, int count)
		{
			if (items != null && items.Length > 0)
			{
				if (RuntimeHelpers.IsReferenceOrContainsReferences<T>() && count > 0)
				{
					Array.Clear(items, 0, count);
				}
				MugenExtensions.ReturnRaw(items, clearArray: false);
			}
		}

		internal static ReadOnlySpan<T> AsReadOnlySpan<T>(this T[]? array, int start, int length)
		{
			return new ReadOnlySpan<T>(array, start, length);
		}

		internal static int BinarySearch<TKey, TValue>(this SortedListSlim<TKey, TValue> items, TKey key) where TKey : IComparable<TKey>
		{
			KeyValuePair<TKey, TValue>[] items2 = items.Values._items;
			if (items2 == null)
			{
				return -1;
			}
			int num = 0;
			int num2 = items.Values.Count - 1;
			while (num <= num2)
			{
				int num3 = num + (num2 - num >> 1);
				int num4 = items2[num3].Key.CompareTo(key);
				if (num4 == 0)
				{
					return num3;
				}
				if (num4 < 0)
				{
					num = num3 + 1;
				}
				else
				{
					num2 = num3 - 1;
				}
			}
			return ~num;
		}

		[MustDisposeResource]
		internal static PooledReadOnlyList<KeyValuePair<TKey, TValue>> GetValues<TKey, TValue>(this SortedListSlim<TKey, TValue> list) where TKey : class, IComparable<TKey>, IEquatable<TKey> where TValue : class?
		{
			return list.Values.ReadOnlySpan.ToPooledReadOnlyList();
		}

		[HandlesResourceDisposal]
		internal static bool IsEmptyWithDispose<T>(this PooledReadOnlyList<T> list)
		{
			if (list.IsEmpty)
			{
				return true;
			}
			list.Dispose();
			return false;
		}

		internal static bool AddDistinct<T>(this scoped ref PooledItemOrList<T> list, T value)
		{
			if (list.Contains(value))
			{
				return false;
			}
			list.Add(value);
			return true;
		}

		private static IEnumerable<TKey> KeysToEnumerableImpl<TKey, TValue>(DictionarySlimEnumerator<TKey, TValue> enumerator, int count) where TKey : notnull
		{
			while (enumerator.MoveNext())
			{
				yield return enumerator.Current.Key;
			}
		}

		private static IEnumerable<TValue> ValuesToEnumerableImpl<TKey, TValue>(DictionarySlimEnumerator<TKey, TValue> enumerator, int count) where TKey : notnull
		{
			while (enumerator.MoveNext())
			{
				yield return enumerator.Current.Value;
			}
		}

		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		private static bool CheckFlag(int flags, ushort flag)
		{
			return (MemoryMarshal.Cast<int, ushort>(MemoryMarshal.CreateSpan(ref flags, 1))[0] & flag) == flag;
		}

		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		private static void SetFlag(scoped ref int flags, ushort flag)
		{
			MemoryMarshal.Cast<int, ushort>(MemoryMarshal.CreateSpan(ref flags, 1))[0] |= flag;
		}

		private static KeyValuePair<TKey, TValue> FirstOrDefault<TKey, TValue>(DictionarySlimEnumerator<TKey, TValue> enumerator, KeyValuePair<TKey, TValue> defaultValue) where TKey : notnull
		{
			if (enumerator.MoveNext())
			{
				return enumerator.Current;
			}
			return defaultValue;
		}

		private static KeyValuePair<TKey, TValue> LastOrDefault<TKey, TValue>(DictionarySlimReverseEnumerator<TKey, TValue> enumerator, KeyValuePair<TKey, TValue> defaultValue) where TKey : notnull
		{
			if (enumerator.MoveNext())
			{
				return enumerator.Current;
			}
			return defaultValue;
		}
	}
