namespace MugenMvvm.Collections.Internal
{
	internal sealed class AccumulateClosure<T, TResult, TState> where T : class?
	{
		private const byte EmptyState = 0;

		private const byte PendingState = 1;

		private readonly Func<T, TState, TResult> _selector;

		private readonly Func<TResult, TResult, TState, TResult> _add;

		private readonly Func<TResult, TResult, TState, TResult> _remove;

		private readonly Action<IReadOnlyObservableCollection, TResult, TState> _onChanged;

		private readonly Func<T, TState, bool>? _condition;

		private readonly ObservableCollectionPredicate<T, TState> _predicate;

		private bool _isDirty;

		private bool _hasValue;

		private TResult _seed;

		private byte _state;

		public AccumulateClosure(ObservableCollectionPredicate<T, TState> predicate, TResult seed, Func<T, TState, TResult> selector, Func<TResult, TResult, TState, TResult> add, Func<TResult, TResult, TState, TResult> remove, Action<IReadOnlyObservableCollection, TResult, TState> onChanged, Func<T, TState, bool>? condition)
		{
			_predicate = predicate;
			_seed = seed;
			_selector = selector;
			_add = add;
			_remove = remove;
			_onChanged = onChanged;
			_condition = condition;
			_isDirty = true;
		}

		public static void OnAdded(TrackerCollectionDecorator<T, T, (TResult value, bool hasValue), AccumulateClosure<T, TResult, TState>> items, TrackerCollectionItemInfo<T, T> itemInfo, ref (TResult value, bool hasValue) state)
		{
			if (itemInfo.Count == 1)
			{
				state = items.State.GetValue(itemInfo.Item);
			}
			else if (items.IsReset)
			{
				OnChanged(items, new TrackerCollectionItemInfo<T, T>(itemInfo.Key, itemInfo.OriginalItem, itemInfo.Item, itemInfo.Count - 1), null, ref state);
			}
			if (state.hasValue)
			{
				items.State.Set(items.State._add(items.State._seed, state.value, items.State._predicate.State), items.IsBatchUpdate);
			}
		}

		public static void OnRemoved(TrackerCollectionDecorator<T, T, (TResult value, bool hasValue), AccumulateClosure<T, TResult, TState>> items, T key, int count, ref (TResult value, bool hasValue) state)
		{
			if (count != 0 && items.IsReset)
			{
				OnChanged(items, new TrackerCollectionItemInfo<T, T>(key, key, key, count + 1), null, ref state);
			}
			if (state.hasValue)
			{
				items.State.Set(items.State._remove(items.State._seed, state.value, items.State._predicate.State), items.IsBatchUpdate);
			}
		}

		public static void OnChanged(TrackerCollectionDecorator<T, T, (TResult value, bool hasValue), AccumulateClosure<T, TResult, TState>> items, TrackerCollectionItemInfo<T, T> itemInfo, object? args, ref (TResult value, bool hasValue) state)
		{
			(TResult, bool) value = items.State.GetValue(itemInfo.Key);
			if (value.Item2 != state.hasValue || !EqualityComparer<TResult>.Default.Equals(value.Item1, state.value))
			{
				TResult val = items.State._seed;
				for (int i = 0; i < itemInfo.Count; i++)
				{
					if (state.hasValue)
					{
						val = items.State._remove(val, state.value, items.State._predicate.State);
					}
					if (value.Item2)
					{
						val = items.State._add(val, value.Item1, items.State._predicate.State);
					}
				}
				items.State.Set(val, items.IsBatchUpdate);
			}
			state = value;
		}

		public static void OnEndBatchUpdate(TrackerCollectionDecorator<T, T, (TResult value, bool hasValue), AccumulateClosure<T, TResult, TState>> items)
		{
			if (items.State._isDirty)
			{
				items.State._isDirty = false;
				Interlocked.Exchange(ref items.State._state, 1);
			}
		}

		public static void OnUnlocked(IReadOnlyObservableCollection collection, ref AccumulateClosure<T, TResult, TState> state)
		{
			if (Interlocked.Exchange(ref state._state, 0) == 1)
			{
				state._onChanged(collection, state._seed, state._predicate.State);
			}
		}

		public static Optional<T> Condition(object? item, AccumulateClosure<T, TResult, TState> s)
		{
			return s._predicate.GetItem(item);
		}

		private void Set(TResult value, bool isBatch)
		{
			if (!_hasValue || !EqualityComparer<TResult>.Default.Equals(_seed, value))
			{
				_hasValue = true;
				_seed = value;
				if (isBatch)
				{
					_isDirty = true;
				}
				else
				{
					Interlocked.Exchange(ref _state, 1);
				}
			}
		}

		private (TResult value, bool hasValue) GetValue(T item)
		{
			if (_condition == null || _condition(item, _predicate.State))
			{
				return (value: _selector(item, _predicate.State), hasValue: true);
			}
			return default((TResult, bool));
		}
	}
	internal sealed class AllClosure<T, TState> where T : class?
	{
		private readonly ObservableCollectionPredicate<T, TState> _predicate;

		private readonly Func<T, TState, bool> _selector;

		private readonly Action<IReadOnlyObservableCollection, bool, TState> _onChanged;

		private readonly Func<T, TState, bool>? _condition;

		private bool _lastValue;

		public AllClosure(ObservableCollectionPredicate<T, TState> predicate, Func<T, TState, bool> selector, Action<IReadOnlyObservableCollection, bool, TState> onChanged, Func<T, TState, bool>? condition)
		{
			_predicate = predicate;
			_selector = selector;
			_onChanged = onChanged;
			_condition = condition;
		}

		public static (int total, int count) Select(T item, AllClosure<T, TState> closure)
		{
			return (total: 1, count: closure._selector(item, closure._predicate.State) ? 1 : 0);
		}

		public static (int total, int count) Add((int total, int count) x1, (int total, int count) x2, AllClosure<T, TState> _)
		{
			return (total: x1.total + x2.total, count: x1.count + x2.count);
		}

		public static (int total, int count) Remove((int total, int count) x1, (int total, int count) x2, AllClosure<T, TState> _)
		{
			return (total: x1.total - x2.total, count: x1.count - x2.count);
		}

		public static bool Condition(T item, AllClosure<T, TState> closure)
		{
			return closure._condition(item, closure._predicate.State);
		}

		public static Optional<T> Predicate(object? item, AllClosure<T, TState> closure)
		{
			return closure._predicate.GetItem(item);
		}

		public static void OnChanged(IReadOnlyObservableCollection collection, (int total, int count) count, AllClosure<T, TState> closure)
		{
			bool flag = count.total == count.count;
			if (closure._lastValue != flag)
			{
				closure._lastValue = flag;
				closure._onChanged(collection, flag, closure._predicate.State);
			}
		}
	}
	[DebuggerDisplay("{Value} - {Index}")]
	internal sealed class AvlNode<T>
	{
		public static readonly AvlNode<T> EmptyNode = new AvlNode<T>();

		public T Value;

		private byte _height;

		internal AvlNode<T>? _right;

		private AvlNode<T>? _left;

		public bool IsEmpty => Left == null;

		public int Height => _height;

		public AvlNode<T>? Parent { get; private set; }

		public AvlNode<T>? Left
		{
			get
			{
				return _left;
			}
			private set
			{
				AvlNode<T> left = _left;
				_left = value;
				OnChildChanged(left, value);
			}
		}

		public AvlNode<T>? Right
		{
			get
			{
				return _right;
			}
			private set
			{
				AvlNode<T> right = _right;
				_right = value;
				OnChildChanged(right, value);
			}
		}

		public int Count { get; private set; }

		private int Index => this.GetIndex();

		private int BalanceFactor => Right._height - Left._height;

		private bool IsRightHeavy => BalanceFactor >= 2;

		private bool IsLeftHeavy => BalanceFactor <= -2;

		private bool IsBalanced => (uint)(BalanceFactor + 1) <= 2u;

		public T this[int index] => GetNodeAt(index).Value;

		public AvlNode(T key, AvlNode<T> left, AvlNode<T> right)
		{
			Init(key, left, right);
		}

		private AvlNode()
		{
		}

		public void BeginBatchUpdate(int? newSize = null)
		{
			AvlNodePool.BeginBatch<T>(newSize ?? 1048576);
		}

		public void EndBatchUpdate()
		{
			AvlNodePool.EndBatch<T>();
		}

		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public bool CheckPoolCapacity(int size)
		{
			return AvlNodePool.CheckCapacity<T>(size);
		}

		public AvlNode<T> GetNodeAt(int index)
		{
			Should.BeValid(index >= 0 && index < Count, "index");
			if (index < Left.Count)
			{
				return Left.GetNodeAt(index);
			}
			if (index > Left.Count)
			{
				return Right.GetNodeAt(index - Left.Count - 1);
			}
			return this;
		}

		public AvlNode<T> Add(T key, out AvlNode<T> newNode)
		{
			if (IsEmpty)
			{
				newNode = CreateLeaf(key);
				return newNode;
			}
			AvlNode<T> right = Right.Add(key, out newNode);
			AvlNode<T> avlNode = MutateRight(right);
			if (!avlNode.IsBalanced)
			{
				return avlNode.BalanceRight();
			}
			return avlNode;
		}

		public AvlNode<T> Insert(int index, T key, out AvlNode<T> newNode)
		{
			Should.BeValid(index >= 0 && index <= Count, "index");
			if (IsEmpty)
			{
				newNode = CreateLeaf(key);
				return newNode;
			}
			if (index <= Left.Count)
			{
				AvlNode<T> left = Left.Insert(index, key, out newNode);
				AvlNode<T> avlNode = MutateLeft(left);
				if (!avlNode.IsBalanced)
				{
					return avlNode.BalanceLeft();
				}
				return avlNode;
			}
			AvlNode<T> right = Right.Insert(index - Left.Count - 1, key, out newNode);
			AvlNode<T> avlNode2 = MutateRight(right);
			if (!avlNode2.IsBalanced)
			{
				return avlNode2.BalanceRight();
			}
			return avlNode2;
		}

		public AvlNode<T> RemoveAt(int index)
		{
			return RemoveAt(index, returnToPool: true);
		}

		internal AvlNode<T> TrimEnd(int newSize)
		{
			if (newSize >= Count)
			{
				return this;
			}
			if (newSize <= 0)
			{
				AvlNodePool.ReturnSubTree(this);
				return EmptyNode;
			}
			if (newSize < Left.Count)
			{
				AvlNode<T> avlNode = Left.TrimEnd(newSize);
				avlNode.Parent = null;
				AvlNodePool.ReturnSubTree(Right);
				AvlNodePool.Return(this);
				return avlNode;
			}
			if (newSize == Left.Count)
			{
				AvlNodePool.ReturnSubTree(Right);
				AvlNode<T>? left = Left;
				left.Parent = null;
				AvlNodePool.Return(this);
				return left;
			}
			AvlNode<T> right = Right.TrimEnd(newSize - Left.Count - 1);
			AvlNode<T> avlNode2 = MutateRight(right);
			if (!avlNode2.IsBalanced)
			{
				return avlNode2.Balance();
			}
			return avlNode2;
		}

		public AvlNode<T> Clear()
		{
			AvlNodePool.ReturnSubTree(this);
			return EmptyNode;
		}

		internal void Init(T key, AvlNode<T> left, AvlNode<T> right)
		{
			Should.NotBeNull(left, "left");
			Should.NotBeNull(right, "right");
			Value = key;
			Left = left;
			Right = right;
			_height = ParentHeight(left, right);
			Count = ParentCount(left, right);
		}

		internal void Reset()
		{
			Value = default(T);
			AvlNode<T> avlNode = (Right = null);
			AvlNode<T> parent = (Left = avlNode);
			Parent = parent;
		}

		internal AvlNode<T> BalanceMany()
		{
			AvlNode<T> avlNode = this;
			while (!avlNode.IsBalanced)
			{
				if (avlNode.IsRightHeavy)
				{
					avlNode = avlNode.BalanceRight();
					avlNode.MutateLeft(avlNode.Left.BalanceMany());
				}
				else
				{
					avlNode = avlNode.BalanceLeft();
					avlNode.MutateRight(avlNode.Right.BalanceMany());
				}
			}
			return avlNode;
		}

		internal AvlNode<T> MutateLeft(AvlNode<T> left)
		{
			Should.NotBeNull(left, "left");
			if (IsEmpty)
			{
				return AvlNodePool.Rent(Value, left, Right);
			}
			Left = left;
			_height = ParentHeight(left, Right);
			Count = ParentCount(left, Right);
			return this;
		}

		internal AvlNode<T> MutateRight(AvlNode<T> right)
		{
			Should.NotBeNull(right, "right");
			if (IsEmpty)
			{
				return AvlNodePool.Rent(Value, Left, right);
			}
			Right = right;
			_height = ParentHeight(Left, right);
			Count = ParentCount(Left, right);
			return this;
		}

		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		private static byte ParentHeight(AvlNode<T> left, AvlNode<T> right)
		{
			return checked((byte)(1 + Math.Max(left._height, right._height)));
		}

		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		private static int ParentCount(AvlNode<T> left, AvlNode<T> right)
		{
			return 1 + left.Count + right.Count;
		}

		private static AvlNode<T> CreateLeaf(T key)
		{
			return AvlNodePool.Rent(key, EmptyNode, EmptyNode);
		}

		private void OnChildChanged(AvlNode<T>? oldValue, AvlNode<T>? newValue)
		{
			if (oldValue != null && oldValue.Parent == this)
			{
				oldValue.Parent = null;
			}
			if (newValue != null && !newValue.IsEmpty)
			{
				newValue.Parent = this;
			}
		}

		private AvlNode<T> RemoveAt(int index, bool returnToPool)
		{
			Should.BeValid(index >= 0 && index < Count, "index");
			AvlNode<T> avlNode;
			if (index == Left.Count)
			{
				if (Right.IsEmpty && Left.IsEmpty)
				{
					avlNode = EmptyNode;
				}
				else if (Right.IsEmpty && !Left.IsEmpty)
				{
					avlNode = Left;
				}
				else if (!Right.IsEmpty && Left.IsEmpty)
				{
					avlNode = Right;
				}
				else
				{
					AvlNode<T> avlNode2 = Right;
					while (!avlNode2.Left.IsEmpty)
					{
						avlNode2 = avlNode2.Left;
					}
					AvlNode<T> right = Right.RemoveAt(0, returnToPool: false);
					avlNode = avlNode2.MutateBoth(Left, right);
				}
				if (returnToPool)
				{
					AvlNodePool.Return(this);
				}
			}
			else if (index < Left.Count)
			{
				AvlNode<T> left = Left.RemoveAt(index, returnToPool);
				avlNode = MutateLeft(left);
			}
			else
			{
				AvlNode<T> right2 = Right.RemoveAt(index - Left.Count - 1, returnToPool);
				avlNode = MutateRight(right2);
			}
			if (!avlNode.IsEmpty && !avlNode.IsBalanced)
			{
				return avlNode.Balance();
			}
			return avlNode;
		}

		private AvlNode<T> RotateLeft()
		{
			return Right.MutateLeft(MutateRight(Right.Left));
		}

		private AvlNode<T> RotateRight()
		{
			return Left.MutateRight(MutateLeft(Left.Right));
		}

		private AvlNode<T> DoubleLeft()
		{
			AvlNode<T> right = Right;
			AvlNode<T> left = right.Left;
			return left.MutateBoth(MutateRight(left.Left), right.MutateLeft(left.Right));
		}

		private AvlNode<T> DoubleRight()
		{
			AvlNode<T> left = Left;
			AvlNode<T> right = left.Right;
			return right.MutateBoth(left.MutateRight(right.Left), MutateLeft(right.Right));
		}

		private AvlNode<T> Balance()
		{
			if (!IsLeftHeavy)
			{
				return BalanceRight();
			}
			return BalanceLeft();
		}

		private AvlNode<T> BalanceLeft()
		{
			if (Left.BalanceFactor <= 0)
			{
				return RotateRight();
			}
			return DoubleRight();
		}

		private AvlNode<T> BalanceRight()
		{
			if (Right.BalanceFactor >= 0)
			{
				return RotateLeft();
			}
			return DoubleLeft();
		}

		private AvlNode<T> MutateBoth(AvlNode<T> left, AvlNode<T> right)
		{
			Should.NotBeNull(left, "left");
			Should.NotBeNull(right, "right");
			if (IsEmpty)
			{
				return AvlNodePool.Rent(Value, left, right);
			}
			Left = left;
			Right = right;
			_height = ParentHeight(left, right);
			Count = ParentCount(left, right);
			return this;
		}
	}
	[StructLayout(LayoutKind.Auto)]
	internal struct AvlNodeEnumerator<T> : IEnumerator<AvlNode<T>>, IEnumerator, IDisposable
	{
		private int _remaining;

		private AvlNode<T>? _current;

		private AvlNode<T>[]? _stack;

		private int _sp;

		public AvlNode<T> Current => _current;

		object IEnumerator.Current => Current;

		public AvlNodeEnumerator(AvlNode<T> root, int startIndex, int count)
		{
			_remaining = count;
			_current = null;
			if (count == 0)
			{
				_stack = null;
				_sp = 0;
			}
			else
			{
				_stack = ((root.Count == 0) ? Array.Empty<AvlNode<T>>() : MugenExtensions.RentRaw<AvlNode<T>>(root.Height));
				_sp = 0;
				PushLeft(root);
			}
		}

		public AvlNodeEnumerator<T> GetEnumerator()
		{
			return this;
		}

		public bool MoveNext()
		{
			if (_remaining == 0)
			{
				return false;
			}
			if (!MoveNextCore())
			{
				return false;
			}
			_remaining--;
			return true;
		}

		public void Reset()
		{
			ExceptionManager.ThrowNotSupported();
		}

		public void Dispose()
		{
			if (_stack != null)
			{
				MugenExtensions.ReturnRaw(_stack, clearArray: true);
				_stack = null;
			}
		}

		private void PushLeft(AvlNode<T> node)
		{
			while (!node.IsEmpty)
			{
				EnsureCapacity();
				_stack[_sp++] = node;
				node = node.Left;
			}
		}

		private bool MoveNextCore()
		{
			if (_sp == 0)
			{
				return false;
			}
			AvlNode<T> avlNode = (_current = _stack[--_sp]);
			if (!avlNode.Right.IsEmpty)
			{
				PushLeft(avlNode.Right);
			}
			return true;
		}

		private void EnsureCapacity()
		{
			if (_sp >= _stack.Length)
			{
				AvlNode<T>[] array = MugenExtensions.RentRaw<AvlNode<T>>(_stack.Length * 2);
				Array.Copy(_stack, array, _stack.Length);
				MugenExtensions.ReturnRaw(_stack, clearArray: true);
				_stack = array;
			}
		}
	}
	internal static class AvlNodePool
	{
		private static class Impl<T>
		{
			public static int Count;

			private static readonly Lock Locker = new Lock();

			private static AvlNode<T>? _head;

			private static AvlNode<T>? _batchLimitHead;

			private static int _batchLimit;

			private static int _batchCount;

			public static int MaxPoolSize
			{
				[MethodImpl(MethodImplOptions.AggressiveInlining)]
				get
				{
					return Math.Max(_batchLimit, 15000);
				}
			}

			public static void BeginBatch(int newSize)
			{
				using (Locker.EnterScope())
				{
					_batchCount++;
					_batchLimit = Math.Max(newSize, _batchLimit + newSize);
				}
			}

			public static void EndBatch()
			{
				using (Locker.EnterScope())
				{
					if (--_batchCount <= 0)
					{
						Should.BeValid(_batchCount == 0, $"EndBatch = {_batchCount}");
						_batchLimit = 0;
						if (Count >= 15000 && _batchLimitHead != null)
						{
							Count = 15000;
							_head = _batchLimitHead;
						}
						_batchLimitHead = null;
					}
				}
			}

			public static AvlNode<T> RentNode(T key, AvlNode<T> left, AvlNode<T> right)
			{
				AvlNode<T> avlNode = null;
				if (_head != null)
				{
					using (Locker.EnterScope())
					{
						if (_head != null)
						{
							avlNode = _head;
							_head = avlNode._right;
							Count--;
						}
					}
				}
				if (avlNode == null)
				{
					return new AvlNode<T>(key, left, right);
				}
				avlNode.Init(key, left, right);
				return avlNode;
			}

			public static bool ReturnNode(AvlNode<T> node)
			{
				if (Count >= MaxPoolSize)
				{
					return false;
				}
				using (Locker.EnterScope())
				{
					if (Count >= MaxPoolSize)
					{
						return false;
					}
					node._right = _head;
					_head = node;
					Count++;
					if (Count == 15000)
					{
						_batchLimitHead = _head;
					}
					return true;
				}
			}
		}

		public static void BeginBatch<T>(int newSize)
		{
			if (typeof(T).IsValueType)
			{
				Impl<T>.BeginBatch(newSize);
			}
			else
			{
				Impl<object>.BeginBatch(newSize);
			}
		}

		public static void EndBatch<T>()
		{
			if (typeof(T).IsValueType)
			{
				Impl<T>.EndBatch();
			}
			else
			{
				Impl<object>.EndBatch();
			}
		}

		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public static bool CheckCapacity<T>(int expectedSize)
		{
			return (typeof(T).IsValueType ? Impl<T>.Count : Impl<object>.Count) >= expectedSize;
		}

		public static AvlNode<T> Rent<T>(T key, AvlNode<T> left, AvlNode<T> right)
		{
			return Impl<T>.RentNode(key, left, right);
		}

		public static bool Return<T>(AvlNode<T> node)
		{
			if (node.IsEmpty)
			{
				return true;
			}
			node.Reset();
			return Impl<T>.ReturnNode(node);
		}

		public static bool ReturnSubTree<T>(AvlNode<T> n)
		{
			if (n.IsEmpty)
			{
				return true;
			}
			if (!ReturnSubTree(n.Left))
			{
				return false;
			}
			if (!ReturnSubTree(n.Right))
			{
				return false;
			}
			return Return(n);
		}
	}
