	internal sealed class HashSetEx<T> : IReadOnlyCollection<T>, IEnumerable<T>, IEnumerable where T : class?
	{
		private int _nullCount;

		private DictionarySlim<T, int> _dictionary;

		public int Count { get; private set; }

		public HashSetEx(IEqualityComparer<T>? comparer)
		{
			_dictionary = new DictionarySlim<T, int>(comparer);
		}

		public void Add(T item)
		{
			if (item == null)
			{
				_nullCount++;
			}
			else
			{
				_dictionary.GetOrAddValueRef(item)++;
			}
			int count = Count + 1;
			Count = count;
		}

		public bool Remove(T item)
		{
			int count;
			if (item == null)
			{
				if (_nullCount == 0)
				{
					return false;
				}
				_nullCount--;
				count = Count - 1;
				Count = count;
				return true;
			}
			ref int valueRefOrNullRef = ref _dictionary.GetValueRefOrNullRef(item);
			if (Unsafe.IsNullRef(in valueRefOrNullRef))
			{
				return false;
			}
			if (valueRefOrNullRef == 1)
			{
				_dictionary.Remove(item);
			}
			else
			{
				valueRefOrNullRef--;
			}
			count = Count - 1;
			Count = count;
			return true;
		}

		public void Clear()
		{
			_dictionary.Clear();
			Count = 0;
			_nullCount = 0;
		}

		public IEnumerator<T> GetEnumerator()
		{
			foreach (KeyValuePair<T, int> pair in _dictionary)
			{
				for (int i = 0; i < pair.Value; i++)
				{
					yield return pair.Key;
				}
			}
			for (int i = 0; i < _nullCount; i++)
			{
				yield return null;
			}
		}

		IEnumerator IEnumerable.GetEnumerator()
		{
			return GetEnumerator();
		}
	}
	[StructLayout(LayoutKind.Auto)]
	public struct IndexMapTree<T>
	{
		internal IndexMapTreeNode<T>? Root;

		private int _tailGap;

		public int OriginalCount { get; private set; }

		public int FilteredCount => Root?.Size ?? 0;

		public IndexMapTreeNode<T> this[int index]
		{
			get
			{
				Should.BeValid(index > -1 && index < FilteredCount, "index");
				IndexMapTreeNode<T> indexMapTreeNode = Root;
				while (true)
				{
					int num = indexMapTreeNode.L?.Size ?? 0;
					if (index < num)
					{
						indexMapTreeNode = indexMapTreeNode.L;
						continue;
					}
					if (index == num)
					{
						break;
					}
					index -= num + 1;
					indexMapTreeNode = indexMapTreeNode.R;
				}
				return indexMapTreeNode;
			}
		}

		public IndexMapTreeEnumerator<T> GetEnumerator()
		{
			return new IndexMapTreeEnumerator<T>(this);
		}

		public void BeginBatchUpdate(int? newSize = null)
		{
			IndexMapTreePool.BeginBatch<T>(newSize ?? 1048576);
		}

		public void EndBatchUpdate()
		{
			IndexMapTreePool.EndBatch<T>();
		}

		public IndexMapTreeNode<T>? Insert(int originalIndex, T? value, bool matches, out int filteredIndex)
		{
			Should.BeValid((uint)originalIndex <= OriginalCount, "originalIndex");
			var (indexMapTreeNode, num, num2) = Locate(originalIndex);
			if (!matches)
			{
				if (indexMapTreeNode != null)
				{
					indexMapTreeNode.Gap++;
				}
				else
				{
					_tailGap++;
				}
				OriginalCount++;
				UpdateUpwards(indexMapTreeNode);
				filteredIndex = num2;
				return null;
			}
			IndexMapTreeNode<T> indexMapTreeNode2 = IndexMapTreePool.Rent(value, num + 1);
			if (indexMapTreeNode != null)
			{
				indexMapTreeNode.Gap -= num;
				UpdateUpwards(indexMapTreeNode);
			}
			else
			{
				_tailGap -= num;
			}
			(IndexMapTreeNode<T>? left, IndexMapTreeNode<T>? right) tuple2 = SplitByRank(Root, num2);
			IndexMapTreeNode<T> item = tuple2.left;
			IndexMapTreeNode<T> item2 = tuple2.right;
			Root = Merge(Merge(item, indexMapTreeNode2), item2);
			OriginalCount++;
			filteredIndex = num2;
			return indexMapTreeNode2;
		}

		public IndexMapTreeNode<T>? Replace(int originalIndex, T? value, bool matches, out int filteredIndex, out T? oldValue, out IndexMapTreeReplaceResult result)
		{
			Should.BeValid((uint)originalIndex < OriginalCount, "originalIndex");
			(IndexMapTreeNode<T>? node, int offset, int rankBefore) tuple = Locate(originalIndex);
			IndexMapTreeNode<T> item = tuple.node;
			int item2 = tuple.offset;
			int leftSize = (filteredIndex = tuple.rankBefore);
			if (matches)
			{
				if (item != null && item2 == item.Gap - 1)
				{
					oldValue = item.Value;
					item.Value = value;
					result = IndexMapTreeReplaceResult.Updated;
					return item;
				}
				int num = item2 + 1;
				IndexMapTreeNode<T> indexMapTreeNode = IndexMapTreePool.Rent(value, num);
				if (item != null)
				{
					item.Gap -= num;
					UpdateUpwards(item);
				}
				else
				{
					_tailGap -= num;
				}
				(IndexMapTreeNode<T>? left, IndexMapTreeNode<T>? right) tuple2 = SplitByRank(Root, leftSize);
				IndexMapTreeNode<T> item3 = tuple2.left;
				IndexMapTreeNode<T> item4 = tuple2.right;
				Root = Merge(Merge(item3, indexMapTreeNode), item4);
				oldValue = default(T);
				result = IndexMapTreeReplaceResult.Added;
				return indexMapTreeNode;
			}
			if (item == null || item2 != item.Gap - 1)
			{
				result = IndexMapTreeReplaceResult.Unchanged;
				oldValue = default(T);
				return null;
			}
			IndexMapTreeNode<T> indexMapTreeNode2 = Successor(item);
			int num2 = indexMapTreeNode2?.Gap ?? _tailGap;
			int num3 = item.Gap + num2;
			if (indexMapTreeNode2 != null)
			{
				indexMapTreeNode2.Gap = num3;
				UpdateUpwards(indexMapTreeNode2);
			}
			else
			{
				_tailGap = num3;
			}
			oldValue = item.Value;
			Delete(item);
			result = IndexMapTreeReplaceResult.Removed;
			return null;
		}

		public bool RemoveAt(int originalIndex, out int filteredIndex, [MaybeNullWhen(false)] out T value)
		{
			Should.BeValid((uint)originalIndex < OriginalCount, "originalIndex");
			(IndexMapTreeNode<T>? node, int offset, int rankBefore) tuple = Locate(originalIndex);
			IndexMapTreeNode<T> item = tuple.node;
			int item2 = tuple.offset;
			int item3 = tuple.rankBefore;
			filteredIndex = item3;
			if (item == null)
			{
				_tailGap--;
				OriginalCount--;
				value = default(T);
				return false;
			}
			if (item2 != item.Gap - 1)
			{
				item.Gap--;
				OriginalCount--;
				UpdateUpwards(item);
				value = default(T);
				return false;
			}
			value = item.Value;
			IndexMapTreeNode<T> indexMapTreeNode = Successor(item);
			int num = indexMapTreeNode?.Gap ?? _tailGap;
			int num2 = item.Gap - 1 + num;
			if (indexMapTreeNode != null)
			{
				indexMapTreeNode.Gap = num2;
				UpdateUpwards(indexMapTreeNode);
			}
			else
			{
				_tailGap = num2;
			}
			Delete(item);
			OriginalCount--;
			return true;
		}

		public bool TryGet(int originalIndex, [MaybeNullWhen(false)] out IndexMapTreeNode<T> value, out int filteredIndex)
		{
			value = null;
			if (originalIndex < 0 || originalIndex >= OriginalCount)
			{
				filteredIndex = -1;
				return false;
			}
			(IndexMapTreeNode<T>? node, int offset, int rankBefore) tuple = Locate(originalIndex);
			IndexMapTreeNode<T> item = tuple.node;
			int item2 = tuple.offset;
			int item3 = tuple.rankBefore;
			filteredIndex = item3;
			if (item == null || item2 != item.Gap - 1)
			{
				return false;
			}
			value = item;
			return true;
		}

		public int GetInsertIndex(int originalIndex)
		{
			Should.BeValid((uint)originalIndex <= OriginalCount, "originalIndex");
			return Locate(originalIndex).rankBefore;
		}

		public void Clear()
		{
			IndexMapTreePool.ReturnSubtree(Root);
			Root = null;
			_tailGap = 0;
			OriginalCount = 0;
		}

		internal (IndexMapTreeNode<T>? node, int offset, int rankBefore) Locate(int index)
		{
			IndexMapTreeNode<T> indexMapTreeNode = Root;
			int num = 0;
			while (indexMapTreeNode != null)
			{
				int num2 = indexMapTreeNode.L?.Span ?? 0;
				if (index < num2)
				{
					indexMapTreeNode = indexMapTreeNode.L;
					continue;
				}
				int num3 = num2 + indexMapTreeNode.Gap - 1;
				if (index <= num3)
				{
					int item = index - num2;
					int item2 = num + (indexMapTreeNode.L?.Size ?? 0);
					return (node: indexMapTreeNode, offset: item, rankBefore: item2);
				}
				index -= num3 + 1;
				num += (indexMapTreeNode.L?.Size ?? 0) + 1;
				indexMapTreeNode = indexMapTreeNode.R;
			}
			return (node: null, offset: index, rankBefore: num);
		}

		private static IndexMapTreeNode<T>? Merge(IndexMapTreeNode<T>? a, IndexMapTreeNode<T>? b)
		{
			if (a == null)
			{
				if (b != null)
				{
					b.Parent = null;
				}
				return b;
			}
			if (b == null)
			{
				a.Parent = null;
				return a;
			}
			if (a.Priority < b.Priority)
			{
				a.R = Merge(a.R, b);
				a.Recalc();
				a.Parent = null;
				return a;
			}
			b.L = Merge(a, b.L);
			b.Recalc();
			b.Parent = null;
			return b;
		}

		private static (IndexMapTreeNode<T>? left, IndexMapTreeNode<T>? right) SplitByRank(IndexMapTreeNode<T>? root, int leftSize)
		{
			if (root == null)
			{
				return (left: null, right: null);
			}
			if ((root.L?.Size ?? 0) >= leftSize)
			{
				(IndexMapTreeNode<T>? left, IndexMapTreeNode<T>? right) tuple = SplitByRank(root.L, leftSize);
				IndexMapTreeNode<T> item = tuple.left;
				IndexMapTreeNode<T> item2 = tuple.right;
				root.L = item2;
				root.Recalc();
				root.Parent = null;
				if (item != null)
				{
					item.Parent = null;
				}
				return (left: item, right: root);
			}
			int leftSize2 = leftSize - (root.L?.Size ?? 0) - 1;
			(IndexMapTreeNode<T>? left, IndexMapTreeNode<T>? right) tuple2 = SplitByRank(root.R, leftSize2);
			IndexMapTreeNode<T> item3 = tuple2.left;
			IndexMapTreeNode<T> item4 = tuple2.right;
			root.R = item3;
			root.Recalc();
			root.Parent = null;
			if (item4 != null)
			{
				item4.Parent = null;
			}
			return (left: root, right: item4);
		}

		private void Delete(IndexMapTreeNode<T> victim)
		{
			IndexMapTreeNode<T> indexMapTreeNode = Merge(victim.L, victim.R);
			IndexMapTreeNode<T> parent = victim.Parent;
			if (indexMapTreeNode != null)
			{
				indexMapTreeNode.Parent = parent;
			}
			if (parent == null)
			{
				Root = indexMapTreeNode;
			}
			else if (parent.L == victim)
			{
				parent.L = indexMapTreeNode;
				UpdateUpwards(parent);
			}
			else
			{
				parent.R = indexMapTreeNode;
				UpdateUpwards(parent);
			}
			victim.Reset();
			IndexMapTreePool.Return(victim);
		}

		private static IndexMapTreeNode<T>? Successor(IndexMapTreeNode<T> n)
		{
			if (n.R != null)
			{
				n = n.R;
				while (n.L != null)
				{
					n = n.L;
				}
				return n;
			}
			while (n.Parent != null && n.Parent.R == n)
			{
				n = n.Parent;
			}
			return n.Parent;
		}

		private static void UpdateUpwards(IndexMapTreeNode<T>? n)
		{
			while (n != null)
			{
				n.Recalc();
				n = n.Parent;
			}
		}
	}
	public struct IndexMapTreeEnumerator<T> : IEnumerator<IndexMapTreeNode<T>>, IEnumerator, IDisposable
	{
		private const int InitialDepth = 64;

