				}
				indexMapTreeNode.Init(value, gap);
				return indexMapTreeNode;
			}

			public static bool ReturnNode(IndexMapTreeNode<T> node)
			{
				if (_count >= MaxPoolSize)
				{
					return false;
				}
				node.Reset();
				using (Locker.EnterScope())
				{
					if (_count >= MaxPoolSize)
					{
						return false;
					}
					node.R = _head;
					_head = node;
					_count++;
					if (_count == 15000)
					{
						_batchLimitHead = _head;
					}
					return true;
				}
			}
		}

