			if (valueTask.IsCompletedSuccessfully)
			{
				return new ValueTask<IEnumerable<object>>(valueTask.Result);
			}
			return valueTask.AsTask().ContinueWith((Func<Task<IEnumerable<TItem>>, IEnumerable<object>>)((Task<IEnumerable<TItem>?> t) => t.Result), TaskContinuationOptions.ExecuteSynchronously).AsValueTask();
		}

		protected override object? GetPendingState()
		{
			return _getPendingState?.Invoke(this);
		}

		protected override ValueTask<object?> GetErrorStateAsync(Exception e, CancellationToken cancellationToken)
		{
			return _getErrorState?.Invoke(this, e, cancellationToken) ?? default(ValueTask<object>);
		}

		protected override void RaiseItemChanged()
		{
			Decorator.Owner?.RaiseItemChanged(OriginalItem);
		}
	}
	internal sealed class TrackItemsNoLockImpl<T, TState> where T : class
	{
		private const int InitialBufferSize = 239;

		private readonly Action<T, TState> _onAdded;

		private readonly Action<T, TState> _onRemoved;

		private readonly ObservableCollectionPredicate<T, TState> _predicate;

		private bool _started;

		private PooledDictionarySlim<T, object?> _pendingItems;

		public TrackItemsNoLockImpl(Action<T, TState> onAdded, Action<T, TState> onRemoved, ObservableCollectionPredicate<T, TState> predicate)
		{
			_onAdded = onAdded;
			_onRemoved = onRemoved;
			_predicate = predicate;
		}

		public static Optional<T> Predicate(object? item, TrackItemsNoLockImpl<T, TState> s)
		{
			return s._predicate.GetItem(item);
		}

		public static void OnAdded(TrackerCollectionDecorator<T, T, T, TrackItemsNoLockImpl<T, TState>> s, T v)
		{
			lock (s.State)
			{
				if (!s.State._pendingItems.IsInitialized)
				{
					s.State._pendingItems = new PooledDictionarySlim<T, object>(239, s.Comparer);
				}
				s.State._pendingItems.GetOrAddValueRef(v) = v;
			}
		}

		public static void OnRemoved(TrackerCollectionDecorator<T, T, T, TrackItemsNoLockImpl<T, TState>> s, T v)
		{
			lock (s.State)
			{
				if (!s.State._pendingItems.IsInitialized)
				{
					s.State._pendingItems = new PooledDictionarySlim<T, object>(239, s.Comparer);
				}
				s.State._pendingItems.GetOrAddValueRef(v, out var hasValue) = null;
				if (hasValue)
				{
					s.State._pendingItems.Remove(v);
				}
			}
		}

		public static void OnUnlocked(IReadOnlyObservableCollection _, ref TrackItemsNoLockImpl<T, TState> s)
		{
			bool flag = false;
			while (true)
			{
				PooledDictionarySlim<T, object> pooledDictionarySlim = default(PooledDictionarySlim<T, object>);
				try
				{
					lock (s)
					{
						if (s._started && !flag)
						{
							break;
						}
						flag = true;
						s._started = true;
						if (s._pendingItems.Count == 0)
						{
							s._pendingItems.Dispose();
							s._pendingItems = default(PooledDictionarySlim<T, object>);
							s._started = false;
							break;
						}
						pooledDictionarySlim = s._pendingItems;
						s._pendingItems = default(PooledDictionarySlim<T, object>);
					}
					foreach (KeyValuePair<T, object> item in pooledDictionarySlim)
					{
						((item.Value == null) ? s._onRemoved : s._onAdded)(item.Key, s._predicate.State);
					}
				}
				catch
				{
					if (flag)
					{
						s._started = false;
					}
					throw;
				}
				finally
				{
					pooledDictionarySlim.Dispose();
				}
			}
		}
	}
	internal sealed class TreeClosure<T, TId, TState> where T : class? where TId : notnull
	{
		private readonly ObservableCollectionPredicate<T, TState> _predicate;

		private readonly Func<T, Optional<TId>> _getParentId;

		private readonly Action<T, T, TState> _onChildAdded;

		private readonly Action<T, T, TState> _onChildRemoved;

		private readonly Action<T, T, TState>? _onParentRemoved;

		private readonly Action<T, TState>? _onAdded;

		private readonly Action<T, TState>? _onRemoved;

		private DictionarySlim<TId, ListSlim<T>> _parentIdToItems;

		public TreeClosure(ObservableCollectionPredicate<T, TState> predicate, Func<T, Optional<TId>> getParentId, Action<T, T, TState> onChildAdded, Action<T, T, TState> onChildRemoved, Action<T, T, TState>? onParentRemoved, Action<T, TState>? onAdded, Action<T, TState>? onRemoved, IEqualityComparer<TId>? comparer)
		{
			Should.NotBeNull(getParentId, "getParentId");
			Should.NotBeNull(onChildAdded, "onChildAdded");
			Should.NotBeNull(onChildRemoved, "onChildRemoved");
			_predicate = predicate;
			_getParentId = getParentId;
			_onChildAdded = onChildAdded;
			_onChildRemoved = onChildRemoved;
			_onParentRemoved = onParentRemoved;
			_onAdded = onAdded;
			_onRemoved = onRemoved;
			_parentIdToItems = new DictionarySlim<TId, ListSlim<T>>(comparer);
		}

		public static void OnAdded(TrackerCollectionDecorator<T, TId, (T item, Optional<TId> parentId), TreeClosure<T, TId, TState>> items, TrackerCollectionItemInfo<TId, T> itemInfo, ref (T item, Optional<TId> parentId) state)
		{
			Optional<TId> optional = items.State._getParentId(itemInfo.Item);
			state.item = itemInfo.Item;
			state.parentId = optional;
			items.State.OnAdded(items, optional, itemInfo.Key, itemInfo.Item);
			items.State._onAdded?.Invoke(itemInfo.Item, items.State._predicate.State);
		}

		public static void OnRemoved(TrackerCollectionDecorator<T, TId, (T item, Optional<TId> parentId), TreeClosure<T, TId, TState>> items, TId id, int count, ref (T item, Optional<TId> parentId) state)
		{
			items.State.OnRemoved(items, state.parentId, id, state.item);
			items.State._onRemoved?.Invoke(state.item, items.State._predicate.State);
		}

		public static void OnChanged(TrackerCollectionDecorator<T, TId, (T item, Optional<TId> parentId), TreeClosure<T, TId, TState>> items, TrackerCollectionItemInfo<TId, T> itemInfo, object? args, ref (T item, Optional<TId> parentId) state)
		{
			Optional<TId> optional = items.State._getParentId(itemInfo.Item);
			Optional<TId> item = state.parentId;
			if (!(item == optional))
			{
				state.parentId = optional;
				items.State.OnRemoved(items, item, itemInfo.Key, itemInfo.Item);
				items.State.OnAdded(items, optional, itemInfo.Key, itemInfo.Item);
			}
		}

		public static Optional<T> Condition(object? item, TreeClosure<T, TId, TState> s)
		{
			return s._predicate.GetItem(item);
		}

		private void OnAdded(TrackerCollectionDecorator<T, TId, (T item, Optional<TId> parentId), TreeClosure<T, TId, TState>> items, Optional<TId> parentId, TId id, T item)
		{
			if (parentId.HasValue)
			{
				_parentIdToItems.GetOrAddValueRef(parentId.GetValueOrDefault()).Add(item);
				if (items.TryGetState(parentId.GetValueOrDefault(), out ((T, Optional<TId>), int) state))
				{
					_onChildAdded(state.Item1.Item1, item, _predicate.State);
				}
			}
			ref ListSlim<T> valueRefOrNullRef = ref _parentIdToItems.GetValueRefOrNullRef(id);
			if (!Unsafe.IsNullRef(in valueRefOrNullRef))
			{
				ArraySegmentEnumerator<T> enumerator = valueRefOrNullRef.GetEnumerator();
				while (enumerator.MoveNext())
				{
					T current = enumerator.Current;
					_onChildAdded(item, current, _predicate.State);
				}
			}
		}

		private void OnRemoved(TrackerCollectionDecorator<T, TId, (T item, Optional<TId> parentId), TreeClosure<T, TId, TState>> items, Optional<TId> parentId, TId id, T item)
		{
			if (parentId.HasValue)
			{
				_parentIdToItems.GetOrAddValueRef(parentId.GetValueOrDefault()).Remove(item);
				if (items.TryGetState(parentId.GetValueOrDefault(), out ((T, Optional<TId>), int) state))
				{
					_onChildRemoved(state.Item1.Item1, item, _predicate.State);
				}
			}
			if (_onParentRemoved == null)
			{
				return;
			}
			ref ListSlim<T> valueRefOrNullRef = ref _parentIdToItems.GetValueRefOrNullRef(id);
			if (!Unsafe.IsNullRef(in valueRefOrNullRef))
			{
				ArraySegmentEnumerator<T> enumerator = valueRefOrNullRef.GetEnumerator();
				while (enumerator.MoveNext())
				{
					T current = enumerator.Current;
					_onParentRemoved(current, item, _predicate.State);
				}
			}
		}
	}
	internal abstract class WhereBindableClosure
	{
		protected sealed class Listener : SingleFastBindableListenerBase<bool>
		{
			private readonly WhereBindableClosure _state;

			private readonly object _item;

			public Listener(WhereBindableClosure state, object item)
			{
				_state = state;
				_item = item;
			}

			public override void OnValue(bool value)
			{
				_state.ValueChanged(_item, value);
			}
		}

		private static readonly object ReadyToRemoveMarker = new object();

		protected IReadOnlyObservableCollection? Collection;

		private DictionarySlim<object, object?> _values;

		private PooledItemOrList<ActionToken> _pendingItems;

		protected WhereBindableClosure()
		{
			_values = new DictionarySlim<object, object>(ReferenceEqualityComparer.Instance);
		}

		protected bool IsVisible(object item)
		{
			lock (this)
			{
				object value;
				return _values.TryGetValue(item, out value) && value != null;
			}
		}

		protected void Dispose(object item, ActionToken disposable)
		{
			lock (this)
			{
				_pendingItems.Add(disposable);
				_values.GetOrAddValueRef(item) = this;
			}
		}

		protected void Remove(object item)
		{
			lock (this)
			{
				_values.Remove(item);
			}
		}

		protected void DisposePending()
		{
			PooledItemOrList<ActionToken> pendingItems;
			lock (this)
			{
				if (_pendingItems.Count == 0)
				{
					return;
				}
				pendingItems = _pendingItems;
				_pendingItems = default(PooledItemOrList<ActionToken>);
				using DictionarySlimEnumerator<object, object> dictionarySlimEnumerator = _values.GetEnumerator();
				while (dictionarySlimEnumerator.MoveNext())
				{
					if (dictionarySlimEnumerator.Current.Value == this)
					{
						dictionarySlimEnumerator.CurrentValueRef = ReadyToRemoveMarker;
					}
				}
			}
			try
			{
				ArraySegmentEnumerator<ActionToken> enumerator = pendingItems.GetEnumerator();
				while (enumerator.MoveNext())
				{
					enumerator.Current.Dispose();
				}
			}
			finally
			{
				pendingItems.Dispose();
			}
			lock (this)
			{
				foreach (KeyValuePair<object, object> value in _values)
				{
					if (value.Value == ReadyToRemoveMarker)
					{
						_values.Remove(value.Key);
					}
				}
			}
		}

		internal void ValueChanged(object item, bool value)
		{
			bool flag;
			lock (this)
			{
				ref object orAddValueRef = ref _values.GetOrAddValueRef(item);
				if (orAddValueRef == this || orAddValueRef == ReadyToRemoveMarker)
				{
					return;
				}
				flag = orAddValueRef != null;
				orAddValueRef = (value ? "" : null);
			}
			if (flag != value)
			{
				Collection.RaiseItemChanged(item);
			}
		}
	}
	internal sealed class WhereBindableClosure<T, TState> : WhereBindableClosure where T : class
	{
		private readonly ObservableCollectionPredicate<T, TState> _predicate;

		private readonly Func<T, TState, Bindable<bool>> _filter;

		public WhereBindableClosure(ObservableCollectionPredicate<T, TState> predicate, Func<T, TState, Bindable<bool>> filter)
		{
			_predicate = predicate;
			_filter = filter;
		}

		public static Optional<T> Condition(object? item, WhereBindableClosure<T, TState> s)
		{
			return s._predicate.GetItem(item);
		}

		public static void OnAdded(TrackerCollectionDecorator<T, T, ActionToken, WhereBindableClosure<T, TState>> tracker, TrackerCollectionItemInfo<T, T> itemInfo, [MustDisposeResource] ref ActionToken state)
		{
			if (itemInfo.Count != 1)
			{
				return;
			}
			Bindable<bool> bindable = tracker.State._filter(itemInfo.Item, tracker.State._predicate.State);
			if (bindable.IsInitialized && !bindable.IsConstant)
			{
				WhereBindableClosure<T, TState> state2 = tracker.State;
				if (state2.Collection == null)
				{
					state2.Collection = tracker.Owner;
				}
				state = bindable.Bind(new Listener(tracker.State, itemInfo.OriginalItem), initialSync: false);
			}
		}

		public static void OnRemoved(TrackerCollectionDecorator<T, T, ActionToken, WhereBindableClosure<T, TState>> tracker, T item, int count, ref ActionToken state)
		{
			if (count == 0 && state.IsInitialized)
			{
				tracker.State.Dispose(item, state);
			}
		}

		public static bool Where(T item, WhereBindableClosure<T, TState> state)
		{
			return state.IsVisible(item);
		}

		public static void OnUnlocked(IReadOnlyObservableCollection collection, ref WhereBindableClosure<T, TState> state)
		{
			state.DisposePending();
		}
	}
