					pooledReadOnlyList = _callbacks.ToPooledReadOnlyList();
				}
				foreach (IBusyTokenCallback item in pooledReadOnlyList)
				{
					item.OnCompleted(this);
				}
			}
			finally
			{
				OnDisposed();
				pooledReadOnlyList.Dispose();
				_callbacks.Dispose();
			}
		}

		protected abstract bool DisposeCore();

		protected virtual void OnDisposed()
