		[StructLayout(LayoutKind.Sequential, Size = 1)]
		public readonly struct CacheSpec<T, TState>
		{
			public Cacheable<T, TState, TResource> CacheAs<TResource>(Func<T, TState, TResource> factory, string cacheKey) where TResource : class?, IDisposable?
			{
				return new Cacheable<T, TState, TResource>(factory, cacheKey);
			}

			public Cacheable<T, TState, TResource> Volatile<TResource>(Func<T, TState, TResource> factory) where TResource : class?, IDisposable?
			{
				return new Cacheable<T, TState, TResource>(factory, null);
			}
		}

		public readonly struct Cacheable<T, TState, TResource> where TResource : class?, IDisposable?
		{
			private readonly Func<T, TState, TResource> _factory;

			internal readonly string? CacheKey;

			internal Cacheable(Func<T, TState, TResource> factory, string? cacheKey)
			{
				_factory = factory;
				CacheKey = cacheKey;
			}

			internal TResource GetItem(T item, TState state)
			{
				return _factory(item, state);
			}
		}

		private const string ValueName = "Value";

		internal static readonly IExpressionNode ConstantMember = MemberExpressionNode.Empty.UpdateMetadata(BindingBuilderMetadata.Weak.ToContext(value: false));

		internal static readonly IExpressionNode ValueMember = new MemberExpressionNode(null, "Value", ConstantMember.Metadata);

		internal static readonly IExpressionNode ValueMemberRaw = new MemberExpressionNode(null, "Value", ConstantMember.Metadata);

		internal static readonly IExpressionNode ValueValueMember = new MemberExpressionNode(MemberExpressionNode.Get("Value"), "Value");

		internal static readonly IExpressionNode ValueUnwrapMember = new MemberExpressionNode(null, "Value~@#B");

		internal static readonly IExpressionNode WeakTargetMember = MemberExpressionNode.Empty.UpdateMetadata(BindingBuilderMetadata.Weak.ToContext(value: true));

		public static Bindable<bool> And(this Bindable<bool> bindable1, Bindable<bool> bindable2)
		{
			return bindable1.Combine(bindable2, (bool b1, bool b2) => b1 && b2);
		}

		public static Bindable<bool> Or(this Bindable<bool> bindable1, Bindable<bool> bindable2)
		{
			return bindable1.Combine(bindable2, (bool b1, bool b2) => b1 || b2);
		}

		public static Bindable<TResult> Combine<T1, T2, TResult>(this Bindable<T1> bindable1, Bindable<T2> bindable2, Func<T1, T2, TResult> map)
		{
			Should.NotBeNull(map, "map");
			if (bindable1.IsConstantOrUninitialized() && bindable2.IsConstantOrUninitialized())
			{
				return Constant(map(bindable1.Constant, bindable2.Constant));
			}
			return new Bindable<TResult>(map, new Combine2Expression<T1, T2, TResult>(bindable1, bindable2));
		}

		public static Bindable<bool> And(this Bindable<bool> bindable1, Bindable<bool> bindable2, Bindable<bool> bindable3)
		{
			return bindable1.Combine(bindable2, bindable3, (bool b1, bool b2, bool b3) => b1 && b2 && b3);
		}

		public static Bindable<bool> Or(this Bindable<bool> bindable1, Bindable<bool> bindable2, Bindable<bool> bindable3)
		{
			return bindable1.Combine(bindable2, bindable3, (bool b1, bool b2, bool b3) => b1 || b2 || b3);
		}

		public static Bindable<TResult> Combine<T1, T2, T3, TResult>(this Bindable<T1> bindable1, Bindable<T2> bindable2, Bindable<T3> bindable3, Func<T1, T2, T3, TResult> map)
		{
			Should.NotBeNull(map, "map");
			if (bindable1.IsConstantOrUninitialized() && bindable2.IsConstantOrUninitialized() && bindable3.IsConstantOrUninitialized())
			{
