		public static Bindable<T> Delay<T>(this Bindable<T> bindable, int milliseconds)
		{
			if (milliseconds <= 0 || !bindable.IsInitialized)
			{
				return bindable;
			}
			if (bindable.IsConstant)
			{
				return FromAsync<T, (T, int)>((bindable.Constant, milliseconds), async delegate((T Constant, int milliseconds) v, CancellationToken t)
				{
					await Task.Delay(v.milliseconds, t).ConfigureAwait(continueOnCapturedContext: false);
					return v.Constant;
				});
			}
			return bindable.SelectAsync<T, T>(async delegate(T v, CancellationToken t)
			{
				await Task.Delay(milliseconds, t).ConfigureAwait(continueOnCapturedContext: false);
				return v;
			});
		}

