		public static Bindable<TValue> BindRaw<T, TValue>(Bindable<T> bindable, object expression)
		{
			Should.NotBeNull(expression, "expression");
			if (!bindable.IsInitialized)
			{
				return default(Bindable<TValue>);
			}
			if (bindable.IsConstant && bindable.Constant.EqualsByRefOrValue<T>(default(T)))
			{
				return default(Bindable<TValue>);
			}
			IHasReadOnlyValue<T> readOnlyValue = bindable.ReadOnlyValue;
			if (readOnlyValue != null)
			{
				return new Bindable<TValue>(readOnlyValue, expression);
			}
			if (((bindable._expression is IHasExpressionBindableProvider<T> hasExpressionBindableProvider) ? hasExpressionBindableProvider.GetExpression(bindable._target) : bindable._expression) is IHasTargetExpressionNode<IExpressionNode> target)
			{
				IHasTargetExpressionNode<IExpressionNode> hasTargetExpressionNode = expression as IHasTargetExpressionNode<IExpressionNode>;
				if (hasTargetExpressionNode != null)
				{
					if (hasTargetExpressionNode.Target == null && hasTargetExpressionNode is IMemberExpressionNode { Member: "Value" })
					{
						return new Bindable<TValue>(bindable._target, bindable._expression, default(TValue));
					}
					IHasTargetExpressionNode<IExpressionNode> hasTargetExpressionNode2 = hasTargetExpressionNode;
					while (hasTargetExpressionNode2?.Target != null)
					{
						hasTargetExpressionNode = hasTargetExpressionNode2;
						hasTargetExpressionNode2 = hasTargetExpressionNode2.Target as IHasTargetExpressionNode<IExpressionNode>;
					}
					if (hasTargetExpressionNode2 != null)
					{
						if (bindable._expression is IHasExpressionBindableProvider<T> hasExpressionBindableProvider2)
						{
							bindable = hasExpressionBindableProvider2.UpdateExpression(bindable._target, hasTargetExpressionNode.UpdateTarget(target));
							return new Bindable<TValue>(bindable._target, bindable._expression, default(TValue));
						}
						if (!bindable.IsConstant)
						{
							return new Bindable<TValue>(bindable._target, hasTargetExpressionNode.UpdateTarget(target));
						}
						return new Bindable<TValue>(bindable.Constant, hasTargetExpressionNode.UpdateTarget(null));
					}
				}
			}
			object exp;
			return new Bindable<TValue>(BindableExpressionBase<T>.GetExpression(bindable, expression, out exp), exp);
		}

