		internal static IHasReadOnlyValue<T?> ToValue<T>(this Bindable<T> bindable, bool isWeak, out ActionToken disposeToken)
		{
			if (!bindable.IsInitialized || bindable.IsConstant)
			{
				disposeToken = default(ActionToken);
				return new HasValueImpl<T>(bindable.Constant);
			}
			IHasReadOnlyValue<T> readOnlyValue = bindable.ReadOnlyValue;
			if (readOnlyValue != null)
			{
				disposeToken = default(ActionToken);
				return readOnlyValue;
			}
			if (!isWeak && bindable._expression is IValueBindableProvider<T> valueBindableProvider)
			{
				IBindableReadOnlyValue<T> bindableReadOnlyValue = valueBindableProvider.ToValue(bindable._target, out disposeToken);
				if (bindableReadOnlyValue != null)
				{
					return bindableReadOnlyValue;
				}
			}
			ListenerBindableValue<T> listenerBindableValue = new ListenerBindableValue<T>();
			disposeToken = (isWeak ? bindable.BindWeak(listenerBindableValue) : bindable.Bind(listenerBindableValue));
			return listenerBindableValue;
		}

		[DynamicDependency("_Convert_``1(System.Object)", typeof(BindingMacrosMethodExtensions))]
		internal static Bindable<TTo> ConvertCore<T, TTo>(Bindable<T> bindable)
		{
			if (!bindable.IsInitialized)
			{
				return default(Bindable<TTo>);
			}
			if (bindable.IsConstant)
			{
				return new Bindable<TTo>(MugenExtensions.Convert<T, TTo>(bindable.Constant));
			}
			IExpressionNode expressionNode;
			if (bindable.ReadOnlyValue == null)
			{
				expressionNode = bindable._expression as IExpressionNode;
				if (expressionNode == null)
				{
					return new Bindable<TTo>(bindable._target, bindable._expression, default(TTo));
				}
			}
			else
			{
				expressionNode = ValueMemberRaw;
			}
			if (!typeof(T).IsValueType)
			{
				if (!RuntimeFeature.IsDynamicCodeSupported && Default.FalseCondition)
				{
					BindingMacrosMethodExtensions._Convert_<TTo>(null);
				}
				expressionNode = new MethodCallExpressionNode(expressionNode, "_Convert_", default(ItemOrIReadOnlyList<IExpressionNode>), typeof(TTo).AssemblyQualifiedName);
			}
			return new Bindable<TTo>(bindable._target, expressionNode, default(TTo));
		}

		[UnconditionalSuppressMessage("Trimming", "IL2072")]
		internal static bool TryGetSimpleProperty(object bindable, object? member, [NotNullWhen(true)] out IAccessorMemberInfo? accessor)
		{
			string name;
			if (member is Expression body && body.TryGetSimpleProperty(out PropertyInfo property))
			{
				name = property.Name;
			}
			else
			{
				if (!(member is IMemberExpressionNode { Target: null } memberExpressionNode))
				{
					accessor = null;
					return false;
				}
				name = memberExpressionNode.Member;
			}
			accessor = IMugenService<IReflectionManager>.Instance.TryGetMember(bindable.GetType(), (FlagsEnumBase<MemberType, ushort>?)MemberType.Accessor, MemberFlags.InstanceAll, name) as IAccessorMemberInfo;
			return accessor != null;
		}

		internal static bool TrySetConstant<T, TState>(Bindable<T> bindable, TState state, Action<T, TState> setter, Action<Exception, BindableErrorType, TState>? onError)
		{
			if (!bindable.IsInitialized)
			{
				return true;
			}
			if (bindable.IsConstant)
			{
				try
				{
					setter(bindable.Constant, state);
					return true;
				}
				catch (Exception arg)
				{
					if (onError == null)
					{
						throw;
					}
					onError(arg, BindableErrorType.Unhandled, state);
					return true;
				}
			}
			return false;
		}
	}
	public readonly struct Bindable<T> : IEquatable<Bindable<T>>, IHasInitializedState, IBindable
	{
		internal readonly object? _target;

		internal readonly object? _expression;

		public bool IsConstant
		{
			[MemberNotNullWhen(true, "Constant")]
			get
			{
				return _expression == Bindable.ConstantMember;
			}
		}

		public IObservable<T>? Observable => _target as IObservable<T>;

		public IHasReadOnlyValue<T>? ReadOnlyValue
		{
