	public abstract class TokenParserContextBase<T> : ITokenParserContext
	{
		private int? _limit;

		private int _position;

		private int _length;

		public T Source { get; private set; }

		public int Position
		{
			get
			{
				return _position;
			}
			set
			{
				Should.BeValid(value <= Length && value >= 0, "value");
				_position = value;
			}
		}

		public int? Limit
		{
			get
			{
				return _limit;
			}
			set
			{
				Should.BeValid(!value.HasValue || (value.Value <= _length && value >= 0), "value");
				_limit = value;
			}
		}

		public int Length => _limit ?? _length;

		public abstract char TokenAt(int position);

		public abstract ReadOnlySpan<char> GetValue(int start, int end);

		public override string ToString()
		{
			return $"Position='{Position}', CurrentToken='{GetToken(Position)}', PrevToken='{GetToken(Position - 1)}', NextToken='{GetToken(Position + 1)}', Source='{Source}'";
		}

		public void Initialize(T source)
		{
			Source = source;
			Position = 0;
			Limit = null;
			_length = GetLength();
		}

		protected abstract int GetLength();

		private string GetToken(int position)
		{
			if (this.IsEof(position))
			{
				return "EOF";
			}
			if (position < 0)
			{
				return "BOF";
			}
			return TokenAt(position).ToString();
