			BindingInstanceMemberExpressionNode bindingImpl = new BindingInstanceMemberExpressionNode(Bind.BindingGetter, "", 0, default(EnumFlags<MemberObserverFlags>), default(EnumFlags<MemberFlags>), null, null, typeof(IBinding));
			BindingInstanceMemberExpressionNode eventArgsImpl = new BindingInstanceMemberExpressionNode(Bind.EventArgsGetter, "", 0, default(EnumFlags<MemberObserverFlags>), default(EnumFlags<MemberFlags>));
			Macros = new DictionarySlim<string, Func<IReadOnlyMetadataContext, IExpressionNode>>(3);
			Macros.GetOrAddValueRef("binding") = (IReadOnlyMetadataContext? _) => bindingImpl;
			Macros.GetOrAddValueRef("args") = (IReadOnlyMetadataContext? _) => eventArgsImpl;
