			MethodAliases.GetOrAddValueRef("Format") = new MethodCallExpressionNode(TypeAccessExpressionNode.Get<string>(), "Format", default(ItemOrIReadOnlyList<IExpressionNode>));
			MethodAliases.GetOrAddValueRef("Equals") = new MethodCallExpressionNode(TypeAccessExpressionNode.Get<object>(), "Equals", default(ItemOrIReadOnlyList<IExpressionNode>));
			MethodAliases.GetOrAddValueRef("ReferenceEquals") = new MethodCallExpressionNode(TypeAccessExpressionNode.Get<object>(), "ReferenceEquals", default(ItemOrIReadOnlyList<IExpressionNode>));
			AccessorMethods = new DictionarySlim<string, string>(11);
			AccessorMethods.GetOrAddValueRef("GetErrors") = "GetErrors";
			AccessorMethods.GetOrAddValueRef("GetError") = "GetError";
			AccessorMethods.GetOrAddValueRef("HasErrors") = "HasErrors";
			AccessorMethods.GetOrAddValueRef("Rel") = "RelativeSource";
			AccessorMethods.GetOrAddValueRef("Relative") = "RelativeSource";
			AccessorMethods.GetOrAddValueRef("RelativeSource") = "RelativeSource";
			AccessorMethods.GetOrAddValueRef("El") = "ElementSource";
			AccessorMethods.GetOrAddValueRef("Element") = "ElementSource";
			AccessorMethods.GetOrAddValueRef("ElementSource") = "ElementSource";
			AccessorMethods.GetOrAddValueRef("CanExecute") = "CanExecute";
			MacrosTargets = new DictionarySlim<string, IExpressionNode>(11);
			MacrosTargets.GetOrAddValueRef("GetErrors") = UnaryExpressionNode.ContextMacros;
			MacrosTargets.GetOrAddValueRef("GetError") = UnaryExpressionNode.ContextMacros;
			MacrosTargets.GetOrAddValueRef("HasErrors") = UnaryExpressionNode.ContextMacros;
			MacrosTargets.GetOrAddValueRef("Rel") = UnaryExpressionNode.SelfMacros;
			MacrosTargets.GetOrAddValueRef("RelativeSource") = UnaryExpressionNode.SelfMacros;
			MacrosTargets.GetOrAddValueRef("El") = UnaryExpressionNode.SelfMacros;
			MacrosTargets.GetOrAddValueRef("Element") = UnaryExpressionNode.SelfMacros;
			MacrosTargets.GetOrAddValueRef("ElementSource") = UnaryExpressionNode.SelfMacros;
