		public IExpressionNode Visit(IExpressionNode expression, IReadOnlyMetadataContext? metadata)
		{
			if (expression is IMethodCallExpressionNode methodCallExpressionNode && AccessorMethods.TryGetValue(methodCallExpressionNode.Method, out string value))
			{
				ItemOrIReadOnlyList<IExpressionNode> arguments = methodCallExpressionNode.Arguments;
				if (arguments.Count == 0)
				{
					if (methodCallExpressionNode.Method == value)
					{
						return methodCallExpressionNode.UpdateMetadata(methodCallExpressionNode.Metadata.MergeToNewContext(AccessorMetadata));
					}
					return new MethodCallExpressionNode(methodCallExpressionNode.Target, value, default(ItemOrIReadOnlyList<IExpressionNode>), methodCallExpressionNode.TypeArgs, methodCallExpressionNode.Metadata.MergeToNewContext(AccessorMetadata));
				}
				if (methodCallExpressionNode.Method == value && arguments.IsConstants())
				{
					return methodCallExpressionNode.UpdateMetadata(methodCallExpressionNode.Metadata.MergeToNewContext(AccessorMetadata));
				}
				ItemOrArray<IExpressionNode> array = ItemOrArray.Get<IExpressionNode>(arguments.Count);
				for (int i = 0; i < array.Count; i++)
				{
					IExpressionNode expressionNode = arguments[i];
					if (expressionNode is IConstantExpressionNode)
					{
						array.SetAt(i, expressionNode);
						continue;
					}
					if (!expressionNode.TryBuildBindingMemberPath(_memberBuilder, (IExpressionNode n) => n is IMemberExpressionNode, null, out IExpressionNode _))
