					}
					CollectionSlimExtensions.SetAt(ref array, i, ConstantExpressionNode.Get(_memberBuilder.GetPath(), typeof(string)));
				}
				return new MethodCallExpressionNode(methodCallExpressionNode.Target, value, array, methodCallExpressionNode.TypeArgs, methodCallExpressionNode.Metadata.MergeToNewContext(AccessorMetadata));
			}
			if (expression is IUnaryExpressionNode unaryExpressionNode && unaryExpressionNode.IsMacros())
			{
				if (unaryExpressionNode.Operand is IMemberExpressionNode memberExpressionNode && Macros.TryGetValue(memberExpressionNode.Member, out Func<IReadOnlyMetadataContext, IExpressionNode> value2))
