					return value2(metadata);
				}
				if (unaryExpressionNode.Operand is IMethodCallExpressionNode methodCallExpressionNode2)
				{
					if (MethodAliases.TryGetValue(methodCallExpressionNode2.Method, out IMethodCallExpressionNode value3))
					{
						return value3.UpdateArguments(methodCallExpressionNode2.Arguments);
					}
					if (methodCallExpressionNode2.Target == null && MacrosTargets.TryGetValue(methodCallExpressionNode2.Method, out IExpressionNode value4))
					{
						return methodCallExpressionNode2.UpdateTarget(value4);
					}
				}
			}
			return expression;
		}
	}
	public sealed class ObservableMethodExpressionVisitor : IExpressionVisitor
	{
		public ExpressionTraversalType TraversalType => ExpressionTraversalType.Postorder;

		public IExpressionNode Visit(IExpressionNode expression, IReadOnlyMetadataContext? metadata)
		{
			if (expression is IMethodCallExpressionNode { Method: "ObservableMethod", Target: not null } methodCallExpressionNode && methodCallExpressionNode.Arguments.Count == 1 && methodCallExpressionNode.Arguments[0].TryGetStringValue(out string value))
			{
				return methodCallExpressionNode.Target.UpdateMetadata(methodCallExpressionNode.Target.Metadata.WithValue(BindingBuilderMetadata.ObservableMethodName, value));
			}
			return expression;
		}
	}
