				return null;
			}
			return new BinaryExpressionNode(BinaryTokenType.Assignment, expression, expressionNode);
		}
	}
	public sealed class BinaryTokenParser : TokenParserBase
	{
		internal ListSlim<BinaryTokenType> Tokens;

		public BinaryTokenParser(int priority = 9500)
			: base(priority)
		{
			Tokens = new ListSlim<BinaryTokenType>(19);
			Tokens.Add(BinaryTokenType.LeftShift);
			Tokens.Add(BinaryTokenType.RightShift);
			Tokens.Add(BinaryTokenType.LessThanOrEqual);
			Tokens.Add(BinaryTokenType.GreaterThanOrEqual);
			Tokens.Add(BinaryTokenType.Equality);
			Tokens.Add(BinaryTokenType.NotEqual);
			Tokens.Add(BinaryTokenType.ConditionalAnd);
			Tokens.Add(BinaryTokenType.ConditionalOr);
			Tokens.Add(BinaryTokenType.NullCoalescing);
			Tokens.Add(BinaryTokenType.Multiplication);
			Tokens.Add(BinaryTokenType.Division);
			Tokens.Add(BinaryTokenType.Remainder);
			Tokens.Add(BinaryTokenType.Addition);
			Tokens.Add(BinaryTokenType.Subtraction);
			Tokens.Add(BinaryTokenType.LessThan);
			Tokens.Add(BinaryTokenType.GreaterThan);
			Tokens.Add(BinaryTokenType.LogicalAnd);
			Tokens.Add(BinaryTokenType.LogicalXor);
			Tokens.Add(BinaryTokenType.LogicalOr);
		}

		protected override IExpressionNode? TryParse(ITokenParserContext context, IExpressionNode? expression, IBindingManager apiProvider, IReadOnlyMetadataContext? metadata, CancellationToken cancellationToken)
		{
			if (expression == null)
			{
				return null;
			}
			BinaryTokenType token = GetToken(context.SkipWhitespaces());
			if (token == null)
			{
				return null;
			}
			using PooledItemOrList<IExpressionNode> pooledItemOrList = default(PooledItemOrList<IExpressionNode>);
			using PooledItemOrList<BinaryTokenType> tokens = default(PooledItemOrList<BinaryTokenType>);
			pooledItemOrList.Add(expression);
			tokens.Add(token);
			expression = null;
			while (true)
			{
				IExpressionNode expressionNode = context.TryParse(expression, base.Priority, metadata, cancellationToken);
				if (expressionNode == null)
				{
					if (expression != null)
					{
						pooledItemOrList.Add(expression);
					}
					break;
				}
				expression = expressionNode;
				if (context.SkipWhitespaces().IsEof())
				{
					pooledItemOrList.Add(expression);
					break;
				}
				token = GetToken(context);
				if (token != null)
				{
					pooledItemOrList.Add(expression);
					expression = null;
					tokens.Add(token);
				}
			}
			if (pooledItemOrList.Count - 1 != tokens.Count)
			{
				apiProvider.GetRequestTracer(metadata)?.AddMessage("Cannot parse binary expression '{0} {1} ' right expression expected".Format(pooledItemOrList[pooledItemOrList.Count - 1], tokens[tokens.Count - 1]));
				return null;
			}
			for (int maxPriorityTokenIndex = GetMaxPriorityTokenIndex(tokens); maxPriorityTokenIndex != -1; maxPriorityTokenIndex = GetMaxPriorityTokenIndex(tokens))
			{
				token = tokens[maxPriorityTokenIndex];
				tokens.RemoveAt(maxPriorityTokenIndex);
				pooledItemOrList.Set(maxPriorityTokenIndex, new BinaryExpressionNode(token, pooledItemOrList[maxPriorityTokenIndex], pooledItemOrList[maxPriorityTokenIndex + 1]));
				pooledItemOrList.RemoveAt(maxPriorityTokenIndex + 1);
			}
			return pooledItemOrList[0];
		}

		private static int GetMaxPriorityTokenIndex(PooledItemOrList<BinaryTokenType> tokens)
		{
			if (tokens.Count == 0)
			{
				return -1;
			}
			if (tokens.Count == 1)
			{
				return 0;
			}
			int result = -1;
			int num = int.MinValue;
			for (int i = 0; i < tokens.Count; i++)
			{
				if (tokens[i].Priority > num)
				{
					num = tokens[i].Priority;
					result = i;
				}
			}
			return result;
		}

		private BinaryTokenType? GetToken(ITokenParserContext context)
		{
			for (int i = 0; i < Tokens.Count; i++)
			{
				BinaryTokenType binaryTokenType = Tokens[i];
				if (context.IsToken(binaryTokenType.Value))
				{
					context.MoveNext(binaryTokenType.Value.Length);
					return binaryTokenType;
				}
				ReadOnlySpan<string> readOnlySpan = binaryTokenType.Aliases.ReadOnlySpan;
				for (int j = 0; j < readOnlySpan.Length; j++)
				{
					string text = readOnlySpan[j];
					if (context.IsToken(text))
					{
						context.MoveNext(text.Length);
						return binaryTokenType;
					}
				}
			}
			return null;
		}
	}
	public sealed class BindingTokenParser : TokenParserBase
	{
		public BindingTokenParser(int priority = 100000)
			: base(priority)
		{
		}

		protected override IExpressionNode? TryParse(ITokenParserContext context, IExpressionNode? expression, IBindingManager apiProvider, IReadOnlyMetadataContext? metadata, CancellationToken cancellationToken)
		{
			if (expression != null || metadata.Get(BindingBuilderMetadata.SuppressBindingParser, defaultValue: false))
			{
				return null;
			}
			metadata = metadata.WithValue(BindingBuilderMetadata.SuppressBindingParser, value: true);
			try
			{
				ItemOrList<IBindingExpressionNode> itemOrList = default(ItemOrList<IBindingExpressionNode>);
				while (!context.IsEof())
				{
					BindingExpressionNode bindingExpressionNode = TryParseNext(context, metadata, cancellationToken);
					if (bindingExpressionNode == null)
					{
						return null;
					}
					itemOrList.Add(bindingExpressionNode);
					context.SkipWhitespaces();
				}
				if (itemOrList.Count == 0)
				{
					return null;
				}
				if (itemOrList.Count == 1)
				{
					return itemOrList[0];
				}
				return new BatchBindingExpressionNode(itemOrList);
			}
			finally
			{
				(metadata as IMetadataContext)?.Remove(BindingBuilderMetadata.SuppressBindingParser);
			}
		}

		private static BindingExpressionNode? TryParseNext(ITokenParserContext context, IReadOnlyMetadataContext? metadata, CancellationToken cancellationToken)
		{
			Span<char> span = stackalloc char[3] { ',', ';', ' ' };
			Span<char> span2 = stackalloc char[2] { ',', ';' };
			bool flag = context.SkipWhitespaces().IsToken('@');
			int num;
			if (flag)
			{
				context.MoveNext();
				num = -1;
			}
			else
			{
				num = context.FindAnyOf(span);
			}
			int? limit = context.Limit;
			if (num > 0)
			{
				context.Limit = num;
			}
			ReadOnlySpan<char> tokens = span2;
			IReadOnlyMetadataContext metadata2 = metadata;
			CancellationToken cancellationToken2 = cancellationToken;
			IExpressionNode expressionNode = context.TryParseWhileAnyOf(tokens, null, null, null, metadata2, cancellationToken2);
			if (expressionNode == null)
			{
				return null;
			}
			context.Limit = limit;
			IExpressionNode expressionNode2 = null;
			if (context.IsToken(' '))
			{
				ReadOnlySpan<char> tokens2 = span2;
				metadata2 = metadata;
				cancellationToken2 = cancellationToken;
				expressionNode2 = context.TryParseWhileAnyOf(tokens2, null, null, null, metadata2, cancellationToken2);
				if (expressionNode2 == null)
				{
					return null;
				}
			}
			ItemOrList<IExpressionNode> itemOrList = new ItemOrList<IExpressionNode>(2);
			while (context.IsToken(','))
			{
				ITokenParserContext context2 = context.MoveNext();
				ReadOnlySpan<char> tokens3 = span2;
				metadata2 = metadata;
				cancellationToken2 = cancellationToken;
				IExpressionNode expressionNode3 = context2.TryParseWhileAnyOf(tokens3, null, null, null, metadata2, cancellationToken2);
				if (expressionNode3 == null)
				{
					return null;
				}
				itemOrList.Add(expressionNode3);
			}
			if (context.SkipWhitespaces().IsEof() || context.IsToken(';'))
			{
				if (context.IsToken(';'))
				{
					context.MoveNext();
				}
				if (flag)
				{
					return new BindingExpressionNode(null, expressionNode, itemOrList);
				}
				return new BindingExpressionNode(expressionNode, expressionNode2 ?? MemberExpressionNode.Empty, itemOrList);
			}
			return null;
		}
