			if (expressionNode == null || !context.SkipWhitespaces().IsToken(':'))
			{
				apiProvider.GetRequestTracer(metadata)?.AddMessage((expressionNode == null) ? "Cannot parse condition expression '{0} ? ' expected expression".Format(expression) : "Cannot parse condition expression '{0} ? {1} ' expected token ':'".Format(expression, expressionNode));
