	public sealed class ConstantTokenParser : TokenParserBase
	{
		internal DictionarySlim<string, IExpressionNode> LiteralToExpression;

		public ConstantTokenParser(DictionarySlim<string, IExpressionNode> expressions, int priority)
			: base(priority)
		{
			LiteralToExpression = expressions;
		}

		public ConstantTokenParser(int priority = 10000)
			: base(priority)
		{
			LiteralToExpression = new DictionarySlim<string, IExpressionNode>(3);
			LiteralToExpression.GetOrAddValueRef("null") = ConstantExpressionNode.Null;
			LiteralToExpression.GetOrAddValueRef("true") = ConstantExpressionNode.True;
			LiteralToExpression.GetOrAddValueRef("false") = ConstantExpressionNode.False;
		}

		protected override IExpressionNode? TryParse(ITokenParserContext context, IExpressionNode? expression, IBindingManager apiProvider, IReadOnlyMetadataContext? metadata, CancellationToken cancellationToken)
		{
			if (expression != null)
			{
				return null;
			}
			int num = context.SkipWhitespacesPosition();
			foreach (KeyValuePair<string, IExpressionNode> item in LiteralToExpression)
			{
				if (context.IsToken(item.Key, num, isPartOfIdentifier: false))
				{
					context.Position = num + item.Key.Length;
					return item.Value;
				}
			}
			return null;
		}
	}
	public sealed class DigitTokenParser : TokenParserBase
	{
		public delegate IExpressionNode? ConvertDelegate(ReadOnlySpan<char> value, bool integer, ReadOnlySpan<char> postfix, ITokenParserContext context, IFormatProvider formatProvider);

		private DictionarySlim<string, ConvertDelegate> _postfixToConverter;

		public IFormatProvider? FormatProvider { get; set; }

		public DigitTokenParser(int priority = 10000)
			: base(priority)
		{
			ConvertDelegate convertDelegate = Convert;
			_postfixToConverter = new DictionarySlim<string, ConvertDelegate>(17);
			_postfixToConverter.GetOrAddValueRef("") = convertDelegate;
			_postfixToConverter.GetOrAddValueRef("f") = convertDelegate;
			_postfixToConverter.GetOrAddValueRef("F") = convertDelegate;
			_postfixToConverter.GetOrAddValueRef("d") = convertDelegate;
			_postfixToConverter.GetOrAddValueRef("D") = convertDelegate;
			_postfixToConverter.GetOrAddValueRef("m") = convertDelegate;
			_postfixToConverter.GetOrAddValueRef("M") = convertDelegate;
			_postfixToConverter.GetOrAddValueRef("u") = convertDelegate;
			_postfixToConverter.GetOrAddValueRef("U") = convertDelegate;
			_postfixToConverter.GetOrAddValueRef("ul") = convertDelegate;
			_postfixToConverter.GetOrAddValueRef("UL") = convertDelegate;
			_postfixToConverter.GetOrAddValueRef("Ul") = convertDelegate;
			_postfixToConverter.GetOrAddValueRef("uL") = convertDelegate;
		}

		public void SetConverter(string prefix, ConvertDelegate converter)
		{
			Should.NotBeNull(prefix, "prefix");
			Should.NotBeNull(converter, "converter");
			_postfixToConverter.GetOrAddValueRef(prefix) = converter;
		}

		public void ClearConverters()
		{
			_postfixToConverter.Clear();
		}

		protected override IExpressionNode? TryParse(ITokenParserContext context, IExpressionNode? expression, IBindingManager apiProvider, IReadOnlyMetadataContext? metadata, CancellationToken cancellationToken)
		{
			if (expression != null)
			{
				return null;
			}
			int num = context.SkipWhitespacesPosition();
			if (!context.IsDigit(num) && !context.IsToken('-', num))
			{
				return null;
			}
			if (context.IsToken('-'))
			{
				context.MoveNext();
			}
			bool integer = true;
			int num2 = num;
			do
			{
				num2++;
			}
			while (context.IsDigit(num2));
			if (context.IsToken('.', num2) && context.IsDigit(num2 + 1))
			{
				integer = false;
				do
				{
					num2++;
				}
				while (context.IsDigit(num2));
			}
			if (context.IsToken('e', num2) || context.IsToken('E', num2))
			{
				integer = false;
				num2++;
				if (context.IsToken('+', num2) || context.IsToken('-', num2))
				{
					num2++;
				}
				if (!context.IsDigit(num2))
				{
					if (!context.IsEof(num2))
					{
						num2++;
					}
					apiProvider.GetRequestTracer(metadata)?.AddMessage("Cannot parse digit expression '{0}'".Format(context.GetValue(num, num2)));
					return null;
				}
				do
				{
					num2++;
				}
				while (context.IsDigit(num2));
			}
			ReadOnlySpan<char> value = context.GetValue(num, num2);
			ReadOnlySpan<char> readOnlySpan = "";
			if (context.IsIdentifier(out var endPosition, num2))
			{
				readOnlySpan = context.GetValue(num2, endPosition);
				num2 = endPosition;
			}
			if (_postfixToConverter.TryGetValueAlternate(readOnlySpan, out var value2))
			{
				IExpressionNode expressionNode = value2(value, integer, readOnlySpan, context, FormatProvider ?? CultureInfo.InvariantCulture);
				if (expressionNode != null)
				{
					context.Position = num2;
					return expressionNode;
				}
			}
			apiProvider.GetRequestTracer(metadata)?.AddMessage(MugenExtensions.Format("Cannot parse digit expression '{0}'", value.ToString() + readOnlySpan));
			return null;
		}

		private static IExpressionNode? Convert(ReadOnlySpan<char> value, bool integer, ReadOnlySpan<char> postfix, ITokenParserContext context, IFormatProvider formatProvider)
		{
			switch (postfix.Length)
			{
			case 1:
				switch (postfix[0])
				{
				case 'F':
				case 'f':
					return TryParse<float>(value, formatProvider);
				case 'D':
				case 'd':
					return TryParse<double>(value, formatProvider);
				case 'M':
				case 'm':
					return TryParse<decimal>(value, formatProvider);
				case 'U':
				case 'u':
					return TryParse<uint>(value, formatProvider);
				}
				break;
			case 2:
			{
				char c = postfix[0];
				if (c != 'U')
				{
					if (c != 'u' || (!postfix.SequenceEqual("ul".AsSpan()) && !postfix.SequenceEqual("uL".AsSpan())))
					{
						break;
					}
				}
				else if (!postfix.SequenceEqual("UL".AsSpan()) && !postfix.SequenceEqual("Ul".AsSpan()))
				{
					break;
				}
				return TryParse<ulong>(value, formatProvider);
			}
			case 0:
			{
				if (!integer)
				{
					return TryParse<double>(value, formatProvider);
				}
				ulong result2;
				if (value[0] == '-')
				{
					if (long.TryParse(value, NumberStyles.Any, formatProvider, out var result))
					{
						if (result <= int.MaxValue && result >= int.MinValue)
						{
							return ConstantExpressionNode.Get((int)result);
						}
						return ConstantExpressionNode.Get(result);
					}
				}
				else if (ulong.TryParse(value, NumberStyles.Any, formatProvider, out result2))
				{
					if (result2 <= int.MaxValue)
					{
						return ConstantExpressionNode.Get((int)result2);
					}
					if (result2 <= long.MaxValue)
					{
						return ConstantExpressionNode.Get((long)result2);
					}
					return ConstantExpressionNode.Get(result2);
				}
				return null;
			}
			}
			return null;
		}

		private static ConstantExpressionNode? TryParse<TNumber>(ReadOnlySpan<char> value, IFormatProvider formatProvider) where TNumber : INumber<TNumber>
		{
			if (TNumber.TryParse(value, NumberStyles.Any, formatProvider, out TNumber result))
			{
				return new ConstantExpressionNode(result, typeof(TNumber));
			}
			return null;
		}
	}
	public sealed class IndexerTokenParser : TokenParserBase
	{
		public IndexerTokenParser(int priority = 9900)
			: base(priority)
		{
