		private string? GetQuoteToken(ITokenParserContext context)
		{
			if (context.IsEof())
			{
				return null;
			}
			ReadOnlySpan<string> readOnlySpan = _quoteTokens.ReadOnlySpan;
			for (int i = 0; i < readOnlySpan.Length; i++)
			{
