			Mapping.GetOrAddValueRef(UnaryTokenType.Minus.Value[0]) = UnaryTokenType.Minus;
			Mapping.GetOrAddValueRef(UnaryTokenType.Plus.Value[0]) = UnaryTokenType.Plus;
			Mapping.GetOrAddValueRef(UnaryTokenType.BitwiseNegation.Value[0]) = UnaryTokenType.BitwiseNegation;
			Mapping.GetOrAddValueRef(UnaryTokenType.LogicalNegation.Value[0]) = UnaryTokenType.LogicalNegation;
			Mapping.GetOrAddValueRef(UnaryTokenType.DynamicExpression.Value[0]) = new UnaryTokenType[2]
			{
				UnaryTokenType.StaticExpression,
				UnaryTokenType.DynamicExpression
			};
		}

		protected override IExpressionNode? TryParse(ITokenParserContext context, IExpressionNode? expression, IBindingManager apiProvider, IReadOnlyMetadataContext? metadata, CancellationToken cancellationToken)
		{
			if (expression != null)
			{
				return null;
			}
			int num = context.SkipWhitespacesPosition();
