			{
				return null;
			}
			ReadOnlySpan<UnaryTokenType> readOnlySpan = ItemOrArray.FromRawValue<UnaryTokenType>(value).ReadOnlySpan;
			for (int i = 0; i < readOnlySpan.Length; i++)
			{
				UnaryTokenType unaryTokenType = readOnlySpan[i];
				if (!context.IsToken(unaryTokenType.Value, num))
				{
					continue;
