					{
						apiProvider.GetRequestTracer(metadata)?.AddMessage(MugenExtensions.Format("Cannot parse unary expression '{0}' expected expression", context.TokenAt(num).ToString()));
						return null;
					}
					return UnaryExpressionNode.Get(unaryTokenType, expressionNode);
				}
				IExpressionNode expressionNode2 = null;
				while (true)
				{
					IExpressionNode expressionNode3 = context.TryParse(expressionNode2, base.Priority, metadata, cancellationToken);
					if (expressionNode3 == null)
					{
						break;
					}
					expressionNode2 = expressionNode3;
				}
				if (expressionNode2 != null)
				{
					return UnaryExpressionNode.Get(unaryTokenType, expressionNode2);
