	public sealed class BatchBindingExpressionNode : ExpressionNodeBase<BatchBindingExpressionNode>, IBatchBindingExpressionNode, IExpressionNode, IEquatable<IExpressionNode>, IMetadataOwner<IReadOnlyMetadataContext>
	{
		private readonly object? _bindings;

		public ItemOrIReadOnlyList<IBindingExpressionNode> Bindings => ItemOrIReadOnlyList.FromRawValue<IBindingExpressionNode>(_bindings);

		public override ExpressionNodeType ExpressionType => ExpressionNodeType.BatchBinding;

		public BatchBindingExpressionNode(ItemOrIReadOnlyList<IBindingExpressionNode> bindings, IReadOnlyMetadataContext? metadata = null)
			: base(metadata)
		{
			Should.BeValid(bindings.Count > 0, "bindings");
			_bindings = bindings.GetRawValue();
		}

		public override BatchBindingExpressionNode Clone(IReadOnlyMetadataContext? metadata)
		{
			return new BatchBindingExpressionNode(Bindings, metadata);
		}

		public override string ToString()
		{
			return string.Join("; ", Bindings.AsEnumerable());
		}

		protected override IExpressionNode Visit(IExpressionVisitor visitor, IReadOnlyMetadataContext? metadata)
		{
			bool changed = false;
			ItemOrIReadOnlyList<IBindingExpressionNode> bindings = VisitWithCheck(visitor, Bindings, ref changed, metadata);
			if (!changed)
			{
				return this;
			}
			return new BatchBindingExpressionNode(bindings, base.Metadata);
		}

		protected override bool Equals(BatchBindingExpressionNode other, IExpressionEqualityComparer? comparer)
		{
			return BindingMugenExtensions.Equals(Bindings, other.Bindings, comparer);
		}

		protected override int GetHashCode(int hashCode, IExpressionEqualityComparer? comparer)
		{
			HashCode hashCode2 = default(HashCode);
			hashCode2.Add(hashCode);
			foreach (IBindingExpressionNode binding in Bindings)
			{
				hashCode2.Add(binding.GetHashCode(comparer));
			}
			return hashCode2.ToHashCode();
		}
	}
	public sealed class BinaryExpressionNode : ExpressionNodeBase<IBinaryExpressionNode>, IBinaryExpressionNode, IExpressionNode, IEquatable<IExpressionNode>, IMetadataOwner<IReadOnlyMetadataContext>
	{
		public IExpressionNode Left { get; }

		public IExpressionNode Right { get; }

		public BinaryTokenType Token { get; }

		public override ExpressionNodeType ExpressionType => ExpressionNodeType.Binary;

		public BinaryExpressionNode(BinaryTokenType token, IExpressionNode left, IExpressionNode right, IReadOnlyMetadataContext? metadata = null)
			: base(metadata)
		{
			Should.NotBeNull(token, "token");
			Should.NotBeNull(left, "left");
			Should.NotBeNull(right, "right");
			Left = left;
			Right = right;
			Token = token;
		}

		public override string ToString()
		{
			return $"({Left} {Token.Value} {Right})";
		}

		public override IBinaryExpressionNode Clone(IReadOnlyMetadataContext? metadata)
		{
			return new BinaryExpressionNode(Token, Left, Right, metadata);
		}

		protected override IExpressionNode AcceptCore(IExpressionVisitor visitor, IReadOnlyMetadataContext? metadata)
		{
			if (visitor.TraversalType != ExpressionTraversalType.Inorder)
			{
				return base.AcceptCore(visitor, metadata);
			}
			bool changed = false;
			IExpressionNode left = VisitWithCheck(visitor, Left, notNull: true, ref changed, metadata);
			changed = false;
			IExpressionNode result = VisitWithCheck(visitor, (IExpressionNode)(changed ? new BinaryExpressionNode(Token, left, Right, base.Metadata) : this), notNull: true, ref changed, metadata);
			if (changed)
			{
				return result;
			}
			IExpressionNode right = VisitWithCheck(visitor, Right, notNull: true, ref changed, metadata);
			if (changed)
			{
				return new BinaryExpressionNode(Token, left, right, base.Metadata);
			}
			return result;
		}

		protected override IExpressionNode Visit(IExpressionVisitor visitor, IReadOnlyMetadataContext? metadata)
		{
			bool changed = false;
			IExpressionNode left = VisitWithCheck(visitor, Left, notNull: true, ref changed, metadata);
			IExpressionNode right = VisitWithCheck(visitor, Right, notNull: true, ref changed, metadata);
			if (changed)
			{
				return new BinaryExpressionNode(Token, left, right, base.Metadata);
			}
			return this;
		}

		protected override bool Equals(IBinaryExpressionNode other, IExpressionEqualityComparer? comparer)
		{
			if (Token == other.Token && Left.Equals(other.Left, comparer))
			{
				return Right.Equals(other.Right, comparer);
			}
			return false;
		}

		protected override int GetHashCode(int hashCode, IExpressionEqualityComparer? comparer)
		{
			return HashCode.Combine(hashCode, Token.GetHashCode(), Left.GetHashCode(comparer), Right.GetHashCode(comparer));
		}
	}
	public sealed class BindingExpressionNode : ExpressionNodeBase<BindingExpressionNode>, IBindingExpressionNode, IExpressionNode, IEquatable<IExpressionNode>, IMetadataOwner<IReadOnlyMetadataContext>
	{
		private readonly object? _parameters;

		public IExpressionNode? Target { get; }

		public IExpressionNode Source { get; }

		public ItemOrIReadOnlyList<IExpressionNode> Parameters => ItemOrIReadOnlyList.FromRawValue<IExpressionNode>(_parameters);

		public override ExpressionNodeType ExpressionType => ExpressionNodeType.Binding;

		public BindingExpressionNode(IExpressionNode? target, IExpressionNode source, ItemOrIReadOnlyList<IExpressionNode> parameters, IReadOnlyMetadataContext? metadata = null)
			: base(metadata)
		{
			Should.NotBeNull(source, "source");
			Target = target;
			Source = source;
			_parameters = parameters.GetRawValue();
		}

		public override BindingExpressionNode Clone(IReadOnlyMetadataContext? metadata)
		{
			return new BindingExpressionNode(Target, Source, Parameters, metadata);
		}

		public override string ToString()
		{
			return $"{Target} {Source}{((Parameters.Count == 0) ? null : (", " + string.Join(",", Parameters.AsEnumerable())))}";
		}

		public IBindingExpressionNode Update(IExpressionNode? target, IExpressionNode source, ItemOrIReadOnlyList<IExpressionNode> parameters)
		{
			if (object.Equals(Target, target) && object.Equals(Source, source) && parameters.Equals(Parameters))
			{
				return this;
			}
			return new BindingExpressionNode(target, source, parameters, base.Metadata);
		}

		protected override IExpressionNode Visit(IExpressionVisitor visitor, IReadOnlyMetadataContext? metadata)
		{
			bool changed = false;
			IExpressionNode target = null;
			if (Target != null)
			{
				target = VisitWithCheck(visitor, Target, notNull: false, ref changed, metadata);
			}
			IExpressionNode source = VisitWithCheck(visitor, Source, notNull: true, ref changed, metadata);
			ItemOrIReadOnlyList<IExpressionNode> parameters = VisitWithCheck(visitor, Parameters, ref changed, metadata);
			if (!changed)
			{
				return this;
			}
			return new BindingExpressionNode(target, source, parameters, base.Metadata);
		}

		protected override bool Equals(BindingExpressionNode other, IExpressionEqualityComparer? comparer)
		{
			if (ExpressionNodeBase<BindingExpressionNode>.Equals(Target, other.Target, comparer) && ExpressionNodeBase<BindingExpressionNode>.Equals(Source, other.Source, comparer))
			{
				return BindingMugenExtensions.Equals(Parameters, other.Parameters, comparer);
			}
			return false;
		}

		protected override int GetHashCode(int hashCode, IExpressionEqualityComparer? comparer)
		{
			return HashCode.Combine(hashCode, Target?.GetHashCode(comparer) ?? 0, Source.GetHashCode(comparer));
		}
	}
	public sealed class BindingInstanceMemberExpressionNode : BindingMemberExpressionNodeBase<BindingInstanceMemberExpressionNode>, IHasMemberPathInfo
	{
		private readonly Type? _type;

		private IMemberPath? _path;

		public object? Instance { get; }

		public BindingInstanceMemberExpressionNode(object? instance, string path, int index, EnumFlags<MemberObserverFlags> flags, EnumFlags<MemberFlags> memberFlags, string? observableMethodName = null, IExpressionNode? expression = null, Type? type = null, IReadOnlyMetadataContext? metadata = null)
			: base(path, index, flags, memberFlags, observableMethodName, expression, metadata)
		{
			_type = type;
			Instance = instance;
		}

		public override object? GetBindingSource(object target, IReadOnlyMetadataContext? metadata)
		{
			if (Instance != null && (!string.IsNullOrEmpty(base.Path) || base.ObservableMethodName != null))
			{
				return GetObserver(Instance, GetPath(metadata), metadata);
			}
			return Instance;
		}

		public override BindingParameterValue GetBindingParameter(object target, IReadOnlyMetadataContext? metadata)
		{
			if (Instance == null)
			{
				return default(BindingParameterValue);
			}
			if (string.IsNullOrEmpty(base.Path))
			{
				if (Instance is Func<IReadOnlyMetadataContext, object> func)
				{
					return BindingParameterValue.FromDelegate(func, _type);
				}
				return BindingParameterValue.FromValue(Instance);
			}
			return BindingParameterValue.FromPath(target, this);
		}

		public override BindingInstanceMemberExpressionNode Clone(IReadOnlyMetadataContext? metadata)
		{
			return new BindingInstanceMemberExpressionNode(Instance, base.Path, base.Index, base.ObserverFlags, base.MemberFlags, base.ObservableMethodName, base.NestedExpression, _type, metadata);
		}

		protected override bool Equals(BindingInstanceMemberExpressionNode other, IExpressionEqualityComparer? comparer)
		{
			if (object.Equals(Instance, other.Instance))
			{
				return base.Equals(other, comparer);
			}
			return false;
		}

		protected override int GetHashCode(int hashCode, IExpressionEqualityComparer? comparer)
		{
			return base.GetHashCode((hashCode * 397) ^ (Instance?.GetHashCode() ?? 0), comparer);
		}

		private IMemberPath GetPath(IReadOnlyMetadataContext? metadata)
		{
			return _path ?? (_path = IMugenService<IObservationManager>.Instance.GetMemberPath(base.Path, metadata));
		}

		IMemberPath IHasMemberPathInfo.GetPath(object? source, IReadOnlyMetadataContext? metadata)
		{
			return GetPath(metadata);
		}
	}
	public sealed class BindingMemberExpressionNode : BindingMemberExpressionNodeBase<BindingMemberExpressionNode>, IHasMemberPathInfo
	{
		private IMemberPath? _path;

		public BindingMemberExpressionNode(string path, int index, EnumFlags<MemberObserverFlags> flags, EnumFlags<MemberFlags> memberFlags, string? observableMethodName = null, IExpressionNode? expression = null, IReadOnlyMetadataContext? metadata = null)
			: base(path, index, flags, memberFlags, observableMethodName, expression, metadata)
		{
		}

		public override object GetBindingSource(object target, IReadOnlyMetadataContext? metadata)
		{
			if (string.IsNullOrEmpty(base.Path) && base.ObservableMethodName == null)
			{
				if (!IsWeak(target))
				{
					return target;
				}
				return target.ToWeakReferenceOrBoxed();
			}
			return GetObserver(IsWeak(target) ? target.ToWeakReferenceOrBoxed() : target, GetPath(metadata), metadata);
		}

		public override BindingParameterValue GetBindingParameter(object target, IReadOnlyMetadataContext? metadata)
		{
			return BindingParameterValue.FromPath(target, this);
		}

		public override BindingMemberExpressionNode Clone(IReadOnlyMetadataContext? metadata)
		{
			return new BindingMemberExpressionNode(base.Path, base.Index, base.ObserverFlags, base.MemberFlags, base.ObservableMethodName, base.NestedExpression, metadata);
		}

		private IMemberPath GetPath(IReadOnlyMetadataContext? metadata)
		{
			return _path ?? (_path = IMugenService<IObservationManager>.Instance.GetMemberPath(base.Path, metadata));
		}

		IMemberPath IHasMemberPathInfo.GetPath(object? source, IReadOnlyMetadataContext? metadata)
		{
			return GetPath(metadata);
		}
	}
	public abstract class BindingMemberExpressionNodeBase<TExpression> : ExpressionNodeBase<TExpression>, IBindingMemberExpressionNode, IExpressionNode, IEquatable<IExpressionNode>, IMetadataOwner<IReadOnlyMetadataContext> where TExpression : BindingMemberExpressionNodeBase<TExpression>
	{
		private ushort _flags;

		private ushort _memberFlags;

		public EnumFlags<MemberObserverFlags> ObserverFlags => new EnumFlags<MemberObserverFlags>(_flags);

		public EnumFlags<MemberFlags> MemberFlags => new EnumFlags<MemberFlags>(_memberFlags);

		public int Index { get; private set; }

		public string? ObservableMethodName { get; private set; }

		public string Path { get; }

		public IExpressionNode? NestedExpression { get; }

		public override ExpressionNodeType ExpressionType => ExpressionNodeType.BindingMember;

		protected BindingMemberExpressionNodeBase(string path, int index, EnumFlags<MemberObserverFlags> flags, EnumFlags<MemberFlags> memberFlags, string? observableMethodName, IExpressionNode? expression, IReadOnlyMetadataContext? metadata)
			: base(metadata)
		{
			Should.NotBeNull(path, "path");
			_flags = flags.Value((ushort)0);
			_memberFlags = memberFlags.Value((ushort)0);
			Path = path;
			Index = index;
			NestedExpression = expression;
			ObservableMethodName = observableMethodName;
		}

		public abstract object? GetBindingSource(object target, IReadOnlyMetadataContext? metadata);

		public abstract BindingParameterValue GetBindingParameter(object target, IReadOnlyMetadataContext? metadata);

		public override string ToString()
		{
			if (NestedExpression != null)
			{
				return $"bind{Index}({NestedExpression})";
			}
			return $"bind{Index}({Path})";
		}

		public IBindingMemberExpressionNode Update(int index, EnumFlags<MemberObserverFlags> flags, EnumFlags<MemberFlags> memberFlags, string? observableMethodName)
		{
			if (Index == index && _flags == flags.Value((ushort)0) && _memberFlags == memberFlags.Value((ushort)0) && ObservableMethodName == observableMethodName)
			{
				return this;
			}
			TExpression val = Clone(base.Metadata);
			val._flags = flags.Value((ushort)0);
			val._memberFlags = memberFlags.Value((ushort)0);
			val.Index = index;
			val.ObservableMethodName = observableMethodName;
			return val;
		}

		protected override bool Equals(TExpression other, IExpressionEqualityComparer? comparer)
		{
			if (_flags == other._flags && _memberFlags == other._memberFlags && Index == other.Index && Path.Equals(other.Path) && string.Equals(ObservableMethodName, other.ObservableMethodName))
			{
				return ExpressionNodeBase<TExpression>.Equals(NestedExpression, other.NestedExpression, comparer);
			}
			return false;
		}

		protected override int GetHashCode(int hashCode, IExpressionEqualityComparer? comparer)
		{
			if (NestedExpression == null)
			{
				return HashCode.Combine(hashCode, Index, Path.GetHashCode(), _flags.GetHashCode(), _memberFlags.GetHashCode(), ObservableMethodName?.GetHashCode() ?? 0);
			}
			return HashCode.Combine(hashCode, Index, Path.GetHashCode(), _flags.GetHashCode(), _memberFlags.GetHashCode(), ObservableMethodName?.GetHashCode() ?? 0, NestedExpression.GetHashCode(comparer));
		}

		protected override IExpressionNode Visit(IExpressionVisitor visitor, IReadOnlyMetadataContext? metadata)
		{
			return this;
		}

		protected bool IsWeak(object target)
		{
			if (!(target is IWeakBindingSource weakBindingSource))
			{
				if (ObserverFlags.HasFlag(MemberObserverFlags.RequireWeak))
				{
					return !(target is Delegate);
				}
				return false;
			}
			return weakBindingSource.IsWeak;
		}

		protected IMemberPathObserver GetObserver(object target, IMemberPath path, IReadOnlyMetadataContext? metadata)
		{
			return IMugenService<IObservationManager>.Instance.GetMemberPathObserver(target, path, MemberFlags, ObserverFlags, ObservableMethodName, this, metadata);
		}

		protected string MergePath(string value)
		{
			if (string.IsNullOrEmpty(Path))
			{
				return value;
			}
			if (Path.StartsWith('['))
			{
				return value + Path;
			}
			return value + "." + Path;
		}
	}
	public sealed class BindingResourceMemberExpressionNode : BindingMemberExpressionNodeBase<BindingResourceMemberExpressionNode>, IHasMemberPathInfo
	{
		private IMemberPath? _requestPath;

		private IMemberPath? _requestResourcePath;

		public string ResourceName { get; }

		public BindingResourceMemberExpressionNode(string resourceName, string path, int index, EnumFlags<MemberObserverFlags> flags, EnumFlags<MemberFlags> memberFlags, string? observableMethodName = null, IExpressionNode? expression = null, IReadOnlyMetadataContext? metadata = null)
			: base(path, index, flags, memberFlags, observableMethodName, expression, metadata)
		{
			Should.NotBeNull(resourceName, "resourceName");
			ResourceName = resourceName;
		}

		public override object? GetBindingSource(object target, IReadOnlyMetadataContext? metadata)
		{
			IMemberPath path;
			object resource = GetResource(target, metadata, out path);
			if (path == null && base.ObservableMethodName == null)
			{
				return resource;
			}
			if (resource == null)
			{
				ExceptionManager.ThrowCannotResolveResource(ResourceName);
			}
			return GetObserver(resource, path ?? MemberPath.Empty, metadata);
		}

		public override BindingParameterValue GetBindingParameter(object target, IReadOnlyMetadataContext? metadata)
		{
			IMemberPath path;
			object resource = GetResource(target, metadata, out path);
			if (path == null)
			{
				return BindingParameterValue.FromValue(resource);
			}
			if (resource == null)
			{
				ExceptionManager.ThrowCannotResolveResource(ResourceName);
			}
			return BindingParameterValue.FromPath(resource, this);
		}

		public override BindingResourceMemberExpressionNode Clone(IReadOnlyMetadataContext? metadata)
		{
			return new BindingResourceMemberExpressionNode(ResourceName, base.Path, base.Index, base.ObserverFlags, base.MemberFlags, base.ObservableMethodName, base.NestedExpression, metadata);
		}

		protected override bool Equals(BindingResourceMemberExpressionNode other, IExpressionEqualityComparer? comparer)
		{
			if (ResourceName.Equals(other.ResourceName))
			{
				return base.Equals(other, comparer);
			}
			return false;
		}

		protected override int GetHashCode(int hashCode, IExpressionEqualityComparer? comparer)
		{
			return base.GetHashCode((hashCode * 397) ^ ResourceName.GetHashCode(), comparer);
		}

		private object? GetResource(object target, IReadOnlyMetadataContext? metadata, out IMemberPath? path)
		{
			Optional<object> optional = IMugenService<IBindingManager>.Instance.TryGetResource(ResourceName, target, metadata);
			if (!optional.HasValue)
			{
				ExceptionManager.ThrowCannotResolveResource(ResourceName);
			}
			if (optional.Value is IBindingResource)
			{
				path = _requestResourcePath ?? (_requestResourcePath = IMugenService<IObservationManager>.Instance.GetMemberPath(MergePath("Value"), metadata));
			}
			else if (string.IsNullOrEmpty(base.Path))
			{
				path = null;
			}
			else
			{
				path = _requestPath ?? (_requestPath = IMugenService<IObservationManager>.Instance.GetMemberPath(base.Path, metadata));
			}
			return optional.Value;
		}

		IMemberPath IHasMemberPathInfo.GetPath(object? source, IReadOnlyMetadataContext? metadata)
		{
			if (source is IBindingResource)
			{
				return _requestResourcePath;
			}
			return _requestPath;
		}
	}
	public sealed class ConditionExpressionNode : ExpressionNodeBase<IConditionExpressionNode>, IConditionExpressionNode, IExpressionNode, IEquatable<IExpressionNode>, IMetadataOwner<IReadOnlyMetadataContext>
	{
		public IExpressionNode Condition { get; }

		public IExpressionNode IfTrue { get; }

		public IExpressionNode IfFalse { get; }

		public override ExpressionNodeType ExpressionType => ExpressionNodeType.Condition;

		public ConditionExpressionNode(IExpressionNode condition, IExpressionNode ifTrue, IExpressionNode ifFalse, IReadOnlyMetadataContext? metadata = null)
			: base(metadata)
		{
			Should.NotBeNull(condition, "condition");
			Should.NotBeNull(ifTrue, "ifTrue");
			Should.NotBeNull(ifFalse, "ifFalse");
			Condition = condition;
			IfTrue = ifTrue;
			IfFalse = ifFalse;
		}

		public override string ToString()
		{
			return $"if ({Condition}) {{{IfTrue}}} else {{{IfFalse}}}";
		}

		public override IConditionExpressionNode Clone(IReadOnlyMetadataContext? metadata)
		{
			return new ConditionExpressionNode(Condition, IfTrue, IfFalse, metadata);
		}

		protected override IExpressionNode Visit(IExpressionVisitor visitor, IReadOnlyMetadataContext? metadata)
		{
			bool changed = false;
			IExpressionNode condition = VisitWithCheck(visitor, Condition, notNull: true, ref changed, metadata);
			IExpressionNode ifTrue = VisitWithCheck(visitor, IfTrue, notNull: true, ref changed, metadata);
			IExpressionNode ifFalse = VisitWithCheck(visitor, IfFalse, notNull: true, ref changed, metadata);
			if (changed)
			{
				return new ConditionExpressionNode(condition, ifTrue, ifFalse, base.Metadata);
			}
			return this;
		}

		protected override bool Equals(IConditionExpressionNode other, IExpressionEqualityComparer? comparer)
		{
			if (Condition.Equals(other.Condition, comparer) && IfTrue.Equals(other.IfTrue, comparer))
			{
				return IfFalse.Equals(other.IfFalse, comparer);
			}
			return false;
		}

		protected override int GetHashCode(int hashCode, IExpressionEqualityComparer? comparer)
		{
			return HashCode.Combine(hashCode, Condition.GetHashCode(comparer), IfTrue.GetHashCode(comparer), IfFalse.GetHashCode(comparer));
		}
	}
