	public sealed class UnaryExpressionNode : ExpressionNodeBase<IUnaryExpressionNode>, IUnaryExpressionNode, IExpressionNode, IEquatable<IExpressionNode>, IMetadataOwner<IReadOnlyMetadataContext>
	{
		public static readonly UnaryExpressionNode EventArgsMacros = new UnaryExpressionNode(UnaryTokenType.DynamicExpression, MemberExpressionNode.EventArgs);

		public static readonly UnaryExpressionNode SelfMacros = new UnaryExpressionNode(UnaryTokenType.StaticExpression, MemberExpressionNode.Self);

		public static readonly UnaryExpressionNode ContextMacros = new UnaryExpressionNode(UnaryTokenType.DynamicExpression, MemberExpressionNode.Context);

		public static readonly UnaryExpressionNode BindingMacros = new UnaryExpressionNode(UnaryTokenType.DynamicExpression, MemberExpressionNode.Binding);

		public override ExpressionNodeType ExpressionType => ExpressionNodeType.Unary;

		public UnaryTokenType Token { get; }

		public IExpressionNode Operand { get; }

		public UnaryExpressionNode(UnaryTokenType token, IExpressionNode operand, IReadOnlyMetadataContext? metadata = null)
			: base(metadata)
		{
			Should.NotBeNull(token, "token");
			Should.NotBeNull(operand, "operand");
			Token = token;
			Operand = operand;
		}

		public static UnaryExpressionNode Get(UnaryTokenType token, IExpressionNode operand)
		{
			if ((token == UnaryTokenType.DynamicExpression || token == UnaryTokenType.StaticExpression) && operand is IMemberExpressionNode { Target: null } memberExpressionNode)
			{
				switch (memberExpressionNode.Member)
				{
				case "self":
				case "this":
					return SelfMacros;
				case "args":
					return EventArgsMacros;
				case "context":
					return ContextMacros;
				case "binding":
					return BindingMacros;
				}
			}
			return new UnaryExpressionNode(token, operand);
		}

		public override string ToString()
		{
			return $"{Token.Value}{Operand}";
		}

		public override IUnaryExpressionNode Clone(IReadOnlyMetadataContext? metadata)
		{
			return new UnaryExpressionNode(Token, Operand, metadata);
		}

		protected override IExpressionNode Visit(IExpressionVisitor visitor, IReadOnlyMetadataContext? metadata)
		{
			bool changed = false;
			IExpressionNode operand = VisitWithCheck(visitor, Operand, notNull: true, ref changed, metadata);
			if (changed)
			{
				return new UnaryExpressionNode(Token, operand, base.Metadata);
			}
			return this;
		}

		protected override bool Equals(IUnaryExpressionNode other, IExpressionEqualityComparer? comparer)
		{
			if (Token == other.Token)
			{
				return Operand.Equals(other.Operand, comparer);
			}
			return false;
		}

		protected override int GetHashCode(int hashCode, IExpressionEqualityComparer? comparer)
		{
			return HashCode.Combine(hashCode, Token.GetHashCode(), Operand.GetHashCode(comparer));
		}
	}
