							accessorMemberInfoBase = (IAccessorMemberInfoBase)typeof(ObservableWrapperAccessorMemberInfo<, >).MakeGenericType(type, accessorMemberInfoBase.Type.GetGenericArguments()[0]).GetConstructors(BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic)[0].Invoke(new object[1] { accessorMemberInfoBase });
						}
						string text = accessorMemberInfoBase.Name;
						bool flag = true;
						MemoryExtensions.SpanSplitEnumerator<char> enumerator = name.AsSpan().Split("~@#B").GetEnumerator();
						while (enumerator.MoveNext())
						{
							_ = enumerator.Current;
							if (flag)
							{
								flag = false;
								continue;
							}
							text += "~@#B";
							Type type2 = (accessorMemberInfoBase.MemberFlags.HasFlag(MemberFlags.Static) ? typeof(object) : accessorMemberInfoBase.DeclaringType);
							accessorMemberInfoBase = (IAccessorMemberInfoBase)typeof(BindableWrapperAccessorMemberInfo<, >).MakeGenericType(type2, accessorMemberInfoBase.Type.GetGenericArguments()[0]).GetConstructors(BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic)[0].Invoke(new object[2] { text, accessorMemberInfoBase });
						}
						items.Add(accessorMemberInfoBase);
					}
					catch (Exception exception)
					{
						IMugenService<IMugenApplication>.Instance.OnUnhandledException(exception, UnhandledExceptionType.Aot, this, metadata);
						items.Add(item);
					}
				}
			}
			catch
			{
				items.Dispose();
				throw;
			}
			return items.AsPooledReadOnlyList();
		}
	}
