	internal sealed class BindableWrapperAccessorMemberInfo<TTarget, TValue> : AccessorAttachedMemberInfoBase<TTarget, TValue> where TTarget : class
	{
		private abstract class BindableValueStorageBase : EventListenerCollection, IEventListener, IWeakItem, IBindableListener<TValue>, IBindableListener
		{
			private readonly IAccessorMemberInfo<TTarget, Bindable<TValue>> _accessor;

			private Bindable<TValue> _lastValue;

			private ActionToken _token;

			private ActionToken _accessorToken;

			private TValue? _value;

			public abstract bool IsAlive { get; }

			public TValue? Value
			{
				get
				{
					return _value;
				}
				private set
				{
					if (!EqualityComparer<TValue>.Default.Equals(_value, value))
					{
						_value = value;
						Raise();
					}
				}
			}

			public bool IsWeak => true;

			protected BindableValueStorageBase(IAccessorMemberInfo<TTarget, Bindable<TValue>> accessor)
			{
				_accessor = accessor;
			}

			public static BindableValueStorageBase GetOrAdd(TTarget? target, string path, IAccessorMemberInfo<TTarget, Bindable<TValue>> accessor)
			{
				AttachedValueStorage attachedValueStorage = (((object)target) ?? ((object)accessor.DeclaringType)).AttachedValues().BatchUpdate();
				try
				{
					if (!attachedValueStorage.TryGet((ReadOnlySpan<char>)path, out BindableValueStorageBase value))
					{
						value = (accessor.MemberFlags.HasFlag(MugenMvvm.Reflection.Enums.MemberFlags.Static) ? ((BindableValueStorageBase)new StaticBindableValueStorage(accessor)) : ((BindableValueStorageBase)new BindableValueStorage(target, accessor)));
						attachedValueStorage.Set(path, value);
					}
					return value;
				}
				finally
				{
					((IDisposable)attachedValueStorage/*cast due to .constrained prefix*/).Dispose();
				}
			}

			public void OnValue(TValue value)
			{
				Value = value;
			}

			public void OnError(Exception error, BindableErrorType errorType)
			{
				if (TryGetTarget(out TTarget target))
				{
					RaiseOnError(target, error, errorType, null);
				}
			}

			public void OnBeginExecuting(object source, BindableExecutionKind kind)
			{
				if (TryGetTarget(out TTarget target))
				{
					RaiseOnBeginExecuting(target, kind, null);
				}
			}

			public void OnEndExecuting(object source, BindableExecutionKind kind)
			{
				if (TryGetTarget(out TTarget target))
				{
					RaiseOnEndExecuting(target, kind, null);
				}
			}

			public bool TryHandle(object? sender, object? message, IReadOnlyMetadataContext? metadata)
			{
				InvalidateValue((TTarget)sender, metadata);
				return IsAlive;
			}

			protected abstract bool TryGetTarget([NotNullWhen(true)] out TTarget? target);

			protected override void OnListenersAdded()
			{
				base.OnListenersAdded();
				if (TryGetTarget(out TTarget target))
				{
					_accessorToken = _accessor.TryObserve(target, this);
					InvalidateValue(target, null);
				}
			}

			protected override void OnListenersRemoved()
			{
				base.OnListenersRemoved();
				_accessorToken.Dispose();
				InvalidateValue(default(Bindable<TValue>));
			}

			private void Raise()
			{
				if (TryGetTarget(out TTarget target))
				{
					Raise(target, null, null);
				}
			}

			private void InvalidateValue(TTarget target, IReadOnlyMetadataContext? metadata)
			{
				InvalidateValue(_accessor.GetValue(target, metadata));
			}

			private void InvalidateValue(Bindable<TValue> bindable)
			{
				if (!(bindable == _lastValue))
				{
					_token.Dispose();
					_lastValue = bindable;
					_token = bindable.Bind(this);
				}
			}
		}

		private sealed class StaticBindableValueStorage : BindableValueStorageBase
		{
			public override bool IsAlive => true;

			public StaticBindableValueStorage(IAccessorMemberInfo<TTarget, Bindable<TValue>> accessor)
				: base(accessor)
			{
			}

			protected override bool TryGetTarget([NotNullWhen(true)] out TTarget? target)
			{
				target = null;
				return true;
			}
		}

		private sealed class BindableValueStorage : BindableValueStorageBase
		{
			private readonly WeakRef<TTarget> _target;

			public override bool IsAlive => _target.IsAlive;

			public BindableValueStorage(TTarget target, IAccessorMemberInfo<TTarget, Bindable<TValue>> accessor)
				: base(accessor)
			{
				_target = target.ToWeakReference();
			}

			protected override bool TryGetTarget([NotNullWhen(true)] out TTarget? target)
			{
				target = _target.Target;
				return target != null;
			}
		}

		public override bool CanRead => true;

		public override bool CanWrite => false;

		public BindableWrapperAccessorMemberInfo(string name, IAccessorMemberInfo<TTarget, Bindable<TValue>> underlyingMember)
			: base(name, underlyingMember.MemberFlags, underlyingMember.DeclaringType, (object?)underlyingMember, 0)
		{
		}

		public override TValue GetValue(TTarget target, IReadOnlyMetadataContext? metadata = null)
		{
			return BindableValueStorageBase.GetOrAdd(target, base.Name, (IAccessorMemberInfo<TTarget, Bindable<TValue>>)base.UnderlyingMember).Value;
		}

		public override void SetValue(TTarget target, TValue value, IReadOnlyMetadataContext? metadata = null)
		{
			ExceptionManager.ThrowMemberMustBeWritable(this);
		}

		public override ActionToken TryObserve(object? target, IEventListener listener, IReadOnlyMetadataContext? metadata = null)
		{
			return BindableValueStorageBase.GetOrAdd((TTarget)target, base.Name, (IAccessorMemberInfo<TTarget, Bindable<TValue>>)base.UnderlyingMember).Add(listener);
		}
	}
	internal sealed class CustomPropertyAttachedMemberInfo<TTarget, TValue> : AccessorAttachedMemberInfoBase<TTarget, TValue>, INotifiableMemberInfo, IObservableMemberInfo, IMemberInfo, IHasName where TTarget : class?
	{
		private readonly string? _id;

		private readonly string? _attachId;

		private readonly Func<IAccessorMemberInfo<TTarget, TValue>, TTarget, IReadOnlyMetadataContext?, TValue>? _getValue;

		private readonly Action<IAccessorMemberInfo<TTarget, TValue>, TTarget, TValue, IReadOnlyMetadataContext?>? _setValue;

		private readonly Func<IAccessorMemberInfo<TTarget, TValue>, TTarget, IEventListener, IReadOnlyMetadataContext?, ActionToken>? _tryObserve;

		private readonly Action<IAccessorMemberInfo<TTarget, TValue>, TTarget, object?, IReadOnlyMetadataContext?>? _raise;

		private readonly Action<IAccessorMemberInfo<TTarget, TValue>, TTarget, IReadOnlyMetadataContext?>? _attachedHandler;

		private MemberObservable _observer;

		public override bool CanRead => _getValue != null;

		public override bool CanWrite => _setValue != null;

		public CustomPropertyAttachedMemberInfo(Func<IAccessorMemberInfo<TTarget, TValue>, TTarget, IReadOnlyMetadataContext?, TValue>? getValue, Action<IAccessorMemberInfo<TTarget, TValue>, TTarget, TValue, IReadOnlyMetadataContext?>? setValue, Func<IAccessorMemberInfo<TTarget, TValue>, TTarget, IEventListener, IReadOnlyMetadataContext?, ActionToken>? tryObserve, Action<IAccessorMemberInfo<TTarget, TValue>, TTarget, object?, IReadOnlyMetadataContext?>? raise, bool autoObservable, Action<IAccessorMemberInfo<TTarget, TValue>, TTarget, IReadOnlyMetadataContext?>? attachedHandler, string name, EnumFlags<MemberFlags> memberFlags, Type? declaringType, object? underlyingMember, int priority)
			: base(name, memberFlags, declaringType, underlyingMember, priority)
		{
			_getValue = getValue;
			_setValue = setValue;
			_tryObserve = tryObserve;
			_raise = raise;
			_attachedHandler = attachedHandler;
			if (autoObservable)
			{
				_id = AttachedMemberBuilder.GenerateMemberId("$#p", base.DeclaringType, name);
				_tryObserve = delegate(IAccessorMemberInfo<TTarget, TValue> member, TTarget target, IEventListener listener, IReadOnlyMetadataContext? metadata)
				{
					CustomPropertyAttachedMemberInfo<TTarget, TValue> customPropertyAttachedMemberInfo = (CustomPropertyAttachedMemberInfo<TTarget, TValue>)member;
					return EventListenerCollection.GetOrAdd(customPropertyAttachedMemberInfo.GetTarget(target), customPropertyAttachedMemberInfo._id, metadata).Add(listener);
				};
				_raise = delegate(IAccessorMemberInfo<TTarget, TValue> member, TTarget target, object? message, IReadOnlyMetadataContext? metadata)
				{
					CustomPropertyAttachedMemberInfo<TTarget, TValue> customPropertyAttachedMemberInfo = (CustomPropertyAttachedMemberInfo<TTarget, TValue>)member;
					EventListenerCollection.Raise(customPropertyAttachedMemberInfo.GetTarget(target), customPropertyAttachedMemberInfo._id, message, metadata);
				};
			}
			if (attachedHandler != null)
			{
				_attachId = AttachedMemberBuilder.GenerateMemberId("$#2", base.DeclaringType, name);
			}
		}

		public override TValue GetValue(TTarget target, IReadOnlyMetadataContext? metadata = null)
		{
			if (_getValue == null)
			{
				ExceptionManager.ThrowMemberMustBeReadable(this);
			}
			if (_attachId != null)
			{
				AttachedMemberBuilder.RaiseMemberAttached(_attachId, target, this, _attachedHandler, metadata);
			}
			return _getValue(this, target, metadata);
		}

		public override void SetValue(TTarget target, TValue value, IReadOnlyMetadataContext? metadata = null)
		{
			if (_setValue == null)
			{
				ExceptionManager.ThrowMemberMustBeWritable(this);
			}
			if (_attachId != null)
			{
				AttachedMemberBuilder.RaiseMemberAttached(_attachId, target, this, _attachedHandler, metadata);
			}
			_setValue(this, target, value, metadata);
			Raise(target, null, metadata);
		}

		public void Raise(object? target, object? message = null, IReadOnlyMetadataContext? metadata = null)
		{
			if (_raise != null)
			{
				if (_attachId != null)
				{
					AttachedMemberBuilder.RaiseMemberAttached(_attachId, (TTarget)target, this, _attachedHandler, metadata);
				}
				_raise(this, (TTarget)target, message, metadata);
			}
		}

		public override ActionToken TryObserve(object? target, IEventListener listener, IReadOnlyMetadataContext? metadata = null)
		{
			if (_attachId != null)
			{
				AttachedMemberBuilder.RaiseMemberAttached(_attachId, (TTarget)target, this, _attachedHandler, metadata);
			}
			if (_tryObserve == null)
			{
				return this.TryObserveCore(target, listener, metadata, ref _observer);
			}
			return _tryObserve(this, (TTarget)target, listener, metadata);
		}
	}
	public ref struct CustomPropertyBuilder<TTarget, TValue> where TTarget : class?
	{
		private PropertyBuilder<TTarget, TValue> _propertyBuilder;

		private Func<IAccessorMemberInfo<TTarget, TValue>, TTarget, IReadOnlyMetadataContext?, TValue>? _getter;

		private Action<IAccessorMemberInfo<TTarget, TValue>, TTarget, TValue, IReadOnlyMetadataContext?>? _setter;

		private Func<IObservableMemberInfo, TTarget, IEventListener, IReadOnlyMetadataContext?, ActionToken>? _tryObserve;

		private Action<IObservableMemberInfo, TTarget, object?, IReadOnlyMetadataContext?>? _raise;

		private bool _isObservable;

		public CustomPropertyBuilder(PropertyBuilder<TTarget, TValue> propertyBuilder)
		{
			Should.BeSupported(!propertyBuilder.IsInherits, "Inherits");
			Should.BeSupported(propertyBuilder.PropertyChanged == null, "PropertyChangedHandler");
			Should.BeSupported(propertyBuilder.GetInterceptorField == null, "GetterInterceptor");
			Should.BeSupported(!propertyBuilder.HasDefaultValueField, "DefaultValue");
			_propertyBuilder = propertyBuilder;
			_isObservable = false;
			_tryObserve = null;
			_raise = null;
			_getter = null;
			_setter = null;
		}

		public CustomPropertyBuilder<TTarget, TValue> Priority(int priority)
		{
			_propertyBuilder.Priority(priority);
			return this;
		}

		public CustomPropertyBuilder<TTarget, TValue> Static()
		{
			_propertyBuilder.Static();
			return this;
		}

		public CustomPropertyBuilder<TTarget, TValue> UnderlyingMember(object member)
		{
			_propertyBuilder.UnderlyingMember(member);
			return this;
		}

		public CustomPropertyBuilder<TTarget, TValue> Getter(Func<IAccessorMemberInfo<TTarget, TValue>, TTarget, IReadOnlyMetadataContext?, TValue> getter)
		{
			Should.NotBeNull(getter, "getter");
			_getter = getter;
			return this;
		}

		public CustomPropertyBuilder<TTarget, TValue> Setter(Action<IAccessorMemberInfo<TTarget, TValue>, TTarget, TValue, IReadOnlyMetadataContext?> setter)
		{
			Should.NotBeNull(setter, "setter");
			_setter = setter;
			return this;
		}

		public CustomPropertyBuilder<TTarget, TValue> Observable()
		{
			Should.BeSupported(_tryObserve == null, "Observable");
			_isObservable = true;
			return this;
		}

		public CustomPropertyBuilder<TTarget, TValue> NonObservable()
		{
			_isObservable = false;
			_propertyBuilder.NonObservable();
			return this;
		}

		public CustomPropertyBuilder<TTarget, TValue> Observable(IObservableMemberInfo? memberInfo)
		{
			if (memberInfo == null)
			{
				return this;
			}
			return Observable(memberInfo.TryObserve, (memberInfo is INotifiableMemberInfo notifiableMemberInfo) ? new Action<IObservableMemberInfo, TTarget, object, IReadOnlyMetadataContext>(notifiableMemberInfo.Raise) : null);
		}

		public CustomPropertyBuilder<TTarget, TValue> Observable(string? memberName, bool canRaise = false)
		{
			if (memberName == null)
			{
				return this;
			}
			MemberObservableClosure memberObservableClosure = new MemberObservableClosure(memberName);
			return Observable(memberObservableClosure.TryObserve, canRaise ? new Action<IObservableMemberInfo, TTarget, object, IReadOnlyMetadataContext>(memberObservableClosure.Raise) : null);
		}

		public CustomPropertyBuilder<TTarget, TValue> Observable(Func<IObservableMemberInfo, TTarget, IEventListener, IReadOnlyMetadataContext?, ActionToken> tryObserve, Action<IObservableMemberInfo, TTarget, object?, IReadOnlyMetadataContext?>? raise = null)
		{
			Should.NotBeNull(tryObserve, "tryObserve");
			Should.BeSupported(!_isObservable, "Observable");
			_tryObserve = tryObserve;
			_raise = raise;
			return this;
		}

		public CustomPropertyBuilder<TTarget, TValue> AttachedHandler(Action<IAccessorMemberInfo<TTarget, TValue>, TTarget, IReadOnlyMetadataContext?> attachedHandler)
		{
			_propertyBuilder.AttachedHandler(attachedHandler);
			return this;
		}

		public IAccessorMemberInfo<TTarget, TValue> Build()
		{
			_propertyBuilder.WrapperClosure?.SetFlags(_propertyBuilder.IsStatic);
			return new CustomPropertyAttachedMemberInfo<TTarget, TValue>(_getter, _setter, _tryObserve, _raise, _isObservable, _propertyBuilder.AttachedHandlerField, _propertyBuilder.Name, AttachedMemberBuilder.GetFlags(_propertyBuilder.IsStatic, _propertyBuilder.NoObservable), _propertyBuilder.DeclaringType, _propertyBuilder.UnderlyingMemberField, _propertyBuilder.PriorityField);
		}

		public IAccessorMemberInfo<TTarget, TValue> Build(AttachedMemberProvider memberProvider)
		{
			IAccessorMemberInfo<TTarget, TValue> accessorMemberInfo = Build();
			memberProvider.Register(accessorMemberInfo);
			return accessorMemberInfo;
		}
	}
	[DebuggerDisplay("{Type} {Name}")]
	internal sealed class EventAttachedMemberInfo<TTarget> : INotifiableMemberInfo, IObservableMemberInfo, IMemberInfo, IHasName, IHasPriority where TTarget : class?
	{
		private readonly string? _id;

		private readonly string? _attachId;

		private readonly Action<INotifiableMemberInfo, TTarget, IReadOnlyMetadataContext?>? _attachedHandler;

		private readonly Func<INotifiableMemberInfo, TTarget, IEventListener, IReadOnlyMetadataContext?, ActionToken> _subscribe;

		private readonly Action<INotifiableMemberInfo, TTarget, object?, IReadOnlyMetadataContext?>? _raise;

		public string Name { get; }

		public int Priority { get; }

		public Type DeclaringType { get; }

		public Type Type { get; }

		public object? UnderlyingMember { get; }

		public MemberType MemberType => MugenMvvm.Reflection.Enums.MemberType.Event;

		public EnumFlags<MemberFlags> MemberFlags { get; }

		public EventAttachedMemberInfo(Func<INotifiableMemberInfo, TTarget, IEventListener, IReadOnlyMetadataContext?, ActionToken>? subscribe, Action<INotifiableMemberInfo, TTarget, object?, IReadOnlyMetadataContext?>? raise, Action<INotifiableMemberInfo, TTarget, IReadOnlyMetadataContext?>? attachedHandler, string name, Type? declaringType, Type? type, object? underlyingMember, EnumFlags<MemberFlags> memberFlags, int priority)
		{
			Should.NotBeNull(name, "name");
			Name = name;
			DeclaringType = declaringType ?? typeof(TTarget);
			Type = type ?? typeof(EventHandler);
			UnderlyingMember = underlyingMember;
			MemberFlags = memberFlags;
			Priority = priority;
			_attachedHandler = attachedHandler;
			_raise = raise;
			if (_attachedHandler != null)
			{
				_attachId = AttachedMemberBuilder.GenerateMemberId("$#1", Type, name);
			}
			if (subscribe == null)
			{
				_id = AttachedMemberBuilder.GenerateMemberId("$#e", Type, name);
				_subscribe = delegate(INotifiableMemberInfo member, TTarget target, IEventListener listener, IReadOnlyMetadataContext? metadata)
				{
					EventAttachedMemberInfo<TTarget> eventAttachedMemberInfo = (EventAttachedMemberInfo<TTarget>)member;
					return EventListenerCollection.GetOrAdd(eventAttachedMemberInfo.GetTarget(target), eventAttachedMemberInfo._id, metadata).Add(listener);
				};
				_raise = delegate(INotifiableMemberInfo member, TTarget target, object? message, IReadOnlyMetadataContext? metadata)
				{
					EventAttachedMemberInfo<TTarget> eventAttachedMemberInfo = (EventAttachedMemberInfo<TTarget>)member;
					EventListenerCollection.Raise(eventAttachedMemberInfo.GetTarget(target), eventAttachedMemberInfo._id, message, metadata);
				};
			}
			else
			{
				_subscribe = subscribe;
			}
		}

		public void Raise(object? target, object? message = null, IReadOnlyMetadataContext? metadata = null)
		{
			if (_raise != null)
			{
				if (_attachId != null)
				{
					AttachedMemberBuilder.RaiseMemberAttached(_attachId, (TTarget)target, this, _attachedHandler, metadata);
				}
				_raise(this, (TTarget)target, message, metadata);
			}
		}

		public ActionToken TryObserve(object? target, IEventListener listener, IReadOnlyMetadataContext? metadata = null)
		{
			if (_attachId != null)
			{
				AttachedMemberBuilder.RaiseMemberAttached(_attachId, (TTarget)target, this, _attachedHandler, metadata);
			}
			return _subscribe(this, (TTarget)target, listener, metadata);
		}
	}
	public ref struct EventBuilder<TTarget> where TTarget : class?
	{
		private readonly Type _declaringType;

		private readonly string _name;

		private readonly Type _eventType;

		private Action<INotifiableMemberInfo, TTarget, IReadOnlyMetadataContext?>? _attachedHandler;

		private Func<INotifiableMemberInfo, TTarget, IEventListener, IReadOnlyMetadataContext?, ActionToken>? _subscribe;

		private Action<INotifiableMemberInfo, TTarget, object?, IReadOnlyMetadataContext?>? _raise;

		private object? _underlyingMember;

		private bool _isStatic;

		private int _priority;

		public EventBuilder(string name, Type declaringType, Type eventType)
		{
			Should.NotBeNull(name, "name");
			Should.NotBeNull(declaringType, "declaringType");
			Should.NotBeNull(eventType, "eventType");
			_name = name;
			_declaringType = declaringType;
			_attachedHandler = null;
			_subscribe = null;
			_raise = null;
			_isStatic = false;
			_eventType = eventType;
			_underlyingMember = null;
			_priority = 0;
		}

		public EventBuilder<TTarget> Priority(int priority)
		{
			_priority = priority;
			return this;
		}

		public EventBuilder<TTarget> Static()
		{
			_isStatic = true;
			return this;
		}

		public EventBuilder<TTarget> UnderlyingMember(object member)
		{
			Should.NotBeNull(member, "member");
			_underlyingMember = member;
			return this;
		}

		public EventBuilder<TTarget> WrapMember(IObservableMemberInfo memberInfo)
		{
			Should.NotBeNull(memberInfo, "memberInfo");
			return Handler(memberInfo.TryObserve, (memberInfo is INotifiableMemberInfo notifiableMemberInfo) ? new Action<INotifiableMemberInfo, TTarget, object, IReadOnlyMetadataContext>(notifiableMemberInfo.Raise) : null);
		}

		public EventBuilder<TTarget> Handler(Func<INotifiableMemberInfo, TTarget, IEventListener, IReadOnlyMetadataContext?, ActionToken> subscribe, Action<INotifiableMemberInfo, TTarget, object?, IReadOnlyMetadataContext?>? raise = null)
		{
			Should.NotBeNull(subscribe, "subscribe");
			_subscribe = subscribe;
			_raise = raise;
			return this;
		}

		public EventBuilder<TTarget> AttachedHandler(Action<INotifiableMemberInfo, TTarget, IReadOnlyMetadataContext?> attachedHandler)
		{
			Should.NotBeNull(attachedHandler, "attachedHandler");
			_attachedHandler = attachedHandler;
			return this;
		}

		public INotifiableMemberInfo Build()
		{
			return new EventAttachedMemberInfo<TTarget>(_subscribe, _raise, _attachedHandler, _name, _declaringType, _eventType, _underlyingMember, AttachedMemberBuilder.GetFlags(_isStatic, nonObservable: false), _priority);
		}

		public INotifiableMemberInfo Build(AttachedMemberProvider memberProvider)
		{
			INotifiableMemberInfo notifiableMemberInfo = Build();
			memberProvider.Register(notifiableMemberInfo);
			return notifiableMemberInfo;
		}
	}
	internal sealed class MemberObservableClosure
	{
		private readonly string _memberName;

		private IObservableMemberInfo? _memberInfo;

		public MemberObservableClosure(string memberName)
		{
			_memberName = memberName;
		}

		public ActionToken TryObserve<TTarget>(IObservableMemberInfo member, TTarget target, IEventListener listener, IReadOnlyMetadataContext? metadata) where TTarget : class?
		{
			if (_memberInfo == null)
			{
				Init(member, target);
			}
