		private const int StateInWindow = 1;

		private const int StatePending = 2;

		private const int StateArmed = 4;

		private const int StateDisposed = 8;

		private readonly int _ms;

		private readonly Bindable.ISuspendable _gate;

		private Timer? _timer;

		private int _state;

		public ThrottleLatestClosure(int milliseconds, Bindable.ISuspendable gate)
		{
