			{
				return;
			}
			SpinWait spinWait = default(SpinWait);
			while (true)
			{
				int num = Volatile.Read(in _state);
				if ((num & 1) == 0)
				{
					int value = num | 1 | 4;
					if (Interlocked.CompareExchange(ref _state, value, num) == num)
					{
						_timer.SafeChange(_ms, -1);
						break;
					}
				}
				else
				{
					int value2 = num | 2;
					if (Interlocked.CompareExchange(ref _state, value2, num) == num)
					{
						break;
					}
				}
				if (spinWait.Count > 128)
