	internal sealed class UseLatestClosure<T, TState> : IDisposable
	{
		private const byte DisposedState = 1;

		private ActionToken _token;

		private byte _disposeState;

		public T Transform(T v, Func<T, TState, ActionToken> factory, TState state)
		{
			if (Volatile.Read(in _disposeState) == 1)
			{
				return v;
			}
			ActionToken token = _token;
			ActionToken token2;
			try
			{
				token2 = factory(v, state);
			}
			finally
			{
				token.Dispose();
			}
			_token = token2;
			if (Volatile.Read(in _disposeState) == 1)
			{
				token2.Dispose();
			}
			return v;
		}

		public void Dispose()
		{
			Interlocked.Exchange(ref _disposeState, 1);
			_token.Dispose();
		}
	}
	internal sealed class UseLatestDisposableClosure<T, TState, TResult> : IDisposable where TResult : IDisposable?
	{
		private const byte DisposedState = 1;

		private TResult? _token;

		private byte _disposeState;

		public TResult Transform(T v, Func<T, TState, TResult> factory, TState state)
		{
			if (Volatile.Read(in _disposeState) == 1)
			{
				return default(TResult);
			}
			TResult val;
			using (_token)
			{
				val = factory(v, state);
			}
			_token = val;
			if (Volatile.Read(in _disposeState) == 1)
			{
				val?.Dispose();
				return default(TResult);
			}
			return val;
		}

		public void Dispose()
		{
			Interlocked.Exchange(ref _disposeState, 1);
			ref TResult reference = ref _token;
			TResult val = default(TResult);
			if (val == null)
			{
				val = reference;
				reference = ref val;
				if (val == null)
				{
					return;
				}
			}
			reference.Dispose();
		}
	}
	internal sealed class WeakBindableListenerWrapper<T> : SingleFastBindableListenerBase<T>
	{
		public ActionToken Token;

		private readonly WeakRef<IBindableListener<T>> _listener;

		public WeakBindableListenerWrapper(IBindableListener<T> listener)
		{
			Should.NotBeNull(listener, "listener");
			_listener = listener.ToWeakReference();
		}

		public override void OnValue(T value)
		{
			GetTarget()?.OnValue(value);
		}

		public override void OnError(Exception error, BindableErrorType errorType)
		{
			GetTarget()?.OnError(error, errorType);
		}

		public override void OnBeginExecuting(object source, BindableExecutionKind kind)
		{
			GetTarget()?.OnBeginExecuting(source, kind);
		}

		public override void OnEndExecuting(object source, BindableExecutionKind kind)
		{
			GetTarget()?.OnEndExecuting(source, kind);
		}

		private IBindableListener<T>? GetTarget()
		{
			IBindableListener<T>? target = _listener.Target;
			if (target == null)
			{
				Token.Dispose();
			}
			return target;
		}
	}
	internal class WeakDelegateBindableListener<T, TTarget> : SingleFastBindableListenerBase<T> where TTarget : class
	{
		private sealed class WeakDelegateBindableListenerError : WeakDelegateBindableListener<T, TTarget>
		{
			private readonly Action<Exception, BindableErrorType, TTarget> _onError;

			internal WeakDelegateBindableListenerError(Action<T?, TTarget> onValue, TTarget state, Action<Exception, BindableErrorType, TTarget> onError)
				: base(onValue, state)
			{
				_onError = onError;
			}

			public override void OnError(Exception error, BindableErrorType errorType)
			{
				TTarget target = GetTarget();
				if (target != null)
				{
					_onError(error, errorType, target);
				}
			}
		}

		public ActionToken Token;

		private readonly Action<T?, TTarget> _onValue;

		private readonly WeakRef<TTarget> _ref;

		private WeakDelegateBindableListener(Action<T?, TTarget> onValue, TTarget target)
		{
			_ref = target.ToWeakReference();
			_onValue = onValue;
		}

		public static WeakDelegateBindableListener<T, TTarget> Get(TTarget state, Action<T?, TTarget> onValue, Action<Exception, BindableErrorType, TTarget>? onError)
		{
			Should.NotBeNull(onValue, "onValue");
			if (onError != null)
			{
				return new WeakDelegateBindableListenerError(onValue, state, onError);
			}
			return new WeakDelegateBindableListener<T, TTarget>(onValue, state);
		}

		public sealed override void OnValue(T? value)
		{
			try
			{
				TTarget target = GetTarget();
				if (target != null)
				{
					_onValue(value, target);
				}
			}
			catch (Exception error)
			{
				OnError(error, BindableErrorType.Unhandled);
			}
		}

		private TTarget? GetTarget()
		{
			TTarget? target = _ref.Target;
			if (target == null)
			{
				Token.Dispose();
			}
			return target;
		}
	}
	internal sealed class WhereBindableExpression<T> : IValueBindableProvider<T>, IBindableProvider<T>, IBindingSourceExpression
	{
		private sealed class WhereBindableListenerWrapper : SingleFastBindableListenerBase<T>, IInner<IBindableListener<T>>
		{
			private readonly Func<T, bool> _predicate;

			public IBindableListener<T> Inner { get; }

			public WhereBindableListenerWrapper(IBindableListener<T> inner, Func<T, bool> predicate)
			{
				Should.NotBeNull(inner, "inner");
				_predicate = predicate;
				Inner = inner;
			}

			public override void OnValue(T value)
			{
				if (_predicate(value))
				{
					Inner.OnValue(value);
				}
			}

			public override void OnError(Exception error, BindableErrorType errorType)
			{
				Inner.OnError(error, errorType);
			}

			public override void OnBeginExecuting(object source, BindableExecutionKind kind)
			{
				Inner.OnBeginExecuting(source, kind);
			}

			public override void OnEndExecuting(object source, BindableExecutionKind kind)
			{
				Inner.OnEndExecuting(source, kind);
			}
		}

		private class WhereBindableValue : ListenerBindableValue<T>
		{
			private readonly Func<T, bool> _predicate;

			public WhereBindableValue(Func<T, bool> predicate)
			{
				_predicate = predicate;
			}

			public override void OnValue(T value)
			{
				if (_predicate(value))
				{
					base.Value = value;
				}
			}
		}

		private readonly object? _bindable;

		private readonly object? _member;

		public WhereBindableExpression(Bindable<T> bindable)
		{
			_bindable = bindable._target;
			_member = bindable._expression;
		}

		public ActionToken Bind(object? target, IBindableListener<T> listener, bool initialSync)
		{
			Func<T, bool> predicate = (Func<T, bool>)target;
			Bindable<T> bindable = new Bindable<T>(_bindable, _member, default(T));
			return bindable.Bind(new WhereBindableListenerWrapper(listener, predicate), initialSync);
		}

		public bool TryGet(object? target, ref object source, ref object expression, ref string? rootPath, IReadOnlyMetadataContext? metadata)
		{
			Func<T, bool> predicate = (Func<T, bool>)source;
			Bindable<T> bindable = new Bindable<T>(_bindable, _member, default(T));
			WhereBindableValue whereBindableValue = new WhereBindableValue(predicate);
			source = new BindableValuePathObserverEx<T>(whereBindableValue, bindable.Bind(whereBindableValue), disposeTarget: false);
			return true;
		}

		public IBindableReadOnlyValue<T> ToValue(object? target, out ActionToken disposeToken)
		{
			Func<T, bool> predicate = (Func<T, bool>)target;
			Bindable<T> bindable = new Bindable<T>(_bindable, _member, default(T));
			WhereBindableValue whereBindableValue = new WhereBindableValue(predicate);
			disposeToken = bindable.Bind(whereBindableValue);
			return whereBindableValue;
		}
	}
