		internal static void OnChanged(IBindableListener<T> listener, IMemberPathObserver observer)
		{
			listener.OnBeginExecuting(observer, BindableExecutionKind.PathObserver);
			try
			{
				observer.GetLastMember().TryGet<T>(null, out var value);
				listener.OnValue(value);
			}
			finally
			{
				listener.OnEndExecuting(observer, BindableExecutionKind.PathObserver);
			}
		}

		bool IEventListener.OnError(object? sender, Exception error, object? state, IReadOnlyMetadataContext? metadata)
		{
			OnError(error, (state as BindableErrorType) ?? BindableErrorType.Path);
			return true;
		}

		bool IEventListener.OnBeginExecuting(object? sender, object? state, IReadOnlyMetadataContext? metadata)
		{
			OnBeginExecuting(sender ?? this, (state as BindableExecutionKind) ?? BindableExecutionKind.PathObserver);
			return true;
		}

		bool IEventListener.OnEndExecuting(object? sender, object? state, IReadOnlyMetadataContext? metadata)
		{
			OnEndExecuting(sender ?? this, (state as BindableExecutionKind) ?? BindableExecutionKind.PathObserver);
			return true;
		}

		bool IEventListener.TryHandle(object? sender, object? message, IReadOnlyMetadataContext? metadata)
		{
			OnBeginExecuting(sender ?? this, BindableExecutionKind.PathObserver);
			try
			{
				OnValue(((IHasReadOnlyValue<T>)sender).Value);
				return true;
			}
			finally
			{
				OnEndExecuting(sender ?? this, BindableExecutionKind.PathObserver);
			}
		}

		void IMemberPathObserverListener.OnPathMembersChanged(IMemberPathObserver observer, IReadOnlyMetadataContext? metadata)
		{
			OnChanged(this, observer);
		}

		void IMemberPathObserverListener.OnLastMemberChanged(IMemberPathObserver observer, IReadOnlyMetadataContext? metadata)
		{
			OnChanged(this, observer);
		}

		void IMemberPathObserverListener.OnError(IMemberPathObserver observer, Exception error, object? state, IReadOnlyMetadataContext? metadata)
		{
			OnError(error, (state as BindableErrorType) ?? BindableErrorType.Path);
		}

		void IMemberPathObserverListener.OnDisposed(IMemberPathObserver observer, IReadOnlyMetadataContext? metadata)
		{
		}

		void IObserver<T>.OnCompleted()
		{
		}

		void IObserver<T>.OnError(Exception error)
		{
			OnError(error, BindableErrorType.Observer);
		}

		void IObserver<T>.OnNext(T value)
		{
			OnBeginExecuting(this, BindableExecutionKind.Observable);
			try
			{
				OnValue(value);
			}
			finally
			{
				OnEndExecuting(this, BindableExecutionKind.Observable);
			}
		}
