			MemberObserverLastMember lastMember = target.GetLastMember(metadata);
			_unsubscriber = (lastMember.Member as IObservableMemberInfo)?.TryObserve(lastMember.Target, this, metadata) ?? default(ActionToken);
			if (!_unsubscriber.IsInitialized)
			{
