		}

		private void OnCanExecuteChanged(object? sender, EventArgs e)
		{
			_binding?.UpdateSource();
		}

		private bool CanExecute(ICommand command, IBindingInternal binding, IReadOnlyMetadataContext? metadata)
		{
			if (command is ICompositeCommand compositeCommand)
			{
				return compositeCommand.CanExecute(_commandParameter.GetValue<object>(binding, metadata), isForce: false, metadata);
			}
			return command.CanExecute(_commandParameter.GetValueRaw<object>(binding, metadata));
		}

		bool IEventListener.TryHandle(object? sender, object? message, IReadOnlyMetadataContext? metadata)
		{
			ICommand target = _commandRef.Target;
			if (target == null)
			{
				return _state != 2;
			}
			try
			{
				if (sender != null || message != null)
				{
					IMetadataContext metadataContext = metadata.WithRawValue(BindingMetadata.Binding, _binding, out metadata);
					if (sender != null)
					{
						metadataContext.SetRaw(BindingMetadata.EventSource, sender);
					}
					if (message != null)
					{
						metadataContext.SetRaw(BindingMetadata.EventArgs, message);
					}
				}
				if (target is ICompositeCommand compositeCommand)
				{
					compositeCommand.Execute(_commandParameter.GetValue<object>(_binding, metadata), isForce: false, metadata);
				}
				else
				{
					target.Execute(_commandParameter.GetValueRaw<object>(_binding, metadata));
				}
			}
			catch (Exception exception)
			{
				_binding.OnError(exception, metadata);
			}
			return _state != 2;
		}

		void IMemberPathObserverListener.OnPathMembersChanged(IMemberPathObserver observer, IReadOnlyMetadataContext? metadata)
		{
			_binding.UpdateTarget(metadata);
		}

		void IMemberPathObserverListener.OnLastMemberChanged(IMemberPathObserver observer, IReadOnlyMetadataContext? metadata)
		{
			_binding.UpdateTarget(metadata);
		}

		void IMemberPathObserverListener.OnError(IMemberPathObserver observer, Exception error, object? state, IReadOnlyMetadataContext? metadata)
		{
		}

		void IMemberPathObserverListener.OnDisposed(IMemberPathObserver observer, IReadOnlyMetadataContext? metadata)
		{
			_binding?.Dispose();
		}
