		private static IBindingHandler? TryGetBindingHandler(Type? targetType, string methodName, BindingParameterValue targetNullValue, BindingParameterValue fallback, IMemberPathObserver? target, ItemOrArray<object?> sources, IReadOnlyMetadataContext? metadata)
		{
