			if (type == null)
			{
				return null;
			}
			IMethodMemberInfo methodMemberInfo = TryResolveMethod(targetType, methodName, sources, metadata);
			if (methodMemberInfo == null)
			{
				return null;
			}
			return GetActionHandler(methodMemberInfo, type, targetNullValue, fallback, metadata);
		}

		[UnconditionalSuppressMessage("Trimming", "IL2067")]
		private static IMethodMemberInfo? TryResolveMethod(Type? targetType, string methodName, ItemOrArray<object?> sources, IReadOnlyMetadataContext? metadata)
		{
