			EnumFlags<MemberFlags> flags;
			if (targetType == null)
			{
				targetType = GetValueType(sources[0], metadata);
				if (targetType == null)
				{
					return null;
				}
				num = 1;
				flags = MemberFlags.InstanceAll;
			}
			else
			{
				num = 0;
				flags = MemberFlags.StaticAll;
			}
			Type[] array = TypeArgsPool.Get(sources.Count - num);
			for (int i = 0; i < array.Length; i++)
			{
				Type valueType = GetValueType(sources[i + num], metadata);
				if (valueType == null)
				{
					return null;
				}
				array[i] = valueType;
			}
			IMethodMemberInfo result = (IMethodMemberInfo)IMugenService<IReflectionManager>.Instance.GetMember(targetType, (FlagsEnumBase<MemberType, ushort>?)MemberType.Method, flags, methodName, array, null, metadata);
			TypeArgsPool.Return(array);
			return result;
