		private static Type? GetValueType(object? source, IReadOnlyMetadataContext? metadata)
		{
			if (source == null)
			{
				return typeof(object);
			}
			if (source is IMemberPathObserver memberPathObserver)
			{
				return memberPathObserver.GetLastMember(metadata).GetValueType(throwOnError: true);
			}
			if (source is IConstantExpressionNode constantExpressionNode)
			{
				return constantExpressionNode.Type;
			}
			if (source is IWeakReference weakReference)
			{
				return weakReference.Target?.GetType();
			}
			if (source is Func<IReadOnlyMetadataContext, IBinding>)
			{
				return typeof(IBinding);
			}
			if (source is Func<IReadOnlyMetadataContext, object>)
			{
				return typeof(object);
			}
			return source.GetType();
		}

