			}
			else
			{
				type = source.GetType();
			}
			return GetAccessorHandler(valueType, type, targetNullValue, fallback);
		}

		private static IBindingHandler? TryGetBindingHandler(IMemberPathObserver target, object source, IReadOnlyMetadataContext? metadata)
		{
			Should.NotBeNull(target, "target");
			Should.NotBeNull(source, "source");
			Type valueType = target.GetLastMember(metadata).GetValueType(throwOnError: true);
			if (valueType == null)
			{
				return null;
			}
			Type type;
			if (source is IMemberPathObserver memberPathObserver)
			{
				type = memberPathObserver.GetLastMember().GetValueType(throwOnError: true);
				if (type == null)
				{
					return null;
				}
			}
			else
			{
				type = source.GetType();
			}
			return GetAccessorHandler(valueType, type);
		}

		private static void UpdateTarget(IBindingInternal binding, BindingParameterValue fallback, BindingParameterValue targetNullValue, IReadOnlyMetadataContext? metadata)
		{
			MemberObserverLastMember memberObserverLastMember = binding.Target.GetLastMember().ThrowIfError();
			if (memberObserverLastMember.IsAvailable)
			{
				object obj = (fallback.IsInitialized ? fallback.GetValue<object>(binding, metadata) : null);
				if (obj == null && targetNullValue.IsInitialized)
				{
					obj = targetNullValue.GetValue<object>(binding, metadata);
				}
				((IAccessorMemberInfo)memberObserverLastMember.Member).SetValue(memberObserverLastMember.Target, obj, metadata);
			}
		}
	}
	[DebuggerDisplay("Proxy({Handler})")]
	internal class ProxyBindingHandler<TProxy> : IBindingHandler, IAttachableBindingComponent, IInner<IBindingHandler> where TProxy : IBindingHandlerProxy
	{
		protected TProxy Proxy;

		protected IBindingHandler? Handler;

		internal ProxyBindingHandler(TProxy proxy)
		{
			Proxy = proxy;
		}

		public bool HasMemberWithType(Type type)
		{
			if (Handler != null)
			{
				return Handler.HasMemberWithType(type);
			}
			return false;
		}

		public virtual void OnAttached(IBindingInternal binding, IReadOnlyMetadataContext? metadata)
		{
			if (Handler == null)
			{
				TryInitialize(binding, metadata);
			}
			else
			{
				Handler.OnAttached(binding, metadata);
			}
		}

		public virtual void UpdateTarget(IBindingInternal binding, IReadOnlyMetadataContext? metadata)
		{
			if (Handler != null)
			{
				Handler.UpdateTarget(binding, metadata);
				return;
			}
			IBindingHandler bindingHandler;
			try
			{
				bindingHandler = TryInitialize(binding, metadata);
				if (bindingHandler == null)
				{
					if (binding.OnTargetUpdating(metadata))
					{
						Proxy.UpdateTarget(binding, metadata);
						binding.OnTargetUpdated(updated: false, null, metadata);
					}
					return;
				}
			}
			catch (Exception exception)
			{
				if (binding.OnTargetUpdating(metadata))
				{
					binding.OnTargetUpdated(updated: false, exception, metadata);
				}
				return;
			}
			bindingHandler.UpdateTarget(binding, metadata);
		}

		public virtual void UpdateSource(IBindingInternal binding, IReadOnlyMetadataContext? metadata)
		{
			if (Handler != null)
			{
				Handler.UpdateSource(binding, metadata);
				return;
			}
			IBindingHandler bindingHandler;
			try
			{
				bindingHandler = TryInitialize(binding, metadata);
				if (bindingHandler == null)
				{
					if (binding.OnSourceUpdating(metadata))
					{
						binding.OnSourceUpdated(updated: false, null, metadata);
					}
					return;
				}
			}
			catch (Exception exception)
			{
				if (binding.OnSourceUpdating(metadata))
				{
					binding.OnSourceUpdated(updated: false, exception, metadata);
				}
				return;
			}
			bindingHandler.UpdateSource(binding, metadata);
		}

		public virtual void OnDisposed(IBindingInternal? binding, IReadOnlyMetadataContext? metadata)
		{
			Proxy = default(TProxy);
			Handler?.OnDisposed(binding, metadata);
		}

		public void OnTargetUpdated(IBindingInternal binding, bool updated, Exception? exception, IReadOnlyMetadataContext? metadata)
		{
			(Handler ?? TryInitialize(binding, metadata))?.OnTargetUpdated(binding, updated, exception, metadata);
		}

		public void OnSourceUpdated(IBindingInternal binding, bool updated, Exception? exception, IReadOnlyMetadataContext? metadata)
		{
			(Handler ?? TryInitialize(binding, metadata))?.OnSourceUpdated(binding, updated, exception, metadata);
		}

		public void OnError(IBindingInternal binding, Exception exception, IReadOnlyMetadataContext? metadata)
		{
			(Handler ?? TryInitialize(binding, metadata))?.OnError(binding, exception, metadata);
		}

		protected virtual void Initialize(IBindingHandler handler, IBindingInternal binding, IReadOnlyMetadataContext? metadata)
		{
			handler.OnAttached(binding, metadata);
		}

		protected IBindingHandler? TryInitialize(IBindingInternal binding, IReadOnlyMetadataContext? metadata)
		{
			lock (this)
			{
				if (Handler == null)
				{
					Handler = Proxy.TryGetBindingHandler(binding, metadata);
					if (Handler != null)
					{
						Proxy = default(TProxy);
						Initialize(Handler, binding, metadata);
						return Handler;
					}
				}
			}
			return null;
		}
	}
	public sealed class SuspendOnDetachBindingHandlerWrapper : IBindingHandler, IAttachableBindingComponent, IInner<IBindingHandler>, IDecorator<IBindingHandler>, IEventListener, IWeakItem
	{
		private const byte UnchangedState = 0;

		private const byte TargetState = 1;

		private const byte SourceState = 2;

		private readonly IBindingHandler _bindingHandler;

		private readonly IAccessorMemberInfo<bool> _attachedMember;

		private IBindingInternal? _binding;

		private ActionToken _token;

		private byte _state;

		public bool IsWeak => true;

		public bool IsAlive => !(_binding?.IsDisposed ?? false);

		IInner<IBindingHandler> IDecorator<IBindingHandler>.Next => _bindingHandler;

		public SuspendOnDetachBindingHandlerWrapper(IBindingHandler bindingHandler, object target, IAccessorMemberInfo<bool> attachedMember)
		{
			Should.NotBeNull(bindingHandler, "bindingHandler");
			Should.NotBeNull(attachedMember, "attachedMember");
			_bindingHandler = bindingHandler;
			_attachedMember = attachedMember;
			_token = attachedMember.TryObserve(target, this);
		}

		public void OnAttached(IBindingInternal binding, IReadOnlyMetadataContext? metadata)
		{
			_binding = binding;
			_bindingHandler.OnAttached(binding, metadata);
		}

		public void OnDisposed(IBindingInternal? binding, IReadOnlyMetadataContext? metadata)
		{
			_token.Dispose();
			_bindingHandler.OnDisposed(binding, metadata);
		}

		public bool HasMemberWithType(Type type)
		{
			return _bindingHandler.HasMemberWithType(type);
		}

		public void UpdateTarget(IBindingInternal binding, IReadOnlyMetadataContext? metadata)
		{
			if (IsAttached(binding))
			{
				_bindingHandler.UpdateTarget(binding, metadata);
			}
			else if (binding.OnTargetUpdating(metadata))
			{
				binding.OnTargetUpdated(updated: false, null, metadata);
				_state = 1;
			}
		}

		public void UpdateSource(IBindingInternal binding, IReadOnlyMetadataContext? metadata)
		{
			if (IsAttached(binding))
			{
				_bindingHandler.UpdateSource(binding, metadata);
			}
			else if (binding.OnSourceUpdating(metadata))
			{
				binding.OnSourceUpdated(updated: false, null, metadata);
				_state = 2;
			}
		}

		public bool TryHandle(object? sender, object? message, IReadOnlyMetadataContext? metadata)
		{
			IBindingInternal binding = _binding;
			byte state = _state;
			if (binding == null || state == 0 || _attachedMember.GetValue(sender, metadata))
			{
				return true;
			}
			if (binding.IsDisposed)
			{
				return false;
			}
			_state = 0;
			switch (state)
			{
			case 1:
				binding.UpdateTarget();
				break;
			case 2:
				binding.UpdateSource();
				break;
			}
			return true;
		}

		private bool IsAttached(IBindingInternal binding)
		{
			object target = binding.GetTarget();
			if (target == null)
			{
				binding.Dispose();
				return false;
			}
			return _attachedMember.GetValue(target);
		}
	}
	[DebuggerDisplay("OnUIThread{Target}")]
	public sealed class UiThreadBindingHandlerWrapper : IBindingHandler, IAttachableBindingComponent, IInner<IBindingHandler>, IDecorator<IBindingHandler>
	{
		private static class CoalescingScheduler
		{
			private static readonly ConcurrentDictionary<UiThreadBindingHandlerWrapper, byte> Targets = new ConcurrentDictionary<UiThreadBindingHandlerWrapper, byte>();

			private static readonly ConcurrentDictionary<UiThreadBindingHandlerWrapper, byte> Sources = new ConcurrentDictionary<UiThreadBindingHandlerWrapper, byte>();

			private static readonly SendOrPostCallback DrainCb = Drain;

			private static int _scheduled;

			[ThreadStatic]
			private static bool _draining;

			public static void EnqueueTarget(UiThreadBindingHandlerWrapper w, SynchronizationContext ctx)
			{
				Targets[w] = 1;
				Schedule(ctx);
			}

			public static void EnqueueSource(UiThreadBindingHandlerWrapper w, SynchronizationContext ctx)
			{
				Sources[w] = 1;
				Schedule(ctx);
			}

			private static void Schedule(SynchronizationContext ctx)
			{
				if (Interlocked.Exchange(ref _scheduled, 1) == 0)
				{
					ctx.Post(DrainCb, null);
				}
			}

			private static void Drain(object? state)
			{
				if (_draining)
				{
					return;
				}
				_draining = true;
				try
				{
					while (true)
					{
						bool flag = false;
						byte value;
						foreach (KeyValuePair<UiThreadBindingHandlerWrapper, byte> target in Targets)
						{
							if (Targets.TryRemove(target.Key, out value))
							{
								target.Key.OnTargetCallback();
								flag = true;
							}
						}
						foreach (KeyValuePair<UiThreadBindingHandlerWrapper, byte> source in Sources)
						{
							if (Sources.TryRemove(source.Key, out value))
							{
								source.Key.OnSourceCallback();
								flag = true;
							}
						}
						if (!flag)
						{
							Interlocked.Exchange(ref _scheduled, 0);
							if (Targets.IsEmpty && Sources.IsEmpty)
							{
								break;
							}
						}
					}
				}
				finally
				{
					_draining = false;
				}
			}
		}

		private IBindingInternal? _binding;

		private IReadOnlyMetadataContext? _targetMetadata;

		private IReadOnlyMetadataContext? _sourceMetadata;

		public IBindingHandler Target { get; }

		IInner<IBindingHandler> IDecorator<IBindingHandler>.Next => Target;

		public UiThreadBindingHandlerWrapper(IBindingHandler target)
		{
			Should.NotBeNull(target, "target");
			Target = target;
		}

		public void OnAttached(IBindingInternal binding, IReadOnlyMetadataContext? metadata)
		{
			_binding = binding;
			Target.OnAttached(binding, metadata);
		}

		public void OnDisposed(IBindingInternal? binding, IReadOnlyMetadataContext? metadata)
		{
			_binding = null;
			Target.OnDisposed(binding, metadata);
		}

		public bool HasMemberWithType(Type type)
		{
			return Target.HasMemberWithType(type);
		}

		public void UpdateTarget(IBindingInternal binding, IReadOnlyMetadataContext? metadata)
		{
			SynchronizationContext synchronizationContext = MugenService.SynchronizationContext;
			if (synchronizationContext == null || synchronizationContext == SynchronizationContext.Current)
			{
				Target.UpdateTarget(binding, metadata);
				return;
			}
			_targetMetadata = metadata;
			CoalescingScheduler.EnqueueTarget(this, synchronizationContext);
		}

		public void UpdateSource(IBindingInternal binding, IReadOnlyMetadataContext? metadata)
		{
			SynchronizationContext synchronizationContext = MugenService.SynchronizationContext;
			if (synchronizationContext == null || synchronizationContext == SynchronizationContext.Current)
			{
				Target.UpdateSource(binding, metadata);
				return;
			}
			_sourceMetadata = metadata;
			CoalescingScheduler.EnqueueSource(this, synchronizationContext);
		}

		public void OnTargetUpdated(IBindingInternal binding, bool updated, Exception? exception, IReadOnlyMetadataContext? metadata)
		{
			Target.OnTargetUpdated(binding, updated, exception, metadata);
		}

		public void OnSourceUpdated(IBindingInternal binding, bool updated, Exception? exception, IReadOnlyMetadataContext? metadata)
		{
			Target.OnSourceUpdated(binding, updated, exception, metadata);
		}

		public void OnError(IBindingInternal binding, Exception exception, IReadOnlyMetadataContext? metadata)
		{
			Target.OnError(binding, exception, metadata);
		}

		private void OnTargetCallback()
		{
			IBindingInternal binding = _binding;
			if (binding != null)
			{
				IReadOnlyMetadataContext targetMetadata = _targetMetadata;
				Target.UpdateTarget(binding, targetMetadata);
				if (targetMetadata != null)
				{
					Interlocked.CompareExchange(ref _targetMetadata, null, targetMetadata);
				}
			}
		}

		private void OnSourceCallback()
		{
			IBindingInternal binding = _binding;
			if (binding != null)
			{
				IReadOnlyMetadataContext sourceMetadata = _sourceMetadata;
				Target.UpdateSource(binding, sourceMetadata);
				if (sourceMetadata != null)
				{
					Interlocked.CompareExchange(ref _sourceMetadata, null, sourceMetadata);
				}
			}
		}
	}
