namespace MugenMvvm.Bindings.Components
{
	public abstract class BindingModeBase : IBindingComponent, IAttachableBindingComponent, IHasPriority, IMemberPathObserverListener
	{
		private IBindingInternal? _binding;

		public virtual int Priority => 0;

		protected abstract string Name { get; }

		public override string ToString()
		{
			return "Mode=" + Name;
		}

		public void OnAttached(IBindingInternal binding, IReadOnlyMetadataContext? metadata)
		{
			_binding = binding;
			Subscribe(binding, metadata);
		}

		public void OnDisposed(IBindingInternal? binding, IReadOnlyMetadataContext? metadata)
		{
			if (binding == null)
			{
				binding = _binding;
			}
			if (binding != null)
			{
				Unsubscribe(binding, metadata);
			}
			_binding = null;
		}

		protected abstract void OnTargetPathMembersChanged(IBindingInternal binding, IReadOnlyMetadataContext? metadata);

		protected abstract void OnTargetLastMemberChanged(IBindingInternal binding, IReadOnlyMetadataContext? metadata);

		protected abstract void OnSourcePathMembersChanged(IBindingInternal binding, IReadOnlyMetadataContext? metadata);

		protected abstract void OnSourceLastMemberChanged(IBindingInternal binding, IReadOnlyMetadataContext? metadata);

		protected abstract void Subscribe(IBindingInternal binding, IReadOnlyMetadataContext? metadata);

		protected abstract void Unsubscribe(IBindingInternal binding, IReadOnlyMetadataContext? metadata);

		protected void Subscribe(ItemOrArray<object?> items, bool onlyCompositePath, IReadOnlyMetadataContext? metadata)
		{
			ReadOnlySpan<object> readOnlySpan = items.ReadOnlySpan;
			for (int i = 0; i < readOnlySpan.Length; i++)
			{
				object obj = readOnlySpan[i];
				Subscribe(obj as IMemberPathObserver, onlyCompositePath, metadata);
			}
		}

		protected void Subscribe(IMemberPathObserver? observer, bool onlyCompositePath, IReadOnlyMetadataContext? metadata)
		{
			if (observer != null && (!onlyCompositePath || observer.Path.Members.Count > 1))
			{
				observer.AddListener(this, metadata);
			}
		}

		protected void Unsubscribe(ItemOrArray<object?> items, bool onlyCompositePath, IReadOnlyMetadataContext? metadata)
		{
			ReadOnlySpan<object> readOnlySpan = items.ReadOnlySpan;
			for (int i = 0; i < readOnlySpan.Length; i++)
			{
				object obj = readOnlySpan[i];
				Unsubscribe(obj as IMemberPathObserver, onlyCompositePath, metadata);
			}
		}

		protected void Unsubscribe(IMemberPathObserver? observer, bool onlyCompositePath, IReadOnlyMetadataContext? metadata)
		{
			if (observer != null && (!onlyCompositePath || observer.Path.Members.Count > 1))
			{
				observer.RemoveListener(this, metadata);
			}
		}

		void IMemberPathObserverListener.OnPathMembersChanged(IMemberPathObserver observer, IReadOnlyMetadataContext? metadata)
		{
			IBindingInternal binding = _binding;
			if (binding != null)
			{
				if (binding.Target == observer)
				{
					OnTargetPathMembersChanged(binding, metadata);
				}
				else
				{
					OnSourcePathMembersChanged(binding, metadata);
				}
			}
		}

		void IMemberPathObserverListener.OnLastMemberChanged(IMemberPathObserver observer, IReadOnlyMetadataContext? metadata)
		{
			IBindingInternal binding = _binding;
			if (binding != null)
			{
				if (binding.Target == observer)
				{
					OnTargetLastMemberChanged(binding, metadata);
				}
				else
				{
					OnSourceLastMemberChanged(binding, metadata);
				}
			}
		}

		void IMemberPathObserverListener.OnError(IMemberPathObserver observer, Exception error, object? state, IReadOnlyMetadataContext? metadata)
		{
		}

		void IMemberPathObserverListener.OnDisposed(IMemberPathObserver observer, IReadOnlyMetadataContext? metadata)
		{
			_binding?.Dispose();
		}
	}
	public class OneTimeBindingMode : BindingModeBase, IBindingComponent, IAttachableBindingComponent, IHasPriority
	{
		private sealed class DisposableOneTimeBindingMode : OneTimeBindingMode
